class ExchangeStateError(RuntimeError):
    pass


def json_default(obj):
    if isinstance(obj, set): return list(obj)
    raise TypeError


def db_connect():
    return sqlite3.connect(DB_PATH, timeout=15)


def _db_backup_dir():
    return os.path.join(os.path.dirname(os.path.abspath(DB_PATH)), 'backups')


def _db_sessions_count(path):
    try:
        c = sqlite3.connect(path, timeout=15)
        try:
            return int(c.execute('SELECT COUNT(*) FROM sessions').fetchone()[0])
        finally:
            c.close()
    except Exception:
        return 0


def backup_db_now(reason='periodic'):
    """نسخه‌ی پشتیبان سازگار (SQLite backup API) در پوشه‌ی backups کنار دیتابیس. فقط وقتی دیتابیس سشن دارد."""
    try:
        if not os.path.exists(DB_PATH) or _db_sessions_count(DB_PATH) <= 0:
            return None
        os.makedirs(_db_backup_dir(), exist_ok=True)
        dst_path = os.path.join(_db_backup_dir(), 'trader_bot_%s.sqlite3' % datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%S'))
        src = sqlite3.connect(DB_PATH, timeout=15); dst = sqlite3.connect(dst_path)
        try:
            src.backup(dst)
        finally:
            dst.close(); src.close()
        files = sorted(f for f in os.listdir(_db_backup_dir()) if f.startswith('trader_bot_') and f.endswith('.sqlite3'))
        for old_f in files[:-DB_BACKUP_KEEP]:
            try:
                os.remove(os.path.join(_db_backup_dir(), old_f))
            except OSError:
                pass
        logger.info('بکاپ دیتابیس ساخته شد (%s): %s', reason, dst_path)
        return dst_path
    except Exception:
        logger.exception('db backup failed')
        return None


_DB_LAST_BACKUP_TS = 0.0


def maybe_backup_db():
    global _DB_LAST_BACKUP_TS
    if time.time() - _DB_LAST_BACKUP_TS >= DB_BACKUP_INTERVAL_SECONDS:
        _DB_LAST_BACKUP_TS = time.time()
        backup_db_now('periodic')


def restore_db_from_latest_backup_if_empty():
    """اگر دیتابیس فعلی هیچ سشنی ندارد (مثلاً با یک فایل خالی جایگزین شده) و بکاپی با سشن وجود دارد،
    آخرین بکاپ سالم برگردانده می‌شود. خاموش‌کردن: BOT_DB_AUTORESTORE=0."""
    try:
        if not DB_AUTORESTORE or _db_sessions_count(DB_PATH) > 0 or not os.path.isdir(_db_backup_dir()):
            return False
        files = sorted((f for f in os.listdir(_db_backup_dir()) if f.startswith('trader_bot_') and f.endswith('.sqlite3')), reverse=True)
        for f in files:
            bpath = os.path.join(_db_backup_dir(), f)
            if _db_sessions_count(bpath) > 0:
                src = sqlite3.connect(bpath, timeout=15); dst = sqlite3.connect(DB_PATH, timeout=15)
                try:
                    src.backup(dst)
                finally:
                    dst.close(); src.close()
                logger.warning('دیتابیس خالی بود؛ از آخرین بکاپ سالم برگردانده شد: %s', bpath)
                return True
    except Exception:
        logger.exception('db auto-restore failed')
    return False


def init_db():
    db_existed_before = os.path.exists(DB_PATH)
    with DB_LOCK:
        conn = db_connect()
        try:
            conn.execute('PRAGMA journal_mode=WAL')
            conn.execute('PRAGMA synchronous=NORMAL')
            conn.execute('PRAGMA busy_timeout=15000')
            fee_id_type = 'INTEGER PRIMARY KEY AUTOINCREMENT'
            real_type = 'REAL'
            conn.execute('CREATE TABLE IF NOT EXISTS sessions(chat_id INTEGER PRIMARY KEY, data TEXT NOT NULL, updated_at INTEGER NOT NULL)')
            conn.execute('CREATE TABLE IF NOT EXISTS bot_meta(key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at INTEGER NOT NULL)')
            conn.execute('''CREATE TABLE IF NOT EXISTS fee_ledger(
                id %s,
                trade_id TEXT NOT NULL UNIQUE,
                chat_id INTEGER NOT NULL,
                mode TEXT NOT NULL,
                gross_pnl_usdt %s NOT NULL DEFAULT 0,
                trading_cost_usdt %s NOT NULL DEFAULT 0,
                net_profit_before_platform_fee_usdt %s NOT NULL DEFAULT 0,
                fee_rate_pct %s NOT NULL DEFAULT 0,
                platform_fee_usdt %s NOT NULL DEFAULT 0,
                user_net_profit_usdt %s NOT NULL DEFAULT 0,
                status TEXT NOT NULL DEFAULT 'SETTLED',
                created_at %s NOT NULL,
                settled_at %s
            )''' % ((fee_id_type,) + (real_type,)*8))
            conn.execute('''CREATE TABLE IF NOT EXISTS user_fee_settings(
                chat_id INTEGER PRIMARY KEY,
                fee_rate_pct %s NOT NULL,
                updated_at INTEGER NOT NULL
            )''' % real_type)
            # V3.44.61: فاکتورهای کارمزد روزانه (یک ردیف به‌ازای هر کاربر در هر روز)
            conn.execute('''CREATE TABLE IF NOT EXISTS fee_invoices(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                chat_id INTEGER NOT NULL,
                day TEXT NOT NULL,
                profit_usdt REAL NOT NULL DEFAULT 0,
                fee_rate_pct REAL NOT NULL DEFAULT 0,
                fee_usdt REAL NOT NULL DEFAULT 0,
                trades INTEGER NOT NULL DEFAULT 0,
                status TEXT NOT NULL DEFAULT 'PENDING',
                created_at REAL NOT NULL,
                due_ts REAL NOT NULL,
                paid_at REAL,
                msg_ids TEXT NOT NULL DEFAULT '',
                UNIQUE(chat_id, day)
            )''')
            for _c, _ddl in (('period', "TEXT NOT NULL DEFAULT 'daily'"), ('end_day', 'TEXT')):      # V3.44.68: بازه‌ی هفتگی/ماهانه
                try:
                    conn.execute(f'ALTER TABLE fee_invoices ADD COLUMN {_c} {_ddl}')
                except Exception:
                    pass
            # V3.42.14: لیست دسترسی پویا (مدیریت از پنل ادمین)
            conn.execute('''CREATE TABLE IF NOT EXISTS allowed_users(
                chat_id INTEGER PRIMARY KEY,
                note TEXT,
                added_by INTEGER,
                added_at INTEGER NOT NULL
            )''')
            # V3.44.103: ادمین‌های افزوده‌شده از پنل ادمین (کنار ADMIN_CHAT_IDS در env)
            conn.execute('''CREATE TABLE IF NOT EXISTS extra_admins(
                chat_id INTEGER PRIMARY KEY,
                note TEXT,
                added_by INTEGER,
                added_at INTEGER NOT NULL
            )''')
            conn.execute('''CREATE TABLE IF NOT EXISTS users(
                chat_id INTEGER PRIMARY KEY,
                telegram_user_id INTEGER,
                username TEXT,
                first_name TEXT,
                last_name TEXT,
                first_seen INTEGER NOT NULL,
                last_seen INTEGER NOT NULL,
                is_active INTEGER NOT NULL DEFAULT 1
            )''')
            conn.commit()
        finally:
            conn.close()
    restore_db_from_latest_backup_if_empty()
    CREDENTIALS.init_table()          # V3.44.57: کلیدهای API رمزشده‌ی کاربران
    logger.info('مسیر دیتابیس: %s', DB_PATH)
    if not db_existed_before:
        logger.warning('فایل دیتابیس (%s) از صفر ساخته شد.', DB_PATH)


