import threading as _threading
_CB_CTX = _threading.local()
_LAST_SENT = _threading.local()       # V3.44.52: message_id آخرین پیامی که send_message در همین thread «ارسال» کرد (نه ویرایش)
_LAST_PHOTO = _threading.local()      # V3.42.11: message_id آخرین عکسی که send_photo در همین thread فرستاد

# V3.42.8: «همه‌ی» دکمه‌های اینلاین به‌صورت پیش‌فرض همان پیامِ منو را ویرایش می‌کنند (نه پیام جدید).
# فقط دکمه‌هایی که روی «کارت سیگنال/پیام کانال» کار می‌کنند یا خروجی مستقل (نمودار/فایل) دارند،
# عمداً مسیر قبلی خودشان را نگه می‌دارند.
_NEW_MESSAGE_PREFIXES = (
    '/tw_qe_', '/tw_open_', '/fq_qe_', '/assist_ok_', '/assist_no_', '/assist_rev_', '/assist_man_', '/assist_open_', '/assist_save_',
    '/assist_saved_', '/assist_cd_', '/assist_ind_', '/autotg_', '/tgref_', '/keep_channel_msg_', '/del_channel_msg_', '/qt_', '/show_chart_',
    '/lv_', '/lvc_', '/an_', '/check_entry_', '/cancel_watch_', '/chind_', '/chlist', '/chlist_buy', '/chlist_sell', '/chreg', '/rvshow_', '/noop', '/dummy',
)


def _inplace_menu_command(cmd):
    c = str(cmd or '')
    if not c.startswith('/'):
        return False
    return not any(c.startswith(pfx) for pfx in _NEW_MESSAGE_PREFIXES)


# دکمه‌ی «بازگشت» برای پیام‌هایی که کیبورد اینلاین ندارند (پرامپت‌ها/نتیجه‌ها): به منوی والدِ همان دکمه.
_BACK_PARENT = {
    '/add_long_symbol': '/manage_watchlist', '/remove_long_symbol': '/manage_watchlist',
    '/add_short_symbol': '/manage_watchlist', '/remove_short_symbol': '/manage_watchlist',
    '/backtest_start': '/manage_watchlist', '/scan_signal_start': '/manage_watchlist',
    '/levels_start': '/menu_reports',
    '/pending_order_start': '/menu_trading', '/market_report': '/menu_reports',
    '/export_trade_data': '/performance', '/export_trade_pipeline': '/trade_tracking_menu',
    '/admin_set_fee_prompt': '/admin_fee_report', '/admin_fee_account_prompt': '/admin_fee_menu', '/admin_access_add_prompt': '/admin_access', '/admin_access_admin_add_prompt': '/admin_access', '/pending_side_buy': '/menu_trading',
    '/pending_side_sell': '/menu_trading', '/confirm_pending_order': '/menu_trading',
    '/cancel_pending_all': '/menu_trading', '/close_longs_prompt': '/open_positions',
    '/close_shorts_prompt': '/open_positions', '/confirm_close_longs': '/open_positions',
    '/confirm_close_shorts': '/open_positions', '/confirm_emergency_close_all': '/menu',
    '/assist_expiry_cycle': '/assist_menu', '/assist_stats': '/assist_menu',
}


def _back_markup(ctx):
    parent = _BACK_PARENT.get((ctx or {}).get('cmd', ''), '/menu')
    # /back: اول وضعیتِ «منتظر ورودی» را پاک می‌کند، بعد منوی والد را باز می‌کند (همان پیام).
    return {'inline_keyboard': [[{'text': '🔙 بازگشت', 'callback_data': '/back:' + parent}]]}


def begin_callback_context(chat_id, message_id, cmd):
    """قبل از process_command برای کلیک روی دکمه‌ی اینلاین صدا زده می‌شود."""
    if message_id and _inplace_menu_command(cmd):
        _CB_CTX.data = {'chat_id': chat_id, 'message_id': message_id, 'used': False, 'cmd': str(cmd or '')}
    else:
        _CB_CTX.data = None


def end_callback_context():
    _CB_CTX.data = None


# ===================== V3.44.38: تایید «بله / خیر» برای دکمه‌های ورود / رد / بستن دستی =====================
# هر دکمه‌ای که با یک لمس ورود، رد یا بستن انجام می‌دهد اول یک سؤال «مطمئنی؟ ✅ بله / ❌ خیر» نشان می‌دهد.
# روی کارتِ داخل چت خصوصی: فقط دکمه‌های همان پیام درجا عوض می‌شود (متن کارت دست نمی‌خورد؛ «خیر» دکمه‌های اصلی را برمی‌گرداند).
# زیر پست کانال (که دکمه‌هایش برای همه مشترک است) یا وقتی کیبوردِ اصلیِ پیام در دسترس نیست: یک پیام جدا در چت خصوصی می‌آید.
# «بله» همان دستور اصلی را عیناً اجرا می‌کند. اگر پیام تایید نشان داده نشود، دستور اجرا نمی‌شود (امن‌تر از اجرای ناخواسته).
# مرحله‌های دوم که خودشان تاییدِ آگاهانه‌اند (تضاد با روند، دور شدن قیمت، تایید بستن، ورود دستی با قیمت) دوباره سؤال نمی‌شوند.
_CONFIRM_TTL_SECONDS = 15 * 60
_CONFIRM_PENDING = {}
_CONFIRM_LOCK = RLock()
_CONFIRM_RULES = (
    ('/assist_ok_', 'entry'), ('/assist_no_', 'reject'), ('/assist_rev_', 'reverse'),
    ('/autotg_ok_', 'entry'), ('/autotg_no_', 'reject'),
    ('/fq_qe_', 'quick'), ('/tw_qe_', 'quick'), ('/qt_buy_', 'qt'), ('/qt_sell_', 'qt'),
    ('/fq_rej_', 'reject'), ('/pclose_', 'pclose'),
    ('/cancel_pending_', 'cancel_order'), ('/cancel_watch_', 'cancel_watch'),
)
_CONFIRM_SKIP_EXACT = ('/cancel_pending_all', '/cancel_pending_all_prompt')


def _confirm_needed(data):
    c = str(data or '')
    if c in _CONFIRM_SKIP_EXACT:
        return None
    for pfx, kind in _CONFIRM_RULES:
        if c.startswith(pfx):
            return kind
    return None


def _confirm_label(chat_id, data):
    return ' '.join(_confirm_label_raw(chat_id, data).split())


def _confirm_label_raw(chat_id, data):
    """متن کوتاه «چه کاری» برای سؤال تایید؛ هر خطایی فقط به برچسب کلی برمی‌گردد."""
    c = str(data or '')
    side_fa = {'buy': 'خرید', 'sell': 'فروش', 'BUY': 'خرید', 'SELL': 'فروش'}
    try:
        s = get_session(chat_id)
        m = re.match(r'^/assist_(ok|no|rev)_(.+)$', c)
        if m:
            rec = _assist_find(s, m.group(2)) or {}
            sym, sg = rec.get('symbol', ''), rec.get('sig')
            if m.group(1) == 'rev':
                sg = {'BUY': 'SELL', 'SELL': 'BUY'}.get(sg, sg)
            return {'ok': 'ورود', 'rev': 'ورود معکوس', 'no': 'رد سیگنال'}[m.group(1)] + (f" {side_fa.get(sg, '')}" if m.group(1) != 'no' else '') + f' {sym}'.rstrip()
        m = re.match(r'^/autotg_(ok|no)_(.+)$', c)
        if m:
            rec = (s.get('auto_trend_pending') or {}).get(m.group(2)) or {}
            return ('ورود ' + side_fa.get(rec.get('sig'), '') if m.group(1) == 'ok' else 'رد سیگنال') + f" {rec.get('symbol', '')}".rstrip()
        m = re.match(r'^/fq_qe_(buy|sell)_(.+)$', c)
        if m:
            rec = (s.get('fav_wait') or {}).get(m.group(2)) or {}
            return f"ورود سریع {side_fa[m.group(1)]} {rec.get('symbol', '')}".rstrip()
        m = re.match(r'^/tw_qe_(buy|sell)_(.+)$', c)
        if m:
            rec = (s.get('touch_wait') or {}).get(m.group(2)) or {}
            return f"ورود سریع {side_fa[m.group(1)]} {rec.get('symbol', '')}".rstrip()
        m = re.match(r'^/qt_(buy|sell)_(.+)$', c)
        if m:
            return f"ورود سریع {side_fa[m.group(1)]} {m.group(2).upper()}"
        m = re.match(r'^/fq_rej_(.+)$', c)
        if m:
            rec = (s.get('fav_wait') or {}).get(m.group(1)) or {}
            return f"رد سیگنال {rec.get('symbol', '')}".rstrip()
        m = re.match(r'^/pclose_(\d+)_(.+)$', c)
        if m:
            return f"بستن {m.group(1)}٪ از معامله‌ی {m.group(2).upper()}"
        if c.startswith('/cancel_pending_'):
            return 'لغو این اوردر معلق'
        m = re.match(r'^/cancel_watch_(.+)$', c)
        if m:
            return f"حذف {m.group(1).upper()} از صف بررسی"
    except Exception:
        logger.exception('confirm label failed cmd=%s', c)
    return 'این کار'


def _confirm_prompt(chat_id, data, msg, orig_mid, in_channel):
    """سؤال بله/خیر را نشان می‌دهد. True = نشان داده شد (دستور اصلی هنوز اجرا نشده)."""
    label = _confirm_label(chat_id, data)
    tok = hashlib.sha1(f"{chat_id}{data}{time.time()}".encode()).hexdigest()[:8]
    kb = {'inline_keyboard': [[{'text': f"⚠️ مطمئنی؟ {label}", 'callback_data': '/noop'}],
                              [{'text': '✅ بله', 'callback_data': f'/cfm_{tok}'}, {'text': '❌ خیر', 'callback_data': f'/cfmno_{tok}'}]]}
    markup = (msg or {}).get('reply_markup')
    inplace = bool(isinstance(markup, dict) and markup.get('inline_keyboard') and orig_mid and not in_channel)
    ok = False
    if inplace:
        res = tg('editMessageReplyMarkup', {'chat_id': chat_id, 'message_id': orig_mid, 'reply_markup': kb}, 10)
        ok = bool(res and res.get('ok'))
    if not ok:
        inplace = False
        res = tg('sendMessage', {'chat_id': chat_id, 'text': f"⚠️ مطمئنی؟\n{label}", 'reply_markup': kb}, 10)
        ok = bool(res and res.get('ok'))
    if ok:
        with _CONFIRM_LOCK:
            _CONFIRM_PENDING[tok] = {'chat': chat_id, 'data': str(data), 'orig_mid': orig_mid, 'inplace': inplace,
                                     'markup': markup if inplace else None, 'ts': time.time()}
    return ok


def _confirm_handle(chat_id, data, now_mid):
    """دکمه‌ی «✅ بله» (/cfm_<tok>) یا «❌ خیر» (/cfmno_<tok>)."""
    yes = str(data).startswith('/cfm_')
    tok = str(data).split('_', 1)[1] if '_' in str(data) else ''
    now = time.time()
    with _CONFIRM_LOCK:
        for k in [k for k, v in _CONFIRM_PENDING.items() if now - v['ts'] > _CONFIRM_TTL_SECONDS]:
            _CONFIRM_PENDING.pop(k, None)
        ent = _CONFIRM_PENDING.pop(tok, None)
    if not ent or ent['chat'] != chat_id:
        if now_mid:
            tg('editMessageReplyMarkup', {'chat_id': chat_id, 'message_id': now_mid, 'reply_markup': {'inline_keyboard': []}}, 10)
        send_message(chat_id, 'ℹ️ این تایید منقضی شده و کاری انجام نشد؛ اگر لازم است دوباره از خودِ کارت یا دکمه اقدام کن.')
        return
    if ent['inplace'] and ent.get('markup'):
        tg('editMessageReplyMarkup', {'chat_id': chat_id, 'message_id': now_mid or ent['orig_mid'], 'reply_markup': ent['markup']}, 10)
    elif now_mid:
        tg('deleteMessage', {'chat_id': chat_id, 'message_id': now_mid}, 10)
    if not yes:
        return
    begin_callback_context(chat_id, ent['orig_mid'], ent['data'])
    try:
        process_command(ent['data'], chat_id, ent['orig_mid'])
    finally:
        end_callback_context()




# --- V3.38.3: کیبورد ثابت پایین چت ---
# تلگرام کیبورد ثابت (Reply Keyboard) را به «آخرین پیامی که آن را ست کرده» گره می‌زند؛ اگر آن پیام
# حذف شود (مثلاً با حذف خودکار پیام‌ها) کیبورد هم از چت ناپدید می‌شود. پس آخرین پیامِ حامل کیبورد
# را از حذف خودکار مستثنا می‌کنیم و پیامِ قبلی را (که دیگر حامل نیست) امن حذف می‌کنیم.
_KB_ANCHOR = {}
_KB_ANCHOR_LOCK = RLock()


def _register_kb_anchor(chat_id, message_id, markup):
    """True برمی‌گرداند اگر این پیام حامل کیبورد ثابت است (و نباید خودکار حذف شود)."""
    if not (isinstance(markup, dict) and 'keyboard' in markup and message_id):
        return False
    with _KB_ANCHOR_LOCK:
        old = _KB_ANCHOR.get(chat_id)
        _KB_ANCHOR[chat_id] = message_id
    _kb_anchor_save()
    if old and old != message_id:
        schedule_auto_delete(chat_id, old)
    return True


def send_message(chat_id, text, markup=None, message_id=None, parse_mode='Markdown', keep=False):
    """keep=True: این پیام (مثلاً سیگنال) هرگز خودکار حذف نمی‌شود."""
    if not is_allowed(chat_id): return False
    if isinstance(text, str) and len(text) > 4000:
        # V3.43.24: شبکه‌ی ایمنی: پیامِ بیشتر از ۴۰۹۶ کاراکتر در تلگرام کلاً رد می‌شود؛ روی مرز یک پاراگراف می‌بُریم
        text = text[:3980].rsplit('\n\n', 1)[0] + '\n\n…'
    s = get_session(chat_id)
    _ctx = getattr(_CB_CTX, 'data', None)
    _can_inplace = bool(not keep and _ctx and not _ctx['used'] and _ctx['chat_id'] == chat_id)
    if markup is None and not keep and (message_id or _can_inplace):
        # V3.42.8: پیام بدون کیبورد اینلاین (پرامپت/نتیجه) هم باید روی همان پیام ویرایش شود، پس دکمه‌ی بازگشت می‌گیرد
        # (کیبورد ثابت پایین چت را نمی‌شود با ویرایش ست کرد).
        markup = _back_markup(_ctx)
    if markup is None: markup = get_bottom_menu_keyboard(s['is_bot_active'], s.get('bottom_menu_open', True))
    # ویرایش درجا: اولین پاسخِ دارای کیبورد اینلاین به کلیک یک دکمه، همان پیام را عوض می‌کند.
    if (not message_id and not keep and _ctx and not _ctx['used'] and _ctx['chat_id'] == chat_id
            and isinstance(markup, dict) and 'inline_keyboard' in markup):
        _ctx['used'] = True
        message_id = _ctx['message_id']
    if message_id:
        body = {'chat_id':chat_id,'message_id':message_id,'text':text,'reply_markup':markup}
        if parse_mode: body['parse_mode'] = parse_mode
        res = tg('editMessageText', body, 10)
        if res and res.get('ok'): return True
        desc = ((res or {}).get('description') or '').lower()
        if 'message is not modified' in desc:
            return True
    body = {'chat_id':chat_id,'text':text,'reply_markup':markup}
    if parse_mode: body['parse_mode'] = parse_mode
    res = tg('sendMessage', body, 10)
    ok = bool(res and res.get('ok'))
    if not ok and parse_mode:
        # V3.44.64: Markdown خراب (مثلاً «_» یا «*» بدون جفت) = تلگرام کل پیام را رد می‌کند و کاربر هیچ چیز نمی‌بیند.
        # فقط برای خطای parse (HTTP 400)، همان متن یک‌بار بدون Markdown فرستاده می‌شود.
        _err = getattr(_TG_ERR, 'last', None)
        if _err and _err[0] == 400 and 'parse' in str(_err[1]).lower():
            logger.warning('send_message: markdown parse failed chat=%s; resending as plain text', chat_id)
            body = {'chat_id': chat_id, 'text': str(text).replace('*', '').replace('`', ''), 'reply_markup': markup}
            res = tg('sendMessage', body, 10)
            ok = bool(res and res.get('ok'))
    if ok:
        _mid = (res.get('result') or {}).get('message_id')
        _LAST_SENT.mid = _mid
        _is_anchor = _register_kb_anchor(chat_id, _mid, markup)
        if not keep and not _is_anchor:
            schedule_auto_delete(chat_id, _mid)
    return ok


def edit_page(chat_id, text, markup=None, message_id=None, parse_mode='Markdown'):
    return send_message(chat_id, text, markup, message_id=message_id, parse_mode=parse_mode)


def sync_bottom_keyboard(chat_id, status_message=None):
    s = get_session(chat_id)
    active = bool(s.get('is_bot_active'))
    text = status_message or (
        "🟢 اسکن فعال است.\n🔒 تنظیمات حساس تا توقف اسکن قفل هستند."
        if active else
        "🔴 اسکن متوقف است.\n⚙️ تنظیمات آماده تغییر هستند."
    )
    return send_message(chat_id, text, get_bottom_menu_keyboard(active), parse_mode=None)


def send_photo(chat_id, img, caption='', markup=None, keep=False):
    _LAST_PHOTO.mid = None
    if not is_allowed(chat_id) or not TELEGRAM_TOKEN: return False
    s = get_session(chat_id)
    if markup is None:
        markup = get_bottom_menu_keyboard(s['is_bot_active'], s.get('bottom_menu_open', True))
    if is_restricted_user(chat_id): markup = _ap.filter_markup(markup, paper=_paper_account(chat_id))      # V3.44.59
    try:
        r = requests.post(f'https://api.telegram.org/bot{TELEGRAM_TOKEN}/sendPhoto', data={'chat_id':chat_id,'caption':caption,'parse_mode':'Markdown','reply_markup':json.dumps(markup, ensure_ascii=False)}, files={'photo':('chart.png',img,'image/png')}, timeout=20)
        if r.status_code == 200:
            try:
                _mid = ((r.json() or {}).get('result') or {}).get('message_id')
                _LAST_PHOTO.mid = _mid
                _day_log_record(chat_id, _mid)
                if not _register_kb_anchor(chat_id, _mid, markup) and not keep: schedule_auto_delete(chat_id, _mid)
            except Exception: pass
        return r.status_code == 200
    except Exception as exc: logger.warning('sendPhoto failed: %s', exc); return False


def fmt(v):
    try:
        x=float(v)
        if abs(x)<.0001: return f'{x:.8f}'
        if abs(x)<1: return f'{x:.6f}'
        return f'{x:.4f}'
    except Exception as exc:
        logger.debug('fmt fallback value=%r: %s', v, exc)
        return str(v)


def market_name(symbol): return f"{symbol.upper().replace('USDT','').replace('/','')}USDT"
def ccxt_symbol(symbol): return f"{symbol.upper().replace('USDT','').replace('/','')}/USDT:USDT"
def normalize_klines(data):
    if not data: return pd.DataFrame()
    rows=[]
    for x in data:
        if isinstance(x,dict): rows.append({'timestamp':x.get('created_at') or x.get('timestamp'),'open':x.get('open'),'close':x.get('close'),'high':x.get('high'),'low':x.get('low'),'volume':x.get('volume')})
        elif isinstance(x,(list,tuple)) and len(x)>=6: rows.append({'timestamp':x[0],'open':x[1],'close':x[2],'high':x[3],'low':x[4],'volume':x[5]})
    df=pd.DataFrame(rows)
    if df.empty: return df
    for c in ['open','close','high','low','volume','timestamp']: df[c]=pd.to_numeric(df[c], errors='coerce')
    return df.dropna(subset=['open','high','low','close']).sort_values('timestamp').reset_index(drop=True)


def _base_asset(symbol):
    return str(symbol).upper().replace('USDT', '').replace('/', '')


# --- منابع داده‌ی بازار: عمومی و بدون API key ---------------------------------
# V3.44.56 ترتیب پیش‌فرض: Bitunix Futures (اول) -> Binance Spot -> آینه‌ی data-api.binance.vision (کمکی).
# با MARKET_DATA_SOURCES (مثلاً "binance,bitunix") می‌شود ترتیب/لیست را عوض کرد.
_SOURCE_DOWN_UNTIL = {}
_SOURCE_FAILS = {}
_SYMBOL_MISS_UNTIL = {}
_DATA_SOURCE_USED = {}      # base -> منبعی که آخرین کندل موفق از آن آمد (برای لینک TradingView)
_DATA_NOTES = {}            # base -> آخرین دلایل شکست به تفکیک منبع (در گزارش «داده بازار خالی» می‌آید)
_BINANCE_SYMBOLS = {'map': {}, 'ts': 0.0, 'next_try': 0.0}
_BINANCE_REFRESH_LOCK = RLock()
_BINANCE_SOURCES = ('binance', 'binancevision')

# ===================== V3.44.98: صرافیِ داده = صرافیِ حالت =====================
# V3.44.108: هم PAPER و هم REAL: همه‌ی داده (کندل، قیمت، سطوح تاریخی سقف/کف، PDH/PDL)، معامله و چارت TradingView از صرافیِ انتخابیِ کاربر
# (PAPER: paper_exchange که اولِ ویزارد انتخاب می‌شود؛ REAL: real_exchange)؛ هیچ fallback‌ی بین دو صرافی نیست.
VENUE_SOURCES = {'binance': ('binance', 'binancevision'), 'bitunix': ('bitunix',)}
_DATA_VENUE_CTX = contextvars.ContextVar('data_venue', default='binance')


def _venue():
    v = _DATA_VENUE_CTX.get()
    return v if v in VENUE_SOURCES else 'binance'


def _sources_now():
    return VENUE_SOURCES[_venue()]


def _tfk(tf):
    """کلید کشِ رژیم تایم‌فریم: برای Binance همان tf (سازگار با قبل)، برای Bitunix جدا؛ تا داده‌ی دو صرافی قاطی نشود."""
    v = _venue()
    return tf if v == 'binance' else f'{tf}@{v}'


def _session_venue(s):
    """از روی خودِ session: REAL → real_exchange کاربر؛ PAPER → paper_exchange کاربر (V3.44.108؛ پیش‌فرض binance)."""
    try:
        if isinstance(s, dict):
            key = 'real_exchange' if s.get('trading_mode') == 'REAL' else 'paper_exchange'
            v = s.get(key)
            return v if v in VENUE_SOURCES else 'binance'
    except Exception:
        pass
    return 'binance'


def data_venue_for(chat_id):
    """صرافیِ انتخابیِ کاربر ('binance' | 'bitunix')؛ در PAPER از paper_exchange و در REAL از real_exchange."""
    try:
        return _session_venue(USER_SESSIONS.get(chat_id))
    except Exception:
        return 'binance'


def _with_data_venue(fn, kind, idx):
    """دکوراتور: صرافیِ داده را برای مدت اجرای تابع (و هر چه از آن صدا زده شود) تنظیم می‌کند.
    kind: 'chat' (آرگومان chat_id) | 'sess' (آرگومان session کاربر) | 'rec' (دیکشنریِ رکورد که 'chat_id' دارد)."""
    def _venue_of(args, kwargs, pname):
        v = kwargs.get(pname) if pname in kwargs else (args[idx] if idx is not None and len(args) > idx else None)
        if v is None: return None
        if kind == 'chat': return data_venue_for(v)
        if kind == 'sess': return _session_venue(v) if isinstance(v, dict) and 'trading_mode' in v else None
        if isinstance(v, dict) and v.get('chat_id') is not None: return data_venue_for(v.get('chat_id'))
        return None
    pname = {'chat': 'chat_id', 'sess': 's'}.get(kind, None) or fn.__code__.co_varnames[idx]
    if inspect.iscoroutinefunction(fn):
        @functools.wraps(fn)
        async def aw(*args, **kwargs):
            ven = _venue_of(args, kwargs, pname)
            if ven is None: return await fn(*args, **kwargs)
            tok = _DATA_VENUE_CTX.set(ven)
            try: return await fn(*args, **kwargs)
            finally: _DATA_VENUE_CTX.reset(tok)
        return aw
    @functools.wraps(fn)
    def w(*args, **kwargs):
        ven = _venue_of(args, kwargs, pname)
        if ven is None: return fn(*args, **kwargs)
        tok = _DATA_VENUE_CTX.set(ven)
        try: return fn(*args, **kwargs)
        finally: _DATA_VENUE_CTX.reset(tok)
    return w


def _install_data_venue_wrappers():
    """V3.44.98: هر تابعِ سطح-ماژول که chat_id / session (s) / رکورد (r, rec) می‌گیرد با صرافیِ داده‌ی همان کاربر اجرا می‌شود؛
    پس همه‌ی get_klines / latest_price / سطوح تاریخی / لینک TradingView داخل آن خودکار از صرافیِ درست می‌آیند."""
    g = globals(); n = 0
    for name, fn in list(g.items()):
        if name.startswith('__') or not inspect.isfunction(fn) or fn.__module__ != __name__: continue
        if getattr(fn, '_venue_wrapped', False) or name in ('_with_data_venue', '_install_data_venue_wrappers', 'data_venue_for', '_session_venue', '_venue', '_sources_now'):
            continue
        if inspect.isgeneratorfunction(fn) or inspect.isasyncgenfunction(fn): continue
        params = list(fn.__code__.co_varnames[:fn.__code__.co_argcount])
        kind = idx = None
        for k, pn in (('chat', 'chat_id'), ('sess', 's'), ('rec', 'rec'), ('rec', 'r')):
            if pn in params: kind, idx = k, params.index(pn); break
        if kind is None: continue
        w = _with_data_venue(fn, kind, idx); w._venue_wrapped = True
        g[name] = w; n += 1
    return n


def _binance_base_url(source):
    return BINANCE_VISION if source == 'binancevision' else BINANCE_SPOT


def _source_available(source):
    return time.time() >= _SOURCE_DOWN_UNTIL.get(source, 0.0)


def _source_trip(source, seconds=None):
    seconds = SOURCE_COOLDOWN_SECONDS if seconds is None else seconds
    _SOURCE_DOWN_UNTIL[source] = time.time() + seconds
    _SOURCE_FAILS[source] = 0
    logger.warning('market data source %s temporarily disabled for %ss', source, seconds)


def _source_fail(source):
    """شکست‌های شبکه‌ای پیاپی؛ بعد از ۳ بار پشت‌سرهم منبع موقتاً کنار گذاشته می‌شود."""
    _SOURCE_FAILS[source] = _SOURCE_FAILS.get(source, 0) + 1
    if _SOURCE_FAILS[source] >= 3:
        _source_trip(source)


def _source_ok(source):
    _SOURCE_FAILS[source] = 0


def _status_trips_source(status):
    # 403/451: بلاک جغرافیایی، 418/429: rate limit، 5xx: خرابی سرور
    return status in (403, 418, 429, 451) or status >= 500


def _symbol_missing(source, base):
    return time.time() < _SYMBOL_MISS_UNTIL.get((source, base), 0.0)


def _mark_symbol_missing(source, base):
    _SYMBOL_MISS_UNTIL[(source, base)] = time.time() + SYMBOL_MISS_TTL_SECONDS


def data_failure_notes(symbol):
    """دلیل شکست دریافت داده‌ی آخرین تلاش برای این نماد، مثلاً: bitunix:not_listed | binance:http_451"""
    notes = _DATA_NOTES.get(_base_asset(symbol))
    return ' | '.join(notes) if notes else ''


def _parse_binance_exchange_info(payload):
    """نقشه‌ی {نام پایه -> نماد اسپات باینانس} فقط برای جفت‌های USDT با وضعیت TRADING."""
    m = {}
    for s in (payload or {}).get('symbols') or []:
        if s.get('quoteAsset') != 'USDT' or s.get('status') != 'TRADING' or s.get('isSpotTradingAllowed') is False:
            continue
        base = str(s.get('baseAsset', '')).upper(); sym = s.get('symbol')
        if base and sym:
            m[base] = sym
    return m


def _binance_map_needs_refresh():
    now = time.time()
    m = _BINANCE_SYMBOLS
    return now >= m['next_try'] and (not m['map'] or now - m['ts'] >= BINANCE_SYMBOLS_TTL)


def _binance_refresh_symbol_map():
    with _BINANCE_REFRESH_LOCK:
        if not _binance_map_needs_refresh():
            return
        for source in _BINANCE_SOURCES:
            if source not in MARKET_DATA_SOURCES or not _source_available(source):
                continue
            try:
                r = requests.get(f'{_binance_base_url(source)}/api/v3/exchangeInfo', params={'symbolStatus': 'TRADING'}, timeout=12)
                if _status_trips_source(r.status_code):
                    _source_trip(source); continue
                if r.ok:
                    parsed = _parse_binance_exchange_info(r.json())
                    if parsed:
                        _BINANCE_SYMBOLS.update(map=parsed, ts=time.time(), next_try=0.0)
                        _source_ok(source)
                        return
            except Exception as exc:
                logger.debug('%s exchangeInfo: %s', source, exc)
                _source_fail(source)
        _BINANCE_SYMBOLS['next_try'] = time.time() + 60


def _binance_symbol_from_cache(base):
    m = _BINANCE_SYMBOLS['map']
    if m:
        return m.get(base)          # None = روی اسپات باینانس لیست نیست
    return f'{base}USDT'            # exchangeInfo در دسترس نبود: حدس ساده


def _ohlcv_df(rows):
    """ردیف‌های [time_ms, open, high, low, close, volume] (هر ترتیبی) -> DataFrame مرتب‌شده‌ی صعودی."""
    if not rows: return pd.DataFrame()
    df = pd.DataFrame(rows, columns=['timestamp', 'open', 'high', 'low', 'close', 'volume'])
    for c in ['timestamp', 'open', 'high', 'low', 'close', 'volume']: df[c] = pd.to_numeric(df[c], errors='coerce')
    return df.dropna(subset=['open', 'high', 'low', 'close']).sort_values('timestamp').reset_index(drop=True)


def _binance_kline_df(payload):
    if not isinstance(payload, list) or not payload: return pd.DataFrame()
    return _ohlcv_df([row[:6] for row in payload if isinstance(row, (list, tuple)) and len(row) >= 6])


# ===================== Bitunix Futures: داده‌ی عمومی (V3.44.56) =====================
# فقط کندل‌های «بسته» را می‌دهد (کندل در حال تشکیل نمی‌آید)؛ ربات یک ردیف «در حال تشکیل» با قیمت لحظه‌ای اضافه می‌کند
# تا همه‌جا iloc[-2] همان آخرین کندل بسته بماند. سقف رسمی: ۱۰ درخواست در ثانیه برای هر IP و حداکثر ۲۰۰ کندل در هر درخواست.
_BITUNIX_SYMBOLS = {'map': {}, 'info': {}, 'ts': 0.0, 'next_try': 0.0}
_BITUNIX_TICKERS = {'ts': 0.0, 'map': {}}
_BITUNIX_LOCK = RLock()
_BITUNIX_RATE_LOCK = threading.Lock()
_BITUNIX_LAST_CALL = [0.0]
_BITUNIX_POOL = ThreadPoolExecutor(max_workers=4, thread_name_prefix='bitunix')   # استخر جدا: انتظارِ نرخ‌گیر استخر پیش‌فرض را نمی‌بندد


def _bitunix_throttle():
    with _BITUNIX_RATE_LOCK:
        wait = _BITUNIX_LAST_CALL[0] + BITUNIX_MIN_GAP - time.time()
        if wait > 0:
            time.sleep(wait)
        _BITUNIX_LAST_CALL[0] = time.time()


def _bitunix_get(path, params=None, timeout=7):
    _bitunix_throttle()
    return requests.get(f'{BITUNIX_PUBLIC}{path}', params=params, timeout=timeout)


def _parse_bitunix_pairs(payload):
    """({نام پایه -> نماد}, {نام پایه -> اطلاعات}) فقط برای جفت‌های USDT با وضعیت OPEN."""
    m, info = {}, {}
    if not isinstance(payload, dict) or payload.get('code') != 0:
        return m, info
    for sdef in payload.get('data') or []:
        if not isinstance(sdef, dict) or str(sdef.get('quote', '')).upper() != 'USDT':
            continue
        if str(sdef.get('symbolStatus', 'OPEN')).upper() != 'OPEN':
            continue
        base = str(sdef.get('base', '')).upper(); sym = sdef.get('symbol')
        if base and sym:
            m[base] = str(sym)
            info[base] = {'min_volume': sdef.get('minTradeVolume'), 'base_precision': sdef.get('basePrecision'),
                          'quote_precision': sdef.get('quotePrecision'), 'max_leverage': sdef.get('maxLeverage'),
                          'api_supported': sdef.get('isApiSupported')}
    return m, info


def _bitunix_map_needs_refresh():
    now = time.time(); m = _BITUNIX_SYMBOLS
    return now >= m['next_try'] and (not m['map'] or now - m['ts'] >= BITUNIX_SYMBOLS_TTL)


def _bitunix_refresh_symbol_map():
    with _BITUNIX_LOCK:
        if not _bitunix_map_needs_refresh():
            return
        try:
            r = _bitunix_get('/api/v1/futures/market/trading_pairs', timeout=12)
            if _status_trips_source(r.status_code):
                _source_trip('bitunix')
            elif r.ok:
                m, info = _parse_bitunix_pairs(r.json())
                if m:
                    _BITUNIX_SYMBOLS.update(map=m, info=info, ts=time.time(), next_try=0.0)
                    _source_ok('bitunix')
                    return
        except Exception as exc:
            logger.debug('bitunix trading_pairs: %s', exc)
            _source_fail('bitunix')
        _BITUNIX_SYMBOLS['next_try'] = time.time() + 60


_BITUNIX_PREFIX_SCALES = (1000, 10000, 100000, 1000000)


def _bitunix_resolve(base):
    """V3.44.112: (نمادِ فیوچرز بیتیونیکس, scale) برای نامِ «اسپات‌گونه»‌ی ربات.
    نمادهای ربات اسپات‌گونه‌اند (PEPE, SHIB, BONK, ...) ولی بیتیونیکس بعضی را با پیشوند ۱۰۰۰ (یا بیشتر) لیست می‌کند
    (1000PEPE, 1000SHIB, 1000BONK, ...) و قیمتشان ۱۰۰۰ برابرِ اسپات است. اول نام عیناً، بعد با پیشوندها جست‌وجو می‌شود.
    scale = ضریب پیشوند (۱ برای نمادهای عادی)؛ قیمتِ ربات = قیمت فیوچرز / scale ، حجم (کوین) = حجم فیوچرز × scale.
    (None, 1) = روی فیوچرز بیتیونیکس لیست نیست (یا OPEN نیست)؛ اگر لیست نمادها هنوز نیامده حدس ساده (BASEUSDT, 1)."""
    base = str(base).upper()
    m = _BITUNIX_SYMBOLS['map']
    if not m:
        return f'{base}USDT', 1
    if base in m:
        return m[base], 1
    for pref in _BITUNIX_PREFIX_SCALES:
        sym = m.get(f'{pref}{base}')
        if sym:
            return sym, pref
    return None, 1


def _bitunix_symbol_from_cache(base):
    return _bitunix_resolve(base)[0]


def _bitunix_scale(base):
    return _bitunix_resolve(base)[1]


def _bitunix_unscale_df(df, scale):
    """کندل‌های فیوچرزِ «واحد ۱۰۰۰تایی» را به واحد کوین (هم‌مقیاس با اسپات و سطوح ربات) برمی‌گرداند."""
    if df is None or getattr(df, 'empty', True) or not scale or scale == 1:
        return df
    df = df.copy()
    for c in ('open', 'high', 'low', 'close'):
        df[c] = df[c] / scale
    df['volume'] = df['volume'] * scale
    return df


def _parse_bitunix_tickers(payload):
    out = {}
    if not isinstance(payload, dict) or payload.get('code') != 0:
        return out
    for t in payload.get('data') or []:
        try:
            px = float(t.get('lastPrice') or t.get('last') or 0)
        except (AttributeError, TypeError, ValueError):
            continue
        if px > 0 and t.get('symbol'):
            out[str(t['symbol'])] = px
    return out


def _bitunix_prices():
    """{نماد -> آخرین قیمت} برای همه‌ی نمادها با یک درخواست (کش ۳ ثانیه‌ای)."""
    now = time.time()
    with _BITUNIX_LOCK:
        c = _BITUNIX_TICKERS
        if c['map'] and now - c['ts'] < BITUNIX_TICKERS_TTL:
            return c['map']
        try:
            r = _bitunix_get('/api/v1/futures/market/tickers')
            if _status_trips_source(r.status_code):
                _source_trip('bitunix')
            elif r.ok:
                m = _parse_bitunix_tickers(r.json())
                if m:
                    c.update(ts=now, map=m)
                    return m
        except Exception as exc:
            logger.debug('bitunix tickers: %s', exc)
            _source_fail('bitunix')
        return c['map'] if c['map'] and now - c['ts'] < 30 else {}


def _bitunix_price(base):
    sym, scale = _bitunix_resolve(base)
    if not sym:
        return None
    px = _bitunix_prices().get(sym)
    if px:
        return px / scale                    # V3.44.112: نمادهای ۱۰۰۰تایی => قیمتِ هم‌مقیاس با اسپات
    try:                                     # فهرست کلی خالی/ناقص بود: فقط همین نماد
        r = _bitunix_get('/api/v1/futures/market/tickers', {'symbols': sym}, timeout=5)
        if r.ok:
            v = _parse_bitunix_tickers(r.json()).get(sym)
            return (v / scale) if v else None
    except Exception as exc:
        logger.debug('bitunix ticker %s: %s', sym, exc)
    return None


def _bitunix_kline_df(payload):
    if not isinstance(payload, dict) or payload.get('code') != 0:
        return pd.DataFrame()
    rows = [[k.get('time'), k.get('open'), k.get('high'), k.get('low'), k.get('close'), k.get('baseVol')]
            for k in (payload.get('data') or []) if isinstance(k, dict)]
    return _ohlcv_df(rows)


def _bitunix_add_forming_candle(df, tf, price, now_ms=None):
    """بیتیونیکس فقط کندل‌های بسته را برمی‌گرداند؛ یک کندل «در حال تشکیل» (باز شدن = کلوز آخرین کندل بسته،
    بسته = قیمت لحظه‌ای) اضافه می‌شود تا ساختار با باینانس یکی باشد (آخرین ردیف = در حال تشکیل، iloc[-2] = آخرین بسته)."""
    secs = BITUNIX_TF_SECONDS.get(tf)
    if df is None or df.empty or not secs:
        return df
    now_ms = int(time.time() * 1000) if now_ms is None else now_ms
    last_t = int(df['timestamp'].iloc[-1])
    if last_t + secs * 1000 > now_ms + 2000:        # اگر API (برخلاف مستندات) کندل در حال تشکیل را هم داده، دوباره اضافه نمی‌شود
        return df
    o = float(df['close'].iloc[-1])
    p = float(price) if price and price > 0 else o
    row = {'timestamp': last_t + secs * 1000, 'open': o, 'high': max(o, p), 'low': min(o, p), 'close': p, 'volume': 0.0}
    return pd.concat([df, pd.DataFrame([row])], ignore_index=True)


def _bitunix_fetch_klines(symbol, tf, limit):
    """(df, http_status, payload) یا None اگر این نماد/تایم‌فریم روی بیتیونیکس نیست. حداکثر ۲۰۰ کندل در هر درخواست؛
    اگر بیشتر خواسته شود صفحه‌ی بعدی با endTime گرفته می‌شود (حداکثر ۵ صفحه)."""
    base = _base_asset(symbol)
    interval = BITUNIX_INTERVAL_MAP.get(tf); sym, scale = _bitunix_resolve(base)
    if not interval or not sym:
        return None
    need = max(int(limit), 60); frames = []; end = None; payload = None; status = 200
    for _ in range(5):
        if need <= 0:
            break
        n = min(need, 200)
        params = {'symbol': sym, 'interval': interval, 'limit': n}
        if end:
            params['endTime'] = end
        r = _bitunix_get('/api/v1/futures/market/kline', params)
        status = r.status_code
        if not r.ok:
            return pd.DataFrame(), status, None
        payload = r.json()
        df = _bitunix_kline_df(payload)
        if df.empty:
            break
        frames.append(df); need -= len(df)
        if len(df) < n:
            break
        end = int(df['timestamp'].iloc[0]) - 1
    if not frames:
        return pd.DataFrame(), status, payload
    df = pd.concat(frames[::-1]).drop_duplicates('timestamp').sort_values('timestamp').reset_index(drop=True)
    df = _bitunix_unscale_df(df, scale)          # V3.44.112: 1000PEPE => قیمت PEPE (÷۱۰۰۰)
    return _bitunix_add_forming_candle(df, tf, _bitunix_price(base)), status, payload


def _klines_usable(df, min_rows=60):
    """داده‌ی خراب/مرده را رد می‌کند تا به منبع بعدی برود: کم‌بودن کندل، high<low، یا ۳۰ کندل آخر بدون هیچ دامنه‌ای."""
    if df is None or len(df) < min_rows: return False
    tail = df.tail(30)
    if (tail['high'] < tail['low']).any(): return False
    if ((tail['high'] - tail['low']) <= 0).all(): return False
    return True


def _kline_request(source, symbol, tf, limit):
    """(url, params, parser) یا None اگر این منبع آن تایم‌فریم/نماد را ندارد."""
    base = _base_asset(symbol)
    if source in _BINANCE_SOURCES:
        interval = BINANCE_INTERVAL_MAP.get(tf); sym = _binance_symbol_from_cache(base)
        if not interval or not sym: return None
        return (f'{_binance_base_url(source)}/api/v3/klines',
                {'symbol': sym, 'interval': interval, 'limit': min(max(int(limit), 60), 1000)}, _binance_kline_df)
    return None            # بیتیونیکس مسیر جدا دارد (_bitunix_fetch_klines)


def _price_from_payload(source, payload):
    try:
        if source in _BINANCE_SOURCES:
            return float(payload['price']) if isinstance(payload, dict) and 'price' in payload else None
    except (KeyError, IndexError, TypeError, ValueError):
        return None
    return None


def _price_request(source, symbol):
    base = _base_asset(symbol)
    if source in _BINANCE_SOURCES:
        sym = _binance_symbol_from_cache(base)
        return (f'{_binance_base_url(source)}/api/v3/ticker/price', {'symbol': sym}) if sym else None
    return None            # بیتیونیکس مسیر جدا دارد (_bitunix_price)


def _fail_note(source, status, payload):
    """توضیح کوتاه و قابل‌خواندن برای گزارش (بدون متن بلند)."""
    if status != 200: return f'{source}:http_{status}'
    if isinstance(payload, dict):
        if 'retCode' in payload: return f"{source}:retCode={payload.get('retCode')}"
        if 'code' in payload: return f"{source}:code={payload.get('code')}"
    return f'{source}:empty_or_invalid'


def get_klines(symbol, tf='5min', limit=200):
    """کندل‌ها را از اولین منبع سالم می‌گیرد (Bitunix Futures -> Binance Spot -> Binance Vision).
    آخرین ردیف کندلِ در حال تشکیل است (استراتژی از iloc[-2] استفاده می‌کند)."""
    period = TIMEFRAME_MAP.get(tf, tf); key = f'{_venue()}:{symbol}:{period}:{limit}'; now = time.time()
    with DATA_LOCK:
        c = DATA_CACHE.get(key)
        if c and now - c['ts'] < DATA_CACHE_SECONDS: return c['df'].copy()
    base = _base_asset(symbol); notes = []
    for source in _sources_now():
        if not _source_available(source): notes.append(f'{source}:down'); continue
        if _symbol_missing(source, base): notes.append(f'{source}:skipped_missing'); continue
        if source in _BINANCE_SOURCES and _binance_map_needs_refresh(): _binance_refresh_symbol_map()
        payload = None
        if source == 'bitunix':
            if _bitunix_map_needs_refresh(): _bitunix_refresh_symbol_map()
            try:
                res = _bitunix_fetch_klines(symbol, tf, limit)
            except Exception as exc:
                logger.debug('bitunix kline %s: %s', symbol, exc); _source_fail(source); notes.append(f'{source}:network_error'); continue
            if res is None: notes.append(f'{source}:not_listed'); continue
            df, status, payload = res
            if _status_trips_source(status):
                _source_trip(source); notes.append(f'{source}:http_{status}'); continue
            _source_ok(source)
        else:
            req = _kline_request(source, symbol, tf, limit)
            if not req: notes.append(f'{source}:not_listed'); continue
            url, params, parse = req
            try:
                r = requests.get(url, params=params, timeout=7)
                status = r.status_code
                if _status_trips_source(status):
                    _source_trip(source); notes.append(f'{source}:http_{status}'); continue
                payload = r.json() if r.ok else None
                df = parse(payload) if r.ok else pd.DataFrame()
                _source_ok(source)
            except Exception as exc:
                logger.debug('%s kline %s: %s', source, symbol, exc); _source_fail(source); notes.append(f'{source}:network_error'); continue
        if _klines_usable(df):
            df = df.tail(max(int(limit), 60)).reset_index(drop=True)
            with DATA_LOCK: DATA_CACHE[key] = {'ts': now, 'df': df.copy()}
            _DATA_NOTES.pop(base, None); _DATA_SOURCE_USED[base] = source
            return df
        notes.append(_fail_note(source, status, payload) if len(df) < 60 or df.empty else f'{source}:bad_data')
        _mark_symbol_missing(source, base)
    _DATA_NOTES[base] = notes
    return pd.DataFrame()



def get_klines_for(chat_id, symbol, tf='5min', limit=200):
    """get_klines با صرافیِ حالتِ همان کاربر (برای حلقه‌های پس‌زمینه که روی همه‌ی کاربران می‌چرخند)."""
    tok = _DATA_VENUE_CTX.set(data_venue_for(chat_id))
    try:
        return get_klines(symbol, tf, limit)
    finally:
        _DATA_VENUE_CTX.reset(tok)


async def get_klines_async(http, symbol, tf='5min', limit=200):
    """نسخه‌ی async با همان ترتیب منابع get_klines."""
    period = TIMEFRAME_MAP.get(tf, tf); key = f'{_venue()}:{symbol}:{period}:{limit}'; now = time.time()
    with DATA_LOCK:
        c = DATA_CACHE.get(key)
        if c and now - c['ts'] < DATA_CACHE_SECONDS: return c['df'].copy()
    base = _base_asset(symbol); notes = []
    loop = asyncio.get_running_loop()
    _srcs = _sources_now()
    if any(s in _srcs and _source_available(s) for s in _BINANCE_SOURCES) and _binance_map_needs_refresh():
        try: await asyncio.to_thread(_binance_refresh_symbol_map)   # درخواست sync را از event loop دور نگه می‌دارد
        except Exception as exc: logger.debug('binance symbol map refresh: %s', exc)
    if 'bitunix' in _srcs and _source_available('bitunix') and _bitunix_map_needs_refresh():
        try: await loop.run_in_executor(_BITUNIX_POOL, _bitunix_refresh_symbol_map)
        except Exception as exc: logger.debug('bitunix symbol map refresh: %s', exc)
    await ASYNC_SEMAPHORE.acquire()
    try:
        for source in _srcs:
            if not _source_available(source): notes.append(f'{source}:down'); continue
            if _symbol_missing(source, base): notes.append(f'{source}:skipped_missing'); continue
            payload = None
            if source == 'bitunix':
                try:
                    res = await loop.run_in_executor(_BITUNIX_POOL, _bitunix_fetch_klines, symbol, tf, limit)
                except Exception as exc:
                    logger.debug('async bitunix kline %s: %s', symbol, exc); _source_fail(source); notes.append(f'{source}:network_error'); continue
                if res is None: notes.append(f'{source}:not_listed'); continue
                df, status, payload = res
                if _status_trips_source(status):
                    _source_trip(source); notes.append(f'{source}:http_{status}'); continue
                _source_ok(source)
            else:
                req = _kline_request(source, symbol, tf, limit)
                if not req: notes.append(f'{source}:not_listed'); continue
                url, params, parse = req
                try:
                    async with http.get(url, params=params, timeout=aiohttp.ClientTimeout(total=7)) as r:
                        status = r.status
                        if _status_trips_source(status):
                            _source_trip(source); notes.append(f'{source}:http_{status}'); continue
                        payload = await r.json(content_type=None) if status == 200 else None
                        df = parse(payload) if status == 200 else pd.DataFrame()
                    _source_ok(source)
                except Exception as exc:
                    logger.debug('async %s kline %s: %s', source, symbol, exc); _source_fail(source); notes.append(f'{source}:network_error'); continue
            if _klines_usable(df):
                df = df.tail(max(int(limit), 60)).reset_index(drop=True)
                with DATA_LOCK: DATA_CACHE[key] = {'ts': now, 'df': df.copy()}
                _DATA_NOTES.pop(base, None); _DATA_SOURCE_USED[base] = source
                return df
            notes.append(_fail_note(source, status, payload) if len(df) < 60 or df.empty else f'{source}:bad_data')
            _mark_symbol_missing(source, base)
    finally: ASYNC_SEMAPHORE.release()
    _DATA_NOTES[base] = notes
    return pd.DataFrame()
def latest_price(symbol):
    """قیمت لحظه‌ای برای PAPER (از همان زنجیره‌ی منابعِ کندل‌ها: Bitunix -> Binance)."""
    key = f'{_venue()}:{symbol.upper()}'; now = time.time()
    with DATA_LOCK:
        c = PRICE_CACHE.get(key)
        if c and now - c['ts'] < 5: return c['price']
    base = _base_asset(symbol)
    for source in _sources_now():
        if not _source_available(source) or _symbol_missing(source, base): continue
        if source in _BINANCE_SOURCES and _binance_map_needs_refresh(): _binance_refresh_symbol_map()
        if source == 'bitunix':
            if _bitunix_map_needs_refresh(): _bitunix_refresh_symbol_map()
            try:
                price = _bitunix_price(base)
            except Exception as exc:
                logger.debug('price bitunix %s: %s', symbol, exc); _source_fail(source); continue
            if price and price > 0:
                with DATA_LOCK: PRICE_CACHE[key] = {'ts': now, 'price': price}
                return price
            continue
        req = _price_request(source, symbol)
        if not req: continue
        url, params = req
        try:
            r = requests.get(url, params=params, timeout=5)
            if _status_trips_source(r.status_code):
                _source_trip(source); continue
            price = _price_from_payload(source, r.json()) if r.ok else None
            _source_ok(source)
        except Exception as exc:
            logger.debug('price %s %s: %s', source, symbol, exc); _source_fail(source); continue
        if price and price > 0:
            with DATA_LOCK: PRICE_CACHE[key] = {'ts': now, 'price': price}
            return price
        _mark_symbol_missing(source, base)
    return None


# ===================== Binance USDⓈ-M Futures (V3.44.0) =====================
# نمادهای ربات «اسپات‌گونه»‌اند (SHIB, PEPE, ...). روی فیوچرز باینانس بعضی نمادها با پیشوند ۱۰۰۰ (یا بیشتر)
# لیست می‌شوند (1000SHIB, 1000PEPE, 1000BONK, ...). قیمت و حجم آن‌ها در «واحد ۱۰۰۰تایی» است؛
# برای همین scale محاسبه می‌شود: قیمت ربات = قیمت فیوچرز / scale ، حجم ربات (کوین) = قرارداد × scale.
_BINANCE_SYMBOL_ALIASES = {'LUNA': 'LUNA2'}
_BINANCE_REVERSE_ALIASES = {v: k for k, v in _BINANCE_SYMBOL_ALIASES.items()}
_FUT_PREFIX_RE = re.compile(r'^(1000000|100000|10000|1000)([A-Z0-9]+)$')
_BINANCE_WORKING_TYPE = 'MARK_PRICE' if PROTECTION_TRIGGER.startswith('mark') else 'CONTRACT_PRICE'
_ALGO_SL = 'STOP_MARKET'
_ALGO_TP = 'TAKE_PROFIT_MARKET'


def _bot_base(symbol):
    return str(symbol).upper().replace('USDT','').replace('/','').replace(':','')


def futures_market(ex, symbol):
    """(market, scale) برای نماد ربات روی فیوچرز باینانس؛ (None, 1) اگر پیدا نشد."""
    base=_bot_base(symbol)
    markets=getattr(ex,'markets',None) or {}
    cands=[(base,1)]
    if base in _BINANCE_SYMBOL_ALIASES: cands.append((_BINANCE_SYMBOL_ALIASES[base],1))
    for pref in (1000,10000,100000,1000000): cands.append((f'{pref}{base}',pref))
    for cand,scale in cands:
        m=markets.get(f'{cand}/USDT:USDT')
        if m and m.get('active') is not False:
            return m,scale
    return None,1


def _fsym(ex, symbol):
    m,scale=futures_market(ex,symbol)
    if not m: raise ExchangeStateError(f"نماد {symbol} روی {'Bitunix Futures' if getattr(ex,'is_bitunix',False) else 'فیوچرز USDⓈ-M باینانس'} وجود ندارد")
    return m['symbol'],scale,m


def _split_futures_base(raw_base):
    """'1000SHIB' -> (1000,'SHIB') ; 'LUNA2' -> (1,'LUNA') ; 'BTC' -> (1,'BTC')"""
    raw_base=str(raw_base).upper()
    if raw_base in _BINANCE_REVERSE_ALIASES: return 1,_BINANCE_REVERSE_ALIASES[raw_base]
    m=_FUT_PREFIX_RE.match(raw_base)
    if m: return int(m.group(1)),m.group(2)
    return 1,raw_base


def _binance_call(ex, method, path, params=None):
    """فراخوانی مستقیم و امضاشده‌ی endpoint های /fapi/v1 (مستقل از نسخه‌ی ccxt)."""
    return ex.request(path,'fapiPrivate',method,params or {})


def _is_usd_like(cur):
    return cur is None or str(cur).upper() in ('USDT','USDC','BUSD','FDUSD','USD')


def exchange_latest_price(chat_id, symbol):
    """REAL price must come from the same Binance futures account/exchange used by the position."""
    key=f'{chat_id}:{symbol.upper()}'; now=time.time()
    with DATA_LOCK:
        c=REAL_PRICE_CACHE.get(key)
        if c and now-c['ts']<3: return c['price']
    ex=get_exchange(chat_id)
    if not ex: return None
    try:
        fsym,scale,_m=_fsym(ex,symbol)
        ticker=ex.fetch_ticker(fsym)
        price=float(ticker.get('last') or ticker.get('mark') or ticker.get('close') or 0)/scale
        if price>0:
            with DATA_LOCK: REAL_PRICE_CACHE[key]={'ts':now,'price':price}
            return price
    except Exception as exc:
        logger.debug('exchange price chat=%s symbol=%s: %s',chat_id,symbol,exc)
    return None


def exchange_balance(chat_id):
    ex=get_exchange(chat_id)
    if not ex: raise ExchangeStateError('exchange unavailable')
    try:
        b=ex.fetch_balance()
        total=(b.get('total') or {}).get('USDT')
        if total is None: raise ExchangeStateError('USDT balance missing')
        value=float(total)
        if not math.isfinite(value) or value < 0: raise ExchangeStateError('invalid USDT balance')
        return value
    except ExchangeStateError:
        raise
    except Exception as exc:
        logger.warning('balance %s: %s',chat_id,exc)
        raise ExchangeStateError(f'balance fetch failed: {exc}') from exc


def get_open_positions(chat_id):
    ex=get_exchange(chat_id)
    if not ex: raise ExchangeStateError('exchange unavailable')
    try:
        rows=ex.fetch_positions()
        return [p for p in rows if abs(float(p.get('contracts') or p.get('amount') or 0))>0]
    except Exception as exc:
        logger.warning('positions %s: %s',chat_id,exc)
        raise ExchangeStateError(f'position fetch failed: {exc}') from exc


def normalize_real_position(pos):
    sym=pos.get('symbol','')
    raw_base=sym.split('/')[0].upper() if '/' in sym else sym.replace(':USDT','').replace('USDT','').upper()
    scale,base=_split_futures_base(raw_base)
    side='BUY (Long)' if str(pos.get('side','')).lower()=='long' else 'SELL (Short)'
    entry=float(pos.get('entryPrice') or pos.get('average') or 0)/scale
    amount=abs(float(pos.get('contracts') or pos.get('amount') or 0))*scale
    return {'symbol':base,'side':side,'entry_price':entry,'amount':amount,'leverage':int(float(pos.get('leverage') or 1)),'unrealized_pnl':float(pos.get('unrealizedPnl') or 0),'position_id':pos.get('id')}


def find_position(chat_id, symbol):
    for p in get_open_positions(chat_id):
        n=normalize_real_position(p)
        if n['symbol']==symbol.upper(): return n
    return None


def _extract_numbers(obj, names):
    found=[]
    if isinstance(obj, dict):
        for k,v in obj.items():
            key=str(k).lower().replace('-','_')
            if key in names:
                try: found.append(float(v))
                except Exception: pass
            found.extend(_extract_numbers(v,names))
    elif isinstance(obj, list):
        for v in obj: found.extend(_extract_numbers(v,names))
    return found


def _price_matches(a,b):
    try:
        a=float(a); b=float(b); scale=max(abs(a),abs(b),1.0)
        return abs(a-b) <= max(1e-8,scale*2e-5)
    except Exception:
        return False


def _live_position_raw(chat_id, symbol):
    ex=get_exchange(chat_id)
    try:
        fsym,_scale,_m=_fsym(ex,symbol)
        rows=ex.fetch_positions([fsym])
    except Exception:
        rows=ex.fetch_positions()
    for p in rows:
        n=normalize_real_position(p)
        if n['symbol']==symbol.upper() and abs(float(p.get('contracts') or p.get('amount') or 0))>0: return p
    return None


def _halt_real_trading(chat_id, reason):
    s=get_session(chat_id)
    s['is_bot_active']=False
    s['real_reconciliation_required']=True
    s['trading_halted_reason']=str(reason)[:500]
    s['scan_generation']=int(s.get('scan_generation',0))+1
    save_session(chat_id)
    send_message(chat_id,f"🚨 *توقف ایمنی REAL فعال شد.*\n\n{reason}\n\nتا بررسی وضعیت حساب {real_venue_name(chat_id)}، معامله جدید مجاز نیست.")


# ---- Binance: حالت پوزیشن / مارجین / اهرم --------------------------------
def _ensure_one_way_mode(ex):
    """ربات با حالت One-way کار می‌کند (نه Hedge)."""
    if getattr(ex,'is_bitunix',False): return ex.ensure_one_way()          # V3.44.57
    if getattr(ex,'_one_way_ok',False): return
    try:
        r=_binance_call(ex,'GET','positionSide/dual')
        dual=str((r or {}).get('dualSidePosition')).lower()=='true'
    except Exception as exc:
        logger.warning('position mode check failed: %s',exc); return
    if dual:
        # اگر پوزیشن باز داشته باشید باینانس اجازه‌ی تغییر نمی‌دهد و خطا می‌دهد (معامله رد می‌شود)
        _binance_call(ex,'POST','positionSide/dual',{'dualSidePosition':'false'})
    try: ex._one_way_ok=True
    except Exception: pass


def _binance_prepare_symbol(ex, sym, leverage):
    """مارجین Isolated/Cross + اهرم را روی نماد تنظیم می‌کند و اهرم نهایی مجاز را برمی‌گرداند."""
    _ensure_one_way_mode(ex)
    mode=MARGIN_MODE if MARGIN_MODE in ('isolated','cross') else 'isolated'
    try:
        ex.set_margin_mode(mode,sym)
    except Exception as exc:
        msg=str(exc)
        if '-4046' not in msg and 'No need to change' not in msg: raise
    lev=max(1,int(leverage))
    try:
        tiers=ex.fetch_market_leverage_tiers(sym)
        mx=max([float(t.get('maxLeverage') or 0) for t in (tiers or [])] or [0])
        if mx>0: lev=min(lev,int(mx))
    except Exception:
        pass
    last=None
    for L in sorted({lev,*[x for x in (20,10,5,3,2,1) if x<lev]},reverse=True):
        try:
            ex.set_leverage(L,sym); return L
        except Exception as exc:
            last=exc
    raise last if last else RuntimeError('set_leverage failed')


# ---- Binance: سفارش‌های شرطی (SL/TP) از طریق Algo Order Service ----------
# از 2025-12-09 باینانس STOP_MARKET/TAKE_PROFIT_MARKET را روی /fapi/v1/order رد می‌کند (خطای -4120)
# و باید از POST /fapi/v1/algoOrder استفاده شود. ویرایش سفارش شرطی ممکن نیست؛ باید لغو و دوباره ثبت شود.
def _algo_open_orders(ex, market_id):
    r=_binance_call(ex,'GET','openAlgoOrders',{'symbol':market_id})
    if isinstance(r,dict): r=r.get('orders') or r.get('data') or []
    return r if isinstance(r,list) else []


def _algo_type(o):
    return str(o.get('orderType') or o.get('type') or '').upper()


def _cancel_algo(ex, market_id, kinds=(_ALGO_SL,_ALGO_TP)):
    done=[]
    for o in _algo_open_orders(ex,market_id):
        if _algo_type(o) in kinds and o.get('algoId') is not None:
            _binance_call(ex,'DELETE','algoOrder',{'algoId':o['algoId']})
            done.append(o)
    return done


def _place_algo(ex, market_id, close_side, kind, trigger_price):
    return _binance_call(ex,'POST','algoOrder',{
        'algoType':'CONDITIONAL','symbol':market_id,'side':close_side.upper(),'type':kind,
        'triggerPrice':str(trigger_price),'closePosition':'true','workingType':_BINANCE_WORKING_TYPE,
        'priceProtect':'FALSE'})


def cancel_all_protection(chat_id, symbol):
    """پاک‌سازی SL/TP باقی‌مانده‌ی یک نماد (بعد از بسته‌شدن پوزیشن). بدون خطا."""
    try:
        ex=get_exchange(chat_id)
        if not ex: return
        _fsym_,_scale,m=_fsym(ex,symbol)
        if getattr(ex,'is_bitunix',False): ex.cancel_position_tpsl(m['symbol']); return     # V3.44.57
        _cancel_algo(ex,m['id'])
    except Exception as exc:
        logger.debug('cancel protection %s: %s',symbol,exc)


def _bitunix_set_protection(chat_id, ex, symbol, sl, tp, only_sl=False):
    """TP/SL «پوزیشن» بیتیونیکس: کل حجمِ لحظه‌ی فعال‌شدن را با مارکت می‌بندد (معادل closePosition باینانس).
    only_sl=True (جابه‌جایی استاپ): TP موجود حفظ می‌شود. بعد از ثبت، مقدار روی صرافی خوانده و با مقدار خواسته‌شده تطبیق داده می‌شود."""
    try:
        fsym,scale,m=_fsym(ex,symbol)
        n=find_position(chat_id,symbol)
        if not n or not n.get('position_id'): return False,'position not found'
        trig={}
        if sl: trig['sl']=ex.price_to_precision(fsym,float(sl)*scale)
        if tp and not only_sl: trig['tp']=ex.price_to_precision(fsym,float(tp)*scale)
        if not trig: return False,'no SL/TP given'
        ex.set_position_tpsl(fsym,n['position_id'],sl=trig.get('sl'),tp=trig.get('tp'),keep_existing=bool(only_sl))
        try:
            got=ex.get_position_tpsl(m['id'],n['position_id'])
            for key,val in trig.items():
                if not _price_matches(got.get(key),val): return False,f'{key.upper()} verification mismatch: expected {val}'
        except Exception as exc:
            logger.warning('bitunix protection verification query failed for %s: %s',symbol,exc)
        return True,'OK'
    except Exception as exc:
        return False,f'protection setup failed: {exc}'


def set_protection(chat_id, symbol, sl, tp):
    ex=get_exchange(chat_id)
    if not ex: return False,'exchange unavailable'
    if getattr(ex,'is_bitunix',False): return _bitunix_set_protection(chat_id,ex,symbol,sl,tp)       # V3.44.57
    try:
        fsym,scale,m=_fsym(ex,symbol)
        n=find_position(chat_id,symbol)
        if not n: return False,'position not found'
        close_side='sell' if side_long(n['side']) else 'buy'
        mid=m['id']
        _cancel_algo(ex,mid)   # باینانس ویرایش ندارد و دو closePosition هم‌جهت را هم‌زمان قبول نمی‌کند
        errors=[]; placed={}
        for kind,label,price in ((_ALGO_SL,'SL',sl),(_ALGO_TP,'TP',tp)):
            if not price: continue
            try:
                trig=ex.price_to_precision(fsym,float(price)*scale)
                _place_algo(ex,mid,close_side,kind,trig)
                placed[kind]=float(trig)
            except Exception as e:
                errors.append(f'{label}:{e}')
        if errors: return False,' | '.join(errors)
        try:
            rows=_algo_open_orders(ex,mid)
            for kind,trig in placed.items():
                ok=any(_algo_type(o)==kind and _price_matches(o.get('triggerPrice'),trig) for o in rows)
                if not ok: return False,f'{kind} verification mismatch: expected {trig}'
        except Exception as exc:
            logger.warning('protection verification query failed for %s: %s',symbol,exc)
        return True,'OK'
    except Exception as exc:
        return False,f'protection setup failed: {exc}'


def move_stop_loss(chat_id, symbol, sl):
    ex=get_exchange(chat_id)
    if not ex: return False,'exchange unavailable'
    if getattr(ex,'is_bitunix',False): return _bitunix_set_protection(chat_id,ex,symbol,sl,None,only_sl=True)    # V3.44.57: ویرایش اتمی؛ شکست یعنی استاپ قبلی سر جایش است
    old=[]; mid=None; close_side=None
    try:
        fsym,scale,m=_fsym(ex,symbol)
        n=find_position(chat_id,symbol)
        if not n: return False,'position not found'
        close_side='sell' if side_long(n['side']) else 'buy'
        mid=m['id']
        old=[o for o in _algo_open_orders(ex,mid) if _algo_type(o)==_ALGO_SL]
        for o in old: _binance_call(ex,'DELETE','algoOrder',{'algoId':o['algoId']})
        trig=ex.price_to_precision(fsym,float(sl)*scale)
        _place_algo(ex,mid,close_side,_ALGO_SL,trig)
        return True,'OK'
    except Exception as e:
        # ثبت SL جدید شکست خورد: SL قبلی را برمی‌گردانیم تا پوزیشن بدون حد ضرر نماند
        restored=False
        for o in old:
            try:
                _place_algo(ex,mid,close_side,_ALGO_SL,o.get('triggerPrice')); restored=True
            except Exception as e2:
                logger.error('SL restore failed %s: %s',symbol,e2)
        if old and not restored:
            try: send_message(chat_id,f'🚨 حد ضرر `{symbol}` روی صرافی لغو شد ولی ثبت دوباره شکست خورد! فوراً حد ضرر را در Binance چک کنید.',parse_mode=None)
            except Exception: pass
        return False,str(e)


def position_history_for(chat_id, symbol, since_ms):
    """PnL خالص (بعد از کارمزد) معاملات یک نماد از زمان since_ms؛ یک ردیف خلاصه یا []."""
    ex=get_exchange(chat_id)
    if not ex: return []
    try:
        fsym,scale,_m=_fsym(ex,symbol)
        trades=ex.fetch_my_trades(fsym,int(since_ms),200)
        if not trades: return []
        gross=0.0; fees=0.0; last_ts=0; last_px=0.0
        for t in trades:
            info=t.get('info') or {}
            gross+=float(info.get('realizedPnl') or 0)
            fee=t.get('fee') or {}
            cost=fee.get('cost'); cur=fee.get('currency')
            if cost is None: cost=info.get('commission'); cur=info.get('commissionAsset')
            if _is_usd_like(cur): fees+=float(cost or 0)
            else: fees+=float(t.get('cost') or 0)*TAKER_FEE_PCT/100.0   # کارمزد با BNB و ... → برآورد با نرخ Taker
            ts=float(t.get('timestamp') or 0)
            if ts>=last_ts: last_ts=ts; last_px=float(t.get('price') or 0)
        return [{'realizedPnl':gross-fees,'timestamp':last_ts,'close_price':(last_px/scale if last_px else None),
                 'info':{'gross_realized':gross,'fees':fees}}]
    except Exception as exc:
        logger.debug('position history %s: %s',symbol,exc); return []


def _close_market(ex, sym, is_long, contracts):
    """بستن (reduce-only) با سفارش مارکت؛ contracts بر حسب واحد قرارداد فیوچرز."""
    amt=float(ex.amount_to_precision(sym,contracts))
    return ex.create_order(sym,'market','sell' if is_long else 'buy',amt,None,{'reduceOnly':True,'newOrderRespType':'RESULT'})


def _order_avg_price(ex, sym, order):
    try:
        avg=float((order or {}).get('average') or 0)
        if avg>0: return avg
    except Exception: pass
    oid=(order or {}).get('id')
    for _ in range(4):
        try:
            o=ex.fetch_order(oid,sym)
            avg=float(o.get('average') or 0)
            if avg>0: return avg
        except Exception: pass
        time.sleep(0.4)
    return 0.0


def side_long(side): return 'BUY' in str(side).upper() or 'LONG' in str(side).upper()
def reserved_margin(s): return sum(float(p.get('margin',0)) for p in s['paper_positions'])


def round_trip_fee_usdt(margin, leverage):
    try:
        notional = abs(float(margin)) * abs(float(leverage))
        if not math.isfinite(notional): return 0.0
        return notional * (TAKER_FEE_PCT / 100.0) * 2
    except Exception:
        return 0.0


def estimate_trade_pnl(entry, sl, tp, side, margin, leverage):
    """سود/زیان مورد انتظار یک معامله در صورت رسیدن به TP یا SL - با کسر کارمزد رفت‌وبرگشت
    (همان فرمول round_trip_fee_usdt که موقع بسته‌شدن پوزیشن هم استفاده می‌شود).
    اسلیپیج و فاندینگ (وابسته به زمان/بازار) در این پیش‌بینی لحاظ نمی‌شوند."""
    entry = float(entry); sl = float(sl); tp = float(tp)
    notional = abs(float(margin)) * abs(float(leverage))
    amount = notional / entry if entry > 0 else 0.0
    is_long = side_long(side)
    tp_gross = ((tp - entry) if is_long else (entry - tp)) * amount
    sl_gross = ((sl - entry) if is_long else (entry - sl)) * amount   # منفی
    fee = round_trip_fee_usdt(margin, leverage)
    return {'tp_gross': tp_gross, 'sl_gross': sl_gross, 'fee': fee,
            'tp_net': tp_gross - fee, 'sl_net': sl_gross - fee, 'notional': notional}


def net_r_estimates(entry, sl, tp):
    """سود/زیان بر حسب R پس از کسر کارمزد رفت‌وبرگشت - مستقل از اندازه‌ی پوزیشن.
    خروجی: (R خالص در TP، R خالص در SL (منفی)، کارمزد بر حسب R)."""
    entry = float(entry); risk = abs(entry - float(sl))
    if entry <= 0 or risk <= 0:
        return 0.0, 0.0, 0.0
    fee_r = (2.0 * TAKER_FEE_PCT / 100.0) / (risk / entry)
    rr = abs(float(tp) - entry) / risk
    return rr - fee_r, -(1.0 + fee_r), fee_r


def estimate_session_size(chat_id, symbol, entry, sl, dynamic=False):
    """(مارجین، اهرم) که ربات برای این ورود با تنظیمات همین کاربر استفاده می‌کند؛ (0, 0) اگر محاسبه نشد."""
    try:
        s = USER_SESSIONS.get(chat_id)
        if not s:
            return 0.0, 0
        s['_symbol_tmp'] = symbol
        try:
            margin, _ = safe_size(chat_id, s, float(entry), float(sl), force=True, dynamic=dynamic)
        finally:
            s.pop('_symbol_tmp', None)
        return float(margin or 0.0), int(s.get('leverage') or 0)
    except Exception:
        return 0.0, 0


def pnl_estimate_lines(entry, sl, tp, side, margin=0.0, leverage=0, platform_rate=None, compact=False):
    """خطوط متنی سود/زیان دقیق برای پیام سیگنال. اگر مارجین معلوم باشد به USDT، و همیشه بر حسب R.
    compact=True: همان اطلاعات، ولی فشرده‌تر (چند مقدار در یک خط) برای کارت تایید سیگنال."""
    lines = []
    tp_r, sl_r, fee_r = net_r_estimates(entry, sl, tp)
    if margin and leverage:
        est = estimate_trade_pnl(entry, sl, tp, side, margin, leverage)
        platform_txt = None
        if PLATFORM_FEE_MODE == 'per_trade' and platform_rate and platform_rate > 0 and est['tp_net'] > PLATFORM_FEE_MIN_PROFIT_USDT:
            platform_txt = f"{est['tp_net'] * (1 - platform_rate / 100.0):+.2f}"
        if compact:
            lines.append(f"• 💰 TP: `{est['tp_net']:+.2f}` USDT")
            lines.append(f"• 🛑 SL: `{est['sl_net']:+.2f}` USDT")
            return lines
        lines.append(f"• 💰 سود در صورت TP: `{est['tp_net']:+.2f} USDT` (ناخالص `{est['tp_gross']:+.2f}` − کارمزد `{est['fee']:.2f}`)")
        lines.append(f"• 🛑 زیان در صورت SL: `{est['sl_net']:+.2f} USDT` (ناخالص `{est['sl_gross']:+.2f}` − کارمزد `{est['fee']:.2f}`)")
        if platform_txt is not None:
            lines.append(f"• سود خالص پس از سهم پلتفرم ({platform_rate:g}%): `{platform_txt} USDT`")
        elif PLATFORM_FEE_MODE == 'daily' and platform_rate and platform_rate > 0:
            lines.append(f"• سهم پلتفرم ({platform_rate:g}%) از این معامله کم نمی‌شود؛ آخر روز از مجموع سود روز حساب می‌شود.")
        lines.append(f"• حجم محاسبه‌شده: مقدار هر معامله `{margin:.2f}` × اهرم `{leverage}`")
    if compact:
        lines.append(f"• خالص R: TP `{tp_r:+.2f}R` / SL `{sl_r:+.2f}R`")
    else:
        lines.append(f"• خالص بر حسب R (پس از کارمزد): TP `{tp_r:+.2f}R` | SL `{sl_r:+.2f}R`")
    return lines


def _tf_regime_line(tf):
    """یک خط کوتاه: رژیم/جهت بازار روی تایم‌فریم فعال (از کش گیت جهت بازار؛ هر چرخه‌ی اسکن تازه می‌شود)."""
    gate = (TIMEFRAME_REGIME_CACHE.get(_tfk(tf)) or {}).get('gate')
    label = {'BULLISH': '🟢 صعودی', 'BEARISH': '🔴 نزولی', 'RANGE': '⚪️ رنج'}.get(gate, '⏳ نامشخص')
    return f"🧭 رژیم بازار ({TF_DISPLAY.get(tf, tf)}): *{label}*"


def _symbol_regime_line(regime, tf):
    """خط رژیم خودِ نماد روی تایم‌فریم سیگنال (همان معیار پیام کانال سیگنال: close نسبت به EMA50 و EMA20 نسبت به EMA50 روی آخرین کندل بسته‌شده)."""
    label = {'BULLISH': '🟢 صعودی', 'BEARISH': '🔴 نزولی', 'RANGE': '⚪️ رنج'}.get(regime, '⏳ نامشخص')
    return f"🧭 رژیم نماد ({TF_DISPLAY.get(tf, tf)}): *{label}*"


def _ensure_tf_gate_sync(tf):
    """رژیم بازار تایم‌فریم tf را در TIMEFRAME_REGIME_CACHE تازه نگه می‌دارد (نسخه‌ی همگام، برای حلقه‌ی
    کانال که جدا از اسکن اصلی اجرا می‌شود). همان منطق refresh_market_gate؛ فقط اگر کش نیست/کهنه است محاسبه می‌کند."""
    try:
        c = TIMEFRAME_REGIME_CACHE.get(_tfk(tf))
        if c and c.get('gate') and time.time() - float(c.get('ts', 0) or 0) < TIMEFRAME_REGIME_TTL:
            return
        with ThreadPoolExecutor(max_workers=min(6, len(MARKET_REPORT_SYMBOLS))) as ex:
            snaps = list(ex.map(lambda sym: _market_snapshot(sym, tf), MARKET_REPORT_SYMBOLS))
        scores = [x['score'] for x in snaps if x is not None]
        total = len(scores)
        bull_n = sum(1 for x in scores if x > 0)
        bear_n = sum(1 for x in scores if x < 0)
        gate = 'BULLISH' if bull_n >= MARKET_GATE_MIN_SYMBOLS else ('BEARISH' if bear_n >= MARKET_GATE_MIN_SYMBOLS else 'RANGE')
        TIMEFRAME_REGIME_CACHE[_tfk(tf)] = {
            'ts': (time.time() if total >= MARKET_GATE_MIN_SYMBOLS else 0.0), 'gate': gate,
            'bull_n': bull_n, 'bear_n': bear_n, 'total': total,
            'bull_pct': (bull_n / total * 100.0) if total else 0.0,
            'bear_pct': (bear_n / total * 100.0) if total else 0.0,
        }
    except Exception:
        logger.exception('ensure tf gate failed tf=%s', tf)


def reset_daily_if_needed(chat_id, equity):
    s=get_session(chat_id); today=time.strftime('%Y-%m-%d',time.gmtime())
    if s.get('daily_start_date')!=today:
        s['daily_start_date']=today; s['daily_start_equity']=float(equity); s['daily_stopped']=False; s['traded_levels']={}; save_session(chat_id)


def current_paper_equity(s):
    eq=float(s['paper_balance'])
    for p in s['paper_positions']:
        price=latest_price(p['symbol'])
        if not price: continue
        entry=float(p['entry_price']); frac=((price-entry)/entry) if side_long(p['side']) else ((entry-price)/entry)
        eq += float(p.get('margin',0))*frac*float(p.get('leverage',1))
    return eq


def risk_guard(chat_id):
    s=get_session(chat_id); now=time.time()
    if now-s.get('last_risk_check',0)<15: return not s['daily_stopped']
    s['last_risk_check']=now
    try:
        equity=exchange_balance(chat_id) if s['trading_mode']=='REAL' else current_paper_equity(s)
    except ExchangeStateError as exc:
        if s['trading_mode']=='REAL':
            _halt_real_trading(chat_id,f'اطلاعات حساب {real_venue_name(chat_id)} قابل اعتماد نیست: {exc}')
        return False
    reset_daily_if_needed(chat_id,equity)
    start=float(s['daily_start_equity'])
    if start<=0: return True
    limit=start*(1-float(s['daily_loss_limit_pct'])/100)
    if equity<=limit:
        stop_scan(chat_id, 'daily-risk')
        s=get_session(chat_id)
        s['daily_stopped']=True
        save_session(chat_id)
        sync_bottom_keyboard(chat_id, "🛑 اسکن به‌دلیل حد ضرر روزانه متوقف شد.\n⚙️ تنظیمات آماده تغییر هستند.")
        send_message(chat_id,f"🛑 *حد ضرر روزانه فعال شد.*\n\nشروع روز: `${start:.2f}`\nسرمایه: `${equity:.2f}`\nحد: `{s['daily_loss_limit_pct']:.2f}%`\n\nورود جدید متوقف شد؛ پوزیشن‌های باز دست‌نخورده باقی می‌مانند.")
        return False
    return True


def market_meta(chat_id,symbol):
    ex=get_exchange(chat_id)
    if not ex: return None
    try:
        m,_scale=futures_market(ex,symbol)
        return m
    except Exception as exc:
        logger.debug('market_meta fallback symbol=%s: %s', symbol, exc)
        return None


def normalize_amount(chat_id,symbol,amount):
    """حجم (بر حسب کوین، واحد ربات) را مطابق دقت قرارداد فیوچرز گرد می‌کند."""
    ex=get_exchange(chat_id)
    if not ex: return 0.0
    try:
        fsym,scale,_m=_fsym(ex,symbol)
        return float(ex.amount_to_precision(fsym,float(amount)/scale))*scale
    except Exception as exc:
        logger.debug('normalize_amount fallback symbol=%s amount=%s: %s', symbol, amount, exc)
        return float(amount)


def normalize_price(chat_id,symbol,price):
    ex=get_exchange(chat_id)
    if not ex: return float(price)
    try:
        fsym,scale,_m=_fsym(ex,symbol)
        return float(ex.price_to_precision(fsym,float(price)*scale))/scale
    except Exception as exc:
        logger.debug('normalize_price fallback symbol=%s price=%s: %s', symbol, price, exc)
        return float(price)


def safe_size(chat_id,s,entry,sl,force=False,dynamic=False,risk_mult=1.0):
    try:
        balance=exchange_balance(chat_id) if s['trading_mode']=='REAL' else float(s['paper_balance'])
    except ExchangeStateError as exc:
        return 0,f'account state unavailable: {exc}'
    stop_dist=abs(entry-sl)/max(abs(entry),1e-12)
    if stop_dist<=0 or not math.isfinite(stop_dist): return 0,'invalid stop distance'
    risk_budget=balance*float(s['risk_per_trade_pct'])/100*float(risk_mult)
    leverage=max(1,int(s['leverage']))
    # dynamic=True: مارجین ثابتِ تنظیمات نادیده گرفته می‌شود و فقط ریسک هر معامله/فاصله‌ی SL و موجودی آزاد تعیین‌کننده‌اند.
    requested_margin=float('inf') if dynamic else float(s['trade_amount_usdt'])*float(risk_mult)
    # force (تایید دستی): سقف درصد مصرف مارجین نادیده گرفته می‌شود؛ فقط موجودی آزاد واقعی محدودکننده است.
    cap=balance if force else balance*float(s['max_margin_usage_pct'])/100
    available=max(0,cap-reserved_margin(s))
    risk_notional=risk_budget/stop_dist
    risk_margin=risk_notional/leverage
    margin=min(requested_margin,available,risk_margin)
    if margin<=0: return 0,'risk/margin cap blocks entry'
    amount=(margin*leverage)/entry
    if s['trading_mode']=='REAL':
        amount=normalize_amount(chat_id,s.get('_symbol_tmp',''),amount)
    return margin,amount


def expected_trade_metrics(trade):
    try:
        entry=float(trade.get('entry_price') or 0)
        tp=float(trade.get('tp') or 0)
        sl=float(trade.get('sl') or 0)
        amount=abs(float(trade.get('amount') or 0))
        if entry <= 0 or tp <= 0 or sl <= 0 or amount <= 0:
            return {'tp_pnl':0.0,'sl_pnl':0.0,'risk':0.0,'reward':0.0,'rr':0.0,'valid':False}
        if side_long(trade.get('side','BUY')):
            tp_pnl=(tp-entry)*amount
            sl_pnl=(sl-entry)*amount
            valid=(tp > entry and sl < entry)
        else:
            tp_pnl=(entry-tp)*amount
            sl_pnl=(entry-sl)*amount
            valid=(tp < entry and sl > entry)
        risk=abs(sl_pnl)
        reward=abs(tp_pnl)
        rr=(reward/risk) if risk > 0 else 0.0
        return {'tp_pnl':tp_pnl,'sl_pnl':sl_pnl,'risk':risk,'reward':reward,'rr':rr,
                'valid':bool(valid and risk > 0 and reward > 0)}
    except Exception:
        return {'tp_pnl':0.0,'sl_pnl':0.0,'risk':0.0,'reward':0.0,'rr':0.0,'valid':False}


TV_INTERVAL_MAP = {'5min': '5', '15min': '15', '1hour': '60', '4hour': '240', '1day': 'D'}


TRADINGVIEW_BUTTON_INTERVAL = os.environ.get('TRADINGVIEW_BUTTON_INTERVAL', '').strip()   # V3.44.25: خالی = چارت با تایم‌فریم همان سیگنال/کاربر باز می‌شود؛ اگر مقدار بگذاری (مثلاً 5) همیشه همان تایم ثابت باز می‌شود
_TV_INTERVALS = {'1min': '1', '3min': '3', '5min': '5', '15min': '15', '30min': '30', '1hour': '60', '2hour': '120', '4hour': '240', '1day': 'D', '1week': 'W'}


def tradingview_symbol(symbol, chat_id=None):
    """نماد برای TradingView. V3.44.98: صرافی = صرافیِ حالتِ کاربر (نه «آخرین منبعی که داده داد»):
    صرافی Binance (PAPER یا REAL) → BINANCE:XUSDT؛ صرافی Bitunix (PAPER یا REAL) → BITUNIX:XUSDT.P (فیوچرز).
    chat_id اگر داده نشود، همان صرافیِ زمینه‌ی جاری (contextvar) خوانده می‌شود."""
    base = _base_asset(symbol)
    venue = data_venue_for(chat_id) if chat_id is not None else _venue()
    exchange = TRADINGVIEW_EXCHANGE or TV_EXCHANGE_MAP.get(venue, 'BINANCE')
    suffix = '.P' if (not TRADINGVIEW_EXCHANGE and venue == 'bitunix') else ''
    if suffix and _bitunix_scale(base) != 1:
        suffix = ''     # V3.44.112: نمادِ ۱۰۰۰تایی (1000PEPE) در فیوچرز با قیمت ×۱۰۰۰ است و با سطوح ربات نمی‌خواند => چارت از «اسپات» همان نام (BITUNIX:PEPEUSDT)
    return f'{exchange}:{base}USDT{suffix}'


def tradingview_chart_url(symbol, timeframe='5min', chat_id=None):
    """
    لینک چارت TradingView برای نماد/تایم‌فریم فعال (بازار اسپات، هم‌جنس با داده‌ی اسکنر).
    این یک لینک معمولی tradingview.com است؛ تلگرام و سیستم‌عامل موبایل به‌صورت خودکار
    اگر اپلیکیشن TradingView نصب باشد آن را در اپ باز می‌کنند (universal/app link)،
    وگرنه در مرورگر پیش‌فرض باز می‌شود - نیازی به منطق تشخیص اپ در سمت سرور نیست.
    """
    # V3.44.25: تایم‌فریم چارت = تایم‌فریم همان سیگنال/کاربر (۱۵ دقیقه → ۱۵، ۴ ساعته → ۲۴۰ ...)؛ اگر TRADINGVIEW_BUTTON_INTERVAL ست شده باشد همان ثابت می‌ماند.
    interval = TRADINGVIEW_BUTTON_INTERVAL or _TV_INTERVALS.get(str(timeframe or '').strip().lower(), '5')
    tv_symbol = urlparse.quote(tradingview_symbol(symbol, chat_id), safe='')
    return f'https://www.tradingview.com/chart/?symbol={tv_symbol}&interval={interval}'


