def check_pending_orders(chat_id):
    """هر اوردر معلق را با قیمت لحظه‌ای می‌سنجد: اول تریگر (اگر باشد)، بعد قیمت ورود.
    این تابع هیچ ارتباطی با منطق سیگنال/استراتژی ندارد - صرفاً اوردرهایی که خودِ
    کاربر دستی با قیمت/مارجین/اهرم دلخواه ثبت کرده را پایش می‌کند."""
    s = get_session(chat_id)
    orders = s.get('pending_orders') or []
    if not orders:
        return
    remaining = []
    changed = False
    for o in orders:
        try:
            live = latest_price(o['symbol'])
            if not live:
                remaining.append(o); continue
            live = float(live)
            if not o.get('triggered'):
                trig = o.get('trigger_price')
                # جهت به‌صورت پویا نسبت به قیمت لحظه‌ای سنجیده می‌شود: اگر تریگر بالای
                # قیمت فعلی است یعنی منتظر رسیدن قیمت به بالا هستیم، وگرنه به پایین.
                hit = (live >= trig) if trig >= live else (live <= trig)
                if hit:
                    o['triggered'] = True
                    changed = True
                    send_message(chat_id, f"🔔 تریگر اوردر `{o['symbol']}` فعال شد؛ حالا منتظر رسیدن قیمت به `{fmt(o['entry_price'])}` است.")
                else:
                    remaining.append(o); continue
            entry = float(o['entry_price'])
            hit_entry = (live >= entry) if entry >= live else (live <= entry)
            # اگر اختلاف قیمت لحظه‌ای با ورود خیلی کم بود هم به‌عنوان رسیدن حساب می‌شود
            if abs(live - entry) / max(entry, 1e-9) < 0.0005:
                hit_entry = True
            if not hit_entry:
                remaining.append(o); continue
            side_txt = 'BUY (Long)' if side_long(o['side']) else 'SELL (Short)'
            old_margin, old_lev = s.get('trade_amount_usdt'), s.get('leverage')
            try:
                s['trade_amount_usdt'] = float(o['margin'])
                s['leverage'] = float(o['leverage'])
                ok, err = execute_manual_trade(chat_id, o['symbol'], side_txt, o['sl'], o['tp'], entry_price=live,
                                               reason=o.get('reason') or 'معامله دستی کاربر', force=bool(o.get('force')),
                                               tp_level_name=o.get('tp_level_name'))
            finally:
                s['trade_amount_usdt'] = old_margin
                s['leverage'] = old_lev
            changed = True
            if ok:
                if o.get('assist_id'):
                    try:
                        mine = [p for p in s.get('paper_positions', []) if p.get('symbol') == o['symbol']]
                        if mine:
                            mine.sort(key=lambda p: float(p.get('opened_at', 0) or 0))
                            mine[-1]['assist_id'] = o['assist_id']
                            mine[-1]['assist_delay_seconds'] = round(time.time() - float(o.get('created_at') or time.time()), 1)
                    except Exception:
                        logger.exception('assist tag for pending order failed')
                send_message(chat_id, f"✅ اوردر معاملاتی `{o['symbol']}` فعال و معامله باز شد.")
            elif str(err).startswith(_BTC_CANDLE_BLOCK_PREFIX) or str(err).startswith(_BTC_FRONT_PREFIX):
                # V3.44.42/45: کندل BTC هنوز هم‌جهت نیست (یا BTC به سطح جلویی نزدیک است)؛ اوردر حذف نمی‌شود و در چرخه‌ی بعد دوباره سنجیده می‌شود (فقط یک‌بار پیام).
                remaining.append(o)
                if not o.get('btc_wait_notified'):
                    o['btc_wait_notified'] = True
                    send_detail_message(chat_id, f"⏳ اوردر `{o['symbol']}` به قیمت رسید ولی وارد نشد و منتظر می‌ماند:\n{err}", simple_text=f"⏳ اوردر `{o['symbol']}` به قیمت رسید ولی فعلاً وارد نشد و منتظر می‌ماند.\n{block_simple_text(err, _BLOCK_SIMPLE_GENERIC)}")
            else:
                send_detail_message(chat_id, f"❌ اوردر `{o['symbol']}` رسید ولی باز نشد: {err}", simple_text=f"❌ اوردر `{o['symbol']}` باز نشد." + (f"\n{block_simple_text(err)}" if block_simple_text(err) else ''))
        except Exception:
            logger.exception('pending order check failed chat_id=%s order=%s', chat_id, o.get('order_id'))
            remaining.append(o)
    if changed:
        s['pending_orders'] = remaining
        save_session(chat_id)


# مدت اعتبار پیام‌های کانال سیگنال قبل از حذف خودکار (ثانیه). V3.38: پیش‌فرض ۶۰۰ (۱۰ دقیقه)؛ با دکمه‌ی «💾 ذخیره» پیام حذف نمی‌شود. ۰ = هرگز حذف نشود.
SIGNAL_CHANNEL_MESSAGE_TTL_SECONDS = max(0, int(os.environ.get('SIGNAL_CHANNEL_MESSAGE_TTL_SECONDS', '600')))
# Timer در حال انتظار برای هر message_id - با دکمه‌ی «ذخیره» لغو می‌شود تا آن پیام
# خاص دیگر خودکار پاک نشود. حافظه‌ی درون‌پردازه‌ای است (با ری‌استارت ربات پاک می‌شود؛
# مشکلی نیست چون آن پیام‌های قدیمی‌تر معمولاً یا از قبل حذف شده‌اند یا کاربر می‌تواند
# دستی حذفشان کند).
_CHANNEL_MSG_TIMERS = {}


def _delete_channel_message_later(channel_id, message_id):
    _CHANNEL_MSG_TIMERS.pop(message_id, None)
    try:
        res = tg('deleteMessage', {'chat_id': channel_id, 'message_id': message_id}, 10)
        if not res or not res.get('ok'):
            logger.warning('deleteMessage channel=%s message_id=%s failed: %s', channel_id, message_id, res)
    except Exception:
        logger.exception('failed to delete channel message %s/%s', channel_id, message_id)


def _schedule_channel_ttl(channel_id, message_id, ttl_seconds=None):
    ttl = SIGNAL_CHANNEL_MESSAGE_TTL_SECONDS if ttl_seconds is None else max(0, int(ttl_seconds))
    if message_id and ttl > 0:
        timer = Timer(ttl, _delete_channel_message_later, args=(channel_id, message_id))
        _CHANNEL_MSG_TIMERS[message_id] = timer
        timer.start()


def send_channel_message(channel_id, text, reply_markup=None, ttl_seconds=None):
    """ارسال مستقیم به کانال - بدون session، بدون کیبورد پایین، بدون هیچ منطق
    کاربری. عمداً از send_message جدا نگه داشته شده چون send_message فرض می‌کند
    chat_id متعلق به یک کاربر واقعی با session است، که برای کانال صدق نمی‌کند.
    اگر ttl_seconds (پیش‌فرض SIGNAL_CHANNEL_MESSAGE_TTL_SECONDS) مثبت باشد، پیام بعد از
    آن مدت خودکار از کانال حذف می‌شود؛ پیش‌فرض ۶۰۰ ثانیه (۱۰ دقیقه).
    خروجی: message_id در صورت موفقیت، وگرنه None."""
    try:
        payload = {'chat_id': channel_id, 'text': text, 'parse_mode': 'Markdown'}
        if reply_markup:
            payload['reply_markup'] = reply_markup
        res = tg('sendMessage', payload, 10)
        if not res or not res.get('ok'):
            return None
        message_id = (res.get('result') or {}).get('message_id')
        _schedule_channel_ttl(channel_id, message_id, ttl_seconds)
        return message_id
    except Exception:
        logger.exception('failed to post to signal channel')
        return None


def send_channel_photo(channel_id, img_bytes, caption, reply_markup=None, ttl_seconds=None):
    """ارسال تصویر چارت + کپشن + دکمه‌ها به کانال. خروجی: message_id یا None (که در این حالت
    فراخواننده به پیام متنی برمی‌گردد). کپشن تلگرام حداکثر ۱۰۲۴ کاراکتر است."""
    if not TELEGRAM_TOKEN or not img_bytes:
        return None
    try:
        data = {'chat_id': channel_id, 'caption': caption[:1024], 'parse_mode': 'Markdown'}
        if reply_markup:
            data['reply_markup'] = json.dumps(reply_markup, ensure_ascii=False)
        r = requests.post(f'https://api.telegram.org/bot{TELEGRAM_TOKEN}/sendPhoto', data=data,
                          files={'photo': ('chart.png', img_bytes, 'image/png')}, timeout=25)
        if r.status_code != 200:
            logger.warning('channel sendPhoto failed: %s %s', r.status_code, r.text[:200])
            return None
        message_id = ((r.json() or {}).get('result') or {}).get('message_id')
        _schedule_channel_ttl(channel_id, message_id, ttl_seconds)
        return message_id
    except Exception:
        logger.exception('failed to post photo to signal channel')
        return None


_CHANNEL_IND_CACHE = {}   # {message_id: متن کامل اندیکاتورها} برای دکمه‌ی «📊 اندیکاتورها» زیر پیام کانال (فقط در حافظه)
_CHANNEL_IND_CACHE_MAX = 500


def _channel_ind_cache_put(message_id, text):
    if not message_id or not text:
        return
    _CHANNEL_IND_CACHE[message_id] = text
    while len(_CHANNEL_IND_CACHE) > _CHANNEL_IND_CACHE_MAX:
        _CHANNEL_IND_CACHE.pop(next(iter(_CHANNEL_IND_CACHE)), None)


def _append_channel_keep_delete_buttons(channel_id, message_id, base_markup):
    """بعد از ارسال پیام کانال (چون message_id فقط بعد از ارسال معلوم می‌شود)، یک ردیف
    «💾 ذخیره برای بررسی بعدی» / «🗑 حذف دستی» زیر همان دکمه‌های موجود اضافه می‌کند."""
    if not message_id:
        return
    try:
        rows = [list(r) for r in (((base_markup or {}).get('inline_keyboard')) or [])]
        if message_id in _CHANNEL_IND_CACHE:
            ind_btn = {'text': '📊 اندیکاتورها', 'callback_data': f'/chind_{message_id}'}
            for r in rows:
                if r and str(r[0].get('text', '')).startswith('📈'):
                    r.append(ind_btn); break
            else:
                rows.append([ind_btn])
        keep_row = []
        if SIGNAL_CHANNEL_MESSAGE_TTL_SECONDS > 0:      # وقتی پیام‌ها هرگز حذف خودکار نمی‌شوند، دکمه‌ی «ذخیره» بی‌معنی است
            keep_row.append({'text': '💾 ذخیره برای بررسی بعدی', 'callback_data': f'/keep_channel_msg_{message_id}'})
        keep_row.append({'text': '🗑 حذف دستی', 'callback_data': f'/del_channel_msg_{message_id}'})
        rows.append(keep_row)
        rows.extend(_channel_fixed_rows())      # V3.43: دکمه‌های ثابت (لیست بررسی‌های آتی / رژیم BTC/ETH)
        tg('editMessageReplyMarkup', {
            'chat_id': channel_id, 'message_id': message_id,
            'reply_markup': {'inline_keyboard': rows},
        }, 10)
    except Exception:
        logger.exception('failed to attach keep/delete buttons to channel message %s', message_id)



# ===================== V3.43: لیست بررسی‌های آتی + دکمه‌ی رژیم BTC/ETH (کانال و ربات) =====================
# • «💾 ذخیره برای بررسی بعدی» علاوه بر لغو حذف خودکار، نماد را در «لیست بررسی‌های آتی» ثبت می‌کند (ماندگار، در فایل JSON).
# • دکمه‌های ثابت کانال: «📋 لیست بررسی‌های آتی» و «🧭 رژیم BTC/ETH» هم زیر هر پیام کانال هستند و هم در یک پیام پین‌شده‌ی دائمی.
# • کانال: نتیجه به‌صورت پنجره‌ی بازشو (حداکثر ۲۰۰ کاراکتر، پس خلاصه)؛ ربات: لیست کامل با حذف تکی.
_CHANNEL_REVIEW_FILE = os.environ.get('SIGNAL_CHANNEL_REVIEW_FILE', 'signal_channel_review.json')
SIGNAL_CHANNEL_PANEL_REPOST = os.environ.get('SIGNAL_CHANNEL_PANEL_REPOST', 'false').lower() in ('1', 'true', 'yes')   # true = پیام پنل ثابت دوباره ارسال و پین شود
_CHANNEL_REVIEW_LOCK = RLock()
_CHANNEL_REVIEW_LOADED = False
_CHANNEL_MSG_META = {}       # {message_id: اطلاعات سیگنال همان پیام کانال} - تا بتوان هنگام «ذخیره» نماد را ثبت کرد
_CHANNEL_MSG_META_MAX = 400
_CHANNEL_REVIEW = {}         # V3.43.3: {آیدی تلگرام کاربر (str): [نمادهای ذخیره‌شده‌ی خودش، جدیدترین اول]} - هر اکانت ذخایر مستقل خودش را دارد
_CHANNEL_REVIEW_MAX = 100
_CHANNEL_PANEL_ID = None


def _review_load():
    global _CHANNEL_REVIEW_LOADED, _CHANNEL_PANEL_ID
    with _CHANNEL_REVIEW_LOCK:
        if _CHANNEL_REVIEW_LOADED:
            return
        _CHANNEL_REVIEW_LOADED = True
        try:
            with open(_CHANNEL_REVIEW_FILE, 'r', encoding='utf-8') as f:
                d = json.load(f) or {}
            for k, v in (d.get('meta') or {}).items():
                if isinstance(v, dict):
                    _CHANNEL_MSG_META[int(k)] = v
            saved = d.get('saved')
            if isinstance(saved, dict):
                for uid, lst in saved.items():
                    _CHANNEL_REVIEW[str(uid)] = [x for x in (lst or []) if isinstance(x, dict) and x.get('symbol')]
            elif isinstance(saved, list):
                # فرمت قدیمی (v3.43.0 تا v3.43.2: یک لیست مشترک) - به اکانت ادمین منتقل می‌شود
                old = [x for x in saved if isinstance(x, dict) and x.get('symbol')]
                if old:
                    _CHANNEL_REVIEW[str(SIGNAL_CHANNEL_TF_CHAT_ID)] = old
            _CHANNEL_PANEL_ID = d.get('panel_id')
        except FileNotFoundError:
            pass
        except Exception:
            logger.exception('failed to load signal channel review list')


def _review_save():
    with _CHANNEL_REVIEW_LOCK:
        try:
            with open(_CHANNEL_REVIEW_FILE, 'w', encoding='utf-8') as f:
                json.dump({'meta': {str(k): v for k, v in _CHANNEL_MSG_META.items()},
                           'saved': {k: list(v) for k, v in _CHANNEL_REVIEW.items()}, 'panel_id': _CHANNEL_PANEL_ID}, f, ensure_ascii=False)
        except Exception:
            logger.exception('failed to save signal channel review list')


def _channel_msg_meta_put(message_id, meta):
    if not message_id or not isinstance(meta, dict):
        return
    _review_load()
    with _CHANNEL_REVIEW_LOCK:
        _CHANNEL_MSG_META[int(message_id)] = meta
        while len(_CHANNEL_MSG_META) > _CHANNEL_MSG_META_MAX:
            _CHANNEL_MSG_META.pop(next(iter(_CHANNEL_MSG_META)), None)
        _review_save()


def _review_add(uid, message_id):
    """نماد پیام کانال را به لیست بررسی‌های آتیِ همین کاربر (uid = آیدی تلگرام) اضافه می‌کند.
    خروجی: ('added'|'updated'|'nometa', entry). اگر همان نماد قبلاً در لیست خودش بود، با سیگنال جدیدتر جایگزین می‌شود ('updated')."""
    _review_load()
    with _CHANNEL_REVIEW_LOCK:
        meta = _CHANNEL_MSG_META.get(int(message_id))
        if not meta or not meta.get('symbol'):
            return 'nometa', None
        entry = dict(meta)
        entry['msg_id'] = int(message_id)
        entry['saved_at'] = time.time()
        mine = _CHANNEL_REVIEW.setdefault(str(uid), [])
        had = any(x.get('symbol') == entry['symbol'] for x in mine)
        mine[:] = [x for x in mine if x.get('symbol') != entry['symbol']]
        mine.insert(0, entry)
        del mine[_CHANNEL_REVIEW_MAX:]
        _review_save()
        return ('updated' if had else 'added'), entry


def _review_remove(uid, message_id=None, clear_all=False):
    """فقط از لیست همین کاربر حذف می‌کند (لیست بقیه‌ی کاربران دست‌نخورده می‌ماند)."""
    _review_load()
    with _CHANNEL_REVIEW_LOCK:
        mine = _CHANNEL_REVIEW.get(str(uid)) or []
        before = len(mine)
        if clear_all:
            mine = []
        else:
            mine = [x for x in mine if x.get('msg_id') != message_id]
        _CHANNEL_REVIEW[str(uid)] = mine
        if len(mine) != before:
            _review_save()
        return before - len(mine)


_REVIEW_FILTER_TITLE = {'BUY': 'سیگنال‌های خرید 🟢', 'SELL': 'سیگنال‌های فروش 🔴'}


def _review_items(uid, side=None):
    _review_load()
    return [x for x in (_CHANNEL_REVIEW.get(str(uid)) or []) if side not in ('BUY', 'SELL') or x.get('side') == side]


def _review_popup_text(uid, side=None):
    """نسخه‌ی خیلی کوتاه (زیر ۲۰۰ کاراکتر، حد پنجره‌ی بازشوی تلگرام) برای دکمه‌ی کانال. side: None (همه) / 'BUY' / 'SELL'."""
    items = _review_items(uid, side)
    if not items:
        if side in _REVIEW_FILTER_TITLE:
            return f'📋 بررسی‌های آتی — {_REVIEW_FILTER_TITLE[side]}\nموردی در لیست نیست.'
        return '📋 لیست بررسی‌های آتی خالی است.\nبا «💾 ذخیره برای بررسی بعدی» زیر هر سیگنال، نماد را اینجا اضافه کنید.'
    head = f'📋 بررسی‌های آتی' + (f' — {_REVIEW_FILTER_TITLE[side]}' if side in _REVIEW_FILTER_TITLE else '') + f' ({len(items)})'
    tail = '\nلیست کامل: ربات ← 📋 بررسی‌های آتی'
    parts = [f"{'🟢' if x.get('side') == 'BUY' else ('🔴' if x.get('side') == 'SELL' else '⚪️')}{x['symbol']}" for x in items]
    shown = []
    for i, part in enumerate(parts):
        rest = len(parts) - i
        cand = head + '\n' + ' '.join(shown + [part]) + (f' … +{rest - 1}' if rest > 1 else '') + tail
        if len(cand) > 195 and shown:
            break
        shown.append(part)
    more = len(parts) - len(shown)
    return head + '\n' + ' '.join(shown) + (f' … +{more}' if more > 0 else '') + tail


_REGIME_FA = {'BULLISH': '🟢 صعودی', 'BEARISH': '🔴 نزولی', 'RANGE': '⚪️ رنج'}


# ===================== V3.44.42: کلید «هم‌جهتی با کندل در حال تشکیل BTC» =====================
# هنگام ورود (خودکار یا دستی)، کندل «در حال تشکیل» BTC روی همان تایم‌فریم فعال سنجیده می‌شود:
# خرید فقط وقتی قیمت لحظه‌ای BTC بالاتر از باز شدن همین کندل باشد (کندل صعودی)، فروش فقط وقتی پایین‌تر (کندل نزولی).
# ورود خودکار: سیگنال حذف نمی‌شود و تا هم‌جهت شدن کندل BTC منتظر می‌ماند. ورود دستی/دستیار/ورود سریع: رد می‌شود (حتی با اصرار کاربر).
# اگر داده‌ی کندل BTC در دسترس نباشد یا کندل خنثی باشد، «هم‌جهت» حساب نمی‌شود (ورود انجام نمی‌شود).
BTC_CANDLE_MIN_BODY_PCT = max(0.0, float(os.environ.get('BTC_CANDLE_MIN_BODY_PCT', '0') or 0))   # 0 = هر بدنه‌ی غیرصفر جهت دارد
_BTC_CANDLE_BLOCK_PREFIX = '⛔ کندل BTC'
_BTC_CANDLE_FA = {'BULLISH': 'صعودی', 'BEARISH': 'نزولی', 'NEUTRAL': 'خنثی'}


def btc_forming_candle(tf):
    """کندل در حال تشکیل BTC روی تایم‌فریم tf: {'open','price','start'} یا None.
    باز شدن کندل از کلاینت‌ها و قیمت جاری از latest_price (کش ۵ ثانیه) می‌آید. اگر کش کندل‌ها کهنه باشد
    (آخرین ردیف مربوط به کندل قبلی)، یک‌بار کش دور زده و دوباره دریافت می‌شود."""
    secs = _TF_SECONDS.get(tf)
    if not secs:
        return None
    period = TIMEFRAME_MAP.get(tf, tf)
    row = None
    for attempt in (0, 1):
        now = time.time()
        start = int(now // secs) * secs
        try:
            df = get_klines('BTC', tf, 60)
        except Exception:
            logger.exception('btc candle: klines failed tf=%s', tf)
            df = None
        if df is None or len(df) == 0:
            return None
        last = df.iloc[-1]
        ts = float(last['timestamp'])
        if ts > 1e11:
            ts /= 1000.0
        if start - 1 <= ts <= now + 1:
            row = last
            break
        if attempt == 0:
            with DATA_LOCK:
                DATA_CACHE.pop(f'BTC:{period}:60', None)
    if row is None:
        return None
    try:
        o = float(row['open'])
        px = None
        try:
            px = latest_price('BTC')
        except Exception:
            px = None
        px = float(px) if px else float(row['close'])
        if not (o > 0 and px > 0):
            return None
        return {'open': o, 'price': px, 'start': start}
    except Exception:
        return None


def btc_candle_state(tf):
    """('BULLISH'|'BEARISH'|'NEUTRAL'|None, candle). None = داده در دسترس نیست."""
    c = btc_forming_candle(tf)
    if not c:
        return None, None
    pct = (c['price'] - c['open']) / c['open'] * 100.0
    c['pct'] = pct
    if abs(pct) <= BTC_CANDLE_MIN_BODY_PCT:
        return 'NEUTRAL', c
    return ('BULLISH' if pct > 0 else 'BEARISH'), c


def btc_candle_verdict(tf, sig):
    """(ok, توضیح). sig = 'BUY'/'SELL'. ok فقط وقتی کندل در حال تشکیل BTC هم‌جهت معامله باشد."""
    want = 'BULLISH' if sig == 'BUY' else 'BEARISH'
    side_fa = 'خرید' if sig == 'BUY' else 'فروش'
    tf_fa = TF_DISPLAY.get(tf, tf)
    state, c = btc_candle_state(tf)
    if state is None:
        _t = f'{_BTC_CANDLE_BLOCK_PREFIX} ({tf_fa}) در دسترس نیست؛ ورود تا دریافت داده‌ی BTC انجام نمی‌شود' + _btc_gate_key_line('gate_btc_candle_enabled')
        _block_simple_register(_t, 'اطلاعات بیتکوین فعلاً کامل نیست؛ در این شرایط ورود به معامله مجاز نیست. لطفاً صبور باشید.')
        return False, _t
    if state == want:
        return True, ''
    _t = (f"{_BTC_CANDLE_BLOCK_PREFIX} ({tf_fa}) در حال تشکیل {_BTC_CANDLE_FA[state]} است "
          f"(باز شدن {fmt(c['open'])} ← الان {fmt(c['price'])}، {c['pct']:+.2f}٪) و با {side_fa} نمی‌خواند؛ "
          f"ورود تا هم‌جهت شدن کندل BTC با معامله انجام نمی‌شود" + _btc_gate_key_line('gate_btc_candle_enabled'))
    _block_simple_register(_t, 'بیتکوین الان خلاف جهت این معامله حرکت می‌کند؛ در این شرایط ورود به معامله مجاز نیست. لطفاً صبور باشید.')
    return False, _t


# ===================== V3.44.44: کلید «فاصله تا سطح جلویی BTC» =====================
# در آخرین مرحله‌ی خروج سیگنال از صف (تبدیل به معامله یا کارت دستیار)، «کلوز آخرین کندل بسته‌شده‌ی BTC» روی تایم‌فریم فعال
# با نزدیک‌ترین سطحِ «روبه‌روی جهت معامله» سنجیده می‌شود (خرید: نزدیک‌ترین سطح بالاتر، فروش: نزدیک‌ترین سطح پایین‌تر). سطوح همان
# سیستمی است که ربات روی همین حساب استفاده می‌کند (مدل نصف‌کردن اگر روشن باشد، وگرنه PDH/PDL و سطوح HTF و شبکه‌ی لگاریتمی).
# فاصله بر حسب ATR کندل بسته‌شده‌ی BTC سنجیده می‌شود؛ کمتر از حداقل (پیش‌فرض ۱×ATR، کلید btc_front_min_atr یا متغیر محیطی
# BTC_FRONT_MIN_ATR) = «معقول نیست»: هشدار ورود (یک‌بار برای هر سطح) صادر می‌شود و ورود نگه داشته می‌شود؛ سیگنال رد نمی‌شود و
# با هر کندل بسته‌شده‌ی جدید BTC دوباره سنجیده می‌شود (سطح شکسته شود → سطح بعدی؛ یا BTC از سطح برگردد → فاصله زیاد می‌شود).
# اگر داده‌ی BTC/سطوح در دسترس نباشد هم ورود نگه داشته می‌شود. «⚡ ورود سریع»، تایید دستی کارت دستیار، اوردر معلق و هر مسیر ورود دیگر هم
# از همین سنجش می‌گذرند (پیش‌بررسی در execute_trade/execute_manual_trade): تا فاصله معقول نشود ورود انجام نمی‌شود (حتی با اصرار کاربر).
BTC_FRONT_MIN_ATR = max(0.0, float(os.environ.get('BTC_FRONT_MIN_ATR', '1.0') or 0))
BTC_FRONT_WARN_TTL = 1800.0
# V3.44.55: فیلتر «BTC در حالت نامشخص (کلاف دور سطح)»: اگر در N کندل بسته‌شده‌ی اخیر، کلوز BTC دست‌کم M بار از نزدیک‌ترین سطح رد و برگشت کرده باشد،
# BTC تصمیم نگرفته و ورود (خرید و فروش هر دو) بسته می‌ماند؛ سیگنال رد نمی‌شود و با هر کندل جدید دوباره سنجیده می‌شود.
# استثنا: اگر آخرین K کلوز همه یک طرف سطح باشند و کلوز آخر دست‌کم X×ATR از سطح فاصله داشته باشد، BTC تصمیم گرفته (شکست قطعی) و کلاف حساب نمی‌شود.
# کلیدهای strategy_config: btc_chop_flips (۰ = خاموش)، btc_chop_window، btc_chop_clear_closes، btc_chop_clear_atr؛ یا متغیرهای محیطی BTC_CHOP_*.
BTC_CHOP_FLIPS = max(0, int(float(os.environ.get('BTC_CHOP_FLIPS', '3') or 0)))
BTC_CHOP_WINDOW = max(4, int(float(os.environ.get('BTC_CHOP_WINDOW', '16') or 16)))
BTC_CHOP_CLEAR_CLOSES = max(1, int(float(os.environ.get('BTC_CHOP_CLEAR_CLOSES', '3') or 3)))
BTC_CHOP_CLEAR_ATR = max(0.0, float(os.environ.get('BTC_CHOP_CLEAR_ATR', '0.5') or 0))
_BTC_FRONT_PREFIX = '⚠️ هشدار ورود'
_BTC_FRONT_CACHE = {}
_BTC_FRONT_WARNED = {}
_BTC_FRONT_LOCK = threading.Lock()


def btc_front_level_info(s, tf, is_long):
    """سنجش فاصله‌ی کلوز آخرین کندل بسته‌شده‌ی BTC تا نزدیک‌ترین سطح روبه‌روی جهت معامله.
    خروجی dict: ok، close، atr، front_price/front_label (None = سطحی روبه‌رو نیست)، dist، dist_atr، min_atr، closed_ts؛ یا None اگر داده نبود."""
    secs = _TF_SECONDS.get(tf)
    if not secs:
        return None
    period = TIMEFRAME_MAP.get(tf, tf)
    limit = 650 if tf in ('5min', '15min', '1hour') else 200
    df = None
    for attempt in (0, 1):
        now = time.time()
        start = int(now // secs) * secs
        try:
            df = get_klines('BTC', tf, limit)
        except Exception:
            logger.exception('btc front: klines failed tf=%s', tf)
            df = None
        if df is None or len(df) < 62:
            return None
        ts = float(df.iloc[-1]['timestamp'])
        if ts > 1e11:
            ts /= 1000.0
        if start - 1 <= ts <= now + 1:
            break
        if attempt == 0:
            with DATA_LOCK:
                DATA_CACHE.pop(f'BTC:{period}:{limit}', None)
        else:
            return None
    cts = float(df.iloc[-2]['timestamp'])
    cfg0 = {**STRATEGY_DEFAULTS, **(s.get('strategy_config') or {})}
    min_atr = cfg0.get('btc_front_min_atr')
    min_atr = BTC_FRONT_MIN_ATR if min_atr is None else max(0.0, float(min_atr))
    def _ci(key, default, lo=0):
        v = cfg0.get(key)
        try:
            return default if v is None else max(lo, int(float(v)))
        except Exception:
            return default
    def _cf(key, default):
        v = cfg0.get(key)
        try:
            return default if v is None else max(0.0, float(v))
        except Exception:
            return default
    chop_flips = _ci('btc_chop_flips', BTC_CHOP_FLIPS)
    chop_win = _ci('btc_chop_window', BTC_CHOP_WINDOW, 4)
    chop_k = _ci('btc_chop_clear_closes', BTC_CHOP_CLEAR_CLOSES, 1)
    chop_x = _cf('btc_chop_clear_atr', BTC_CHOP_CLEAR_ATR)
    ckey = (_venue(), tf, cts, bool(is_long), round(min_atr, 4), chop_flips, chop_win, chop_k, round(chop_x, 4), bool(cfg0.get('halving_model_enabled')), cfg0.get('halving_k_atr'),
            cfg0.get('halving_min_depth'), cfg0.get('halving_max_depth'), bool(cfg0.get('halving_dynamic_k')),
            bool(cfg0.get('halving_only_targets', True)))
    with _BTC_FRONT_LOCK:
        hit = _BTC_FRONT_CACHE.get(ckey)
    if hit is not None:
        return dict(hit)
    ind = calculate_indicators(df)
    closed = ind.iloc[-2]
    close = float(closed['close'])
    atr = float(closed.get('atr') or 0)
    if not (math.isfinite(close) and close > 0 and math.isfinite(atr) and atr > 0):
        return None
    cfg = cfg0
    if cfg.get('halving_model_enabled'):
        rng = get_halving_range_sync('BTC')
        if not rng:
            return None
        cfg = _with_halving_cfg(cfg, rng)
    _grid = _log_grid_levels_sync('BTC')
    levels = _quick_opposing_levels(ind, close, bool(is_long), _grid, cfg)
    info = {'ok': True, 'close': close, 'atr': atr, 'front_price': None, 'front_label': None, 'dist': None, 'dist_atr': None,
            'min_atr': min_atr, 'closed_ts': cts, 'is_long': bool(is_long),
            'side_ok': True, 'ref_price': None, 'ref_label': None, 'ref_above': None,
            'chop': False, 'chop_flips': 0, 'chop_window': 0}
    if levels:
        fp, fl = min(levels, key=lambda t: abs(t[0] - close))
        dist = abs(float(fp) - close)
        info.update(front_price=float(fp), front_label=fl, dist=dist, dist_atr=dist / atr, ok=(dist / atr) >= min_atr)
    # V3.44.54: «سمت درست سطح»: نزدیک‌ترین سطحِ BTC (از هر دو طرف) به کلوز آخرین کندل بسته‌شده، مرجع است.
    # خرید فقط وقتی کلوز BTC بالای این سطح باشد، فروش فقط وقتی پایین آن؛ در غیر این صورت ورود بسته است.
    try:
        _other = _quick_opposing_levels(ind, close, not bool(is_long), _grid, cfg)
    except Exception:
        _other = []
    _all = list(levels or []) + list(_other or [])
    if _all:
        rp, rl = min(_all, key=lambda t: abs(t[0] - close))
        above = float(rp) > close
        info.update(ref_price=float(rp), ref_label=rl, ref_above=above, side_ok=((not above) if is_long else above))
        # V3.44.55: کلاف دور سطح (تعداد رد و برگشت کلوزها از سطح مرجع در چند کندل بسته‌شده‌ی اخیر)
        if chop_flips > 0:
            try:
                _cl = [float(x) for x in ind['close'].iloc[-(chop_win + 1):-1] if math.isfinite(float(x))]
                _sg = [1 if c_ > float(rp) else -1 for c_ in _cl if c_ != float(rp)]
                flips = sum(1 for a_, b_ in zip(_sg, _sg[1:]) if a_ != b_)
                tail = _sg[-chop_k:]
                decisive = (len(tail) == chop_k and len(set(tail)) == 1 and abs(close - float(rp)) / atr >= chop_x)
                info.update(chop=(flips >= chop_flips and not decisive), chop_flips=flips, chop_window=len(_sg))
            except Exception:
                logger.exception('btc chop: failed')
    with _BTC_FRONT_LOCK:
        if len(_BTC_FRONT_CACHE) > 64:
            _BTC_FRONT_CACHE.clear()
        _BTC_FRONT_CACHE[ckey] = dict(info)
    return info


def _gate_label(key):
    """نام دقیق دکمه‌ی یک کلید در منوی فیلترها (GATE_REGISTRY یا دکمه‌های «قوانین معامله»)."""
    try:
        return GATE_REGISTRY[key][0]
    except Exception:
        pass
    try:
        return _filter_info(key)[0]
    except Exception:
        return key


# V3.44.74: متن ساده‌ی هر «دلیل رد ورود» برای کاربر عادی (بدون هیچ حرفی از کلید/فیلتر/اصطلاح تخصصی).
# هر دلیل (متن کامل ادمین) هنگام ثبت با متن سادهٔ خودش جفت می‌شود؛ مسیرهای پیام با block_simple_text آن را پیدا می‌کنند.
_BLOCK_SIMPLE = {}
_BLOCK_SIMPLE_GENERIC = 'در این شرایط ورود به معامله مجاز نیست. لطفاً صبور باشید.'


def _block_simple_register(reason, simple):
    if not reason or not simple:
        return
    if len(_BLOCK_SIMPLE) > 400:
        _BLOCK_SIMPLE.clear()
    _BLOCK_SIMPLE[str(reason)] = simple


def block_simple_text(text, default=None):
    """متن ساده‌ی کاربر عادی برای یک دلیل رد ورود؛ اگر ثبت نشده بود default."""
    if not text:
        return default
    t = str(text)
    hit = _BLOCK_SIMPLE.get(t)
    if hit:
        return hit
    for k_, v_ in _BLOCK_SIMPLE.items():
        if k_ and k_ in t:
            return v_
    return default


def _btc_gate_key_line(*keys):
    """V3.44.73: خط «کلید مانع» برای ادمین: نام دقیقِ دکمه‌ی همان کلید در منوی فیلترها (از GATE_REGISTRY)."""
    names = []
    for k in keys:
        nm = _gate_label(k)
        if nm not in names:
            names.append(nm)
    if not names:
        return ''
    return '\n🔑 کلید مانع: ' + ' + '.join(f'«{n}»' for n in names)


# V3.44.73: متن ساده‌ی هشدار ورود برای کاربر عادی (بدون هیچ اصطلاح تخصصی)؛ کلید = info['block'] (chop/side/near) یا nodata.
_BTC_FRONT_SIMPLE = {
    'chop': 'بیتکوین الان در یک کلاف قیمتی است و هنوز مسیرش مشخص نیست؛ در این شرایط ورود به معامله مجاز نیست. لطفاً صبور باشید.',
    'side': 'بیتکوین هنوز با این معامله هم‌سو نشده؛ در این شرایط ورود به معامله مجاز نیست. لطفاً صبور باشید.',
    'near': 'بیتکوین به یک قیمت مهم نزدیک است و هنوز معلوم نیست از آن برمی‌گردد یا رد می‌شود؛ در این شرایط ورود به معامله مجاز نیست. لطفاً صبور باشید.',
    'nodata': 'اطلاعات بیتکوین فعلاً کامل نیست؛ در این شرایط ورود به معامله مجاز نیست. لطفاً صبور باشید.',
}


def btc_front_level_verdict(s, tf, sig, front=True, chop=True):
    """(ok, توضیح، info). sig = 'BUY'/'SELL' (جهت نهایی معامله). ok وقتی فاصله‌ی BTC تا سطح جلویی معقول (یا سطحی روبه‌رو نیست) باشد.
    front: چک «سمت سطح + فاصله» (کلید gate_btc_front_level_enabled)؛ chop: چک «کلاف دور سطح» (کلید مستقل gate_btc_chop_enabled)."""
    tf_fa = TF_DISPLAY.get(tf, tf)
    info = btc_front_level_info(s, tf, sig == 'BUY')
    if info is None:
        return False, (f'{_BTC_FRONT_PREFIX}: داده‌ی BTC برای سنجش فاصله تا سطح جلویی ({tf_fa}) در دسترس نیست؛ '
                       f'منتظر ورود می‌مانیم، لطفاً صبور باشید'
                       + _btc_gate_key_line(*(([ 'gate_btc_front_level_enabled'] if front else []) + (['gate_btc_chop_enabled'] if chop else [])))), None
    if chop and info.get('chop'):
        # V3.44.55: BTC دور سطح کلاف است (رد و برگشت‌های پیاپی) → ورود هر دو جهت بسته است تا BTC تصمیم بگیرد.
        info['warn_price'] = info.get('ref_price')
        info['block'] = 'chop'
        return False, (f"{_BTC_FRONT_PREFIX}: بیتکوین (BTC) دور سطح {info['ref_label']} {fmt(info['ref_price'])} در حالت نامشخص است "
                       f"({info['chop_flips']} بار رد و برگشت کلوز از سطح در {info['chop_window']} کندل بسته‌شده‌ی اخیر · {tf_fa})؛ "
                       f"تا تصمیم‌گیری BTC و بسته شدن چند کندل پشت‌سرهم یک طرف سطح، ورود انجام نمی‌شود. سیگنال رد نمی‌شود و منتظر می‌مانیم، لطفاً صبور باشید"
                       + _btc_gate_key_line('gate_btc_chop_enabled')), info
    if not front:
        return True, '', info          # V3.44.55: فقط کلید «کلاف» روشن است؛ چک سمت سطح و فاصله اعمال نمی‌شود
    if not info.get('side_ok', True):
        # V3.44.54: کلوز کندل بسته‌شده‌ی BTC سمت درستِ سطح نیست (خرید: باید بالای سطح؛ فروش: باید پایین سطح) → ورود بسته است.
        info['warn_price'] = info.get('ref_price')
        info['block'] = 'side'
        pos_fa = 'بالای' if info.get('ref_above') is False else 'زیر'
        need_fa = 'بالای' if sig == 'BUY' else 'زیر'
        side_fa = 'خرید' if sig == 'BUY' else 'فروش'
        return False, (f"{_BTC_FRONT_PREFIX}: کلوز آخرین کندل بسته‌شده‌ی BTC ({tf_fa}) {pos_fa} سطح {info['ref_label']} {fmt(info['ref_price'])} است "
                       f"(کلوز {fmt(info['close'])}) و با {side_fa} نمی‌خواند؛ ورود فقط وقتی انجام می‌شود که BTC {need_fa} سطح ببندد. "
                       f"سیگنال رد نمی‌شود و منتظر می‌مانیم، لطفاً صبور باشید"
                       + _btc_gate_key_line('gate_btc_front_level_enabled')), info
    if info['ok']:
        return True, '', info
    kind = 'مقاومتی' if sig == 'BUY' else 'حمایتی'
    info['block'] = 'near'
    return False, (f"{_BTC_FRONT_PREFIX}: بیتکوین (BTC) به سطح {kind} نزدیک است و تا واکنش به سطح منتظر ورود می‌مانیم؛ لطفاً صبور باشید "
                   f"({info['front_label']} {fmt(info['front_price'])} · فاصله {info['dist_atr']:.2f}×ATR · {tf_fa})"
                   + _btc_gate_key_line('gate_btc_front_level_enabled')), info


def _btc_front_warn(chat_id, symbol, sig, tf, txt, info):
    """هشدار ورود: برای هر (چت، نماد، جهت، سطح جلویی) در هر ۳۰ دقیقه حداکثر یک‌بار (تیک‌های پشت‌سرهم پیام تکراری نمی‌سازند)."""
    fp = (info.get('warn_price') or info.get('front_price')) if info else None
    key = (chat_id, symbol, sig, round(float(fp), 6) if fp else 'na')
    now = time.time()
    with _BTC_FRONT_LOCK:
        last = _BTC_FRONT_WARNED.get(key)
        if last and now - last < BTC_FRONT_WARN_TTL:
            return
        _BTC_FRONT_WARNED[key] = now
        if len(_BTC_FRONT_WARNED) > 500:
            for k_ in [k_ for k_, t_ in _BTC_FRONT_WARNED.items() if now - t_ > BTC_FRONT_WARN_TTL]:
                _BTC_FRONT_WARNED.pop(k_, None)
    side_fa = 'خرید' if sig == 'BUY' else 'فروش'
    try:
        _simple = _BTC_FRONT_SIMPLE.get((info or {}).get('block') or 'nodata', _BTC_FRONT_SIMPLE['nodata'])
        # V3.44.73: ادمین متن کامل + نام دقیق کلید مانع؛ کاربر عادی یک جمله‌ی ساده (بدون اصطلاح تخصصی)
        send_detail_message(chat_id, f"{txt}\n\n`{symbol}` · سیگنال {side_fa}", simple_text=f"⚠️ {_simple}\n\n`{symbol}` · سیگنال {side_fa}")
    except Exception:
        logger.exception('btc front: warning send failed chat=%s symbol=%s', chat_id, symbol)


def _btc_front_gate(chat_id, s, symbol, sig, tf, warn=True, allow_inverse=True, front=True, chop=True):
    """(ok, توضیح). جهتِ سنجیده‌شده جهتِ نهایی معامله است (با «معاملات معکوس» روشن و allow_inverse برعکس می‌شود).
    warn=True: وقتی ok نیست، هشدار ورود یک‌بار (به ازای هر سطح) فرستاده می‌شود؛ فراخواننده سیگنال را (بدون رد کردن) نگه می‌دارد.
    مسیرهای دستی warn=False می‌گیرند چون دلیل رد را خودشان به کاربر نشان می‌دهند."""
    eff = sig
    if allow_inverse and gate_on(s, 'gate_inverse_trading_enabled'):
        eff = 'SELL' if sig == 'BUY' else 'BUY'
    try:
        ok, txt, info = btc_front_level_verdict(s, tf, eff, front=front, chop=chop)
    except Exception:
        logger.exception('btc front gate failed symbol=%s', symbol)
        ok, txt, info = False, (f'{_BTC_FRONT_PREFIX}: خطا در سنجش فاصله تا سطح جلویی BTC؛ منتظر ورود می‌مانیم، لطفاً صبور باشید'
                                + _btc_gate_key_line(*(([ 'gate_btc_front_level_enabled'] if front else []) + (['gate_btc_chop_enabled'] if chop else [])))), None
    if not ok:
        _block_simple_register(txt, _BTC_FRONT_SIMPLE.get((info or {}).get('block') or 'nodata', _BTC_FRONT_SIMPLE['nodata']))
    if not ok and warn:
        _btc_front_warn(chat_id, symbol, sig, tf, txt, info)
    return ok, txt


def btc_eth_regime_rows(tf):
    """رژیم BTC و ETH روی تایم‌فریم tf با همان معیار داشبورد بازار/گیت (close نسبت به EMA50 و EMA20 نسبت به EMA50،
    آخرین کندل بسته‌شده). خروجی: [(نماد، رژیم یا None، ADX یا None، RSI یا None)]"""
    rows = []
    for sym in ('BTC', 'ETH'):
        snap = None
        try:
            snap = _trend_snapshot_cached(sym, tf)
        except Exception:
            logger.exception('btc/eth regime snapshot failed sym=%s tf=%s', sym, tf)
        if not snap:
            rows.append((sym, None, None, None))
            continue
        sc = snap.get('score', 0)
        rows.append((sym, 'BULLISH' if sc > 0 else ('BEARISH' if sc < 0 else 'RANGE'), snap.get('adx'), snap.get('rsi')))
    return rows


def btc_eth_aligned(tf):
    """(ok, توضیح): True فقط وقتی رژیم BTC و ETH روی تایم‌فریم tf هر دو صعودی یا هر دو نزولی باشند.
    رنج، ناهم‌جهت یا نبود داده = False. (کلید gate_btceth_aligned_enabled)"""
    rows = btc_eth_regime_rows(tf)
    regs = [r[1] for r in rows]
    fa = {'BULLISH': 'صعودی', 'BEARISH': 'نزولی', 'RANGE': 'رنج'}
    if not all(regs):
        return False, 'رژیم BTC/ETH در دسترس نیست'
    if regs[0] == regs[1] and regs[0] in ('BULLISH', 'BEARISH'):
        return True, f'هر دو {fa[regs[0]]}'
    if regs[0] == regs[1]:
        return False, 'هر دو رنج'
    return False, f'BTC {fa[regs[0]]} و ETH {fa[regs[1]]} (ناهم‌جهت)'


def btc_eth_regime_text(tf, popup=False, plain=False):
    """plain=True (کاربر عادی): فقط رژیم هر نماد و هم‌جهتی؛ بدون ADX/RSI و توضیح پارامترها."""
    rows = btc_eth_regime_rows(tf)
    tf_label = TF_DISPLAY.get(tf, tf)
    icons = {'BTC': '₿', 'ETH': 'Ξ'}
    if popup:
        lines = [f'🧭 رژیم BTC/ETH ({tf_label})']
        for sym, reg, adx, rsi in rows:
            lines.append(f"{icons[sym]} {sym}: {_REGIME_FA.get(reg, '⏳ نامشخص')}" + (f' (ADX {adx:.0f})' if adx is not None else ''))
        return '\n'.join(lines)
    lines = [f'🧭 *رژیم BTC و ETH — تایم‌فریم فعال ({tf_label})*', '━━━━━━━━━━━━━━━━━━━━']
    for sym, reg, adx, rsi in rows:
        extra = f" · ADX `{adx:.0f}` · RSI `{rsi:.0f}`" if (not plain and adx is not None and rsi is not None) else ''
        lines.append(f"{icons[sym]} {sym}: *{_REGIME_FA.get(reg, '⏳ نامشخص')}*{extra}")
    regs = [r[1] for r in rows]
    if all(regs) and regs[0] == regs[1]:
        lines.append(f"\n✅ هر دو هم‌جهت: {_REGIME_FA[regs[0]]}")
    elif all(regs):
        lines.append('\n⚠️ دو رژیم هم‌جهت نیستند.')
    if regime_advanced_on() and not plain:
        lines.append(f"ℹ️ صعودی/نزولی یعنی: EMA20/50 هم‌جهت + ADX ≥ {REGIME_ADX_MIN:g} + DI هم‌جهت + شیب EMA50 هم‌جهت؛ وگرنه رنج.")
    lines.append(f"🕒 {datetime.now().strftime('%H:%M:%S')}")
    return '\n'.join(lines)


def _channel_fixed_row():
    return [{'text': '📋 لیست بررسی‌های آتی', 'callback_data': '/chlist'},
            {'text': '🧭 رژیم BTC/ETH', 'callback_data': '/chreg'}]


def _channel_fixed_rows():
    """V3.43.2: ردیف‌های ثابت کانال: لیست + رژیم، و فیلتر لیست بررسی‌ها روی سیگنال‌های خرید / فروش."""
    return [_channel_fixed_row(),
            [{'text': '🟢 فقط خرید‌ها', 'callback_data': '/chlist_buy'},
             {'text': '🔴 فقط فروش‌ها', 'callback_data': '/chlist_sell'}]]


def _signal_channel_ensure_panel():
    """یک‌بار یک پیام ثابت (بدون حذف خودکار) با دکمه‌های «لیست بررسی‌های آتی» و «رژیم BTC/ETH» در کانال می‌فرستد و پین می‌کند.
    شناسه‌ی پیام در فایل JSON می‌ماند تا با ری‌استارت دوباره ارسال نشود (مگر SIGNAL_CHANNEL_PANEL_REPOST=true)."""
    global _CHANNEL_PANEL_ID
    if not SIGNAL_CHANNEL_ID:
        return
    _review_load()
    if _CHANNEL_PANEL_ID and not SIGNAL_CHANNEL_PANEL_REPOST:
        # پنل قبلاً ارسال شده؛ فقط دکمه‌هایش به‌روز می‌شود (مثلاً افزوده‌شدن دکمه‌های فیلتر خرید/فروش)
        tg('editMessageReplyMarkup', {'chat_id': SIGNAL_CHANNEL_ID, 'message_id': _CHANNEL_PANEL_ID,
                                      'reply_markup': {'inline_keyboard': _channel_fixed_rows()}}, 10)
        return
    text = '🎛 پنل ثابت کانال\nلیست نمادهای ذخیره‌شده برای بررسی و رژیم BTC/ETH روی تایم‌فریم فعال را با دکمه‌های زیر ببینید.'
    mid = send_channel_message(SIGNAL_CHANNEL_ID, text, reply_markup={'inline_keyboard': _channel_fixed_rows()}, ttl_seconds=0)
    if not mid:
        return
    _CHANNEL_PANEL_ID = mid
    _review_save()
    res = tg('pinChatMessage', {'chat_id': SIGNAL_CHANNEL_ID, 'message_id': mid, 'disable_notification': True}, 10)
    if not res or not res.get('ok'):
        logger.warning('pin of channel panel failed (ربات باید در کانال ادمین با دسترسی Pin Messages باشد)')


def review_list_show(chat_id, message_id=None, side=None):
    """لیست کامل بررسی‌های آتی داخل ربات (جابه‌جایی در همان پیام؛ حذف تکی/کامل + چارت)."""
    items = _review_items(chat_id, side)
    total = len(_review_items(chat_id))
    now = time.time()
    ftxt = f' — {_REVIEW_FILTER_TITLE[side]}' if side in _REVIEW_FILTER_TITLE else ''
    lines = [f'📋 *بررسی‌های آتی{ftxt} ({len(items)}' + (f' از {total}' if side in _REVIEW_FILTER_TITLE else '') + ')*', '']
    rows = [[{'text': ('✅ ' if side is None else '') + '📋 همه', 'callback_data': '/review_list'},
             {'text': ('✅ ' if side == 'BUY' else '') + '🟢 خرید', 'callback_data': '/review_list_buy'},
             {'text': ('✅ ' if side == 'SELL' else '') + '🔴 فروش', 'callback_data': '/review_list_sell'}]]
    if not items:
        lines.append('موردی با این فیلتر نیست.' if total else 'هنوز نمادی ذخیره نشده. زیر هر سیگنال کانال دکمه‌ی «💾 ذخیره برای بررسی بعدی» را بزنید.')
    for n, it in enumerate(items[:20], 1):
        side = it.get('side')
        side_txt = '🟢 خرید' if side == 'BUY' else ('🔴 فروش' if side == 'SELL' else '⚪️ بدون جهت')
        tf = it.get('tf') or '5min'
        mins = max(0, int((now - float(it.get('saved_at') or now)) // 60))
        age = f'{mins} دقیقه' if mins < 120 else (f'{mins // 60} ساعت' if mins < 2880 else f'{mins // 1440} روز')
        lines.append(f"{n}) `{it['symbol']}` {side_txt} · {TF_DISPLAY.get(tf, tf)} · {age} پیش")
        detail = f"    🎯 {it.get('level_label', '')} `{fmt(float(it['level_value']))}`" if it.get('level_value') is not None else ''
        if it.get('pattern'):
            detail += f" · {_signal_channel_pattern_label(it['pattern'], it.get('side_fa', ''))}"
        if detail:
            lines.append(detail)
        if it.get('price'):
            lines.append(f"    💵 قیمت هنگام سیگنال `{fmt(float(it['price']))}`")
        rows.append([{'text': f"📌 {it['symbol']} · کارت سیگنال", 'callback_data': f"/rvshow_{it.get('msg_id')}"},
                     {'text': '📈', 'url': tradingview_chart_url(it['symbol'], tf)},
                     {'text': '🗑', 'callback_data': f"/rvdel_{it.get('msg_id')}"}])
    if len(items) > 20:
        lines.append(f'\n… و {len(items) - 20} مورد دیگر (قدیمی‌ترها)')
    ctl = [{'text': '🔄 بروزرسانی', 'callback_data': {'BUY': '/review_list_buy', 'SELL': '/review_list_sell'}.get(side, '/review_list')}]
    if total:
        ctl.append({'text': '🧹 خالی‌کردن لیست من', 'callback_data': '/rvclear'})
    rows.append(ctl)
    rows.append([{'text': '🏠 منوی اصلی', 'callback_data': '/menu'}])
    send_message(chat_id, '\n'.join(lines), {'inline_keyboard': rows}, message_id=message_id)


def review_card_show(chat_id, msg_id):
    """V3.43.5: با لمس نماد در «بررسی‌های آتی»، کارت سیگنال همان نماد (همان پیام کانال: چارت + متن) در چت ربات می‌آید.
    اول خودِ پست کانال کپی می‌شود (عکس چارت + متن اصلی)؛ اگر پست دیگر در کانال نبود، متن ذخیره‌شده‌ی کارت فرستاده می‌شود."""
    it = next((x for x in _review_items(chat_id) if x.get('msg_id') == msg_id), None)
    if not it:
        send_message(chat_id, 'ℹ️ این مورد دیگر در لیست بررسی‌های آتی شما نیست.', {'inline_keyboard': [[{'text': '📋 بررسی‌های آتی', 'callback_data': '/review_list'}]]}, keep=True)
        return
    sym, tf = it['symbol'], it.get('tf') or '5min'
    markup = {'inline_keyboard': [
        [{'text': '📈 چارت در TradingView', 'url': tradingview_chart_url(sym, tf)}],
        [{'text': '🟢 خرید (Long)', 'callback_data': f'/qt_buy_{sym}'}, {'text': '🔴 فروش (Short)', 'callback_data': f'/qt_sell_{sym}'}],
        [{'text': '📋 بازگشت به لیست', 'callback_data': '/review_list'}]]}
    res = None
    if SIGNAL_CHANNEL_ID:
        res = tg('copyMessage', {'chat_id': chat_id, 'from_chat_id': SIGNAL_CHANNEL_ID, 'message_id': msg_id, 'reply_markup': markup}, 15)
    if res and res.get('ok'):
        return
    text = it.get('text')
    if text:
        send_message(chat_id, text, markup, keep=True)
    else:
        send_message(chat_id, f"ℹ️ کارت قدیمیِ `{sym}` دیگر در دسترس نیست (پست کانال حذف شده).", markup, keep=True)


