_SETTINGS_KEYS = ('leverage', 'risk_per_trade_pct', 'max_open_positions', 'max_same_direction_positions',
                  'same_direction_entry_cooldown_seconds', 'max_total_open_risk_pct', 'profit_autoclose_enabled',
                  'total_profit_autoclose_enabled', 'fav_confirm_enabled', 'fav_confirm_min_r', 'fav_confirm_max_r',
                  'fav_confirm_max_mode', 'fav_confirm_max_tp_pct', 'fav_confirm_wait_sec', 'fav_close_5m_enabled', 'fav_close_15m_enabled', 'touch_auto_mode', 'timeframe', 'active_strategy',
                  'be_close_alert_enabled', 'be_close_auto_enabled', 'be_close_profit_r', 'be_close_loss_r', 'btc_guard_enabled', 'btc_guard_frac', 'trail_enabled', 'trail_profile', 'hours_filter_enabled', 'hours_profile',
                  'enabled_setup_tags', 'trading_mode', 'active_preset', 'daily_loss_limit_pct', 'max_margin_usage_pct',
                  'manual_block_buy_entries', 'manual_block_sell_entries', 'manual_block_all_entries')
_SETTINGS_LOCK = RLock()
_SETTINGS_REGISTRY = {}
PATH_LOG_MAX = 300


def _settings_registry_path():
    return os.path.join(os.path.dirname(os.path.abspath(DB_PATH)), 'settings_registry.json')


def _settings_register(s):
    """V3.44.12: تنظیمات و کلیدهای فعال لحظه‌ی ورود را به یک هش کوتاه تبدیل می‌کند و متن کامل را یک‌بار در
    settings_registry.json نگه می‌دارد؛ هر معامله فقط هش را دارد (settings_hash)."""
    try:
        cfg = {k: s.get(k) for k in _SETTINGS_KEYS}
        cfg['strategy_config'] = dict(s.get('strategy_config') or {})
        cfg['filters'] = dict(s.get('filters') or {})
        raw = json.dumps(cfg, sort_keys=True, ensure_ascii=False, default=str)
        h = hashlib.sha1(raw.encode('utf-8')).hexdigest()[:10]
        with _SETTINGS_LOCK:
            if h not in _SETTINGS_REGISTRY:
                _SETTINGS_REGISTRY[h] = True
                path = _settings_registry_path()
                data = {}
                if os.path.exists(path):
                    try:
                        with open(path, 'r', encoding='utf-8') as fh:
                            data = json.load(fh)
                    except Exception:
                        data = {}
                if h not in data:
                    data[h] = {'first_seen': time.time(), 'first_seen_text': fmt_scan_time(time.time()), 'bot_version': BOT_VERSION, 'config': json.loads(raw)}
                    if len(data) > 300:
                        for k in sorted(data, key=lambda x: data[x].get('first_seen', 0))[:len(data) - 300]:
                            data.pop(k, None)
                    tmp = path + '.tmp'
                    with open(tmp, 'w', encoding='utf-8') as fh:
                        json.dump(data, fh, ensure_ascii=False, indent=1, default=str)
                    os.replace(tmp, path)
        return h
    except Exception:
        logger.exception('settings register failed')
        return None


def _settings_lookup(hashes):
    try:
        path = _settings_registry_path()
        if not os.path.exists(path):
            return {}
        with _SETTINGS_LOCK:
            with open(path, 'r', encoding='utf-8') as fh:
                data = json.load(fh)
        return {h: data[h] for h in set(x for x in hashes if x) if h in data}
    except Exception:
        logger.debug('settings lookup failed', exc_info=True)
        return {}


def _path_log(pos, price):
    """V3.44.12: مسیر قیمت پوزیشن بر حسب R (مثبت = به نفع معامله) با ترتیب زمانی: [ثانیه از ورود, R].
    نقطه وقتی ثبت می‌شود که ≥۰.۱R از نقطه‌ی قبلی فاصله گرفته یا از ورود رد شده باشد؛ اکسترمم‌ها جدا نگه داشته می‌شوند."""
    try:
        bt = pos.get('be_track')
        if not isinstance(bt, dict): return
        entry = float(bt['entry']); rd = float(bt['risk_dist']); pr = float(price)
        if entry <= 0 or rd <= 0 or pr <= 0: return
        r = ((pr - entry) / rd) if bt['long'] else ((entry - pr) / rd)
        t = int(max(0.0, time.time() - float(pos.get('opened_at') or time.time())))
        if r > float(pos.get('path_max_r', -1e9)):
            pos['path_max_r'] = round(r, 3); pos['path_max_t'] = t
        if r < float(pos.get('path_min_r', 1e9)):
            pos['path_min_r'] = round(r, 3); pos['path_min_t'] = t
        path = pos.setdefault('path', [])
        last = path[-1][1] if path else None
        if last is None or abs(r - last) >= 0.1 or ((r > 0) != (last > 0)):
            path.append([t, round(r, 2)])
            if len(path) > PATH_LOG_MAX:
                del path[1:-1:2]
    except Exception as exc:
        logger.debug('path log failed trade=%s: %s', (pos or {}).get('trade_id'), exc)


BE_TRACK_TRIGGERS = (0.3, 0.5, 0.75)   # V3.44.11: تریگرهای ردیاب مجازی سر به سر (بر حسب R)


def _be_track(pos, price):
    """V3.44.11: ردیاب مجازی سر به سر. با ترتیب واقعی قیمت‌های لحظه‌ای (هر چرخه)، برای هر تریگر ثبت می‌کند که
    آیا قیمت به T×R رسیده («armed») و بعدش به قیمت ورود برگشته («hit») یا نه. فقط گزارش است."""
    try:
        bt = pos.get('be_track')
        if not isinstance(bt, dict): return
        entry = float(bt['entry']); rd = float(bt['risk_dist']); pr = float(price)
        if entry <= 0 or rd <= 0 or pr <= 0: return
        is_long = bool(bt['long'])
        now = time.time()
        for key, st in bt['levels'].items():
            if st.get('hit'): continue
            target = entry + float(key) * rd if is_long else entry - float(key) * rd
            if st.get('armed'):
                if (pr <= entry) if is_long else (pr >= entry):
                    st['hit'] = True; st['hit_at'] = now
            else:
                if (pr >= target) if is_long else (pr <= target):
                    st['armed'] = True; st['armed_at'] = now
    except Exception as exc:
        logger.debug('be tracking failed trade=%s: %s', (pos or {}).get('trade_id'), exc)


def _be_finalize(pos):
    """V3.44.11: نتیجه‌ی شبیه‌سازی سر به سر را حساب و در pos['be_sim'] ذخیره می‌کند؛ یک خط کوتاه برای پیام برمی‌گرداند."""
    try:
        bt = pos.get('be_track')
        if not isinstance(bt, dict): return ''
        margin = float(pos.get('margin') or 0.0); lev = float(pos.get('leverage') or 1.0); risk = float(pos.get('risk_usdt') or 0.0)
        if margin <= 0 or risk <= 0: return ''
        slip_usdt = margin * lev * ((PAPER_SLIPPAGE_BPS / 10000.0) if (not pos.get('is_real') and PAPER_SLIPPAGE_BPS > 0) else 0.0)
        cost_r = (float(round_trip_fee_usdt(margin, lev)) + slip_usdt) / risk
        actual_r = pos.get('realized_r')
        if actual_r is None: return ''
        actual_r = float(actual_r)
        out = {}; marks = []
        for key, st in bt['levels'].items():
            armed = bool(st.get('armed')); hit = bool(st.get('hit'))
            verdict = 'none'; sim_r = actual_r
            if hit:
                sim_r = -cost_r
                if sim_r > actual_r + 0.05: verdict = 'saved'
                elif sim_r < actual_r - 0.05: verdict = 'killed'
                else: verdict = 'neutral'
            out[key] = {'armed': armed, 'hit': hit, 'verdict': verdict, 'sim_r': round(sim_r, 3)}
            icon = {'saved': '✅', 'killed': '❌', 'neutral': '➖', 'none': ('·' if not armed else '⏭')}[verdict]
            marks.append(f"{float(key):g}R {icon}")
        pos['be_sim'] = {'cost_r': round(cost_r, 3), 'actual_r': round(actual_r, 3), 'levels': out}
        if not any(v['armed'] for v in out.values()): return ''
        return "\n• 🛡 سر به سر مجازی: " + " | ".join(marks) + ""
    except Exception:
        logger.exception('be finalize failed trade=%s', (pos or {}).get('trade_id'))
        return ''


def _shadow_track(pos, high, low):
    """V3.44.9: حالت سایه برای معامله‌ی معکوس - فقط گزارش، روی معامله‌ی واقعی اثری ندارد.
    اگر معامله با جهت عادیِ سیگنال باز شده بود، سطوح SL/TP عادی در این بازه‌ی قیمتی خورده بود یا نه؟"""
    try:
        sh = pos.get('shadow')
        if not isinstance(sh, dict) or sh.get('status') != 'open':
            return
        hi = float(high); lo = float(low)
        if side_long(sh['side']):
            hit_tp = hi >= float(sh['tp']); hit_sl = lo <= float(sh['sl'])
        else:
            hit_tp = lo <= float(sh['tp']); hit_sl = hi >= float(sh['sl'])
        if hit_tp and hit_sl:
            status = 'sl' if PAPER_CONSERVATIVE_OHLC else 'tp'
        elif hit_sl:
            status = 'sl'
        elif hit_tp:
            status = 'tp'
        else:
            return
        sh['status'] = status
        sh['closed_at'] = time.time()
        sh['exit_price'] = float(sh['sl'] if status == 'sl' else sh['tp'])
    except Exception as exc:
        logger.debug('shadow tracking failed trade=%s: %s', (pos or {}).get('trade_id'), exc)


def _shadow_finalize(pos, ref_price=None, actual_pnl=None):
    """V3.44.9: نتیجه‌ی سایه (معامله‌ی عادی) را حساب و در pos['shadow'] ذخیره می‌کند و متن گزارش را برمی‌گرداند."""
    try:
        sh = pos.get('shadow')
        if not isinstance(sh, dict):
            return ''
        entry = float(sh['entry']); margin = float(pos.get('margin') or 0.0); lev = float(pos.get('leverage') or 1.0)
        if entry <= 0 or margin <= 0:
            return ''
        is_long = side_long(sh['side'])
        status = sh.get('status')
        if status in ('tp', 'sl'):
            exit_p = float(sh['exit_price'])
            if not pos.get('is_real') and PAPER_SLIPPAGE_BPS > 0:
                slip = PAPER_SLIPPAGE_BPS / 10000.0
                exit_p = exit_p * (1.0 - slip) if is_long else exit_p * (1.0 + slip)
            end_ts = float(sh.get('closed_at') or time.time())
        else:
            exit_p = float(ref_price or latest_price(pos.get('symbol')) or entry)
            end_ts = time.time()
        frac = ((exit_p - entry) / entry) if is_long else ((entry - exit_p) / entry)
        gross = margin * frac * lev
        fee = round_trip_fee_usdt(margin, lev)
        hours = max(0.0, end_ts - float(pos.get('opened_at') or end_ts)) / 3600.0
        funding = 0.0 if pos.get('is_real') else margin * lev * (PAPER_FUNDING_RATE_PCT_8H / 100.0) * (hours / 8.0)
        pnl = gross - fee - funding
        risk = float(pos.get('risk_usdt') or 0.0)
        r = (pnl / risk) if risk > 0 else None
        sh['pnl_usdt'] = round(pnl, 4); sh['r'] = (round(r, 3) if r is not None else None)
        sh['final_price'] = exit_p; sh['reported'] = True
        r_txt = f" (`{r:+.2f}R`)" if r is not None else ''
        if status == 'tp':
            res = f"✅ به حد سود می‌خورد: `{pnl:+.2f} USDT`{r_txt}"
        elif status == 'sl':
            res = f"❌ به حد ضرر می‌خورد: `{pnl:+.2f} USDT`{r_txt}"
        else:
            res = f"⏳ تا لحظه‌ی بسته‌شدن این پوزیشن نه حد سود خورده بود نه حد ضرر؛ سود/زیان شناور: `{pnl:+.2f} USDT`{r_txt}"
        side_fa = 'خرید (Long)' if is_long else 'فروش (Short)'
        diff_line = ''
        if actual_pnl is not None:
            d = pnl - float(actual_pnl)
            diff_line = f"\n• اختلاف با معامله‌ی معکوس واقعی: `{d:+.2f} USDT` ({'عادی بهتر بود' if d > 0.005 else ('معکوس بهتر بود' if d < -0.005 else 'تقریباً برابر')})"
        return (f"\n\n🕶 *گزارش سایه (اگر معامله‌ی عادی بود)*\n• جهت عادی: `{side_fa}` | ورود `{fmt(entry)}` | SL `{fmt(sh['sl'])}` | TP `{fmt(sh['tp'])}`\n"
                f"• نتیجه: {res}{diff_line}\n• _تقریبی و بر پایه‌ی کندل‌ها؛ فقط گزارش است و روی معامله اثری ندارد_")
    except Exception:
        logger.exception('shadow finalize failed trade=%s', (pos or {}).get('trade_id'))
        return ''


def update_trade_excursions(pos, high, low):
    try:
        entry = float(pos.get('entry_price') or 0)
        margin = float(pos.get('margin') or 0)
        leverage = float(pos.get('leverage') or 1)
        risk = float(pos.get('risk_usdt') or 0)
        if entry <= 0 or margin <= 0 or leverage <= 0:
            return
        if side_long(pos.get('side')):
            favorable = max(0.0, float(high) - entry)
            adverse = max(0.0, entry - float(low))
            fav_price = float(high)
            adv_price = float(low)
        else:
            favorable = max(0.0, entry - float(low))
            adverse = max(0.0, float(high) - entry)
            fav_price = float(low)
            adv_price = float(high)
        scale = margin * leverage / entry
        mfe_usdt = favorable * scale
        mae_usdt = adverse * scale
        if mfe_usdt > float(pos.get('mfe_usdt') or 0.0):
            pos['mfe_usdt'] = mfe_usdt
            pos['peak_favorable_price'] = fav_price
        if mae_usdt > float(pos.get('mae_usdt') or 0.0):
            pos['mae_usdt'] = mae_usdt
            pos['peak_adverse_price'] = adv_price
        pos['mfe_r'] = (float(pos.get('mfe_usdt') or 0.0) / risk) if risk > 0 else 0.0
        pos['mae_r'] = (float(pos.get('mae_usdt') or 0.0) / risk) if risk > 0 else 0.0
        pos['last_price'] = float((float(high) + float(low)) / 2.0)
    except Exception as exc:
        logger.debug('excursion tracking failed trade=%s symbol=%s: %s', pos.get('trade_id'), pos.get('symbol'), exc)


def _paper_stop_fill_price(pos, low, high, risk_distance):
    """
    فیل واقع‌بینانه‌تر برای برخورد حد ضرر در PAPER.

    فرض «همیشه دقیقاً روی قیمت SL فیل می‌شویم» خوش‌بینانه است: وقتی کندل با
    فاصلهٔ زیاد از SL رد شده (ویک شدید، به‌خصوص روی آلت‌کوین‌های کم‌نقدشوندگی)،
    یک سفارش استاپ-مارکت واقعی احتمالاً بدتر از سطح دقیق SL پر می‌شود. اینجا
    بخشی از آن فاصلهٔ اضافه (overshoot) را به‌عنوان اسلیپیج به قیمت خروج اعمال
    می‌کنیم، با یک سقف مشخص تا معاملات با ویک‌های فوق‌العاده شدید هم به‌شکل
    غیرمنطقی جریمه نشوند. این تابع فقط دقتِ گزارش را بالا می‌برد؛ تصمیم اینکه
    SL خورده یا نه، جای دیگری (update_positions) گرفته می‌شود.
    """
    sl = float(pos.get('sl') or 0.0)
    is_long = side_long(pos.get('side'))
    # V3.42: استاپِ در سود اسلیپیج کمتری می‌خورد؛ ویکِ کندل ممکن است قبل از
    # جابه‌جایی استاپ رخ داده باشد و جریمه‌ی کامل برای ضرر عادی برای آن منصفانه نیست.
    entry_p = float(pos.get('entry_price') or 0.0)
    in_profit_stop = entry_p > 0 and ((sl > entry_p) if is_long else (sl < entry_p))
    frac = PAPER_LOCKED_STOP_SLIPPAGE_FRACTION if in_profit_stop else PAPER_STOP_SLIPPAGE_FRACTION
    max_r = PAPER_LOCKED_STOP_SLIPPAGE_MAX_R if in_profit_stop else PAPER_STOP_SLIPPAGE_MAX_R
    if risk_distance <= 0 or frac <= 0:
        return sl
    overshoot = (sl - float(low)) if is_long else (float(high) - sl)
    if overshoot <= 0:
        return sl
    charged = min(overshoot, max_r * risk_distance) * frac
    return (sl - charged) if is_long else (sl + charged)


def _entry_snapshot(symbol, side, timeframe, reason, price, sl):
    """V3.43.26: عکس‌فوری لحظه‌ی ورود برای تحلیل بعدیِ معامله‌ها (فقط ثبت؛ هیچ تصمیم ورود/خروجی را عوض نمی‌کند):
    ۱) جهت رژیم BTC/ETH (امتیاز EMA روی آخرین کندل بسته‌شده) نسبت به جهت معامله
    ۲) رأی RSI/MACD/ADX نسبت به جهت معامله (هم‌جهت / مخالف / خنثی) + مقدارهای خام
    ۳) آخرین کندل‌های بسته‌شده نسبت به سطح سیگنال (HVL یا ANCHOR داخل متن دلیل ورود)، و فاصله‌ی قیمت ورود از سطح به‌اندازه‌ی فاصله‌ی استاپ
    ۴) حجم: نسبت حجم آخرین کندل بسته‌شده به میانگین ۲۰ کندل (و میانگین ۳ کندل آخر)
    هر بخشی که داده‌اش نبود None می‌ماند."""
    is_long = str(side).upper().startswith('BUY')
    out = {'btc': None, 'eth': None, 'indicators': None, 'level': None, 'volume': None, 'symbol_tf_regimes': None, 'symbol_h4_regime': None, 'checked_at': time.time()}
    try:
        out['symbol_h4_regime'] = _symbol_h4_regime(symbol)
    except Exception:
        logger.exception('entry snapshot h4 failed symbol=%s', symbol)
    try:
        out['symbol_tf_regimes'] = _symbol_tf_regimes(symbol)
    except Exception:
        logger.exception('entry snapshot tf regimes failed symbol=%s', symbol)
    for key, sym in (('btc', 'BTC'), ('eth', 'ETH')):
        try:
            snap = _market_snapshot(sym, timeframe)
            if snap:
                sc = int(snap.get('score', 0))
                out[key] = {'score': sc, 'label': 'صعودی' if sc > 0 else ('نزولی' if sc < 0 else 'خنثی'),
                            'with_trade': None if sc == 0 else ((sc > 0) == is_long)}
        except Exception:
            logger.exception('entry snapshot regime failed sym=%s', sym)
    try:
        d = get_klines(symbol, timeframe, 160)
        if d is None or d.empty or len(d) < 60:
            return out
        ind = calculate_indicators(d)
        row = ind.iloc[-2]
        def _f(v):
            return None if v is None or pd.isna(v) else round(float(v), 4)
        rsi, adx = _f(row.get('rsi')), _f(row.get('adx'))
        pdi, mdi = _f(row.get('plus_di')), _f(row.get('minus_di'))
        # V3.43.31: MACD hist برای نمادهای ارزان (مثلاً قیمت ۰.۰۱) ~1e-5 است؛ گرد کردن به ۴ رقم اعشار آن را صفر و رأی را اشتباهاً «خنثی» می‌کرد.
        # حالا رأی از مقدار خام محاسبه می‌شود و مقدار ذخیره‌شده ۶ رقم معنادار دارد.
        _macd_raw = row.get('macd_hist')
        _macd_raw = None if _macd_raw is None or pd.isna(_macd_raw) else float(_macd_raw)
        macd_h = None if _macd_raw is None else float(f'{_macd_raw:.6g}')
        def _vote(bias):
            if bias is None:
                return 'neutral'
            return 'agree' if ((bias == 'BUY') == is_long) else 'against'
        rsi_bias = None
        if rsi is not None:
            rsi_bias = 'SELL' if rsi >= 70 else ('BUY' if rsi <= 30 else ('BUY' if rsi >= 55 else ('SELL' if rsi <= 45 else None)))
        macd_bias = None if _macd_raw in (None, 0) else ('BUY' if _macd_raw > 0 else 'SELL')
        adx_bias = None
        if adx is not None and adx >= 20 and pdi is not None and mdi is not None and pdi != mdi:
            adx_bias = 'BUY' if pdi > mdi else 'SELL'
        votes = {'rsi': _vote(rsi_bias), 'macd': _vote(macd_bias), 'adx': _vote(adx_bias)}
        out['indicators'] = {'rsi': rsi, 'macd_hist': macd_h, 'adx': adx, 'plus_di': pdi, 'minus_di': mdi, 'votes': votes,
                             'agree': sum(v == 'agree' for v in votes.values()), 'against': sum(v == 'against' for v in votes.values())}
        vol = d['volume'].astype(float)
        vma = vol.rolling(20).mean()
        ratios = []
        for i in (-2, -3, -4):
            try:
                ratios.append(float(vol.iloc[i] / vma.iloc[i]) if float(vma.iloc[i]) > 0 else None)
            except Exception:
                ratios.append(None)
        good = [r for r in ratios if r is not None]
        out['volume'] = {'last_closed_ratio': round(ratios[0], 2) if ratios and ratios[0] is not None else None,
                         'avg3_ratio': round(sum(good) / len(good), 2) if good else None}
        m = re.search(r'HVL=([0-9.]+)', reason or '') or re.search(r'ANCHOR=([0-9.]+)', reason or '')
        if m:
            lvl = float(m.group(1))
            closes = [float(ind.iloc[i].close) for i in (-2, -3, -4)]
            beyond = [(c > lvl) if is_long else (c < lvl) for c in closes]
            risk_px = abs(float(price) - float(sl))
            out['level'] = {'level': lvl, 'last_close': closes[0],
                            'last_close_side': 'above' if closes[0] > lvl else ('below' if closes[0] < lvl else 'at'),
                            'last_close_confirms': beyond[0],
                            'closed_candles_beyond_of_3': sum(beyond),
                            'entry_vs_level_r': round(((float(price) - lvl) * (1 if is_long else -1)) / risk_px, 3) if risk_px > 0 else None}
    except Exception:
        logger.exception('entry snapshot failed symbol=%s', symbol)
    return out


def _regime_alignment_snapshot(symbol, timeframe):
    """
    عکس‌فوری عددی سه لایه‌ای که در بحث «هم‌جهتی چندلایه» مطرح شد، در لحظه‌ی ورود:
    ۱) قدرت روند بازار کلی (میانگین ADX لیدرها، از کش refresh_market_regime)
    ۲) درصد اجماع صعودی/نزولی در تایم‌فریم فعال (از کش refresh_market_gate)
    ۳) ADX خود نماد در همان تایم‌فریم (محاسبه‌ی سبک، از کش get_klines موجود)

    فقط برای ثبت در رکورد معامله است؛ هیچ تصمیم ورود/خروجی را عوض نمی‌کند.
    اگر هرکدام در دسترس نبود، None برمی‌گردد تا بعداً به‌اشتباه به‌جای «صفر واقعی»
    خوانده نشود.
    """
    out = {'market_adx': None, 'timeframe_bull_pct': None, 'timeframe_bear_pct': None, 'symbol_adx': None}
    try:
        if MARKET_REGIME_CACHE.get('ts', 0) > 0:
            out['market_adx'] = round(float(MARKET_REGIME_CACHE.get('avg_adx') or 0.0), 2)
    except Exception:
        pass
    try:
        tf_cache = TIMEFRAME_REGIME_CACHE.get(_tfk(timeframe))
        if tf_cache:
            out['timeframe_bull_pct'] = round(float(tf_cache.get('bull_pct') or 0.0), 1)
            out['timeframe_bear_pct'] = round(float(tf_cache.get('bear_pct') or 0.0), 1)
    except Exception:
        pass
    try:
        d = get_klines(symbol, timeframe, 160)
        if d is not None and not d.empty and len(d) >= 60:
            x = calculate_indicators(d).iloc[-2]
            adx = x.get('adx')
            if adx is not None:
                out['symbol_adx'] = round(float(adx), 2)
    except Exception:
        pass
    return out


_LAST_BLOCK_REASON = {}


_BLK_CTX = {}
_REJECT_LOCK = RLock()
_REJECT_RECENT = {}
_REJECT_APPENDS = [0]


def _reject_log_path():
    return os.path.join(os.path.dirname(os.path.abspath(DB_PATH)), 'rejected_signals.jsonl')


def _reject_record(chat_id, reason):
    """V3.44.12: هر سیگنالی که به مرحله‌ی ورود رسید ولی رد شد (دلیل + قیمت‌ها) در rejected_signals.jsonl ثبت می‌شود.
    تکراری‌ها (همان نماد/جهت/دلیل) تا ۱۰ دقیقه ثبت نمی‌شوند."""
    try:
        ctx = _BLK_CTX.get(chat_id)
        now = time.time()
        if not ctx or now - float(ctx.get('ts') or 0) > 5.0:
            return
        key = (chat_id, ctx['symbol'], ctx['side'], str(reason)[:60])
        with _REJECT_LOCK:
            if now - _REJECT_RECENT.get(key, 0.0) < 600.0:
                return
            _REJECT_RECENT[key] = now
            if len(_REJECT_RECENT) > 4000:
                for k in [k for k, v in _REJECT_RECENT.items() if now - v > 600.0]:
                    _REJECT_RECENT.pop(k, None)
            rec = {'ts': now, 'time': fmt_scan_time(now), 'chat_id': chat_id, 'symbol': ctx['symbol'], 'side': ctx['side'],
                   'scenario': ctx.get('scenario'), 'signal_price': ctx.get('signal_price'), 'sl': ctx.get('sl'), 'tp': ctx.get('tp'),
                   'forced': bool(ctx.get('force')), 'reason': str(reason)[:300], 'bot_version': BOT_VERSION}
            path = _reject_log_path()
            with open(path, 'a', encoding='utf-8') as fh:
                fh.write(json.dumps(rec, ensure_ascii=False, default=str) + '\n')
            _REJECT_APPENDS[0] += 1
            if _REJECT_APPENDS[0] % 300 == 0:       # نگه‌داری فقط ۴۰۰۰ ردیف آخر
                with open(path, 'r', encoding='utf-8') as fh:
                    lines = fh.readlines()
                if len(lines) > 6000:
                    tmp = path + '.tmp'
                    with open(tmp, 'w', encoding='utf-8') as fh:
                        fh.writelines(lines[-4000:])
                    os.replace(tmp, path)
    except Exception:
        logger.debug('reject record failed', exc_info=True)


def _reject_tail(chat_id, n=500):
    try:
        path = _reject_log_path()
        if not os.path.exists(path):
            return []
        with _REJECT_LOCK:
            with open(path, 'r', encoding='utf-8') as fh:
                lines = fh.readlines()
        out = []
        for ln in lines[-4000:]:
            try:
                r = json.loads(ln)
            except Exception:
                continue
            if str(r.get('chat_id')) == str(chat_id):
                out.append(r)
        return out[-n:]
    except Exception:
        logger.debug('reject tail failed', exc_info=True)
        return []


def _blk(chat_id, reason, key=None, simple=None):
    """دلیل رد شدن ورود را نگه می‌دارد (برای نمایش در حالت دستیار) و False برمی‌گرداند.
    V3.44.74: key = کلید(های) مانع (برای ادمین نام دقیق دکمه به متن اضافه می‌شود)؛ simple = متن ساده برای کاربر عادی."""
    if key:
        reason = reason + _btc_gate_key_line(*((key,) if isinstance(key, str) else tuple(key)))
    if simple:
        _block_simple_register(reason, simple)
    _LAST_BLOCK_REASON[chat_id] = reason
    _reject_record(chat_id, reason)
    return False


def _execute_trade_unlocked(chat_id,symbol,side,signal_price,sl,tp,reason='',generation=None,require_active=True,structural_tp=False,plan_score=None,plan_rr=None,plan_quality_label=None,order_type=None,bypass_burst_cooldown=False,force=False,tp_level_name=None,tp_stages=None,keep_levels=False,allow_inverse=True):
    _LAST_BLOCK_REASON.pop(chat_id, None)
    try:
        _m_scn = re.search(r'SCN=(\d+)', reason or '')
        _BLK_CTX[chat_id] = {'ts': time.time(), 'symbol': symbol, 'side': side, 'signal_price': float(signal_price), 'sl': float(sl), 'tp': float(tp),
                             'scenario': int(_m_scn.group(1)) if _m_scn else None, 'force': bool(force)}
    except Exception:
        pass
    s=get_session(chat_id)
    # V3.44.61: کارمزد روزانه پرداخت‌نشده → ورود جدید (حتی دستی/دستیار/معلق) ممنوع؛ پوزیشن‌های باز همچنان مدیریت می‌شوند
    if is_fee_blocked(chat_id):
        return _blk(chat_id, '⛔ حساب به‌دلیل کارمزد پرداخت‌نشده مسدود است؛ ورود جدید ممکن نیست', key=None, simple='حساب شما فعلاً به\u200cخاطر کارمزد پرداخت\u200cنشده بسته است؛ تا تسویه، ورود جدید ممکن نیست.')
    # V3.43.15: ۳۰ دقیقه‌ی آخر کندل ۴ ساعته - هیچ معامله‌ای باز نمی‌شود (حتی force/دستی/دستیار)
    _blocked_4h, _rem_4h = four_h_close_block_active(s)
    if _blocked_4h:
        return _blk(chat_id, f'⏳ در ۳۰ دقیقه‌ی پایانی کندل ۴ ساعته هستیم ({_rem_4h:.0f} دقیقه تا بسته شدن)؛ ورود جدید تا شروع کندل بعدی ممنوع است', key='gate_4h_close_block_enabled', simple='الان در چند دقیقه\u200cی آخر یک بازه\u200cی چهارساعته\u200cی بازار هستیم؛ ورود به معامله تا شروع بازه\u200cی بعدی مجاز نیست. لطفاً صبور باشید.')
    # V3.44.9: معاملات معکوس (آزمایشی، پیش‌فرض خاموش) - فقط «جهت» برعکس می‌شود و معامله آینه‌ی قیمتیِ سیگنال است:
    # فاصله‌ی حد ضرر و فاصله‌ی حد سود دقیقاً همان فاصله‌های سیگنال اصلی می‌مانند (جابه‌جا نمی‌شوند)،
    # پس نسبت پاداش به ریسک هم همان سیگنال اصلی (حداقل مقدار تنظیم‌شده) می‌ماند و ضرر از سود کمتر است.
    inverse_applied = False
    _signal_side = side
    _shadow_spec = None
    if allow_inverse and gate_on(s, 'gate_inverse_trading_enabled'):
        _orig_side = side
        _shadow_spec = {'side': side, 'gap_sl': abs(float(signal_price) - float(sl)), 'gap_tp': abs(float(tp) - float(signal_price)),
                        'orig_tp': float(tp), 'structural': bool(structural_tp)}
        _gap_sl_orig = abs(float(signal_price) - float(sl))
        _gap_tp_orig = abs(float(tp) - float(signal_price))
        if side_long(side):      # سیگنال خرید -> معامله‌ی فروش (آینه حول قیمت سیگنال)
            side = 'SELL (Short)'
            sl = float(signal_price) + _gap_sl_orig
            tp = float(signal_price) - _gap_tp_orig
        else:                    # سیگنال فروش -> معامله‌ی خرید
            side = 'BUY (Long)'
            sl = float(signal_price) - _gap_sl_orig
            tp = float(signal_price) + _gap_tp_orig
        tp_stages = None         # خروج پله‌ای سیگنال اصلی در حالت معکوس معنی ندارد
        structural_tp = False    # هدف دیگر روی سطح ساختاری نیست؛ فاصله‌ی آینه‌ای است
        tp_level_name = None     # برچسب سطح هدف سیگنال اصلی برای معامله‌ی معکوس درست نیست
        reason = f'🔁 معکوس (سیگنال اصلی: {_orig_side}) | ' + (reason or '')
        inverse_applied = True
    trade_id = new_trade_id(chat_id, symbol)
    quality_score = None; quality_label = None; planned_rr = None
    # لایه V1.5 Enhanced Selection رشته دلیل را با فرمت انگلیسی «Quality XX/100»
    # (بدون برچسب داخل پرانتز) می‌سازد، در حالی که build_trade_plan/build_sweep_trade_plan
    # فرمت فارسی «کیفیت XX/100 (برچسب)» را تولید می‌کنند. قبلاً فقط فرمت فارسی match
    # می‌شد و در نتیجه quality_score برای اکثر معاملات V1.5 همیشه None ثبت می‌شد.
    m_score=re.search(r'(?:کیفیت|Quality) (\d+)/100(?: \(([^)]+)\))?', reason or '')
    if m_score:
        quality_score=int(m_score.group(1)); quality_label=m_score.group(2)
    m_rr=re.search(r'R:R ([0-9.]+)R', reason or '')
    if m_rr:
        planned_rr=float(m_rr.group(1))
    # منبع درست‌تر: خودِ plan (از build_trade_plan/build_sweep_trade_plan) این سه مقدار
    # را به‌صورت عددی خام دارد - نیازی به حدس‌زدن از متن نیست و مشکلات فرمت متنی
    # (مثل مورد بالا) را کلاً کنار می‌زند. وقتی صدا از scan_symbol با plan واقعی می‌آید،
    # این مقادیر جایگزین استخراج regex می‌شوند؛ برای مسیرهایی که plan ندارند (مثل
    # معامله‌ی دستی کاربر)، همان استخراج قبلی از متن fallback باقی می‌ماند.
    if plan_score is not None:
        quality_score = int(round(float(plan_score)))
    if plan_quality_label is not None:
        quality_label = plan_quality_label
    if plan_rr is not None:
        planned_rr = float(plan_rr)
    # آیا این معامله به‌خاطر تعلق به خانواده‌ی برگشتی (Liquidity Sweep) از فیلتر
    # خلاف‌جهت بازار معاف بوده؟ صرفاً ثبت می‌شود، تصمیم ورود را عوض نمی‌کند.
    regime_filter_exempt = is_reversal_family_reason(reason)
    level_key = None
    _level_tag, _level_token, _level_value = extract_setup_level(reason)
    if _level_token is not None:
        level_key = f"{symbol}:{_level_token}:{_level_value}"
    # A setup is consumable only once. Use the latest closed signal identity so
    # repeated scan loops cannot create duplicate audit signals or re-enter the
    # exact same liquidity event.
    setup_source = f"{symbol}|{side}|{s.get('timeframe')}|{signal_price:.12g}|{sl:.12g}|{tp:.12g}|{reason}"
    setup_id = hashlib.sha256(setup_source.encode('utf-8')).hexdigest()[:24]
    if any(str(p.get('setup_id') or '') == setup_id for p in s.get('paper_positions', [])):
        return _blk(chat_id, 'همین ستاپ همین الان به‌صورت پوزیشن باز وجود دارد', key=None, simple='این معامله همین الان باز است.')
    if setup_id in set(s.get('consumed_setups') or []) and not force:
        return _blk(chat_id, 'روی همین ستاپ قبلاً معامله انجام شده (ستاپ مصرف‌شده)', key=None, simple='روی همین فرصت قبلاً معامله شده و دوباره وارد نمی\u200cشویم.')
    if require_active and not force and not s['is_bot_active']:
        return _blk(chat_id, 'ربات غیرفعال است (دکمه‌ی شروع/توقف را چک کنید)', key=None, simple='ربات الان غیرفعال است.')
    if s['daily_stopped'] and not force and gate_on(s, 'gate_risk_guard_enabled'):
        return _blk(chat_id, 'ربات امروز به‌خاطر حد ضرر روزانه متوقف شده است', key='gate_risk_guard_enabled', simple='به\u200cخاطر ضرر امروز، ورود جدید فعلاً متوقف است.')
    if not force and gate_on(s, 'gate_risk_guard_enabled') and not risk_guard(chat_id):
        return _blk(chat_id, 'محافظ ریسک (حد ضرر/ضرر پیاپی/حد روزانه) اجازه‌ی ورود نمی‌دهد', key='gate_risk_guard_enabled', simple='به\u200cخاطر چند ضرر اخیر، برای حفظ سرمایه ورود جدید فعلاً متوقف است. لطفاً صبور باشید.')
    now=time.time(); cd=float(s['cooldowns'].get(symbol,0))
    if now<cd and not force and gate_on(s, 'gate_cooldown_enabled'):
        return _blk(chat_id, f'کول‌داون نماد {symbol} بعد از معامله‌ی قبلی هنوز {int(cd-now)} ثانیه مانده', key='gate_cooldown_enabled', simple='روی این ارز تازه معامله بسته شده؛ کمی صبر می\u200cکنیم تا دوباره وارد شویم.')
    s['cooldowns'].pop(symbol,None)
    if level_key and level_key in s.get('traded_levels', {}) and not force and gate_on(s, 'gate_traded_level_enabled'):
        return _blk(chat_id, 'روی همین سطح قبلاً معامله شده و سطح هنوز آزاد نشده', key='gate_traded_level_enabled', simple='روی همین محدوده\u200cی قیمتی قبلاً معامله شده و دوباره وارد نمی\u200cشویم.')
    is_dynamic_strategy = s.get('active_strategy') == 'dynamic'
    if not force and not is_dynamic_strategy and s['filters'].get('no_short_filter') and 'SELL' in side:
        return _blk(chat_id, 'فیلتر ممنوعیت فروش فعال است', key='block_sell', simple='ورود به معامله\u200cی فروش در حال حاضر مجاز نیست.')
    if not force and not is_dynamic_strategy and s['filters'].get('no_buy_filter') and 'BUY' in side:
        return _blk(chat_id, 'فیلتر ممنوعیت خرید فعال است', key='block_buy', simple='ورود به معامله\u200cی خرید در حال حاضر مجاز نیست.')
    if not force and s['max_open_positions']>0 and len(s['paper_positions'])>=s['max_open_positions']:
        return _blk(chat_id, f"سقف تعداد پوزیشن باز ({s['max_open_positions']}) پر است", key=None, simple='تعداد معامله\u200cهای باز به سقف مجاز رسیده؛ تا بسته شدن یکی از آن\u200cها ورود جدید ممکن نیست.')
    if any(p['symbol']==symbol for p in s['paper_positions']):
        return _blk(chat_id, f'روی {symbol} همین الان پوزیشن باز داریم', key=None, simple='روی این ارز همین الان معامله باز داریم.')
    # Correlated-exposure guard: cap how many positions can be open in the SAME
    # direction at once (e.g. all Long on different alts), and throttle back-to-back
    # same-direction entries opened seconds apart in one scan burst. This prevents a
    # single market-wide move from hitting many correlated positions simultaneously,
    # which independent per-trade risk sizing does not account for.
    dir_key = 'BUY' if side_long(side) else 'SELL'
    max_same_dir = int(s.get('max_same_direction_positions', 0) or 0)
    # V3.42.8: سقف هم‌جهت برای «همه‌ی» مسیرهای ورود اعمال می‌شود (اسکن خودکار، سیگنال ذخیره‌شده،
    # تایید دستیار، ورود سریع کانال، معامله‌ی دستی، اوردر معلق) و با force=True هم دور زده نمی‌شود.
    if max_same_dir > 0:
        same_dir_open = sum(1 for p in s['paper_positions'] if side_long(p.get('side', '')) == side_long(side))
        if same_dir_open >= max_same_dir:
            return _blk(chat_id, f"سقف پوزیشن هم‌جهت ({max_same_dir}) پر است؛ {same_dir_open} پوزیشن {'Long' if dir_key=='BUY' else 'Short'} باز است", key='same_dir', simple='تعداد معامله\u200cهای هم\u200cجهت به سقف مجاز رسیده؛ تا بسته شدن یکی از آن\u200cها ورود جدید ممکن نیست.')
    same_dir_cooldown = float(s.get('same_direction_entry_cooldown_seconds', 0) or 0)
    if same_dir_cooldown > 0 and not bypass_burst_cooldown and not force:
        last_dir_ts = float((s.get('last_direction_entry_ts') or {}).get(dir_key, 0))
        if time.time() - last_dir_ts < same_dir_cooldown:
            return _blk(chat_id, f'فاصله‌ی زمانی بین دو ورود هم‌جهت ({int(same_dir_cooldown)} ثانیه) رعایت نشده', key=None, simple='چند لحظه پیش وارد معامله\u200cای هم\u200cجهت شدیم؛ کمی صبر می\u200cکنیم.')
    audit_event(chat_id, trade_id, 'signal_and_plan', {
        'symbol': symbol, 'side': side, 'signal_price': signal_price, 'sl': sl, 'tp': tp,
        'reason': reason, 'setup_id': setup_id, 'timeframe': s.get('timeframe'),
        'strategy': s.get('active_strategy'), 'quality_score': quality_score,
        'quality_label': quality_label, 'planned_rr': planned_rr
    })

    price=latest_price(symbol) or float(signal_price)
    _raw_entry_price = float(price)
    # Conservative paper execution: adverse entry slippage only.
    if s.get('trading_mode') != 'REAL' and PAPER_SLIPPAGE_BPS > 0:
        slip = PAPER_SLIPPAGE_BPS / 10000.0
        price = price * (1.0 + slip) if side_long(side) else price * (1.0 - slip)
    # خروج پله‌ای (مدل PDH/PDL+P4): plan['tp_stages'] سطوح مسیر را از نزدیک به دور دارد.
    # PAPER: روی هر سطح سهم مساوی بسته می‌شود و آخرین سطح همان TP نهایی است.
    # REAL: فعلاً فقط نزدیک‌ترین سطح به‌عنوان TP ثبت می‌شود (سفارش جزئی روی صرافی پیاده نشده).
    _stage_list=[st for st in (tp_stages or []) if isinstance(st,dict) and st.get('price')]
    if _stage_list and s['trading_mode']=='REAL':
        tp=float(_stage_list[0]['price']); tp_level_name=_stage_list[0].get('name') or tp_level_name
        _stage_list=[]
    gap_sl=abs(float(signal_price)-float(sl))
    gap_tp=abs(float(tp)-float(signal_price))
    if keep_levels:
        # V3.43.32: ورود بعد از «صبر برای تایید» - SL/TP همان سطوح سیگنال می‌مانند (جابه‌جا نمی‌شوند)
        sl=float(sl); tp=float(tp)
    elif side_long(side):
        sl=price-gap_sl
        tp=float(tp) if (structural_tp and float(tp)>price) else price+gap_tp
    else:
        sl=price+gap_sl
        tp=float(tp) if (structural_tp and float(tp)<price) else price-gap_tp
    paper_stage_rows=None
    if _stage_list:
        _is_l=side_long(side)
        _valid=[st for st in _stage_list if (float(st['price'])>price if _is_l else float(st['price'])<price)]
        if _valid:
            tp=float(_valid[-1]['price'])
            if len(_valid)>=2:
                _n=len(_valid)
                paper_stage_rows=[{'price':float(st['price']),'name':st.get('name'),'fraction':1.0/_n,'done':False} for st in _valid[:-1]]
                tp_level_name=' → '.join(str(st.get('name')) for st in _valid)+' (پله‌ای)'
    # V3.44.13: رتبه‌ی نرم با رژیم ۴ ساعته - سیگنال را رد نمی‌کند، فقط ریسک/حجم را کم می‌کند
    _tier_mult = 1.0; _tier_info = None
    if gate_on(s, 'gate_h4_tier_enabled') and not force:
        try:
            _reg = _symbol_h4_regime(symbol)
            if _reg is not None:
                _sig_long = side_long(_signal_side)
                _aligned = (_reg == 'BULLISH' and _sig_long) or (_reg == 'BEARISH' and not _sig_long)
                _reduce = _aligned if inverse_applied else (not _aligned)
                if _reduce: _tier_mult = float(H4_TIER_REDUCED_RISK_MULT)
                _tier_info = {'h4_regime': _reg, 'signal_aligned': bool(_aligned), 'risk_mult': _tier_mult}
        except Exception:
            logger.exception('h4 tier failed symbol=%s', symbol)
    s['_symbol_tmp']=symbol
    margin, amount_or_reason=safe_size(chat_id,s,price,sl,force=force,risk_mult=_tier_mult)
    s.pop('_symbol_tmp',None)
    if margin<=0:
        return _blk(chat_id, f'محاسبه‌ی حجم/مقدار معامله ناموفق: {amount_or_reason}', key=None, simple='حجم معامله با موجودی و شرایط فعلی قابل محاسبه نبود.')
    leverage=int(s['leverage'])
    risk_dist=abs(float(price)-float(sl))
    risk_usdt=float(margin)*((risk_dist/float(price))*float(leverage)) if price>0 else 0.0
    fee_estimate=round_trip_fee_usdt(margin,leverage)
    if not force and gate_on(s, 'gate_open_fee_ratio_enabled') and MIN_RISK_TO_FEE_RATIO>0 and risk_usdt < fee_estimate*MIN_RISK_TO_FEE_RATIO:
        return _blk(chat_id, f'ریسک دلاری ({risk_usdt:.2f}$) نسبت به کارمزد رفت‌وبرگشت ({fee_estimate:.2f}$) کمتر از {MIN_RISK_TO_FEE_RATIO:g} برابر است', key='gate_open_fee_ratio_enabled', simple='سود احتمالی این معامله نسبت به کارمزدش کم است؛ برای همین وارد نمی\u200cشویم.')
    # سقف مجموع ریسک باز: جمع ریسک دلاری همهٔ پوزیشن‌های باز (صرف‌نظر از جهت) به‌علاوهٔ
    # این معاملهٔ جدید نباید از درصد مشخصی از سرمایه بگذرد. با تنظیمات پیش‌فرض عملاً
    # هیچ‌وقت فعال نمی‌شود؛ فقط وقتی سقف پوزیشن یا درصد ریسک بالا برود اثر می‌کند.
    max_total_risk_pct = float(s.get('max_total_open_risk_pct') or 0.0)
    if max_total_risk_pct > 0 and not force:
        try:
            equity = exchange_balance(chat_id) if s['trading_mode'] == 'REAL' else current_paper_equity(s)
            open_risk = sum(float(p.get('risk_usdt') or 0.0) for p in s.get('paper_positions', []))
            if gate_on(s, 'gate_total_risk_cap_enabled') and equity > 0 and (open_risk + risk_usdt) > equity * (max_total_risk_pct / 100.0):
                return _blk(chat_id, f'سقف مجموع ریسک باز ({max_total_risk_pct:g}% سرمایه) رد می‌شود', key='gate_total_risk_cap_enabled', simple='مجموع ریسک معامله\u200cهای باز به سقف مجاز رسیده؛ ورود جدید فعلاً ممکن نیست.')
        except Exception:
            pass
    _regime_snap = _regime_alignment_snapshot(symbol, s['timeframe'])
    try:
        _entry_warns = _entry_warning_tags(chat_id, symbol, side, s['timeframe'])
    except Exception:
        logger.exception('entry warnings failed symbol=%s', symbol); _entry_warns = None
    _entry_snap = _entry_snapshot(symbol, side, s['timeframe'], reason, price, sl)
    trade={'trade_id':trade_id,'setup_id':setup_id,'symbol':symbol,'side':side,'entry_price':price,'sl':sl,'tp':tp,'margin':margin,'leverage':leverage,'amount':0,'timeframe':s['timeframe'],'strategy':s['active_strategy'],'is_real':False,'paper_slippage_bps':PAPER_SLIPPAGE_BPS,'paper_funding_rate_pct_8h':PAPER_FUNDING_RATE_PCT_8H,'opened_at':time.time(),'signal_reason':reason[:900],'entry_reason':reason[:900],'risk_pct':float(s['risk_per_trade_pct']),'risk_usdt':risk_usdt,'quality_score':quality_score,'quality_label':quality_label,'planned_rr':planned_rr,'regime_filter_exempt':regime_filter_exempt,'sl_slippage_r':None,'market_adx_at_entry':_regime_snap['market_adx'],'timeframe_bull_pct_at_entry':_regime_snap['timeframe_bull_pct'],'timeframe_bear_pct_at_entry':_regime_snap['timeframe_bear_pct'],'symbol_adx_at_entry':_regime_snap['symbol_adx'],'mfe_usdt':0.0,'mae_usdt':0.0,'mfe_r':0.0,'mae_r':0.0,'peak_favorable_price':None,'peak_adverse_price':None,'last_price':price,'duration_seconds':0.0,'realized_r':None,'risk_distance':gap_sl,'entry_snapshot':_entry_snap,'entry_warnings':_entry_warns,'inverse_trade':inverse_applied,**presets_mod.trade_tag(s)}
    if paper_stage_rows:
        trade['tp_stages']=paper_stage_rows; trade['orig_margin']=float(margin)
    if inverse_applied and _shadow_spec:
        try:
            _sh_long = side_long(_shadow_spec['side'])
            _sh_slip = (PAPER_SLIPPAGE_BPS / 10000.0) if (s.get('trading_mode') != 'REAL' and PAPER_SLIPPAGE_BPS > 0) else 0.0
            _sh_entry = _raw_entry_price * (1.0 + _sh_slip) if _sh_long else _raw_entry_price * (1.0 - _sh_slip)
            if _sh_long:
                _sh_sl = _sh_entry - _shadow_spec['gap_sl']
                _sh_tp = _shadow_spec['orig_tp'] if (_shadow_spec['structural'] and _shadow_spec['orig_tp'] > _sh_entry) else _sh_entry + _shadow_spec['gap_tp']
            else:
                _sh_sl = _sh_entry + _shadow_spec['gap_sl']
                _sh_tp = _shadow_spec['orig_tp'] if (_shadow_spec['structural'] and _shadow_spec['orig_tp'] < _sh_entry) else _sh_entry - _shadow_spec['gap_tp']
            trade['shadow'] = {'side': _shadow_spec['side'], 'entry': _sh_entry, 'sl': _sh_sl, 'tp': _sh_tp, 'status': 'open'}
        except Exception:
            logger.exception('shadow setup failed symbol=%s', symbol)
    # V3.44.12: فیلدهای کمکِ ارزیابی (قیمت سیگنال/ورود خام، SL و TP اولیه، نسخه و هش تنظیمات)
    try:
        trade.update({'signal_price': float(signal_price), 'raw_entry_price': float(_raw_entry_price), 'sl_initial': float(sl), 'tp_initial': float(tp),
                      'bot_version': BOT_VERSION, 'settings_hash': _settings_register(s), 'h4_tier': _tier_info})
    except Exception:
        logger.exception('trade extra fields failed symbol=%s', symbol)
    # V3.44.11: ردیاب مجازی «انتقال SL به سر به سر» - فقط گزارش؛ روی معامله اثری ندارد
    try:
        trade['be_track'] = {'entry': float(price), 'risk_dist': float(risk_dist), 'long': bool(side_long(side)),
                             'levels': {str(t): {'armed': False, 'hit': False} for t in BE_TRACK_TRIGGERS}}
    except Exception:
        logger.exception('be_track setup failed symbol=%s', symbol)

    if s['trading_mode']=='REAL':
        ex=get_exchange(chat_id)
        if not ex:
            send_message(chat_id,f'❌ حساب {real_venue_name(chat_id)} این کاربر پیکربندی نشده یا اتصال برقرار نیست.'); return False
        market,scale=futures_market(ex,symbol)
        if not market:
            send_message(chat_id,f"❌ نماد `{symbol}` روی {'Bitunix Futures' if getattr(ex,'is_bitunix',False) else 'فیوچرز USDⓈ-M باینانس'} وجود ندارد (یا غیرفعال است)."); return False
        sym=market['symbol']
        try:
            leverage=_binance_prepare_symbol(ex,sym,int(leverage)); trade['leverage']=leverage
        except Exception as exc:
            send_message(chat_id,f'❌ تنظیم اهرم `{symbol}` شکست خورد: `{exc}`',parse_mode=None); return False
        amount=(margin*leverage)/price
        amount=normalize_amount(chat_id,symbol,amount)      # بر حسب کوین (واحد ربات)
        contracts=amount/scale                              # بر حسب قرارداد فیوچرز
        _lim=market.get('limits') or {}
        min_amt=float((_lim.get('amount') or {}).get('min') or 0)
        min_cost=float((_lim.get('cost') or {}).get('min') or 0)
        if amount<=0 or (min_amt and contracts<min_amt) or (min_cost and amount*price<min_cost):
            send_message(chat_id,f'❌ حجم/ارزش معامله `{symbol}` از حداقل مجاز صرافی کمتر است (حداقل ارزش سفارش: `{min_cost or "-"}` USDT).'); return False
        try:
            norm_price = normalize_price(chat_id, symbol, price)
            _side_ex='buy' if side_long(side) else 'sell'
            if (order_type or ENTRY_ORDER_TYPE) == 'limit':
                f_price=float(ex.price_to_precision(sym,norm_price*scale))
                order = ex.create_order(sym, 'limit', _side_ex, contracts, f_price, {'newOrderRespType':'RESULT'})
            else:
                order = ex.create_order(sym, 'market', _side_ex, contracts, None, {'newOrderRespType':'RESULT'})

            order_id = order.get('id')
            confirmed = None
            for _ in range(ORDER_CONFIRM_RETRIES):
                try:
                    confirmed = ex.fetch_order(order_id, sym) if order_id else order
                except Exception:
                    confirmed = order
                filled_c = float((confirmed or {}).get('filled') or 0)
                status = str((confirmed or {}).get('status') or '').lower()
                if filled_c > 0 and (status in ('closed', 'filled') or not status): break
                time.sleep(ORDER_CONFIRM_DELAY)

            if confirmed is None: confirmed = order
            filled_c = float(confirmed.get('filled') or 0)
            _st = str(confirmed.get('status') or '').lower()
            if order_id and _st in ('open','new','partially_filled'):
                # سفارش هنوز باز است (Limit پر نشده یا نیمه‌پر): باقی‌مانده را لغو و مقدار نهایی را دوباره می‌خوانیم
                try: ex.cancel_order(order_id, sym)
                except Exception: pass
                try: filled_c = float((ex.fetch_order(order_id, sym) or {}).get('filled') or filled_c)
                except Exception: pass

            if filled_c <= 0:
                live = find_position(chat_id, symbol)
                if live and float(live.get('amount') or 0) > 0:
                    filled_c = float(live['amount']) / scale
                    exec_price = float(live.get('entry_price') or norm_price)
                else:
                    send_message(chat_id, f'⏱ سفارش Limit نماد `{symbol}` در قیمت `{fmt(norm_price)}` پر نشد و لغو شد.')
                    return False
            else:
                exec_price = float(confirmed.get('average') or confirmed.get('price') or (norm_price*scale)) / scale
            filled = filled_c * scale   # بر حسب کوین (واحد ربات)

            trade['entry_price'] = exec_price
            trade['amount'] = filled
            trade['margin'] = exec_price * filled / max(leverage, 1)
            trade['is_real'] = True
            trade['order_id'] = order_id

            if keep_levels:
                pass
            elif side_long(side):
                trade['sl'] = exec_price - gap_sl
                trade['tp'] = exec_price + gap_tp
            else:
                trade['sl'] = exec_price + gap_sl
                trade['tp'] = exec_price - gap_tp

            trade['sl'] = normalize_price(chat_id, symbol, trade['sl'])
            trade['tp'] = normalize_price(chat_id, symbol, trade['tp'])
            trade['risk_usdt'] = abs(float(trade['entry_price']) - float(trade['sl'])) / max(float(trade['entry_price']), 1e-12) * float(trade['margin']) * float(trade['leverage'])

            audit_event(chat_id, trade_id, 'order_filled', {'entry_price': trade['entry_price'], 'amount': trade['amount'], 'order_id': order_id})
            ok, err = set_protection(chat_id, symbol, trade['sl'], trade['tp'])
            audit_event(chat_id, trade_id, 'protection_set', {'ok': ok, 'detail': err, 'sl': trade.get('sl'), 'tp': trade.get('tp')})
            if not ok:
                _halt_real_trading(chat_id, f'ثبت SL/TP برای {symbol} ناموفق بود: {err}')
                try: _close_market(ex, sym, side_long(side), filled_c)
                except Exception as close_exc: send_message(chat_id, f'🚨 *حفاظت شکست و بستن خودکار هم شکست.* `{symbol}`\nSL/TP: `{err}`\nخطای بستن: `{close_exc}`')
                else: send_message(chat_id, f'⚠️ معامله `{symbol}` به‌دلیل عدم ثبت SL/TP فوراً بسته شد.')
                cancel_all_protection(chat_id, symbol)
                return False

            current = get_session(chat_id)
            if (require_active and not current['is_bot_active']) or int(current.get('scan_generation', 0)) != generation:
                try:
                    _close_market(ex, sym, side_long(side), filled_c)
                    cancel_all_protection(chat_id, symbol)
                except Exception as close_exc:
                    _halt_real_trading(chat_id, f'توقف هنگام ورود رخ داد ولی بستن {symbol} ناموفق بود: {close_exc}')
                return False
        except BitunixOrderRejected as exc:
            # V3.44.57: بیتیونیکس صریحاً سفارش را رد کرد (سفارشی ساخته نشد، مثلاً موجودی/حداقل حجم) → ربات متوقف نمی‌شود
            send_message(chat_id, f'❌ سفارش REAL `{symbol}` توسط {real_venue_name(chat_id)} رد شد: `{exc.msg or exc.code}`', parse_mode=None)
            return False
        except Exception as exc:
            _halt_real_trading(chat_id, f'وضعیت سفارش REAL {symbol} قابل تأیید نیست: {exc}')
            send_message(chat_id, f'❌ سفارش REAL `{symbol}` به‌طور قطعی تأیید نشد؛ ربات متوقف شد.', parse_mode=None)
            return False
    else:
        if float(s['paper_balance']) - reserved_margin(s) < margin:
            return _blk(chat_id, 'موجودی آزاد پیپر برای مقدار این معامله کافی نیست', key=None, simple='موجودی آزاد برای این معامله کافی نیست.')
        trade['amount'] = (margin * leverage) / price
        audit_event(chat_id, trade_id, 'paper_opened', {'entry_price': price, 'amount': trade['amount'], 'margin': margin, 'quality_score': quality_score, 'quality_label': quality_label, 'planned_rr': planned_rr})
        s['paper_positions'].append(trade)
    last_dir_ts_map = s.setdefault('last_direction_entry_ts', {})
    last_dir_ts_map[dir_key] = time.time()
    consumed = s.setdefault('consumed_setups', [])
    if setup_id not in consumed:
        consumed.append(setup_id)
        # Keep memory bounded while preserving enough recent setup identities.
        if len(consumed) > 2000:
            del consumed[:-2000]
        save_session(chat_id)

    if trade.get('is_real'):
        s['paper_positions'].append(trade)
        save_session(chat_id)
    if level_key:
        s['traded_levels'][level_key] = time.strftime('%Y-%m-%d', time.gmtime())
        save_session(chat_id)

    # ثبت سود/زیان دقیق مورد انتظار (پس از کسر کارمزد رفت‌وبرگشت) و نام سطح TP روی خود پوزیشن
    try:
        _m = estimate_trade_pnl(trade['entry_price'], trade['sl'], trade['tp'], trade['side'], trade['margin'], trade['leverage'])
        trade['expected_tp_pnl_net'] = round(_m['tp_net'], 4)
        trade['expected_sl_pnl_net'] = round(_m['sl_net'], 4)
        trade['expected_fee_usdt'] = round(_m['fee'], 4)
    except Exception:
        logger.exception('expected pnl estimate failed trade=%s', trade_id)
    trade['tp_level_name'] = tp_level_name
    save_session(chat_id)
    audit_event(chat_id, trade_id, 'position_opened', audit_trade_record(trade))
    chart_tf = s['timeframe']
    df = get_klines(symbol, chart_tf, 650 if chart_tf in ('5min', '15min', '1hour') else 200)
    if not df.empty:
        chart(chat_id, symbol, calculate_indicators(df), trade, entry_card=True)
    return True


def scan_watchlist_for_timeframe(timeframe, regime=None):
    if regime == 'BEARISH':
        return list(WINNING_SHORT_WATCHLISTS.get(timeframe, WINNING_SHORT_WATCHLISTS['5min']))
    if regime == 'BULLISH':
        return list(WINNING_WATCHLISTS.get(timeframe, WINNING_WATCHLISTS['5min']))
    long_list = WINNING_WATCHLISTS.get(timeframe, WINNING_WATCHLISTS['5min'])
    short_list = WINNING_SHORT_WATCHLISTS.get(timeframe, WINNING_SHORT_WATCHLISTS['5min'])
    return list(dict.fromkeys(list(long_list) + list(short_list)))


MARKET_REGIME_CACHE = {'ts': 0.0, 'regime': 'NEUTRAL', 'detail': '', 'ttl': 90, 'avg_adx': 0.0}
MARKET_REGIME_MIN_ADX = float(os.environ.get('MARKET_REGIME_MIN_ADX', '18'))
MARKET_REGIME_TIMEFRAME = os.environ.get('MARKET_REGIME_TIMEFRAME', '4hour')


async def refresh_market_regime(http):
    now = time.time()
    if now - MARKET_REGIME_CACHE['ts'] < MARKET_REGIME_CACHE['ttl']:
        return MARKET_REGIME_CACHE['regime'], MARKET_REGIME_CACHE['detail']
    tf = MARKET_REGIME_TIMEFRAME if MARKET_REGIME_TIMEFRAME in TIMEFRAME_MAP else '4hour'
    states = {}
    for leader in LEADER_SYMBOLS:
        try:
            d = await get_klines_async(http, leader, tf, 120)
            if d is None or d.empty or len(d) < 60:
                detail = f'داده کافی برای {leader} در دسترس نیست'
                MARKET_REGIME_CACHE.update(ts=now, regime='NEUTRAL', detail=detail)
                return 'NEUTRAL', detail
            x = calculate_indicators(d).iloc[-2]
            adx = float(x.get('adx') or 0)
            bullish = bool(x['close'] > x['ema20'] > x['ema50'] and x['plus_di'] > x['minus_di'] and adx >= MARKET_REGIME_MIN_ADX)
            bearish = bool(x['close'] < x['ema20'] < x['ema50'] and x['minus_di'] > x['plus_di'] and adx >= MARKET_REGIME_MIN_ADX)
            states[leader] = ('BULLISH' if bullish else 'BEARISH' if bearish else 'NEUTRAL', adx)
        except Exception as exc:
            detail = f'خطا در دریافت داده {leader}: {exc}'
            MARKET_REGIME_CACHE.update(ts=now, regime='NEUTRAL', detail=detail)
            return 'NEUTRAL', detail
    detail = ' | '.join(f'{leader}={states[leader][0]} (ADX={states[leader][1]:.1f})' for leader in LEADER_SYMBOLS)
    unique_dirs = {v[0] for v in states.values()}
    avg_adx = sum(v[1] for v in states.values())/len(states) if states else 0.0
    if 'BULLISH' in unique_dirs and 'BEARISH' not in unique_dirs:
        regime = 'BULLISH'
    elif 'BEARISH' in unique_dirs and 'BULLISH' not in unique_dirs:
        regime = 'BEARISH'
    else:
        regime = 'NEUTRAL'
    MARKET_REGIME_CACHE.update(ts=now, regime=regime, detail=detail, avg_adx=avg_adx)
    return regime, detail


# --- شبکه سطوح لگاریتمی (بر اساس اسکریپت Pine کاربر) --------------------------------
# ساختار کلان و کم‌تغییر است (بر پایه‌ی کف/سقف تاریخچه‌ی روزانه)، پس مثل رژیم بازار کش
# می‌شود و فقط هر چند ساعت یک‌بار به‌روزرسانی می‌شود، نه در هر اسکن.
LOG_GRID_BASE_STEPS = int(os.environ.get('LOG_GRID_BASE_STEPS', '20'))
LOG_GRID_LOOKBACK_DAYS = int(os.environ.get('LOG_GRID_LOOKBACK_DAYS', '500'))
LOG_GRID_TTL = float(os.environ.get('LOG_GRID_TTL_SECONDS', '21600'))  # هر ۶ ساعت
LOG_GRID_CACHE: Dict[str, Dict[str, Any]] = {}


async def get_log_grid_levels(http, symbol):
    """
    سطوح شبکه‌ی لگاریتمی یک نماد را برمی‌گرداند (کش‌شده). بر پایه‌ی داده‌ی روزانه
    (تا LOG_GRID_LOOKBACK_DAYS کندل، برای تخمین نزدیک به کف/سقف کل تاریخچه‌ی نماد -
    دقیقاً مثل chart_low/chart_high در اسکریپت اصلی که کل چارت را می‌بیند).
    """
    now = time.time(); _ck = f'{_venue()}:{symbol}'
    c = LOG_GRID_CACHE.get(_ck)
    if c and now - c['ts'] < LOG_GRID_TTL:
        return c['levels']
    d = await get_klines_async(http, symbol, '1day', LOG_GRID_LOOKBACK_DAYS)
    levels = compute_log_grid_levels(d, LOG_GRID_BASE_STEPS) if d is not None and not d.empty else []
    LOG_GRID_CACHE[_ck] = {'ts': now, 'levels': levels}
    return levels


def _btc_candle_precheck(chat_id, symbol, side, price, sl, tp, force, allow_inverse):
    """V3.44.42: کلید «هم‌جهتی با کندل BTC». True = اجازه‌ی ادامه. همه‌ی مسیرهای ورود (خودکار، دستی، دستیار، ورود سریع،
    اوردر معلق) از execute_trade/execute_manual_trade می‌گذرند، پس این‌جا حتی با force=True هم دور زده نمی‌شود.
    قبل از گرفتن قفل ورود اجرا می‌شود تا دریافت داده‌ی شبکه، بستن پوزیشن‌ها را معطل نکند. جهت، جهتِ نهایی معامله است
    (اگر «معاملات معکوس» روشن باشد، جهت برعکس‌شده سنجیده می‌شود)."""
    s = get_session(chat_id)
    if not gate_on(s, 'gate_btc_candle_enabled'):
        return True
    try:
        _BLK_CTX[chat_id] = {'ts': time.time(), 'symbol': symbol, 'side': side, 'signal_price': float(price), 'sl': float(sl), 'tp': float(tp),
                             'scenario': None, 'force': bool(force)}
    except Exception:
        pass
    eff_long = side_long(side)
    if allow_inverse and gate_on(s, 'gate_inverse_trading_enabled'):
        eff_long = not eff_long
    try:
        ok, txt = btc_candle_verdict(s.get('timeframe', '5min'), 'BUY' if eff_long else 'SELL')
    except Exception:
        logger.exception('btc candle precheck failed chat=%s symbol=%s', chat_id, symbol)
        ok, txt = False, f'{_BTC_CANDLE_BLOCK_PREFIX}: خطا در بررسی کندل؛ ورود انجام نمی‌شود'
    if ok:
        return True
    _blk(chat_id, txt)
    return False


def _btc_front_flags(s):
    """(front, chop): کلید «فاصله/سمت سطح جلویی BTC» و کلید مستقل «BTC کلاف دور سطح»."""
    return bool(gate_on(s, 'gate_btc_front_level_enabled')), bool(gate_on(s, 'gate_btc_chop_enabled'))


def _btc_front_precheck(chat_id, symbol, side, price, sl, tp, force, allow_inverse):
    """V3.44.45: کلید «فاصله تا سطح جلویی BTC» روی همه‌ی مسیرهای ورود (خودکار، دستی، ⚡ ورود سریع، تایید کارت دستیار، اوردر معلق).
    True = اجازه‌ی ادامه. با force=True هم دور زده نمی‌شود. مسیرهای دستی دلیل رد را از _LAST_BLOCK_REASON به کاربر نشان می‌دهند؛
    مسیر خودکار (force=False) هشدار ورود را یک‌بار می‌فرستد."""
    s = get_session(chat_id)
    _ff, _fc = _btc_front_flags(s)
    if not (_ff or _fc):
        return True
    try:
        _BLK_CTX[chat_id] = {'ts': time.time(), 'symbol': symbol, 'side': side, 'signal_price': float(price), 'sl': float(sl), 'tp': float(tp),
                             'scenario': None, 'force': bool(force)}
    except Exception:
        pass
    sig = 'BUY' if side_long(side) else 'SELL'
    ok, txt = _btc_front_gate(chat_id, s, symbol, sig, s.get('timeframe', '5min'), warn=not force, allow_inverse=allow_inverse, front=_ff, chop=_fc)
    if ok:
        return True
    _blk(chat_id, txt)
    return False


def execute_trade(chat_id,symbol,side,signal_price,sl,tp,reason='',structural_tp=False,plan_score=None,plan_rr=None,plan_quality_label=None,bypass_burst_cooldown=False,force=False,tp_level_name=None,tp_stages=None,keep_levels=False):
    """force=True (تایید دستی کاربر در حالت دستیار): محدودیت‌های خودکار (سقف پوزیشن، کول‌داون،
    محافظ ریسک، توقف روزانه، فعال‌نبودن ربات، ...) نادیده گرفته می‌شود. فقط موانع فنی می‌مانند
    (پوزیشن باز روی همان نماد، مارجین/حجم نامعتبر، خطای صرافی) + سقف معاملات هم‌جهت که همیشه اعمال می‌شود."""
    s=get_session(chat_id)
    generation=int(s.get('scan_generation',0))
    _LAST_BLOCK_REASON.pop(chat_id, None)
    if not force:
        if not s['is_bot_active']:
            return _blk(chat_id, 'ربات غیرفعال است (دکمه‌ی شروع/توقف را چک کنید)', key=None, simple='ربات الان غیرفعال است.')
        if s['daily_stopped']:
            return _blk(chat_id, 'ربات امروز به‌خاطر حد ضرر روزانه متوقف شده است', key='gate_risk_guard_enabled', simple='به\u200cخاطر ضرر امروز، ورود جدید فعلاً متوقف است.')
    if not _btc_candle_precheck(chat_id, symbol, side, signal_price, sl, tp, force, True):
        return False
    if not _btc_front_precheck(chat_id, symbol, side, signal_price, sl, tp, force, True):
        return False
    lock=get_entry_lock(chat_id)
    with lock:
        s=get_session(chat_id)
        if not force:
            if not s['is_bot_active'] or s['daily_stopped']:
                return _blk(chat_id, 'ربات غیرفعال یا متوقف شد', key=None, simple='ربات الان غیرفعال است.')
            if int(s.get('scan_generation',0)) != generation:
                return _blk(chat_id, 'تنظیمات ربات همین لحظه تغییر کرد؛ دوباره تایید کنید', key=None, simple='تنظیمات همین لحظه تغییر کرد؛ لطفاً دوباره تایید کنید.')
        return _execute_trade_unlocked(chat_id,symbol,side,signal_price,sl,tp,reason,generation,require_active=not force,structural_tp=structural_tp,plan_score=plan_score,plan_rr=plan_rr,plan_quality_label=plan_quality_label,bypass_burst_cooldown=bypass_burst_cooldown,force=force,tp_level_name=tp_level_name,tp_stages=tp_stages,keep_levels=keep_levels)


def execute_manual_trade(chat_id,symbol,side,sl,tp,entry_price=None,reason='معامله دستی کاربر',order_type=None,force=False,tp_level_name=None):
    """force=True (ورود سریع از کانال): محدودیت‌های خودکار نادیده گرفته می‌شود؛ فقط موانع فنی و سقف معاملات هم‌جهت می‌مانند."""
    s=get_session(chat_id)
    if s['daily_stopped'] and not force:
        return False, 'محدودیت ضرر روزانه فعال است؛ ورود دستی هم مسدود است.'
    live_price=latest_price(symbol)
    if not live_price:
        return False, f'قیمت لحظه‌ای `{symbol}` دریافت نشد.'
    price=float(entry_price) if entry_price else live_price
    if not _btc_candle_precheck(chat_id, symbol, side, price, sl, tp, force, bool(force)):
        return False, _LAST_BLOCK_REASON.pop(chat_id, None) or 'ورود دستی رد شد (کندل BTC با جهت معامله نمی‌خواند).'
    if not _btc_front_precheck(chat_id, symbol, side, price, sl, tp, force, bool(force)):
        return False, _LAST_BLOCK_REASON.pop(chat_id, None) or 'ورود دستی رد شد (BTC به سطح نزدیک است؛ تا واکنش به سطح منتظر بمانید).'
    generation=int(s.get('scan_generation',0))
    lock=get_entry_lock(chat_id)
    with lock:
        s=get_session(chat_id)
        if s['daily_stopped'] and not force:
            return False, 'محدودیت ضرر روزانه فعال است؛ ورود دستی هم مسدود است.'
        ok=_execute_trade_unlocked(chat_id,symbol,side,price,sl,tp,reason,generation,require_active=False,order_type=order_type,force=force,tp_level_name=tp_level_name,allow_inverse=bool(force))
    if ok:
        return True, ''
    # دلیل دقیق رد شدن (اگر ثبت شده باشد) به‌جای پیام کلی
    detail = _LAST_BLOCK_REASON.pop(chat_id, None)
    if detail:
        return False, detail
    return False, 'ورود دستی رد شد (ممکن است ظرفیت پوزیشن پر باشد، نماد از قبل باز باشد، یا حجم/ریسک معتبر نباشد).'


def _log_grid_levels_sync(symbol):
    """نسخه‌ی همگام get_log_grid_levels (از همان کش LOG_GRID_CACHE استفاده می‌کند) -
    برای مسیرهایی که داخل حلقه‌ی async اسکن نیستند، مثل ورود سریع از دکمه‌ی کانال."""
    now = time.time(); _ck = f'{_venue()}:{symbol}'
    c = LOG_GRID_CACHE.get(_ck)
    if c and now - c['ts'] < LOG_GRID_TTL:
        return c['levels']
    try:
        d = get_klines(symbol, '1day', LOG_GRID_LOOKBACK_DAYS)
        levels = compute_log_grid_levels(d, LOG_GRID_BASE_STEPS) if d is not None and not d.empty else []
    except Exception:
        logger.exception('log grid (sync) failed symbol=%s', symbol)
        levels = []
    LOG_GRID_CACHE[_ck] = {'ts': now, 'levels': levels}
    return levels


HALVING_RANGE_TTL = float(os.environ.get('HALVING_RANGE_TTL_SECONDS', '21600'))  # هر ۶ ساعت
HALVING_RANGE_CACHE: Dict[str, Dict[str, Any]] = {}


HALVING_RANGE_WICK_RATIO = float(os.environ.get('HALVING_RANGE_WICK_RATIO', '0.01') or 0.01)   # V3.44.100: سایه‌ی کمتر از این نسبتِ بدنه (یا بیش از معکوسش) خطای داده است؛ 0 = فیلتر خاموش


def _halving_range_from_df(d):
    """(سقف، کف) تاریخی از کندل‌های هفتگی/روزانه (سایه‌ها: high/low) یا None.
    V3.44.100: سایه‌ی غیرواقعی (مثلاً کف 0.0001 روی کندلی که بدنه‌اش حدود 2 است: LINK هفته‌ی 2020-03-09 در Binance) به بدنه‌ی همان
    کندل محدود می‌شود تا سقف/کف با چارت TradingView یکی بماند و کل شبکه‌ی سطوح جابه‌جا نشود."""
    try:
        if d is None or d.empty or len(d) < 8:
            return None
        hi_s = pd.to_numeric(d['high'], errors='coerce'); lo_s = pd.to_numeric(d['low'], errors='coerce')
        ratio = HALVING_RANGE_WICK_RATIO
        if ratio and ratio > 0 and 'open' in d.columns and 'close' in d.columns:
            op = pd.to_numeric(d['open'], errors='coerce'); cl = pd.to_numeric(d['close'], errors='coerce')
            body_lo = pd.concat([op, cl], axis=1).min(axis=1); body_hi = pd.concat([op, cl], axis=1).max(axis=1)
            bad_lo = (body_lo > 0) & (lo_s < body_lo * ratio)
            bad_hi = (body_hi > 0) & (hi_s > body_hi / ratio)
            if bool(bad_lo.any()) or bool(bad_hi.any()):
                logger.info('halving range: %d low-wick / %d high-wick outlier candle(s) clipped to body', int(bad_lo.sum()), int(bad_hi.sum()))
            lo_s = lo_s.where(~bad_lo, body_lo); hi_s = hi_s.where(~bad_hi, body_hi)
        hi = float(hi_s.max()); lo = float(lo_s.min())
        if math.isfinite(hi) and math.isfinite(lo) and lo > 0 and hi > lo:
            return (hi, lo)
    except Exception:
        pass
    return None


_HIST_RANGE_SRC = {}     # {symbol: ('Binance', (سقف, کف))}؛ برای نمایش منبعِ سقف/کف در گزارش سطوح


# V3.44.92: سقف/کفِ مدل نصف‌کردن باید «دقیقاً» همان اندیکاتور HalvLvl در TradingView باشد. TradingView برای رنج خودکار
# از تاریخچه‌ی همان چارت (Bybit perp) استفاده می‌کند، نه کل تاریخچه‌ی Binance Spot (مثلاً کف اتریوم ۸۱.۷۹ در Binance
# ولی ۸۷۸ در چارت) و شبکه‌ی سطوح کاملاً جابه‌جا می‌شد. ترتیب اولویت:
#   1) env HALVING_RANGE_OVERRIDE   2) جدول داخلی (مقادیرِ استخراج‌شده از چارت TV)   3) Binance (V3.44.97: تنها منبع؛ Bybit و کندل ربات حذف شدند)
# V3.44.99: جدول داخلی BTC/ETH حذف شد؛ سقف/کف همه‌ی نمادها (از جمله BTC/ETH) از کل تاریخچه‌ی صرافیِ حالت (Binance یا Bitunix) می‌آید.
# فقط override صریح کاربر (env HALVING_RANGE_OVERRIDE) بر آن اولویت دارد.
_HALVING_RANGE_BUILTIN = {}


def _halving_manual_table():
    """جدول دستی {BASE: (سقف, کف)}: داخلی + env HALVING_RANGE_OVERRIDE (JSON مثل {"ETHUSDT":[4956,878]})؛
    env مقدار داخلی را بازنویسی می‌کند؛ مقدار \"off\"/null برای یک نماد آن را از جدول حذف می‌کند."""
    table = dict(_HALVING_RANGE_BUILTIN)
    raw = (os.environ.get('HALVING_RANGE_OVERRIDE') or '').strip()
    if raw:
        try:
            data = json.loads(raw)
            if isinstance(data, dict):
                for k, v in data.items():
                    base = _base_asset(k)
                    if v is None or (isinstance(v, str) and v.strip().lower() in ('off', 'none', '')):
                        table.pop(base, None)
                        continue
                    hi, lo = float(v[0]), float(v[1])
                    if math.isfinite(hi) and math.isfinite(lo) and hi > lo > 0:
                        table[base] = (hi, lo)
        except Exception as exc:
            logger.warning('HALVING_RANGE_OVERRIDE invalid: %s', exc)
    return table


def _manual_halving_range(symbol):
    table = _halving_manual_table()
    if _venue() != 'binance':
        # V3.44.98: مقادیر داخلی (BTC/ETH) از چارت/Binance استخراج شده‌اند؛ برای Bitunix فقط override صریح کاربر (env) معتبر است.
        table = {k: v for k, v in table.items() if k not in _HALVING_RANGE_BUILTIN or tuple(v) != tuple(_HALVING_RANGE_BUILTIN[k])}
    rng = table.get(_base_asset(symbol))
    if rng:
        _HIST_RANGE_SRC[symbol] = ('Manual', tuple(rng))
    return rng


def _bitunix_hist_range_sync(symbol):
    """V3.44.98: سقف/کف تاریخیِ نماد از فیوچرز Bitunix (کندل هفتگی تا ۵×۲۰۰؛ اگر تاریخچه کمتر از ۸ هفته بود روزانه). یا None."""
    base = _base_asset(symbol)
    if _bitunix_map_needs_refresh():
        try:
            _bitunix_refresh_symbol_map()
        except Exception as exc:
            logger.debug('bitunix symbol map refresh: %s', exc)
    sym, scale = _bitunix_resolve(base)
    if not sym or not _source_available('bitunix'):
        return None
    for interval in ('1w', '1d'):
        frames = []; end = None
        try:
            for _ in range(5):
                params = {'symbol': sym, 'interval': interval, 'limit': 200}
                if end:
                    params['endTime'] = end
                r = _bitunix_get('/api/v1/futures/market/kline', params, timeout=10)
                if _status_trips_source(r.status_code):
                    _source_trip('bitunix'); return None
                if not r.ok:
                    break
                df = _bitunix_kline_df(r.json())
                if df.empty:
                    break
                frames.append(df)
                if len(df) < 200:
                    break
                end = int(df['timestamp'].iloc[0]) - 1
        except Exception as exc:
            logger.debug('bitunix hist range %s: %s', symbol, exc)
            _source_fail('bitunix')
            return None
        if not frames:
            continue
        _source_ok('bitunix')
        rng = _halving_range_from_df(_bitunix_unscale_df(pd.concat(frames[::-1]).drop_duplicates('timestamp').sort_values('timestamp').reset_index(drop=True), scale))
        if rng:
            logger.info('halving range %s from bitunix/%s: high=%s low=%s', symbol, interval, rng[0], rng[1])
            _HIST_RANGE_SRC[symbol] = ('Bitunix', tuple(rng))
            return rng
    return None


def _hist_range_sync_for_venue(symbol):
    return _bitunix_hist_range_sync(symbol) if _venue() == 'bitunix' else _binance_hist_range_sync(symbol)


def _binance_hist_range_sync(symbol):
    """سقف/کف تاریخیِ واقعی نماد از Binance Spot (سایه‌ها: high/low) یا None.
    کندل هفتگی تا ۱۰۰۰ عدد (≈۱۹ سال، یعنی کل تاریخچه‌ی Binance) در یک درخواست؛ اگر نماد خیلی تازه بود
    (کمتر از ۸ هفته) کندل روزانه. اول api.binance.com و بعد آینه‌ی data-api.binance.vision.
    اگر نماد روی اسپات Binance نبود (مثلاً نام‌های ×۱۰۰۰ فیوچرز) None برمی‌گردد تا مقیاس قیمت
    با منبع معاملاتی یکی بماند و تابع صدا‌زننده به منبع قبلی برگردد."""
    base = _base_asset(symbol)
    if _binance_map_needs_refresh():
        try:
            _binance_refresh_symbol_map()
        except Exception as exc:
            logger.debug('binance symbol map refresh: %s', exc)
    sym = _binance_symbol_from_cache(base)
    if not sym:
        return None
    for source in _BINANCE_SOURCES:
        if not _source_available(source):
            continue
        for interval in ('1w', '1d'):
            try:
                r = requests.get(f'{_binance_base_url(source)}/api/v3/klines',
                                 params={'symbol': sym, 'interval': interval, 'limit': 1000}, timeout=10)
            except Exception as exc:
                logger.debug('%s hist range %s: %s', source, symbol, exc)
                _source_fail(source)
                break
            if _status_trips_source(r.status_code):
                _source_trip(source)
                break
            if not r.ok:
                continue
            _source_ok(source)
            try:
                rng = _halving_range_from_df(_binance_kline_df(r.json()))
            except Exception:
                rng = None
            if rng:
                logger.info('halving range %s from %s/%s: high=%s low=%s', symbol, source, interval, rng[0], rng[1])
                _HIST_RANGE_SRC[symbol] = ('Binance', tuple(rng))
                return rng
    return None


async def get_halving_range(http, symbol):
    """سقف/کف تاریخی نماد برای مدل نصف‌کردن (کش‌شده). فقط Binance (یا جدول دستی/داخلی برای BTC/ETH یا env).
    V3.44.97: Bybit و کندل‌های منبع‌های دیگر حذف شدند؛ نمادی که روی Binance نیست سقف/کف ندارد (None) و معامله نمی‌شود."""
    now = time.time(); _ck = f'{_venue()}:{symbol}'
    c = HALVING_RANGE_CACHE.get(_ck)
    if c and now - c['ts'] < HALVING_RANGE_TTL and c.get('range'):
        return c['range']
    rng = _manual_halving_range(symbol)        # V3.44.92: اول جدول دستی/داخلی (هم‌تراز با TradingView)
    if not rng:
        try:
            rng = await asyncio.to_thread(_hist_range_sync_for_venue, symbol)      # V3.44.98: کل تاریخچه‌ی نماد روی صرافیِ حالت (Binance یا Bitunix)
        except Exception as exc:
            logger.debug('binance hist range %s: %s', symbol, exc)
            rng = None
    if rng:
        HALVING_RANGE_CACHE[_ck] = {'ts': now, 'range': rng}
    elif c and c.get('range'):
        return c['range']      # صرافی لحظه‌ای جواب نداد: آخرین مقدار معتبرِ همان صرافی
    return rng


def get_halving_range_sync(symbol):
    now = time.time(); _ck = f'{_venue()}:{symbol}'
    c = HALVING_RANGE_CACHE.get(_ck)
    if c and now - c['ts'] < HALVING_RANGE_TTL and c.get('range'):
        return c['range']
    rng = _manual_halving_range(symbol)            # V3.44.92: اول جدول دستی/داخلی (هم‌تراز با TradingView)
    if not rng:
        try:
            rng = _hist_range_sync_for_venue(symbol)     # V3.44.98: صرافیِ حالت (Binance یا Bitunix)
        except Exception as exc:
            logger.debug('binance hist range %s: %s', symbol, exc)
            rng = None
    if rng:
        HALVING_RANGE_CACHE[_ck] = {'ts': now, 'range': rng}
    elif c and c.get('range'):
        return c['range']
    return rng


def _with_halving_cfg(cfg, rng):
    """کپی کانفیگ با سقف/کف تاریخی برای مدل نصف‌کردن (بدون دست‌زدن به کانفیگ ذخیره‌شده)."""
    if not (cfg or {}).get('halving_model_enabled') or not rng:
        return cfg
    return {**cfg, 'halving_high': float(rng[0]), 'halving_low': float(rng[1])}


def build_quick_plan_with_fallback(symbol, side, strategy_config, live, tf, df_ind=None):
    """طرح SL/TP ورود سریع (سوینگ/ATR + سطح مقابل)؛ اگر ساخته نشد، SL/TP درصدی جایگزین.
    خروجی: (plan، df با اندیکاتورها یا None). plan همیشه کلید tp_level_name دارد."""
    is_long = side == 'BUY'
    plan, why = None, 'داده‌ی بازار در دسترس نبود'
    if isinstance(strategy_config, dict) and strategy_config.get('halving_model_enabled') and strategy_config.get('halving_high') is None:
        strategy_config = _with_halving_cfg(strategy_config, get_halving_range_sync(symbol))   # هدف‌ها از سطوح نصف‌کردن
    try:
        if df_ind is None:
            df = get_klines(symbol, tf, 650 if tf in ('5min', '15min', '1hour') else 200)
            df_ind = calculate_indicators(df) if df is not None and not df.empty else None
        if df_ind is not None and not df_ind.empty:
            plan, why = build_quick_trade_plan(
                df_ind, side, strategy_config,
                grid_levels=_log_grid_levels_sync(symbol), live_price=live,
            )
    except Exception:
        logger.exception('quick trade plan failed symbol=%s', symbol)
    if not plan:
        # طرح اصلی (سوینگ/ATR) ساخته نشد؛ SL/TP درصدی ساده ساخته می‌شود.
        d = float(live) * QUICK_TRADE_FALLBACK_SL_PCT
        k = 1 if is_long else -1
        plan = {'sl': float(live) - k * d, 'tp': float(live) + k * d * QUICK_TRADE_FALLBACK_RR,
                'rr': QUICK_TRADE_FALLBACK_RR, 'sl_source': f'درصدی {QUICK_TRADE_FALLBACK_SL_PCT*100:g}% (جایگزین: {why})',
                'tp_source': f'{QUICK_TRADE_FALLBACK_RR:g}R', 'reason': 'ورود سریع کانال | SL/TP درصدی جایگزین',
                'tp_level_name': f'بدون سطح مشخص - هدف {QUICK_TRADE_FALLBACK_RR:g}R (درصدی)', 'entry': float(live)}
    return plan, df_ind


_SIGNAL_ORIGIN = threading.local()


def _from_signal_origin(fn):
    """معامله‌هایی که از سیگنال کانال/دستیار شروع می‌شوند: کارت ورودشان تا پاک‌سازی روزانه می‌ماند (حذف خودکار ۳ دقیقه‌ای ندارد)."""
    @functools.wraps(fn)
    def _wrapper(*a, **k):
        prev = getattr(_SIGNAL_ORIGIN, 'on', False)
        _SIGNAL_ORIGIN.on = True
        try:
            return fn(*a, **k)
        finally:
            _SIGNAL_ORIGIN.on = prev
    return _wrapper


@_from_signal_origin
def quick_channel_trade(chat_id, symbol, side, skip_trend=False):
    """ورود فوری با قیمت بازار از دکمه‌ی 🟢/🔴 زیر پیام کانال.
    کاربر فقط جهت را با انتخاب دکمه مشخص می‌کند؛ SL/TP را build_quick_trade_plan
    (سوینگ/ATR + سطح مقابل) می‌سازد و اجرا از همان مسیر معامله‌ی دستی می‌گذرد
    (سایزینگ بر اساس ریسک، سقف پوزیشن، کول‌داون، ...). در REAL سفارش Market است."""
    s = get_session(chat_id)
    symbol = re.sub(r'[^A-Z0-9]', '', str(symbol).upper())
    is_long = side == 'BUY'
    side_fa = 'خرید (Long)' if is_long else 'فروش (Short)'
    if not (2 <= len(symbol) <= 12):
        send_message(chat_id, '⚠️ نماد نامعتبر است.'); return
    # ورود سریع از کانال بدون موانع استراتژیک: حد ضرر روزانه، سقف پوزیشن باز، کول‌داون، محافظ ریسک،
    # ستاپ/سطح مصرف‌شده و ... نادیده گرفته می‌شوند. استثنا: «سقف معاملات هم‌جهت» (V3.42.8) که روی
    # همه‌ی ورودها اعمال می‌شود. مانع فنی دیگر: وجود پوزیشن باز روی همین نماد (یک پوزیشن به‌ازای هر نماد).
    if any(p['symbol'] == symbol for p in s['paper_positions']):
        send_message(chat_id, f'⚠️ برای `{symbol}` همین حالا یک پوزیشن باز داری.'); return
    # V3.42.7: هشدار تضاد با روند BTC/ETH قبل از ورود سریع از کانال (با کلیدهای منوی فیلتر قابل خاموش‌شدن)
    if not skip_trend and _assist_trend_warn(chat_id, symbol, side, f"/qt_tgok_{'buy' if is_long else 'sell'}_{symbol}", '/assist_trendcancel'):
        return

    try:
        live = exchange_latest_price(chat_id, symbol) if s.get('trading_mode') == 'REAL' else latest_price(symbol)
    except Exception:
        live = None
    if not live:
        send_message(chat_id, f'❌ قیمت لحظه‌ای `{symbol}` دریافت نشد.'); return
    tf = s['timeframe']
    plan, _df_ind = build_quick_plan_with_fallback(symbol, side, s.get('strategy_config'), live, tf)

    ok, err = execute_manual_trade(
        chat_id, symbol, 'BUY (Long)' if is_long else 'SELL (Short)', plan['sl'], plan['tp'],
        entry_price=live, reason=plan['reason'], order_type='market', force=True,
        tp_level_name=plan.get('tp_level_name'),
    )
    if not ok:
        send_detail_message(chat_id, f'❌ ورود سریع `{symbol}` باز نشد: {err}', simple_text=f'❌ ورود سریع `{symbol}` باز نشد.' + (f"\n{block_simple_text(err)}" if block_simple_text(err) else '')); return
    s = get_session(chat_id)
    pos = next((p for p in reversed(s['paper_positions']) if p['symbol'] == symbol), None)
    if pos:
        send_message(chat_id,
            f"⚡ *ورود سریع انجام شد* — `{symbol}` {side_fa}\n"
            f"• ورود (بازار): `{fmt(pos['entry_price'])}`\n"
            f"• حد ضرر: `{fmt(pos['sl'])}` ({plan['sl_source']})\n"
            f"• حد سود: `{fmt(pos['tp'])}` ({plan['tp_source']})\n"
            f"• سطح هدف (TP): `{plan.get('tp_level_name') or '-'}`\n"
            f"• R:R: `{plan['rr']:.2f}` | مقدار معامله: `{fmt(pos['margin'])}` × اهرم `{pos['leverage']}` | ریسک: `{pos['risk_usdt']:.2f}$`\n"
            + (f"• 💰 سود در صورت TP (پس از کارمزد): `{pos['expected_tp_pnl_net']:+.2f} USDT`\n"
               f"• 🛑 زیان در صورت SL (با کارمزد): `{pos['expected_sl_pnl_net']:+.2f} USDT`\n"
               if pos.get('expected_tp_pnl_net') is not None else "") +
            f"• تایم‌فریم: `{TF_DISPLAY.get(tf, tf)}`")


def realized_history_value(chat_id,symbol,opened_at):
    rows=position_history_for(chat_id,symbol,max(0,int((opened_at-120)*1000)))
    if not rows: return None
    best=None; best_ts=0
    for r in rows:
        rp=(r.get('realizedPnl') if r.get('realizedPnl') is not None else (r.get('info') or {}).get('realized_pnl')) if isinstance(r,dict) else None
        try: rp=float(rp)
        except: continue
        ts=float(r.get('timestamp') or r.get('datetime') and time.mktime(time.strptime(r['datetime'],'%Y-%m-%dT%H:%M:%S.%fZ'))*1000 or 0)
        if ts>=best_ts: best_ts=ts; best=rp
    return best


