def fee_reload_state():
    """مجموعه‌ی کاربران مسدود و پیام‌های محافظت‌شده را از دیتابیس دوباره می‌سازد (شروع برنامه و هر تغییر وضعیت فاکتور)."""
    blocked = set(); prot = {}
    try:
        with DB_LOCK:
            conn = db_connect()
            try:
                rows = conn.execute("SELECT chat_id,status,msg_ids FROM fee_invoices WHERE status IN ('PENDING','OVERDUE')").fetchall()
            finally:
                conn.close()
        for cid, st, mids in rows:
            if st == 'OVERDUE':
                blocked.add(int(cid))
            for m in str(mids or '').split(','):
                if m.strip().isdigit():
                    prot.setdefault(int(cid), set()).add(int(m))
    except Exception:
        logger.exception('fee state reload failed')
        return
    with _FEE_STATE_LOCK:
        _FEE_BLOCKED.clear(); _FEE_BLOCKED.update(blocked)
        _FEE_PROT.clear(); _FEE_PROT.update(prot)


def is_fee_blocked(chat_id):
    if PLATFORM_FEE_MODE != 'daily':
        return False
    try:
        cid = int(chat_id)
    except Exception:
        return False
    if cid in ADMIN_CHAT_IDS:
        return False
    with _FEE_STATE_LOCK:
        return cid in _FEE_BLOCKED


def fee_protected_ids(chat_id):
    try:
        cid = int(chat_id)
    except Exception:
        return set()
    with _FEE_STATE_LOCK:
        out = set(_FEE_PROT.get(cid, ()))
        for lst in _FEE_ADMIN_MSG.values():
            for aid, mid in lst:
                if aid == cid:
                    out.add(mid)
    return out


def fee_block_allows(data):
    d = str(data or '').strip()
    if not d:
        return False
    if d.startswith(_FEE_BLOCK_ALLOW_PREFIXES):
        return True
    dl = d.replace('\u200c', '')
    # دکمه‌های کیبورد ثابت: پوزیشن‌ها / بستن همه / بستن اضطراری / V3.44.63: «🔴 توقف اسکن» (توقف هیچ‌وقت نباید بسته باشد؛ فقط «شروع اسکن» و ورود جدید برای حساب مسدود بسته می‌ماند)
    return any(w in dl for w in ('پوزیشن', 'بستن', 'اضطراری', 'توقف اسکن', '🔴 توقف'))


def _fee_claim_keyboard(inv_id):
    return {'inline_keyboard': [[{'text': '✅ واریز کردم', 'callback_data': f'/fee_claim_{int(inv_id)}'}]]}


def _fee_add_msg(inv_id, chat_id, mid):
    if not mid:
        return
    with DB_LOCK:
        conn = db_connect()
        try:
            conn.execute('PRAGMA busy_timeout=15000')
            row = conn.execute('SELECT msg_ids FROM fee_invoices WHERE id=?', (int(inv_id),)).fetchone()
            new = (str(row[0] or '') + ',' + str(int(mid))).strip(',') if row else str(int(mid))
            conn.execute('UPDATE fee_invoices SET msg_ids=? WHERE id=?', (new, int(inv_id)))
            conn.commit()
        finally:
            conn.close()
    with _FEE_STATE_LOCK:
        _FEE_PROT.setdefault(int(chat_id), set()).add(int(mid))


def _fee_send(chat_id, text, markup=None, inv_id=None):
    """پیام کارمزد را به کاربر می‌فرستد و (اگر inv_id داده شد) شناسه‌اش را محافظت می‌کند تا تا تسویه حذف نشود."""
    try:
        _LAST_SENT.mid = None
        ok = send_message(chat_id, text, markup, keep=True)
        mid = getattr(_LAST_SENT, 'mid', None)
        if inv_id and mid:
            _fee_add_msg(inv_id, chat_id, mid)
        return ok
    except Exception:
        logger.exception('fee message send failed chat=%s', chat_id)
        return False


def _fee_notify_admins(text, markup=None, inv_id=None):
    for aid in list(ADMIN_CHAT_IDS):
        try:
            _LAST_SENT.mid = None
            send_message(aid, text, markup, keep=True)
            mid = getattr(_LAST_SENT, 'mid', None)
            if inv_id and mid:
                with _FEE_STATE_LOCK:
                    _FEE_ADMIN_MSG.setdefault(int(inv_id), []).append((int(aid), int(mid)))
        except Exception:
            logger.exception('fee admin notice failed admin=%s', aid)


def fee_issue_for_day(day):
    return fee_issue_for_range(day, _df.shift_day(day, 1), 'daily')


def fee_issue_for_range(day, end_excl, period='daily'):
    """فاکتور بازه‌ی [day, end_excl) را برای همه‌ی کاربران (غیرادمین) می‌سازد و پیام می‌فرستد. روزانه: یک روز.
    کلید فاکتور (`day`) = روز شروع بازه. خروجی: [(chat_id, day, profit, fee)]"""
    tz = _fee_tz(); start, _x = _df.day_bounds(day, tz); end, _y = _df.day_bounds(end_excl, tz)
    end_day = _df.shift_day(end_excl, -1)
    account = fee_payment_account()
    made = []
    for cid, s in list(USER_SESSIONS.items()):
        try:
            if int(cid) in ADMIN_CHAT_IDS:
                continue
            profit, n = _df.day_profit(list(s.get('closed_positions') or []), start, end, FEE_INCLUDE_PAPER)
            if n <= 0:
                continue
            rate = get_user_fee_rate(cid)
            fee = _df.compute_fee(profit, rate, PLATFORM_FEE_MIN_PROFIT_USDT)
            if fee <= 0:
                continue
            now = time.time()
            due = _df.due_timestamp(now, tz, FEE_DUE_HOUR, FEE_MIN_GRACE_HOURS)
            with DB_LOCK:
                conn = db_connect()
                try:
                    conn.execute('PRAGMA busy_timeout=15000')
                    cur = conn.execute('INSERT OR IGNORE INTO fee_invoices(chat_id,day,profit_usdt,fee_rate_pct,fee_usdt,trades,status,created_at,due_ts,period,end_day) VALUES(?,?,?,?,?,?,?,?,?,?,?)',
                                       (int(cid), day, float(profit), float(rate), float(fee), int(n), 'PENDING', now, due, period, end_day))
                    is_new = cur.rowcount > 0
                    row = conn.execute('SELECT id FROM fee_invoices WHERE chat_id=? AND day=?', (int(cid), day)).fetchone()
                    conn.commit()
                finally:
                    conn.close()
            if not is_new or not row:
                continue
            inv_id = int(row[0])
            made.append((int(cid), day, float(profit), float(fee)))
            _fee_send(cid, _df.invoice_message(day, profit, rate, fee, due, tz, account, FEE_DAY_TZ, period, end_day), _fee_claim_keyboard(inv_id), inv_id)
            audit_event(cid, f'fee-{day}', 'fee_invoice_issued', {'day': day, 'end_day': end_day, 'period': period, 'profit_usdt': profit, 'fee_usdt': fee, 'rate_pct': rate, 'trades': n, 'due_ts': due})
        except Exception:
            logger.exception('fee invoice failed chat=%s day=%s', cid, day)
    return made


def fee_process_overdue():
    """فاکتورهای PENDING که مهلتشان گذشته → OVERDUE و مسدودسازی کاربر."""
    now = time.time()
    with DB_LOCK:
        conn = db_connect()
        try:
            rows = conn.execute("SELECT id,chat_id,day,fee_usdt,period,end_day FROM fee_invoices WHERE status='PENDING' AND due_ts<=?", (now,)).fetchall()
        finally:
            conn.close()
    if not rows:
        return
    changed = []
    for inv_id, cid, day, fee, _per, _end in rows:
        with DB_LOCK:
            conn = db_connect()
            try:
                conn.execute('PRAGMA busy_timeout=15000')
                cur = conn.execute("UPDATE fee_invoices SET status='OVERDUE' WHERE id=? AND status='PENDING'", (int(inv_id),))
                conn.commit()
                if cur.rowcount > 0:
                    changed.append((int(inv_id), int(cid), day, float(fee), _per, _end))
            finally:
                conn.close()
    if not changed:
        return
    fee_reload_state()
    account = fee_payment_account()
    for inv_id, cid, day, fee, _per, _end in changed:
        _fee_send(cid, _df.blocked_message(day, fee, account, _per or 'daily', _end), _fee_claim_keyboard(inv_id), inv_id)
        audit_event(cid, f'fee-{day}', 'fee_user_blocked', {'day': day, 'fee_usdt': fee})
    lines = ['⛔ *کاربران مسدودشده به‌خاطر کارمزد پرداخت‌نشده:*'] + [f'• `{cid}` — {_fee_lbl(day, _per, _end)} — `{fee:.2f} USDT`' for _i, cid, day, fee, _per, _end in changed]
    _fee_notify_admins('\n'.join(lines))


def fee_daily_tick():
    tz = _fee_tz(); period = fee_period()
    today = _df.day_key(time.time(), tz)
    complete = _df.shift_day(today, -1)          # آخرین روزِ کاملِ گذشته
    last = _fee_meta_get('fee_invoiced_through')
    if not last:
        # اولین اجرا: از روزهای قبل فاکتور نمی‌سازیم؛ از «دیروز» به بعد حساب می‌شود.
        _fee_meta_set('fee_invoiced_through', complete); last = complete
    if period == 'daily':
        last = max(last, _df.shift_day(complete, -7))     # مثل قبل: حداکثر ۷ روز عقب‌افتاده
    cursor = _df.shift_day(last, 1)
    for _ in range(24):
        end_excl = _df.period_end_excl(cursor, period, FEE_WEEK_START)
        end_incl = _df.shift_day(end_excl, -1)
        if end_incl > complete:                    # این بازه هنوز تمام نشده
            break
        # تغییر دوره وسط راه: بازه از «روز بعد از آخرین فاکتور» شروع می‌شود، پس هیچ روزی دوبار حساب نمی‌شود
        made = fee_issue_for_range(cursor, end_excl, period)
        _fee_meta_set('fee_invoiced_through', end_incl)
        if made:
            total = sum(m[3] for m in made)
            warn = '' if fee_payment_account() else '\n⚠️ حساب پرداخت تنظیم نشده است: دکمه‌ی «🏦 حساب واریز» در منوی کارمزد'
            _fee_notify_admins(f'🧾 *فاکتور کارمزد {_df.PERIOD_FA[period]} — {_fee_lbl(cursor, period, end_incl)}*\n• تعداد کاربر: `{len(made)}`\n• جمع کارمزد: `{total:.2f} USDT`\n• مهلت پرداخت: ساعت `{FEE_DUE_HOUR:02d}:00` ({FEE_DAY_TZ}){warn}')
        cursor = end_excl
    fee_process_overdue()


def _fee_daily_loop():
    if PLATFORM_FEE_MODE != 'daily':
        logger.info('PLATFORM_FEE_MODE=%s - فاکتور روزانه‌ی کارمزد خاموش است.', PLATFORM_FEE_MODE)
        return
    logger.info('کارمزد روزانه فعال: مرز روز=%s، مهلت پرداخت=%02d:00', FEE_DAY_TZ, FEE_DUE_HOUR)
    while True:
        try:
            fee_daily_tick()
        except Exception:
            logger.exception('fee daily tick failed')
        time.sleep(30)


def fee_settle_invoices(target, status='PAID', day=None, inv_id=None, notify_user=True):
    """فاکتورهای باز کاربر را PAID/WAIVED می‌کند. خروجی: [(id, day, fee)]"""
    sel = "SELECT id,day,fee_usdt,period,end_day FROM fee_invoices WHERE chat_id=? AND status IN ('PENDING','OVERDUE')"
    args = [int(target)]
    if day:
        sel += ' AND day=?'; args.append(day)
    if inv_id:
        sel += ' AND id=?'; args.append(int(inv_id))
    done = []; _fee_done_meta = {}
    with DB_LOCK:
        conn = db_connect()
        try:
            conn.execute('PRAGMA busy_timeout=15000')
            rows = conn.execute(sel, tuple(args)).fetchall()
            for r_id, r_day, r_fee, _per, _end in rows:
                cur = conn.execute("UPDATE fee_invoices SET status=?, paid_at=? WHERE id=? AND status IN ('PENDING','OVERDUE')", (status, time.time(), int(r_id)))
                if cur.rowcount > 0:
                    done.append((int(r_id), r_day, float(r_fee)))
                    _fee_done_meta[int(r_id)] = (_per or 'daily', _end)
            conn.commit()
        finally:
            conn.close()
    if not done:
        return done
    with _FEE_STATE_LOCK:
        for r_id, _d, _f in done:
            _FEE_ADMIN_MSG.pop(r_id, None)
    fee_reload_state()
    for r_id, r_day, r_fee in done:
        audit_event(target, f'fee-{r_day}', 'fee_invoice_' + status.lower(), {'day': r_day, 'fee_usdt': r_fee})
    if notify_user:
        still = is_fee_blocked(target)
        for r_id, r_day, r_fee in done:
            if status == 'PAID':
                send_message(target, _df.paid_message(r_day, r_fee, still, *_fee_done_meta.get(r_id, ('daily', None))))
            else:
                send_message(target, f'ℹ️ کارمزد {_fee_lbl(r_day, *_fee_done_meta.get(r_id, ("daily", None)))} توسط ادمین بخشیده شد.' + ('' if still else '\n✅ حساب شما فعال است.'))
    return done


def fee_claim(chat_id, inv_id):
    """دکمه‌ی «✅ واریز کردم» کاربر: برای ادمین درخواست تایید می‌فرستد."""
    with DB_LOCK:
        conn = db_connect()
        try:
            row = conn.execute('SELECT chat_id,day,fee_usdt,status,period,end_day FROM fee_invoices WHERE id=?', (int(inv_id),)).fetchone()
            urow = conn.execute('SELECT username,first_name FROM users WHERE chat_id=?', (int(chat_id),)).fetchone()
        finally:
            conn.close()
    if not row or int(row[0]) != int(chat_id):
        send_message(chat_id, '❌ این فاکتور پیدا نشد.'); return
    _cid, day, fee, status, _per, _end = row
    day = _fee_lbl(day, _per, _end)
    if status not in _FEE_OPEN:
        send_message(chat_id, 'ℹ️ این فاکتور قبلاً تسویه شده است.'); return
    now = time.time()
    if now - _FEE_CLAIM_TS.get(int(inv_id), 0) < 300:
        send_message(chat_id, '⏳ درخواست شما قبلاً برای ادمین ارسال شده؛ لطفاً منتظر تایید بمانید.'); return
    _FEE_CLAIM_TS[int(inv_id)] = now
    name = ' '.join(x for x in ((urow or (None, None))[1],) if x) or 'بدون نام'
    uname = f'@{urow[0]}' if urow and urow[0] else '—'
    text = (f'🧾 *اعلام واریز کارمزد*\n\nکاربر: `{name}` — `{uname}`\nChat ID: `{chat_id}`\n{'روز' if (_per or 'daily') == 'daily' else 'بازه'}: `{day}`\nمبلغ: `{float(fee):.2f} USDT`\n'
            f'وضعیت: `{_FEE_STATUS_FA.get(status, status)}`\n\nبعد از بررسی حساب خودتان، تایید را بزنید.')
    markup = {'inline_keyboard': [[{'text': f'✅ تایید دریافت #{int(inv_id)}', 'callback_data': f'/fee_ok_{int(inv_id)}'}]]}
    _fee_notify_admins(text, markup, inv_id=int(inv_id))
    send_message(chat_id, '✅ اعلام واریز شما برای ادمین ارسال شد؛ بعد از تایید ادمین، پیام فعال‌سازی می‌گیرید.')


def fee_notify_blocked(chat_id):
    """وقتی کاربر مسدود دکمه/دستور غیرمجاز می‌زند: یادآوری بدهی (حداکثر هر ۲۰ ثانیه)."""
    now = time.time()
    if now - _FEE_BLOCK_NOTICE_TS.get(int(chat_id), 0) < 20:
        return
    _FEE_BLOCK_NOTICE_TS[int(chat_id)] = now
    with DB_LOCK:
        conn = db_connect()
        try:
            rows = conn.execute("SELECT id,day,fee_usdt,status,period,end_day FROM fee_invoices WHERE chat_id=? AND status IN ('PENDING','OVERDUE') ORDER BY day LIMIT 5", (int(chat_id),)).fetchall()
        finally:
            conn.close()
    acct = fee_payment_account()
    lines = ['⛔ *حساب شما به‌دلیل کارمزد پرداخت‌نشده مسدود است.*', '']
    lines += [f'• {"روز" if (_p or "daily") == "daily" else "بازه"} `{_fee_lbl(d, _p, _e)}` — `{float(f):.2f} USDT` — {_FEE_STATUS_FA.get(st, st)}' for _i, d, f, st, _p, _e in rows]
    if acct:
        lines += ['', 'حساب ادمین:', f'`{acct.replace(chr(96), chr(39))}`']
    lines += ['', 'بعد از واریز، دکمه‌ی زیر را بزنید. (دیدن و بستن پوزیشن‌ها همچنان آزاد است.)']
    send_message(chat_id, '\n'.join(lines), _fee_claim_keyboard(rows[0][0]) if rows else None)


def fee_debts(limit=8):
    """(متن، کیبورد) فاکتورهای پرداخت‌نشده برای ادمین."""
    with DB_LOCK:
        conn = db_connect()
        try:
            rows = conn.execute('''SELECT i.id,i.chat_id,i.day,i.fee_usdt,i.status,i.due_ts,u.username,i.period,i.end_day FROM fee_invoices i
                                   LEFT JOIN users u ON u.chat_id=i.chat_id WHERE i.status IN ('PENDING','OVERDUE')
                                   ORDER BY i.due_ts LIMIT 30''').fetchall()
        finally:
            conn.close()
    tz = _fee_tz()
    total = sum(float(r[3]) for r in rows)
    lines = ['📋 *کارمزدهای پرداخت‌نشده*', '', f'• تعداد: `{len(rows)}` | جمع: `{total:.2f} USDT`', '']
    for i_id, cid, day, fee, st, due, uname, _per, _end in rows:
        day = _fee_lbl(day, _per, _end)
        due_txt = datetime.fromtimestamp(float(due), tz).strftime('%m-%d %H:%M')
        lines.append(f"• #{i_id} `{cid}`{(' @' + uname) if uname else ''} — {day} — `{float(fee):.2f}` — {_FEE_STATUS_FA.get(st, st)} (مهلت {due_txt})")
    if not rows:
        lines.append('هیچ بدهی بازی وجود ندارد ✅')
    acct = fee_payment_account()
    lines += ['', f"حساب پرداخت: `{acct}`" if acct else '⚠️ حساب پرداخت تنظیم نشده (کلید «🏦 حساب واریز» در منوی کارمزد)',
              'دستورها: `/fee_paid USER_ID [YYYY-MM-DD]` | `/fee_waive USER_ID [YYYY-MM-DD]`']
    rows_kb = [[{'text': f'✅ تایید #{r[0]} ({r[1]})', 'callback_data': f'/fee_ok_{r[0]}'}] for r in rows[:limit]]
    rows_kb.append([{'text': '👑 بازگشت به کارمزد', 'callback_data': '/admin_fee_menu'}])
    return '\n'.join(lines), {'inline_keyboard': rows_kb}


def fee_handle_command(cmd, chat_id, message_id=None):
    """دستورهای کارمزد روزانه. True = دستور مال این بخش بود و اجرا شد."""
    c = str(cmd or '').strip()
    m = re.match(r'^/fee_claim_(\d+)$', c)
    if m:
        fee_claim(chat_id, int(m.group(1))); return True
    is_ok = re.match(r'^/fee_ok_(\d+)$', c)
    first = c.split(None, 1)[0] if c else ''
    if not (is_ok or c == '/fee_debts' or first in ('/fee_paid', '/fee_waive', '/set_fee_account')
            or c.startswith('/admin_fee_period_') or c == '/admin_fee_account_prompt'):
        return False
    if not is_admin(chat_id):
        send_message(chat_id, '⛔ دسترسی ادمین ندارید.'); return True
    if is_ok:
        inv_id = int(is_ok.group(1))
        with DB_LOCK:
            conn = db_connect()
            try:
                row = conn.execute('SELECT chat_id FROM fee_invoices WHERE id=?', (inv_id,)).fetchone()
            finally:
                conn.close()
        if not row:
            send_message(chat_id, '❌ فاکتور پیدا نشد.'); return True
        done = fee_settle_invoices(int(row[0]), 'PAID', inv_id=inv_id)
        send_message(chat_id, f'✅ فاکتور #{inv_id} تایید شد (کاربر `{row[0]}`).' if done else f'ℹ️ فاکتور #{inv_id} قبلاً تسویه شده بود.')
        return True
    if c.startswith('/admin_fee_period_'):
        per = c[len('/admin_fee_period_'):]
        if not fee_set_period(per):
            send_message(chat_id, '⚠️ دوره‌ی نامعتبر.'); return True
        note = ('\n\nℹ️ از فاکتور بعدی اعمال می‌شود. روزهای قبلاً فاکتورشده دوباره حساب نمی‌شوند؛ '
                'فاکتور بعدی از روز بعد از آخرین فاکتور تا پایان دوره‌ی جدید را شامل می‌شود.')
        edit_page(chat_id, fee_admin_header() + note + '\n\n' + admin_fee_report('all'), get_admin_fee_menu_keyboard(), message_id)
        return True
    if c == '/admin_fee_account_prompt':
        s = get_session(chat_id); s['user_state'] = 'WAIT_ADMIN_FEE_ACCOUNT'; save_session(chat_id)
        cur = fee_payment_account()
        send_message(chat_id, '🏦 *حساب واریز کارمزد*\n\n' + (f"حساب فعلی: `{cur.replace(chr(96), chr(39))}`\n\n" if cur else 'حسابی تنظیم نشده.\n\n')
                     + 'آدرس/شماره‌ی حسابی که کاربران باید کارمزد را به آن واریز کنند را بفرستید (مثلاً آدرس کیف پول + شبکه).\nبرای حذف حساب بنویسید: `حذف`')
        return True
    if c == '/fee_debts':
        text, mk = fee_debts()
        edit_page(chat_id, text, mk, message_id); return True
    if first == '/set_fee_account':
        acct = c[len('/set_fee_account'):].strip()
        if not acct:
            cur = fee_payment_account()
            send_message(chat_id, ('حساب فعلی: `' + cur.replace(chr(96), chr(39)) + '`\n' if cur else 'حسابی تنظیم نشده.\n') + 'فرمت: `/set_fee_account متن_حساب_یا_آدرس`')
            return True
        _fee_meta_set('fee_payment_account', acct)
        send_message(chat_id, '✅ حساب پرداخت ذخیره شد و در پیام‌های فاکتور بعدی نمایش داده می‌شود.')
        return True
    parts = c.split()
    status = 'PAID' if first == '/fee_paid' else 'WAIVED'
    if len(parts) not in (2, 3) or not parts[1].lstrip('-').isdigit():
        send_message(chat_id, f'فرمت: `{first} USER_CHAT_ID [YYYY-MM-DD]`\nبدون تاریخ = همه‌ی فاکتورهای باز آن کاربر.')
        return True
    day = parts[2] if len(parts) == 3 else None
    if day:
        try:
            datetime.strptime(day, '%Y-%m-%d')
        except Exception:
            send_message(chat_id, '❌ تاریخ باید به شکل `YYYY-MM-DD` باشد.'); return True
    done = fee_settle_invoices(int(parts[1]), status, day=day)
    word = 'تایید پرداخت' if status == 'PAID' else 'بخشیده'
    send_message(chat_id, f'✅ {len(done)} فاکتور {word} شد (کاربر `{parts[1]}`).' if done else 'ℹ️ فاکتور بازی برای این کاربر/روز پیدا نشد.')
    return True


def _fee_since(period):
    now = time.time()
    return {'day': now - 86400, 'week': now - 7 * 86400, 'month': now - 30 * 86400}.get(period, 0)


def _fee_report_daily(chat_id, period):
    since = _fee_since(period)
    with DB_LOCK:
        conn = db_connect()
        try:
            tot = conn.execute("SELECT COALESCE(SUM(profit_usdt),0),COALESCE(SUM(fee_usdt),0),COUNT(*) FROM fee_invoices WHERE chat_id=? AND created_at>=? AND status!='WAIVED'", (int(chat_id), since)).fetchone()
            unpaid = conn.execute("SELECT COALESCE(SUM(fee_usdt),0) FROM fee_invoices WHERE chat_id=? AND status IN ('PENDING','OVERDUE')", (int(chat_id),)).fetchone()
            rows = conn.execute('SELECT day,profit_usdt,fee_usdt,status FROM fee_invoices WHERE chat_id=? AND created_at>=? ORDER BY day DESC LIMIT 5', (int(chat_id), since)).fetchall()
        finally:
            conn.close()
    profit, fee, count = tot or (0, 0, 0)
    lines = [f'💰 *کارمزد پلتفرم ({_df.PERIOD_FA[fee_period()]})*', '', f'• بازه: `{period}`', f'• فاکتورهای صادرشده: `{count}`',
             f'• سود روزهای فاکتورشده: `{profit:.2f} USDT`', f'• کارمزد این بازه: `{fee:.2f} USDT`',
             f'• ⚠️ پرداخت‌نشده: `{float((unpaid or (0,))[0]):.2f} USDT`', f'• نرخ فعلی: `{get_user_fee_rate(chat_id):.2f}%`']
    if rows:
        lines += ['', '*آخرین فاکتورها:*'] + [f'• {d}: سود `{float(p):+.2f}` → کارمزد `{float(f):.2f}` — {_FEE_STATUS_FA.get(st, st)}' for d, p, f, st in rows]
    return '\n'.join(lines)


_FEE_PERIOD_DAYS = {'day': 1, 'week': 7, 'month': 30}
_FEE_PERIOD_FA = {'day': 'امروز', 'week': '۷ روز اخیر', 'month': '۳۰ روز اخیر'}
FEE_REPORT_MAX_DAYS = 31


def _fee_report_by_day(chat_id, period='all'):
    """V3.44.63: گزارش «💰 کارمزد من» برای کاربر: لیست کارمزد هر روز (جدیدترین اول) + جمع کل کارمزد.
    حالت روزانه: فاکتورهای ثبت‌شده + کارمزد «امروز» به‌صورت تخمینی (هنوز فاکتور نشده).
    حالت هر معامله: کارمزدهای کسرشده، گروه‌بندی بر اساس روز. روزهای زیان‌ده کارمزد ندارند و در لیست نمی‌آیند."""
    tz = _fee_tz()
    now = time.time()
    today = _df.day_key(now, tz)
    n_days = _FEE_PERIOD_DAYS.get(period)
    cutoff = _df.shift_day(today, -(n_days - 1)) if n_days else None        # روز تقویمی، نه ۲۴ ساعت متحرک
    rows = []            # (day, profit, fee, status_fa, counted)
    unpaid = None
    with DB_LOCK:
        conn = db_connect()
        try:
            if PLATFORM_FEE_MODE == 'daily':
                for d, p, f, st in conn.execute('SELECT day,profit_usdt,fee_usdt,status FROM fee_invoices WHERE chat_id=? ORDER BY day DESC', (int(chat_id),)).fetchall():
                    if cutoff is None or d >= cutoff:
                        rows.append((d, float(p), float(f), _FEE_STATUS_FA.get(st, st), st != 'WAIVED', st))
                unpaid = float(conn.execute("SELECT COALESCE(SUM(fee_usdt),0) FROM fee_invoices WHERE chat_id=? AND status IN ('PENDING','OVERDUE')", (int(chat_id),)).fetchone()[0] or 0)
            else:
                per_day = {}
                for ts, p, f in conn.execute('SELECT created_at,net_profit_before_platform_fee_usdt,platform_fee_usdt FROM fee_ledger WHERE chat_id=?', (int(chat_id),)).fetchall():
                    d = _df.day_key(float(ts), tz)
                    if cutoff is None or d >= cutoff:
                        a = per_day.setdefault(d, [0.0, 0.0]); a[0] += float(p or 0); a[1] += float(f or 0)
                for d in sorted(per_day, reverse=True):
                    rows.append((d, per_day[d][0], per_day[d][1], 'کسر‌شده از سود', True, 'SETTLED'))
        finally:
            conn.close()
    if PLATFORM_FEE_MODE == 'daily' and not any(r[0] == today for r in rows):
        try:
            s = get_session(chat_id)
            st_ts, en_ts = _df.day_bounds(today, tz)
            tp, tn = _df.day_profit(list(s.get('closed_positions') or []), st_ts, en_ts, FEE_INCLUDE_PAPER)
            tf = _df.compute_fee(tp, get_user_fee_rate(chat_id), PLATFORM_FEE_MIN_PROFIT_USDT) if tn > 0 else 0.0
            if tf > 0:
                rows.insert(0, (today, float(tp), float(tf), 'تخمینی تا این لحظه (هنوز فاکتور نشده)', True, 'LIVE'))
        except Exception:
            logger.exception('fee report: today estimate failed chat=%s', chat_id)
    counted = [r for r in rows if r[4]]
    total_fee = sum(r[2] for r in counted)
    total_profit = sum(r[1] for r in counted)
    paid_fee = sum(r[2] for r in counted if r[5] == 'PAID')
    shown, rest = rows[:FEE_REPORT_MAX_DAYS], rows[FEE_REPORT_MAX_DAYS:]
    lines = ['💰 *کارمزد من*', '', f"بازه: {_FEE_PERIOD_FA.get(period, 'کل سابقه')}", '', '*📅 تفکیک روزانه:*']
    if shown:
        for d, p, f, st_fa, ok, st in shown:
            lines.append(f"• `{d}` — سود `{p:+.2f}` ← کارمزد `{f:.2f}` — {st_fa}")
        if rest:
            rc = [r for r in rest if r[4]]
            lines.append(f"• … و `{len(rest)}` روز قدیمی‌تر — کارمزد `{sum(r[2] for r in rc):.2f}`")
    else:
        lines.append('• در این بازه هنوز کارمزدی ثبت نشده است.')
    lines += ['', '*جمع کل:*',
              f'• تعداد روزهای دارای کارمزد: `{len(counted)}`',
              f'• جمع سود این روزها: `{total_profit:+.2f} USDT`',
              f'• 💰 *جمع کل کارمزد: `{total_fee:.2f} USDT`*']
    if unpaid is not None:
        lines += [f'• پرداخت‌شده: `{paid_fee:.2f} USDT`', f'• ⚠️ پرداخت‌نشده (کل): `{unpaid:.2f} USDT`']
    lines += [f'• نرخ فعلی: `{get_user_fee_rate(chat_id):.2f}%`', '', '_فقط روزهای سودده کارمزد دارند._']
    return '\n'.join(lines)


def _admin_fee_report_daily(period):
    since = _fee_since(period)
    with DB_LOCK:
        conn = db_connect()
        try:
            tot = conn.execute("SELECT COALESCE(SUM(fee_usdt),0),COUNT(*),COUNT(DISTINCT chat_id) FROM fee_invoices WHERE created_at>=? AND status!='WAIVED'", (since,)).fetchone()
            paid = conn.execute("SELECT COALESCE(SUM(fee_usdt),0) FROM fee_invoices WHERE created_at>=? AND status='PAID'", (since,)).fetchone()
            unpaid = conn.execute("SELECT COALESCE(SUM(fee_usdt),0),COUNT(*) FROM fee_invoices WHERE status IN ('PENDING','OVERDUE')").fetchone()
            rows = conn.execute("SELECT chat_id,COALESCE(SUM(fee_usdt),0),COUNT(*) FROM fee_invoices WHERE created_at>=? AND status!='WAIVED' GROUP BY chat_id ORDER BY SUM(fee_usdt) DESC LIMIT 20", (since,)).fetchall()
        finally:
            conn.close()
    fee, count, users = tot or (0, 0, 0)
    with _FEE_STATE_LOCK:
        nblocked = len(_FEE_BLOCKED)
    lines = [f'👑 *گزارش درآمد پلتفرم (روزانه) — {period}*', '', f'• کارمزد فاکتورشده: `{fee:.2f} USDT` ({count} فاکتور)',
             f'• دریافت‌شده: `{float((paid or (0,))[0]):.2f} USDT`',
             f'• پرداخت‌نشده (کل): `{float((unpaid or (0, 0))[0]):.2f} USDT` در `{int((unpaid or (0, 0))[1])}` فاکتور',
             f'• کاربران مسدود: `{nblocked}`', f'• کاربران دارای فاکتور: `{users}`', '', '*برترین کاربران:*']
    lines += [f'• `{uid}` → `{float(amt):.2f} USDT` ({cnt} فاکتور)' for uid, amt, cnt in rows] or ['• هنوز فاکتوری ثبت نشده است.']
    lines += ['', 'لیست بدهکاران: `/fee_debts`']
    return '\n'.join(lines)
# ===== END کارمزد روزانه =====


def partial_close_position(chat_id,pos,price,frac_orig,label=''):
    """بستن بخشی از یک پوزیشن PAPER روی یک پله‌ی TP (سهم frac_orig از مارجین اولیه).
    PnL همان بخش (با کارمزد رفت‌وبرگشت و فاندینگِ همان بخش) همین حالا به بالانس اضافه می‌شود و
    در partial_* روی پوزیشن جمع می‌ماند تا موقع بسته‌شدن نهایی، PnL/R کل معامله درست گزارش شود.
    هرگز کل پوزیشن را نمی‌بندد (آخرین پله همان TP/SL معمولی است)."""
    lock=get_entry_lock(chat_id)
    with lock:
        s=get_session(chat_id)
        if pos not in s['paper_positions'] or pos.get('is_real'): return False
        cur_margin=float(pos.get('margin') or 0)
        orig_margin=float(pos.get('orig_margin') or cur_margin)
        close_margin=min(cur_margin, orig_margin*float(frac_orig))
        if close_margin<=0 or close_margin>=cur_margin*0.999: return False
        lev=float(pos['leverage']); entry=float(pos['entry_price'])
        px=float(price)
        if PAPER_SLIPPAGE_BPS > 0:
            slip = PAPER_SLIPPAGE_BPS / 10000.0
            px = px * (1.0 - slip) if side_long(pos['side']) else px * (1.0 + slip)
        frac=((px-entry)/entry) if side_long(pos['side']) else ((entry-px)/entry)
        gross=close_margin*frac*lev
        fee=round_trip_fee_usdt(close_margin, lev)
        hours=max(0.0, time.time()-float(pos.get('opened_at',time.time())))/3600.0
        funding=close_margin*lev*(PAPER_FUNDING_RATE_PCT_8H/100.0)*(hours/8.0)
        pnl=gross-fee-funding
        s['paper_balance']+=pnl
        new_margin=cur_margin-close_margin
        pos['amount']=float(pos.get('amount') or 0)*(new_margin/cur_margin)
        pos['margin']=new_margin
        pos['partial_pnl_usdt']=float(pos.get('partial_pnl_usdt') or 0.0)+pnl
        pos['partial_gross_usdt']=float(pos.get('partial_gross_usdt') or 0.0)+gross
        pos['partial_fee_usdt']=float(pos.get('partial_fee_usdt') or 0.0)+fee
        pos['partial_funding_usdt']=float(pos.get('partial_funding_usdt') or 0.0)+funding
        pos.setdefault('partial_exits',[]).append({'stage':label,'price':px,'fraction':float(frac_orig),'pnl_usdt':pnl,'ts':time.time()})
        audit_event(chat_id, pos.get('trade_id') or new_trade_id(chat_id, pos.get('symbol','?')), 'partial_exit', {'stage':label,'price':px,'fraction':float(frac_orig),'pnl_usdt':pnl,'remaining_margin':new_margin})
        save_session(chat_id)
        side_fa='خرید (Long)' if side_long(pos.get('side')) else 'فروش (Short)'
        send_message(chat_id,f"🪜 *خروج پله‌ای PAPER*\n• `{pos['symbol']}` ({side_fa})\n• پله: `{label}` | قیمت: `{fmt(px)}`\n• سهم بسته‌شده: `{float(frac_orig)*100:.0f}%` از حجم اولیه\n• PnL این بخش: `{pnl:+.2f} USDT`\n• بقیه‌ی پوزیشن باز می‌ماند.")
        return True


def partial_close_real_position(chat_id,pos,price,frac_orig,label=''):
    """V3.44.54: بستن بخشی از پوزیشن REAL با سفارش مارکت reduce-only (سهم frac_orig از حجم اولیه).
    SL/TP روی صرافی از نوع closePosition هستند و بعد از بستن بخشی برای بقیه‌ی پوزیشن سر جایشان می‌مانند.
    PnL نهایی REAL از تاریخچه‌ی معاملات صرافی (از زمان باز شدن) محاسبه می‌شود و خروج بخشی را خودکار شامل است؛
    عدد partial_real_est_usdt فقط برآورد برای حالتی است که تاریخچه در دسترس نباشد.
    هرگز کل پوزیشن را نمی‌بندد و هر خطایی فقط False برمی‌گرداند (ربات متوقف نمی‌شود)."""
    lock=get_entry_lock(chat_id)
    with lock:
        s=get_session(chat_id)
        if pos not in s['paper_positions'] or not pos.get('is_real'): return False
        ex=get_exchange(chat_id)
        if not ex: return False
        try:
            fsym,scale,m=_fsym(ex,pos['symbol'])
            live=find_position(chat_id,pos['symbol'])
            if not live: return False
            cur_amt=float(live['amount'])
            orig_amt=float(pos.get('orig_amount') or cur_amt)
            close_amt=min(cur_amt, orig_amt*float(frac_orig))
            if close_amt<=0 or close_amt>=cur_amt*0.999: return False
            contracts=float(ex.amount_to_precision(fsym, close_amt/scale))
            rem_contracts=cur_amt/scale-contracts
            lim=(m.get('limits') or {}) if isinstance(m,dict) else {}
            min_amt=float((lim.get('amount') or {}).get('min') or 0)
            min_cost=float((lim.get('cost') or {}).get('min') or 0)
            ref_px=float(price)
            if contracts<=0 or rem_contracts<=0: return False
            if min_amt and (contracts<min_amt or rem_contracts<min_amt): return False
            if min_cost and (contracts*scale*ref_px<min_cost or rem_contracts*scale*ref_px<min_cost): return False
            order=_close_market(ex,fsym,side_long(pos['side']),contracts)
            avg=_order_avg_price(ex,fsym,order) or 0.0
            px=(float(avg)/scale) if float(avg)>0 else ref_px
        except Exception as exc:
            logger.warning('partial close REAL failed %s: %s',pos.get('symbol'),exc)
            return False
        # از اینجا به بعد سفارش اجرا شده؛ خطای تایید وضعیت نباید حساب‌وکتاب را خراب کند
        closed_amt=contracts*scale
        new_amt=max(0.0,cur_amt-closed_amt)
        try:
            for _ in range(4):
                time.sleep(0.5)
                lv=find_position(chat_id,pos['symbol'])
                if lv is None: new_amt=0.0; break
                new_amt=float(lv['amount'])
                if new_amt<cur_amt*0.999: break
        except Exception as exc:
            logger.warning('partial close REAL verify failed %s: %s',pos.get('symbol'),exc)
        cur_margin=float(pos.get('margin') or 0)
        if not pos.get('orig_amount'): pos['orig_amount']=orig_amt
        if not pos.get('orig_margin'): pos['orig_margin']=cur_margin
        if new_amt>0 and cur_amt>0: pos['margin']=cur_margin*(new_amt/cur_amt)
        pos['amount']=new_amt
        entry=float(pos['entry_price'])
        gross=(px-entry)*closed_amt if side_long(pos['side']) else (entry-px)*closed_amt
        fee=px*closed_amt*TAKER_FEE_PCT/100.0*2
        pos['partial_real_est_usdt']=float(pos.get('partial_real_est_usdt') or 0.0)+gross-fee
        pos['partial_real_gross_est_usdt']=float(pos.get('partial_real_gross_est_usdt') or 0.0)+gross
        pos.setdefault('partial_exits',[]).append({'stage':label,'price':px,'fraction':float(frac_orig),'pnl_usdt_est':gross-fee,'real':True,'ts':time.time()})
        audit_event(chat_id, pos.get('trade_id') or new_trade_id(chat_id, pos.get('symbol','?')), 'partial_exit', {'stage':label,'price':px,'fraction':float(frac_orig),'pnl_usdt_est':gross-fee,'remaining_amount':new_amt,'real':True})
        save_session(chat_id)
        return True

