def _paper_effective_hl(p, c, high, low, price):
    """V3.38.6: کندلِ در حال تشکیلی که پوزیشن وسطش باز شده شامل قیمت‌های «قبل از ورود» هم هست.
    اگر high/low کامل آن کندل برای تشخیص TP/SL استفاده شود، ویکِ قبل از ورود می‌تواند TP/SL تازه‌چیده‌شده را
    همان چرخه‌ی بعد «بزند» و پوزیشن چند دقیقه بعد از ورود بسته شود. برای کندل ورود فقط بازه‌ی قیمت‌های
    دیده‌شده «بعد از ورود» (ورود + قیمت‌های لحظه‌ای هر چرخه) استفاده می‌شود؛ از کندل بعدی به بعد کندل کامل."""
    try:
        ts = float(c.get('timestamp') or 0)
        if ts > 1e11: ts /= 1000.0          # میلی‌ثانیه -> ثانیه
        opened = float(p.get('opened_at') or 0)
        if ts > 0 and opened > 0 and ts <= opened:
            entry = float(p['entry_price'])
            hi = max(float(p.get('seen_high') or entry), entry, float(price))
            lo = min(float(p.get('seen_low') or entry), entry, float(price))
            p['seen_high'] = hi; p['seen_low'] = lo
            return hi, lo
    except Exception:
        logger.exception('paper effective hl failed')
    return high, low


def update_positions(chat_id):
    s=get_session(chat_id)
    if not s['paper_positions']: return
    if s['trading_mode']=='REAL':
        if not reconcile_real(chat_id): return
    for p in s['paper_positions'][:]:
        if s['trading_mode']=='REAL' and not p.get('is_real'): continue
        if s['trading_mode']=='REAL':
            price=exchange_latest_price(chat_id,p['symbol'])
            if not price: continue
        else:
            price=None
        primary_tf=p.get('timeframe','5min')
        primary_df=get_klines(p['symbol'],primary_tf,120)
        if s['trading_mode']!='REAL':
            if primary_df.empty: continue
            c=primary_df.iloc[-1]
            high,low,close=float(c['high']),float(c['low']),float(c['close'])
            live_market = latest_price(p['symbol'])
            price = float(live_market) if live_market else close
            high, low = _paper_effective_hl(p, c, high, low, price)
            # PAPER excursion remains candle-based for deterministic backtests, while
            # current PnL/management decisions use the freshest available market price.
            update_trade_excursions(p,high,low)
            _shadow_track(p,high,low)
            _be_track(p, price)
            _path_log(p, price)
            p['last_unrealized_pnl'] = ((price-float(p['entry_price']))*abs(float(p.get('amount') or 0))
                                        if side_long(p['side']) else
                                        (float(p['entry_price'])-price)*abs(float(p.get('amount') or 0)))
            p['last_price']=float(price)
        else:
            # REAL: excursion/MFE/MAE starts at the actual position lifetime.
            # Never feed historical candles from before the position opened.
            update_trade_excursions(p, float(price), float(price))
            _shadow_track(p, float(price), float(price))
            _be_track(p, float(price))
            _path_log(p, float(price))
            p['last_unrealized_pnl']=float(p.get('margin',0))*(((price-float(p['entry_price']))/float(p['entry_price'])) if side_long(p['side']) else ((float(p['entry_price'])-price)/float(p['entry_price'])))*float(p['leverage'])
            p['last_price']=float(price)

        entry=float(p['entry_price'])
        risk_distance=float(p.get('risk_distance') or 0.0)
        if risk_distance<=0: risk_distance=abs(entry-float(p.get('sl',entry)))

        # Hard SL/TP is always checked before any discretionary stop movement.
        exit_price=None; reason=None
        if s['trading_mode']=='PAPER' and not primary_df.empty:
            sl_low, sl_high = low, high
            if p.get('trail_active'):
                # V3.44.33: بعد از جابه‌جایی SL توسط تریلینگ، ویکِ کندل «قبل از جابه‌جایی» نباید SL جدید را بزند؛
                # فقط قیمت‌های لحظه‌ای دیده‌شده بعد از آخرین جابه‌جایی سنجیده می‌شوند (مثل REAL که صرافی روی قیمت واقعی تریگر می‌کند).
                sl_low = min(float(p.get('trail_lo') or price), float(price)); sl_high = max(float(p.get('trail_hi') or price), float(price))
                p['trail_lo'] = sl_low; p['trail_hi'] = sl_high      # تریلینگ خاموش شده باشد هم ردیابی ادامه دارد
            if side_long(p['side']):
                hit_tp=high>=float(p['tp']); hit_sl=sl_low<=float(p['sl'])
            else:
                hit_tp=low<=float(p['tp']); hit_sl=sl_high>=float(p['sl'])
            _trail_tag = (f" trailing {float(p.get('trail_lock_r') or 0):+.2f}R" if p.get('trail_active') else '')
            if hit_tp and hit_sl and PAPER_CONSERVATIVE_OHLC:
                exit_price=_paper_stop_fill_price(p,sl_low,sl_high,risk_distance); reason=f'SL (same candle{_trail_tag})'
            elif hit_tp: exit_price=float(p['tp']); reason='TP'
            elif hit_sl: exit_price=_paper_stop_fill_price(p,sl_low,sl_high,risk_distance); reason=f'SL ({_trail_tag.strip()})' if _trail_tag else 'SL'
            # خروج پله‌ای (مدل PDH/PDL+P4): پله‌هایی که در این کندل لمس شدند (و SL همزمان نخورده)
            # به ترتیب نزدیک به دور، قبل از TP نهایی بسته می‌شوند.
            if (reason is None or reason=='TP') and p.get('tp_stages'):
                for st in p['tp_stages']:
                    if st.get('done'): continue
                    st_hit=(high>=float(st['price'])) if side_long(p['side']) else (low<=float(st['price']))
                    if not st_hit: break
                    if partial_close_position(chat_id,p,float(st['price']),float(st.get('fraction') or 0),str(st.get('name') or '')):
                        st['done']=True
                    else:
                        break
            if reason and reason.startswith('SL') and risk_distance > 0:
                # چقدر از فیل واقعی، بدتر از قیمت دقیق SL شبیه‌سازی شده - جدا از pnl
                # نهایی ثبت می‌شود تا بشود دید چقدر از ضرر از اسلیپیج آمده، نه قیمت.
                p['sl_slippage_r'] = round(abs(float(exit_price) - float(p['sl'])) / risk_distance, 4)

        if reason:
            close_position(chat_id,p,exit_price,reason)
    save_session(chat_id)


def _breakout_filter_diagnostics(df, filters=None, strategy_config=None):
    out = {
        'adx_ok': False, 'volume_breakout_ok': False, 'body_ok': False,
        'trend_buy_ok': False, 'trend_sell_ok': False,
        'breakout_buy_ok': False, 'breakout_sell_ok': False,
        'candle_volume_ok': False, 'candle_buy_ok': False, 'candle_sell_ok': False,
        'final_buy_ok': False, 'final_sell_ok': False,
    }
    try:
        if df is None or df.empty or len(df) < 60:
            return out
        curr, prev = df.iloc[-2], df.iloc[-3]
        cfg = strategy_config if isinstance(strategy_config, dict) else STRATEGY_DEFAULTS
        f = filters if isinstance(filters, dict) else FILTER_DEFAULTS
        adx = float(curr.get('adx', 0) or 0)
        vr = float(curr.get('volume_ratio', 0) or 0)
        body_ratio = float(curr.get('body_ratio', 0) or 0)
        channel_high = curr.get('channel_high')
        channel_low = curr.get('channel_low')
        if pd.isna(channel_high) or pd.isna(channel_low):
            return out
        min_adx = float(cfg.get('min_adx', 20.0))
        min_vr = float(cfg.get('min_volume_ratio', 1.05))
        min_body = float(cfg.get('min_body_ratio', 0.45))
        out['adx_ok'] = adx >= max(15.0, min_adx - 5.0)
        out['volume_breakout_ok'] = (not f.get('volume_filter', True)) or vr >= min_vr
        out['body_ok'] = body_ratio >= min_body
        out['trend_buy_ok'] = bool(curr['close'] > curr['ema20'] > curr['ema50'] and curr['plus_di'] > curr['minus_di'])
        out['trend_sell_ok'] = bool(curr['close'] < curr['ema20'] < curr['ema50'] and curr['minus_di'] > curr['plus_di'])
        out['breakout_buy_ok'] = bool(curr['close'] > channel_high and prev['close'] <= prev.get('channel_high', float('inf')) and out['trend_buy_ok'] and adx >= min_adx)
        out['breakout_sell_ok'] = bool(curr['close'] < channel_low and prev['close'] >= prev.get('channel_low', -float('inf')) and out['trend_sell_ok'] and adx >= min_adx)

        if not f.get('volume_filter', True):
            out['candle_volume_ok'] = True
        else:
            out['candle_volume_ok'] = vr >= 1.0

        if not f.get('candlestick_filter', True):
            out['candle_buy_ok'] = True
            out['candle_sell_ok'] = True
        else:
            body = abs(float(curr['close']) - float(curr['open']))
            rng = max(float(curr['high']) - float(curr['low']), 1e-12)
            upper = float(curr['high']) - max(float(curr['close']), float(curr['open']))
            lower = min(float(curr['close']), float(curr['open'])) - float(curr['low'])
            bullish_pin = lower >= 2 * max(body, 1e-12) and upper <= max(body * 1.2, 1e-12) and curr['close'] > curr['open']
            bearish_pin = upper >= 2 * max(body, 1e-12) and lower <= max(body * 1.2, 1e-12) and curr['close'] < curr['open']
            prev_body = abs(float(prev['close']) - float(prev['open']))
            bull_engulf = prev['close'] < prev['open'] and curr['close'] > curr['open'] and curr['close'] >= prev['open'] and curr['open'] <= prev['close'] and body > prev_body
            bear_engulf = prev['close'] > prev['open'] and curr['close'] < curr['open'] and curr['close'] <= prev['open'] and curr['open'] >= prev['close'] and body > prev_body
            strong_bull = curr['close'] > curr['open'] and body / rng >= 0.60
            strong_bear = curr['close'] < curr['open'] and body / rng >= 0.60
            out['candle_buy_ok'] = bool(bullish_pin or strong_bull)
            out['candle_sell_ok'] = bool(bearish_pin or strong_bear)
        out['final_buy_ok'] = bool(out['adx_ok'] and out['volume_breakout_ok'] and out['body_ok'] and out['breakout_buy_ok'] and out['candle_volume_ok'] and (out['candle_buy_ok'] or not f.get('candlestick_filter', True)))
        out['final_sell_ok'] = bool(out['adx_ok'] and out['volume_breakout_ok'] and out['body_ok'] and out['breakout_sell_ok'] and out['candle_volume_ok'] and (out['candle_sell_ok'] or not f.get('candlestick_filter', True)))
    except Exception:
        pass
    return out


def _pipeline_record(chat_id, symbol, stage, status='', reason='', signal=None, data=None):
    """Persist an end-to-end scan/entry pipeline event when the audit toggle is on.

    هر رویداد بلافاصله زیر نماد، زمان دقیق همان اسکن را (هم به‌صورت epoch و هم
    خوانا با تایم‌زون تهران) ثبت می‌کند. همچنین بر اساس سیستم ستاپ‌های چندسطحی
    جدید (Monthly/Weekly/Daily/4h/1h) تگ ستاپ و سطح دقیق شناسایی‌شده از روی
    reason/سیگنال استخراج و در رویداد ذخیره می‌شود تا مسیر ممیزی همیشه با آخرین
    ساختار استراتژی هماهنگ باشد.
    """
    try:
        try:
            _fn_scan_hook(chat_id, symbol, stage, status, reason, signal)
        except Exception:
            pass
        s = get_session(chat_id)
        if not s.get('trade_pipeline_enabled', False):
            return
        scan_ts = time.time()
        reason_text = str(reason or '')
        signal_reason = ''
        if isinstance(signal, dict):
            signal_reason = str(signal.get('reason') or signal.get('signal_reason') or '')
        setup_source = reason_text or signal_reason
        try:
            setup_tag = extract_setup_tag(setup_source) or None
        except Exception:
            setup_tag = None
        try:
            level_tag, level_token, level_value = extract_setup_level(setup_source)
        except Exception:
            level_tag, level_token, level_value = (None, None, None)
        event = {
            'pipeline_id': f"{symbol}:{s.get('timeframe','5min')}:{int(scan_ts*1000)}",
            'symbol': symbol,
            'scan_time': fmt_scan_time(scan_ts),
            'timeframe': s.get('timeframe','5min'),
            'stage': str(stage), 'status': str(status or ''),
            'reason': reason_text, 'signal': signal,
            'setup_tag': setup_tag,
            'setup_level': {'timeframe': level_tag, 'name': level_token, 'value': level_value} if level_tag else None,
            'ts': scan_ts,
            'data': data or {},
        }
        s.setdefault('trade_pipeline_audit', []).append(event)
        s['trade_pipeline_audit'] = s['trade_pipeline_audit'][-5000:]
        save_session(chat_id)
    except Exception:
        logger.exception('pipeline audit failed chat=%s symbol=%s stage=%s', chat_id, symbol, stage)


def _pipeline_start(chat_id, symbol):
    _pipeline_record(chat_id, symbol, 'watchlist_review', 'review_started', 'نماد وارد مرحله بررسی شد')


def _entry_diag_result(chat_id, symbol, status, reason='', stage='', signal=None, diagnostics=None):
    _pipeline_record(chat_id, symbol, stage or status, status, reason, signal, diagnostics)
    return {
        'chat_id': chat_id,
        'symbol': symbol,
        'status': status,
        'reason': str(reason or '').strip(),
        'stage': stage,
        'signal': signal,
        'diagnostics': diagnostics or {},
        'ts': time.time(),
    }


def _entry_diag_label(reason):
    """Turn internal strategy reasons into short, human trading language.
    The diagnostic log is for decision transparency, not for exposing indicator math.
    """
    r = str(reason or '').strip()
    if not r:
        return 'شرایط ورود هنوز کامل نشده'

    # Keep the explanation at the level a trader actually needs: what is missing,
    # not which indicator number failed.
    rules = [
        (r'گیت جهت بازار', 'گیت جهت بازار ورود در این جهت را مجاز نمی‌داند'),
        (r'داده کافی|داده بازار خالی|سطوح روز قبل هنوز آماده|یک روز کامل قبلی', 'هنوز داده یا سطح معتبر کافی برای تصمیم‌گیری نداریم'),
        (r'ظرفیت پوزیشن|محدودیت ریسک|ریسک به کارمزد|وضعیت ربات|توقف', 'فعلاً اجازه ورود از سمت مدیریت ریسک/ربات داده نمی‌شود'),
        (r'cooldown|دوره انتظار', 'ربات بعد از معامله قبلی در زمان انتظار است'),
        (r'R:R کافی نیست|نسبت سود به ضرر', 'ستاپ خوب به نظر می‌رسد، اما سود احتمالی به ریسک آن نمی‌ارزد'),
        (r'امتیاز کیفیت پایین', 'ستاپ شکل گرفته، ولی کیفیت کلی هنوز به حد ورود نرسیده'),
        (r'فاصله .* معتبر نیست|فاصله .* حد ضرر', 'برای این معامله حد ضرر منطقی پیدا نشد'),
        (r'کندل تأیید|قدرت بدنه|تأیید معتبر|برگشت تأیید نشده', 'قیمت به ناحیه مناسب نزدیک شده، اما تأیید نهایی هنوز نیامده'),
        (r'حجم .*کافی نیست|حجم .* تأیید', 'حرکت دیده می‌شود، ولی قدرت لازم برای تأیید آن هنوز کافی نیست'),
        (r'شکست جدیدی ثبت نشد|شکست معتبر ثبت نشده', 'هنوز شکست معناداری برای ورود شکل نگرفته'),
        (r'شکست تأیید نشد|هم‌جهت نیست|خلاف جهت بازار', 'حرکت دیده شده با جهت کلی بازار هماهنگ نیست؛ ورود رد شد'),
        (r'روند ضعیف|شرایط روندی برقرار نیست', 'بازار هنوز روند واضحی برای ورود ندارد'),
        (r'Mean Reversion|محدوده میانگین|RSI خنثی|اشباع .*برگشت', 'بازار هنوز به نقطه مناسب برای برگشت نرسیده'),
        (r'ستاپ جدیدی ثبت نشد|ستاپ مناسب پیدا نشد|بدون Pullback|V2:', 'فعلاً ستاپ تمیز و قابل معامله‌ای شکل نگرفته'),
    ]
    import re as _re
    for pattern, label in rules:
        if _re.search(pattern, r, flags=_re.I):
            return label
    return 'هنوز شرایط کامل یک ورود کم‌ریسک فراهم نشده'


def _entry_diag_stage(item):
    """Map an internal scan result to a small human stage machine."""
    status = str(item.get('status') or '')
    reason = str(item.get('reason') or '')
    if status == 'entry_opened':
        return '🟢', 'سیگنال آماده', 'ورود انجام شد'
    if status in ('assist_sent', 'assist_waiting'):
        return '🤝', 'منتظر تایید شما', 'سیگنال آماده است و برای ورود منتظر تایید دستی شماست'
    if status == 'assist_skipped':
        return '⏳', 'در انتظار', 'سیگنال آماده بود اما محدودیت‌های معمول ورود (پوزیشن باز/کول‌داون) اجازه‌ی پیشنهاد نمی‌دهد'
    if status in ('data_error', 'insufficient_data'):
        return '⚠️', 'داده ناقص', 'برای تصمیم‌گیری داده کافی نیست'
    if status in ('risk_blocked', 'blocked', 'execute_blocked', 'leader_guard_blocked'):
        if 'دوره انتظار' in reason or 'cooldown' in reason.lower():
            return '⏳', 'در انتظار', 'بعد از معامله قبلی هنوز زمان انتظار تمام نشده'
        return '🛑', 'ورود محافظت شد', 'قواعد محافظتی فعلاً اجازه ورود نمی‌دهند'
    r = reason.lower()
    if 'trade_plan' in str(item.get('stage','')).lower() or 'حد ضرر منطقی' in reason or 'rr' in r:
        return '❌', 'رد شد', 'طرح معامله کیفیت لازم را نداشت'
    if 'pullback' in r or 'پولبک' in reason or 'retest' in r or 'بازآزمایی' in reason:
        return '🔄', 'منتظر پولبک', 'حرکت انجام شده؛ منتظر برگشت امن به ناحیه ورودیم'
    if 'ستاپ قبلی' in reason or 'نزدیک' in reason:
        return '👀', 'نزدیک ورود', 'ستاپ در حال شکل‌گیری است و یک تأیید دیگر لازم دارد'
    if 'تأیید' in reason or 'confirmation' in r or 'قدرت' in reason or 'حجم' in reason:
        return '⏳', 'منتظر تأیید', 'ناحیه مناسب است ولی تأیید نهایی هنوز نیامده'
    if 'شکست' in reason or 'breakout' in r or 'روند' in reason:
        return '⏳', 'منتظر حرکت واضح', 'هنوز حرکت معناداری برای ورود تأیید نشده'
    if 'ستاپ' in reason or 'شرایط ورود' in reason or 'محدوده' in reason:
        return '💤', 'بدون ستاپ', 'فعلاً ناحیه و ساختار مناسبی برای معامله نداریم'
    return '💤', 'بدون ستاپ', 'فعلاً ورود تمیزی دیده نشده'


def _entry_diag_next_step(results):
    stages = [_entry_diag_stage(x)[1] for x in results if x.get('status') != 'entry_opened']
    if 'نزدیک ورود' in stages:
        return '👀 چند نماد به ورود نزدیک‌اند؛ ربات فقط منتظر تأیید لازم می‌ماند.'
    if 'منتظر پولبک' in stages:
        return '🔄 شکست‌هایی دیده شده؛ ربات وسط حرکت وارد نمی‌شود و منتظر پولبک می‌ماند.'
    if 'منتظر تأیید' in stages:
        return '⏳ ستاپ‌ها بررسی شده‌اند؛ هنوز تأیید نهایی برای ورود کم‌ریسک کامل نیست.'
    if 'منتظر حرکت واضح' in stages:
        return '⏳ بازار هنوز حرکت واضحی نداده؛ ورود اجباری نداریم.'
    return '🛡️ فعلاً ستاپ تمیزی نیست؛ ربات صبر می‌کند تا فرصت ارزشمندتری شکل بگیرد.'


def _entry_diag_direction(item):
    """Return the relevant LONG/SHORT context for a diagnostic row."""
    sig = str(item.get('signal') or '').upper()
    if sig == 'BUY':
        return '🟢 LONG'
    if sig == 'SELL':
        return '🔴 SHORT'
    sym = str(item.get('symbol') or '').upper()
    in_long = sym in SHARED_LONG_WATCHLIST
    in_short = sym in SHARED_SHORT_WATCHLIST
    if in_long and in_short:
        return '🟡 LONG/SHORT'
    if in_long:
        return '🟢 LONG'
    if in_short:
        return '🔴 SHORT'
    return '⚪️'


def _entry_diag_report(chat_id, results, elapsed, symbol_states=None, transitions=None):
    """Compact opportunity dashboard: show only active/non-idle opportunities."""
    s = get_session(chat_id)
    results = list(results or [])
    symbol_states = symbol_states or {}
    transitions = transitions or []
    opened = sum(1 for x in results if x.get('status') == 'entry_opened')
    data_issues = sum(1 for x in results if x.get('status') in ('data_error','insufficient_data'))
    tf = TF_DISPLAY.get(s.get('timeframe'), s.get('timeframe'))

    all_items = list(symbol_states.values()) or results
    active_items = []
    for item in all_items:
        icon, stage, desc = _entry_diag_stage(item)
        # Keep the report focused on actionable/watch states. Pure idle/no-setup
        # symbols are intentionally omitted from Telegram.
        if stage in ('بدون ستاپ', 'داده ناقص'):
            continue
        active_items.append((item, icon, stage, desc))

    long_active = sum(1 for item, *_ in active_items if 'LONG' in _entry_diag_direction(item))
    short_active = sum(1 for item, *_ in active_items if 'SHORT' in _entry_diag_direction(item))
    confirm_wait = sum(1 for _, _, stage, _ in active_items if stage in ('منتظر تأیید', 'نزدیک ورود', 'منتظر حرکت واضح', 'در انتظار'))
    pullback_wait = sum(1 for _, _, stage, _ in active_items if stage == 'منتظر پولبک')

    lines = [
        '🧠 *داشبورد زنده فرصت‌ها*',
        '━━━━━━━━━━━━━━━━━━━━',
        f'⏱ گزارش دوره‌ای: هر ۱۰ دقیقه | تایم‌فریم: `{tf}`',
        f'🟢 LONG زیر نظر: `{len(SHARED_LONG_WATCHLIST)}` نماد',
        f'🔴 SHORT زیر نظر: `{len(SHARED_SHORT_WATCHLIST)}` نماد',
        f'🔎 مجموع مسیرهای بررسی: `{len(SHARED_LONG_WATCHLIST) + len(SHARED_SHORT_WATCHLIST)}`',
    ]
    if opened:
        lines.append(f'🟢 در این چرخه `{opened}` ورود انجام شد.')
    elif active_items:
        lines.append(f'📌 فرصت‌های فعال: `{len(active_items)}`')
    else:
        lines.append('💤 فعلاً فرصت فعال و قابل پیگیری وجود ندارد؛ موارد بدون ستاپ نمایش داده نمی‌شوند.')
    if data_issues:
        lines.append(f'⚠️ `{data_issues}` مورد مشکل داده داشت و در فهرست فرصت‌های فعال نمایش داده نشده است.')

    for item, icon, stage, desc in active_items:
        sym = item.get('symbol','?')
        direction = _entry_diag_direction(item)
        prev = item.get('previous_stage')
        change = ''
        if prev and prev != stage:
            change = f' | تغییر: {prev} → {stage}'
        lines.append(f'\n{icon} *{sym}* — {direction} — {stage}{change}\n   {desc}')

    if active_items:
        lines.append('\n━━━━━━━━━━━━━━━━━━━━')
        lines.append(f'📊 *خلاصه فرصت‌ها:* `{len(active_items)}` فعال | 🟢 LONG: `{long_active}` | 🔴 SHORT: `{short_active}`')
        lines.append(f'⏳ منتظر تأیید: `{confirm_wait}` | 🔄 منتظر پولبک: `{pullback_wait}`')

    # Only show transitions that are still relevant to the compact active dashboard.
    relevant_transitions = [t for t in transitions if not any(x in t for x in ('→ بدون ستاپ', '→ داده ناقص'))]
    if relevant_transitions:
        lines.append('\n*تغییرات مهم از گزارش قبل:*')
        for t in relevant_transitions[-5:]:
            lines.append(f'• `{t}`')

    if active_items:
        lines.append('\n' + _entry_diag_next_step([x[0] for x in active_items]))
    return '\n'.join(lines)

def _active_tf_regime_status(tf):
    """رژیم بازار روی تایم‌فریم فعال (فقط نمایش؛ منطق در refresh_market_gate)."""
    c = TIMEFRAME_REGIME_CACHE.get(_tfk(tf)) or {}
    gate = c.get('gate')
    if not gate:
        return '⏳ هنوز محاسبه نشده'
    counts = f"{c.get('bull_n', 0)} صعودی / {c.get('bear_n', 0)} نزولی از {c.get('total', 0)} نماد"
    if gate == 'BULLISH':
        return f'🟢 صعودی ({counts})'
    if gate == 'BEARISH':
        return f'🔴 نزولی ({counts})'
    return f'⚪️ رنج ({counts})'


def _simple_status_report(chat_id):
    """گزارش دوره‌ای ساده: وضعیت کلی بازار، قیمت لحظه‌ای BTC/ETH، موجودی کیف پول
    و سود/زیان لحظه‌ای پوزیشن‌های باز — به‌جای داشبورد طولانی تشخیصی."""
    s = get_session(chat_id)
    regime = MARKET_REGIME_CACHE.get('regime', 'NEUTRAL')
    regime_label = {'BULLISH': '📈 صعودی', 'BEARISH': '📉 نزولی', 'NEUTRAL': '➡️ رنج'}.get(regime, '➡️ رنج')
    tf = s.get('timeframe', '5min')
    tf_label = TF_DISPLAY.get(tf, tf)
    active_tf_status = _active_tf_regime_status(tf)

    btc_price = latest_price('BTC')
    eth_price = latest_price('ETH')

    balance = exchange_balance(chat_id) if s.get('trading_mode') == 'REAL' else float(s.get('paper_balance', 0.0))

    positions = list(s.get('paper_positions') or [])
    total_pnl = 0.0
    for p in positions:
        try:
            symbol = p['symbol']
            live = exchange_latest_price(chat_id, symbol) if p.get('is_real') else latest_price(symbol)
            live = float(live or p.get('last_price') or p.get('entry_price') or 0)
            entry = float(p.get('entry_price') or live or 0)
            amount = abs(float(p.get('amount') or 0))
            pnl = (live - entry) * amount if side_long(p['side']) else (entry - live) * amount
            total_pnl += pnl
        except Exception:
            continue

    lines = [
        '📊 *وضعیت بازار و حساب*',
        '━━━━━━━━━━━━━━━━━━━━',
        f'🧭 وضعیت کلی بازار (BTC/ETH ۴h): {regime_label}',
        f'⚡ رژیم تایم‌فریم فعال ({tf_label}): {active_tf_status}',
        f'₿ BTC: `{fmt(btc_price) if btc_price is not None else "—"}`',
        f'Ξ ETH: `{fmt(eth_price) if eth_price is not None else "—"}`',
        f'💰 موجودی کیف پول: `{balance:.2f} USDT`',
    ]
    if positions:
        lines.append(f'📈 سود/زیان پوزیشن‌های باز ({len(positions)}): `{total_pnl:+.2f} USDT`')
    else:
        lines.append('📈 سود/زیان پوزیشن‌های باز: پوزیشن باز ندارید')
    return '\n'.join(lines), {'inline_keyboard': [[{'text': '📂 نمایش پوزیشن‌های باز', 'callback_data': '/positions'}]]}


def _entry_diag_batch_update(chat_id, results):
    now = time.time()
    state = ENTRY_DIAG_STATE.setdefault(chat_id, {
        'no_entry_since': now,
        'last_report_at': 0.0,
        'last_entry_at': 0.0,
        'window_results': [],
        'symbol_states': {},
        'transitions': [],
    })
    if not results:
        return
    if not get_session(chat_id).get('entry_diag_enabled', True):
        return

    state.setdefault('symbol_states', {})
    state.setdefault('transitions', [])
    state.setdefault('window_results', [])
    state['window_results'].extend(results)
    state['window_results'] = state['window_results'][-300:]

    # Keep the latest state for every symbol, and remember only meaningful stage changes.
    for item in results:
        sym = item.get('symbol')
        if not sym:
            continue
        old = state['symbol_states'].get(sym)
        old_stage = old.get('stage') if old else None
        icon, stage, desc = _entry_diag_stage(item)
        updated = dict(item)
        updated['stage'] = stage
        updated['stage_icon'] = icon
        updated['stage_desc'] = desc
        updated['previous_stage'] = old_stage
        updated['last_update_at'] = now
        state['symbol_states'][sym] = updated
        if old_stage and old_stage != stage:
            state['transitions'].append(f'{sym}: {old_stage} → {stage}')
    state['transitions'] = state['transitions'][-20:]

    # Always report periodically, even if a trade happened. This makes the log a real
    # live dashboard instead of only a "why no entry" alarm.
    if not state.get('no_entry_since'):
        state['no_entry_since'] = now
    last_report = float(state.get('last_report_at', 0.0) or 0.0)
    if (not last_report) or now - last_report >= entry_report_interval(get_session(chat_id)):
        try:
            elapsed = now - float(state.get('no_entry_since') or now)
            report_text, report_markup = _simple_status_report(chat_id)
            send_message(chat_id, report_text, report_markup, parse_mode='Markdown')
            state['last_report_at'] = now
            state['window_results'] = []
            state['transitions'] = []
            state['no_entry_since'] = now
        except Exception as exc:
            logger.warning('ENTRY_DIAG telegram report failed chat=%s error=%s', chat_id, exc)


# ============================ حالت دستیار معاملاتی ============================
# وقتی s['assist_mode_enabled'] روشن باشد، scan_symbol به‌جای ورود خودکار، سیگنال را به شکل
# یک پیام با دکمه‌ی ✅ ورود / ❌ رد / ⏳ تمدید برای کاربر می‌فرستد. با تایید، همان مسیر
# execute_trade معمولی اجرا می‌شود (قیمت لحظه‌ای، SL/TP دور قیمت جدید، تمام گیت‌های ریسک).
# سیگنال‌های ردشده/منقضی‌شده هم «سایه‌ای» ثبت و پیگیری می‌شوند تا بعداً معلوم شود اگر وارد شده
# بودیم نتیجه چه می‌شد - تنها راه فهمیدن این‌که فیلتر دستی واقعاً کمک می‌کند یا نه.
ASSIST_MAX_EXTENSIONS = 2
ASSIST_MAX_DRIFT_R = max(0.05, float(os.environ.get('ASSIST_MAX_DRIFT_R', '0.5')))
ASSIST_SHADOW_HORIZON_SECONDS = 24 * 3600
ASSIST_LOG_CAP = 500
ASSIST_SEEN_TTL_SECONDS = 6 * 3600
ASSIST_EXPIRY_CHOICES = (180, 300, 600, 1800)
_ASSIST_LOCK = RLock()
# V3.42.12: لمس دکمه توسط یک thread تک‌رشته‌ی دریافت پیام‌ها پردازش می‌شود؛ اگر آن thread مشغول کار دیگری بوده (چارت، قیمت‌گیری،
# ...) پردازش لمس ممکن است چند ثانیه/دقیقه بعد از لمس واقعی انجام شود و سیگنال «در لحظه‌ی پردازش» منقضی دیده شود، در حالی
# که کاربر به‌موقع لمس کرده بود. برای همین مهلت را با «زودترین زمان ممکن برای لمس» می‌سنجیم (لحظه‌ی برگشتن getUpdates قبلی).
_PRESS = _threading.local()
ASSIST_SAVE_GRACE_SECONDS = max(0, int(os.environ.get('ASSIST_SAVE_GRACE_SECONDS', '20')))
# V3.42.13: «💾 ذخیره» روی سیگنالی که تا این مدت پیش منقضی شده هم آن را زنده می‌کند (ذخیره‌شده ورود خودکار ندارد و
# ورود فقط با ✅ + تایید قیمت انجام می‌شود، پس زنده‌کردنش بی‌خطر است). لمس‌هایی که دیر پردازش شده‌اند از دست نمی‌روند.
ASSIST_SAVE_REVIVE_SECONDS = max(0, int(os.environ.get('ASSIST_SAVE_REVIVE_SECONDS', '1800')))


def _assist_now():
    """زمانِ «لمس» برای مقایسه با مهلت سیگنال: کوچک‌تر از (الان) و (زودترین زمان ممکن لمس) وقتی از یک لمس دکمه آمده‌ایم."""
    t = time.time()
    e = getattr(_PRESS, 'earliest', None)
    return min(t, e) if e else t


def _assist_find(s, aid):
    for rec in (s.get('assist_log') or []):
        if rec.get('id') == aid:
            return rec
    return None


def _assist_strip_buttons(chat_id, message_id, rec=None):
    """دکمه‌های عملیاتی (✅ ورود/❌ رد/⏳ تمدید) را بعد از تعیین‌تکلیف سیگنال (منقضی/رد/نامعتبر)
    حذف می‌کند، اما دکمه‌ی نمایش چارت (TradingView و در صورت وجود MiniApp) را نگه می‌دارد تا کاربر
    بعداً هم بتواند وضعیت چارت را ببیند."""
    if not message_id:
        return
    rows = []
    if rec:
        sym = rec.get('symbol'); tf = rec.get('tf') or '5min'
        mini = miniapp_chart_url(sym, tf) if sym else None
        if mini:
            rows.append([{'text': '🌐 چارت تعاملی (MiniApp)', 'web_app': {'url': mini}}])
        if sym:
            rows.append([{'text': '📈 TradingView', 'url': tradingview_chart_url(sym, tf)}])
    try:
        tg('editMessageReplyMarkup', {'chat_id': chat_id, 'message_id': message_id, 'reply_markup': {'inline_keyboard': rows}}, 10)
    except Exception:
        logger.exception('assist: failed to strip buttons')


def _assist_prune_log(s):
    log = s.get('assist_log') or []
    if len(log) <= ASSIST_LOG_CAP:
        return
    keep_pending = [r for r in log if r.get('status') == 'pending']
    others = [r for r in log if r.get('status') != 'pending']
    s['assist_log'] = (others[-(ASSIST_LOG_CAP - len(keep_pending)):] + keep_pending)


def _send_photo_get_id(chat_id, img_bytes, caption, markup):
    """ارسال عکس با کپشن و دکمه‌ها؛ message_id را برمی‌گرداند (None اگر ناموفق)."""
    if not TELEGRAM_TOKEN:
        return None
    if is_restricted_user(chat_id): markup = _ap.filter_markup(markup, paper=_paper_account(chat_id))      # V3.44.59
    try:
        r = requests.post(f'https://api.telegram.org/bot{TELEGRAM_TOKEN}/sendPhoto',
                          data={'chat_id': chat_id, 'caption': caption[:1000], 'parse_mode': 'Markdown',
                                'reply_markup': json.dumps(markup, ensure_ascii=False)},
                          files={'photo': ('chart.png', img_bytes, 'image/png')}, timeout=25)
        if r.status_code != 200:
            logger.warning('assist sendPhoto failed: %s %s', r.status_code, r.text[:200])
            return None
        _mid = ((r.json() or {}).get('result') or {}).get('message_id')
        _day_log_record(chat_id, _mid)
        return _mid
    except Exception:
        logger.exception('assist sendPhoto error')
        return None


def _assist_describe_source(reason, level_token, level_value, scn):
    """نام سطح و نوع سناریوی سیگنال را برای پیام تایید می‌سازد. سیگنال‌های «آداپتیو» (سوییپ/ادامه
    روی سطوح سشن، رنج افتتاحیه یا سوینگ) خارج از ۶ سناریوی PDH/PDL‌اند و تگ SCN ندارند."""
    if level_token is not None and level_value is not None:
        level_txt = f"{level_token} = {fmt(float(level_value))}"
    else:
        a_name, a_val = extract_adaptive_anchor(reason)
        level_txt = f"{a_name} = {fmt(float(a_val))}" if (a_name and a_val is not None) else '-'
    if scn:
        scn_txt = f"{scn} - {_scenario_label(scn, reason)}"
    elif 'ADAPTIVE_SWEEP' in (reason or ''):
        scn_txt = 'آداپتیو: سوییپ روی سطح سشن/سوینگ (خارج از ۶ سناریو)'
    elif 'ADAPTIVE_CONTINUATION' in (reason or ''):
        scn_txt = 'آداپتیو: ادامه روی سطح سشن/سوینگ (خارج از ۶ سناریو)'
    else:
        scn_txt = 'نامشخص'
    return level_txt, scn_txt


ASSIST_EXTEND_SECONDS = max(60, int(os.environ.get('ASSIST_EXTEND_SECONDS', '1800')))   # V3.38: با لمس «تمدید مهلت» مهلت روی ۳۰ دقیقه تنظیم می‌شود
# V3.38.5: لیست «📋 سیگنال‌های در انتظار» فقط سیگنال‌هایی را نشان می‌دهد که حداقل این‌قدر ثانیه از مهلتشان باقی مانده (۳۰۰ = ۵ دقیقه؛ ۰ = همه).
ASSIST_LIST_MIN_REMAINING_SECONDS = max(0, int(os.environ.get('ASSIST_LIST_MIN_REMAINING_SECONDS', '300')))
# V3.38.8: کارت سیگنال‌های منقضی/نامعتبر این‌قدر ثانیه بعد از انقضا از چت حذف می‌شوند (۶۰ = ۱ دقیقه؛ ۰ = هرگز).
# V3.41: کارت سیگنال‌ها تا پاک‌سازی روزانه می‌مانند (۰ = حذف زمان‌دار خاموش)؛ اگر پاک‌سازی روزانه خاموش باشد همان ۶۰ ثانیه‌ی قبلی.
ASSIST_EXPIRED_DELETE_AFTER_SECONDS = max(0, int(os.environ.get('ASSIST_EXPIRED_DELETE_AFTER_SECONDS', '0' if DAILY_MESSAGE_CLEANUP else '60')))
_ASSIST_CD_LAST = {}   # آخرین برچسب شمارش معکوس ارسال‌شده برای هر سیگنال (جلوگیری از ویرایش تکراری)


def _assist_countdown_label(remaining):
    remaining = max(0, int(remaining))
    return f"⏳ {remaining // 60:02d}:{remaining % 60:02d} باقی‌مانده"


def _assist_markup(rec, remaining=None):
    """کیبورد کارت دستیار. اگر شمارش معکوس فعال باشد، دکمه‌ی «تمدید مهلت» به زمان باقی‌مانده تبدیل می‌شود."""
    aid = rec['id']; sym = rec['symbol']; tf = rec.get('tf') or '5min'
    is_long = rec['sig'] == 'BUY'
    if rec.get('saved'):
        # V3.42.9: سیگنال ذخیره‌شده مهلت ندارد و ورود خودکار ندارد؛ کاربر هر وقت خواست «✅ ورود» می‌زند.
        ext_btn = {'text': '💾 ذخیره‌شده · بدون مهلت', 'callback_data': f'/assist_saved_{aid}'}
    elif rec.get('countdown'):
        rem = remaining if remaining is not None else max(0, float(rec.get('expires_at', 0)) - time.time())
        ext_btn = {'text': _assist_countdown_label(rem), 'callback_data': f'/assist_cd_{aid}'}
    else:
        ext_btn = {'text': '💾 ذخیره و بررسی تغییر', 'callback_data': f'/assist_save_{aid}'}
    rows = [
        [{'text': '✅ ورود', 'callback_data': f'/assist_ok_{aid}'}, {'text': '❌ رد', 'callback_data': f'/assist_no_{aid}'}],
        [{'text': f"🔄 معامله برعکس ({'فروش' if is_long else 'خرید'}) با قیمت لحظه‌ای", 'callback_data': f'/assist_rev_{aid}'}],
        [{'text': '✏️ ورود با قیمت دستی', 'callback_data': f'/assist_man_{aid}'}, ext_btn],
        [{'text': '📈 TradingView', 'url': tradingview_chart_url(sym, tf)}, {'text': '📊 اندیکاتورها', 'callback_data': f'/assist_ind_{aid}'}],
    ]
    mini = miniapp_chart_url(sym, tf)
    if mini:
        rows.insert(0, [{'text': '🌐 چارت تعاملی (MiniApp)', 'web_app': {'url': mini}}])
    return {'inline_keyboard': rows}


def _assist_edit_markup(chat_id, rec):
    mid = rec.get('message_id')
    if not mid:
        return False
    rem = float(rec.get('expires_at', 0)) - time.time()
    markup = _assist_markup(rec, remaining=rem)
    label = markup['inline_keyboard'][-2][-1]['text']      # ردیف ماقبل آخر (ورود دستی | تمدید/شمارش معکوس)
    _ASSIST_CD_LAST[rec['id']] = label
    try:
        tg('editMessageReplyMarkup', {'chat_id': chat_id, 'message_id': mid, 'reply_markup': markup}, 10)
        return True
    except Exception:
        logger.exception('assist: countdown edit failed')
        return False


def assist_countdown_once():
    """برچسب دکمه‌ی شمارش معکوس سیگنال‌های تمدیدشده را تازه می‌کند (هر ~۱۵ ثانیه از _assist_loop)."""
    now = time.time()
    for chat_id, s in list(USER_SESSIONS.items()):
        try:
            for rec in list(s.get('assist_log') or []):
                if rec.get('status') != 'pending' or not rec.get('countdown'):
                    _ASSIST_CD_LAST.pop(rec.get('id'), None)
                    continue
                rem = float(rec.get('expires_at', 0)) - now
                if rem <= 0:
                    continue     # assist_maintenance_once دکمه‌های عملیاتی را برمی‌دارد
                if _ASSIST_CD_LAST.get(rec['id']) == _assist_countdown_label(rem):
                    continue
                _assist_edit_markup(chat_id, rec)
        except Exception:
            logger.exception('V3.42.13 per-user failure isolated: %s chat=%s', 'assist_countdown_once', chat_id)  # خطای یک کاربر بقیه را متوقف نکند


def _assist_queue_signal(chat_id, symbol, sig, plan, entry, sl, tp, full_reason, df=None):
    s = get_session(chat_id)
    now = time.time()
    _tag, level_token, level_value = extract_setup_level(full_reason)
    scn = extract_scenario_tag(full_reason)
    seen_key = f"{symbol}|{sig}|{level_token}|{level_value}|{scn}"
    with _ASSIST_LOCK:
        seen = s.setdefault('assist_seen', {})
        if now - float(seen.get(seen_key, 0) or 0) < ASSIST_SEEN_TTL_SECONDS:
            return _entry_diag_result(chat_id, symbol, 'assist_waiting', 'این ستاپ قبلاً برای تایید ارسال شده', 'assist', sig)
        if any(p.get('symbol') == symbol for p in s.get('paper_positions', [])):
            return _entry_diag_result(chat_id, symbol, 'assist_skipped', 'روی این نماد پوزیشن باز داریم', 'assist', sig)
        if now < float(s.get('cooldowns', {}).get(symbol, 0) or 0):
            return _entry_diag_result(chat_id, symbol, 'assist_skipped', 'دوره انتظار بعد از معامله قبلی هنوز تمام نشده', 'assist', sig)
        if level_token is not None and f"{symbol}:{level_token}:{level_value}" in s.get('traded_levels', {}):
            return _entry_diag_result(chat_id, symbol, 'assist_skipped', 'روی همین سطح قبلاً معامله شده', 'assist', sig)
        risk_dist = abs(float(entry) - float(sl))
        if risk_dist <= 0:
            return _entry_diag_result(chat_id, symbol, 'assist_skipped', 'فاصله SL نامعتبر', 'assist', sig)
        rr = float(plan.get('rr') or (abs(float(tp) - float(entry)) / risk_dist))
        expiry = int(s.get('assist_expiry_seconds', 300) or 300)
        aid = hashlib.sha1(f"{chat_id}{symbol}{now}".encode()).hexdigest()[:8]
        is_long = sig == 'BUY'
        level_txt, scn_txt = _assist_describe_source(full_reason, level_token, level_value, scn)
        score = plan.get('score')
        tp_level_name = plan.get('tp_level_name')
        _m, _lev = estimate_session_size(chat_id, symbol, float(entry), float(sl))
        try:
            _prate = float(get_user_fee_rate(chat_id))
        except Exception:
            _prate = None
        pnl_lines = pnl_estimate_lines(float(entry), float(sl), float(tp), sig, _m, _lev, platform_rate=_prate, compact=True)
        _tf_key = s.get('timeframe', '5min')
        try:
            _sym_regime = _signal_channel_symbol_regime(df) if df is not None else None
        except Exception:
            _sym_regime = None
        text = (
            f"{_tf_regime_line(_tf_key)}\n"
            f"{_symbol_regime_line(_sym_regime, _tf_key)}\n"
            f"• `{symbol}` ({'🟢 خرید' if is_long else '🔴 فروش'}) | تایم‌فریم: `{TF_DISPLAY.get(_tf_key, _tf_key)}`\n"
            f"• سطح: `{level_txt}` | سناریو: `{scn_txt}`\n"
            f"• ورود پیشنهادی: `{fmt(float(entry))}` | SL: `{fmt(float(sl))}`\n"
            f"• TP: `{fmt(float(tp))}`\n"
            f"• R:R: `{rr:.2f}`" + (f" | کیفیت: `{int(round(float(score)))}/100`" if score is not None else "") + "\n"
            + "\n".join(pnl_lines)
        )
        markup = _assist_markup({'id': aid, 'symbol': symbol, 'sig': sig, 'tf': s.get('timeframe', '5min')})
        if not is_allowed(chat_id):
            return _entry_diag_result(chat_id, symbol, 'assist_skipped', 'کاربر مجاز نیست', 'assist', sig)
        message_id = None
        if df is not None:
            pseudo_trade = {'entry_price': float(entry), 'tp': float(tp), 'sl': float(sl),
                            'side': 'BUY (Long)' if is_long else 'SELL (Short)', 'timeframe': s.get('timeframe', '5min'),
                            'entry_reason': full_reason, 'is_real': s.get('trading_mode') == 'REAL', 'assist_pending': True}
            png, _ctx = render_trade_chart_png(symbol, df, pseudo_trade)
            if png is not None:
                message_id = _send_photo_get_id(chat_id, png.getvalue(), text, markup)
        if message_id is None:
            res = tg('sendMessage', {'chat_id': chat_id, 'text': text, 'parse_mode': 'Markdown', 'reply_markup': markup}, 10)
            if not (res and res.get('ok')):
                return _entry_diag_result(chat_id, symbol, 'assist_skipped', 'ارسال پیام تایید ناموفق بود', 'assist', sig)
            message_id = (res.get('result') or {}).get('message_id')
        rec = {
            'id': aid, 'symbol': symbol, 'sig': sig, 'side_label': 'BUY (Long)' if is_long else 'SELL (Short)',
            'entry': float(entry), 'sl': float(sl), 'tp': float(tp), 'rr': round(rr, 3),
            'score': (int(round(float(score))) if score is not None else None),
            'quality_label': plan.get('quality_label'), 'structural_tp': bool(plan.get('structural_target', False)),
            'tp_level_name': tp_level_name, 'tp_stages': plan.get('tp_stages'), 'exp_tp_pnl_net': (round(estimate_trade_pnl(entry, sl, tp, sig, _m, _lev)['tp_net'], 4) if (_m and _lev) else None),
            'exp_sl_pnl_net': (round(estimate_trade_pnl(entry, sl, tp, sig, _m, _lev)['sl_net'], 4) if (_m and _lev) else None),
            'symbol_regime': _sym_regime,
            'reason': full_reason, 'scn': scn, 'level_token': level_token, 'level_value': level_value,
            'tf': s.get('timeframe'), 'created_at': now, 'expires_at': now + expiry, 'status': 'pending',
            'ext': 0, 'message_id': message_id,
        }
        s.setdefault('assist_log', []).append(rec)
        seen[seen_key] = now
        _assist_prune_log(s)
    save_session(chat_id)
    return _entry_diag_result(chat_id, symbol, 'assist_sent', 'سیگنال برای تایید ارسال شد', 'assist', sig)


# ===================== هشدار هم‌جهتی با روند BTC/ETH (قبل از تایید ورود در حالت دستیار) =====================
# قبل از هر ورودِ مسیر دستیار (✅ ورود، 🔄 معامله برعکس، ثبت اوردر با قیمت دستی، ورود خودکارِ سیگنال ذخیره‌شده)
# روند بیت‌کوین و اتریوم روی «تایم‌فریم معاملاتی فعال» سنجیده می‌شود (همان معیار داشبورد بازار:
# قیمت نسبت به EMA50 و EMA20>=EMA50 روی آخرین کندل بسته‌شده). اگر جهت معامله با روند هرکدام در تضاد
# باشد، ورود نگه داشته می‌شود و پیام هشدار با دکمه‌ی «بله، وارد شو / نه» می‌آید. اگر داده در دسترس نباشد
# یا هم‌جهت/خنثی باشد، هیچ مانعی ایجاد نمی‌شود (fail-open).
TREND_WARN_ENABLED = os.environ.get('ASSIST_TREND_WARN', '1') not in ('0', 'false', 'False')
TREND_WARN_SYMBOLS = ('BTC', 'ETH')
_TREND_WARN_NAMES = {'BTC': 'بیت‌کوین', 'ETH': 'اتریوم'}
_TREND_WARN_RECENT = {}


_TREND_SNAP_CACHE = {}      # {(symbol, tf): (ts, snapshot)} - کش کوتاه تا چند سیگنال پشت‌سرهم دوباره داده نگیرند
_TREND_SNAP_TTL = 20.0


def _trend_snapshot_cached(sym, tf):
    now = time.time()
    c = _TREND_SNAP_CACHE.get((sym, tf, _venue()))
    if c and now - c[0] < _TREND_SNAP_TTL:
        return c[1]
    snap = _market_snapshot(sym, tf)
    _TREND_SNAP_CACHE[(sym, tf, _venue())] = (now, snap)
    return snap


def _trend_active_symbols(chat_id, symbol=None):
    """نمادهای شاخصی که طبق کلیدهای کاربر باید چک شوند (کلید کلی + کلید جدای BTC/ETH)."""
    if not TREND_WARN_ENABLED:
        return []
    if chat_id is not None:
        s = get_session(chat_id)
        if not s.get('trend_warn_enabled', True):
            return []
        flags = {'BTC': bool(s.get('trend_warn_btc', True)), 'ETH': bool(s.get('trend_warn_eth', True))}
    else:
        flags = {'BTC': True, 'ETH': True}
    return [x for x in TREND_WARN_SYMBOLS if flags.get(x, True) and x != str(symbol or '').upper()]


def _ind_warn_active(chat_id):
    """V3.43.6: کلید «هشدار تضاد با اندیکاتورها» برای این کاربر روشن است؟"""
    if chat_id is None:
        return False
    return bool(get_session(chat_id).get('ind_warn_enabled', False))


def _indicator_conflict(symbol, side, tf):
    """(conflict, lines) - اجماع اندیکاتورها (همان رأی‌های دکمه‌ی «📊 اندیکاتورها»: RSI/MACD/ADX روی آخرین کندل بسته‌شده)
    در برابر جهت معامله. تضاد = تعداد رأی‌های خلاف جهت معامله بیشتر از رأی‌های هم‌جهت باشد. نبود داده/اجماع = بدون تضاد."""
    try:
        df = get_klines(symbol, tf, 650 if tf in ('5min', '15min', '1hour') else 200)
        ind_df = calculate_indicators(df) if df is not None and not df.empty else None
        if ind_df is None or ind_df.empty or len(ind_df) < 2:
            return False, ['• 📊 اندیکاتورها: ⚪ داده‌ی کافی نیست — بدون تضاد']
        row = ind_df.iloc[-2].to_dict()
        _l, b_votes, s_votes = _signal_channel_indicator_summary(row, side)
        popup = _signal_channel_indicator_popup(row, b_votes, s_votes) or ''
    except Exception:
        logger.exception('indicator warn failed symbol=%s', symbol)
        return False, []
    same, opp = (b_votes, s_votes) if side == 'BUY' else (s_votes, b_votes)
    total = b_votes + s_votes
    opp_fa = 'فروش' if side == 'BUY' else 'خرید'
    same_fa = 'خرید' if side == 'BUY' else 'فروش'
    lines = []
    first = popup.split('\n')[0].strip() if popup else ''
    if first:
        lines.append(f"• {first}")
    if total == 0:
        # V3.43.31: هیچ اندیکاتوری جهت نمی‌دهد (همه خنثی) = ورود بدون هیچ تاییدی => هشدار
        lines.append('• 🧠 هیچ اندیکاتوری از این معامله پشتیبانی نمی‌کند (RSI/MACD/ADX همه خنثی‌اند) — ⚠️ بدون تایید')
        return True, lines
    if opp > same:
        lines.append(f"• 🧠 {opp} از {total} اندیکاتور به سمت {opp_fa} — ⚠️ با جهت معامله‌ی شما در تضاد است")
        return True, lines
    if same == 0:
        lines.append(f"• 🧠 هیچ اندیکاتوری از این معامله پشتیبانی نمی‌کند ({opp} مخالف، بقیه خنثی) — ⚠️ بدون تایید")
        return True, lines
    if same > opp:
        lines.append(f"• 🧠 {same} از {total} اندیکاتور به سمت {same_fa} — هم‌جهت ✅")
    else:
        lines.append(f"• 🧠 اجماع مشخصی نیست ({same} به {opp}) — حداقل یک اندیکاتور هم‌جهت است")
    return False, lines


_TFR_TIMEFRAMES = ('5min', '15min')


def _tfr_warn_active(chat_id):
    """V3.43.29: کلید «هشدار ناهم‌جهتی رژیم نماد در ۵ و ۱۵ دقیقه» برای این کاربر روشن است؟"""
    if chat_id is None:
        return False
    return bool(get_session(chat_id).get('symbol_tf_regime_warn_enabled', True))


def _symbol_tf_regimes(symbol):
    """رژیم خودِ نماد روی ۵ و ۱۵ دقیقه ({tf: 'BULLISH'|'BEARISH'|'RANGE'|None}) با همان معیار داشبورد/کانال سیگنال
    (close نسبت به EMA50 و EMA20 نسبت به EMA50 روی آخرین کندل بسته‌شده)."""
    def one(tf):
        try:
            df = get_klines(symbol, tf, 160)
            if df is None or df.empty or len(df) < 60:
                return None
            return _signal_channel_symbol_regime(df)
        except Exception:
            logger.exception('symbol tf regime failed symbol=%s tf=%s', symbol, tf)
            return None
    try:
        with ThreadPoolExecutor(max_workers=len(_TFR_TIMEFRAMES)) as ex:
            vals = list(ex.map(one, _TFR_TIMEFRAMES))
    except Exception:
        logger.exception('symbol tf regimes failed symbol=%s', symbol)
        vals = [None] * len(_TFR_TIMEFRAMES)
    return dict(zip(_TFR_TIMEFRAMES, vals))


def _tfr_conflict(symbol, side=None):
    """(conflict, lines, regs): V3.43.31 - تضاد وقتی است که (الف) رژیم نماد روی ۵ و ۱۵ دقیقه با هم فرق کند، یا
    (ب) رژیم هرکدام از این دو خلاف جهت معامله باشد (خرید در رژیم نزولی / فروش در رژیم صعودی). رنج خلاف جهت حساب نمی‌شود.
    نبود داده = بدون تضاد (مثل بقیه‌ی هشدارها)."""
    regs = _symbol_tf_regimes(symbol)
    fa = {'BULLISH': '🟢 صعودی', 'BEARISH': '🔴 نزولی', 'RANGE': '⚪️ رنج'}
    is_long = (side == 'BUY') if side in ('BUY', 'SELL') else None
    lines, opposed = [], []
    for tf in _TFR_TIMEFRAMES:
        reg = regs.get(tf)
        txt = f"• {TF_DISPLAY.get(tf, tf)}: {fa.get(reg, '⚪ داده در دسترس نیست')}"
        if is_long is not None and reg in ('BULLISH', 'BEARISH') and ((reg == 'BULLISH') != is_long):
            txt += ' — ⚠️ خلاف جهت ' + ('خرید' if is_long else 'فروش')
            opposed.append(tf)
        lines.append(txt)
    r5, r15 = regs.get(_TFR_TIMEFRAMES[0]), regs.get(_TFR_TIMEFRAMES[1])
    mismatch = (r5 is not None and r15 is not None and r5 != r15)
    if mismatch:
        lines.append('• ⚠️ رژیم نماد در این دو تایم‌فریم هم‌جهت نیست')
    elif r5 is not None and r15 is not None and not opposed:
        lines.append('• هم‌جهت با هم و با معامله ✅' if is_long is not None else '• هم‌جهت ✅')
    return bool(mismatch or opposed), lines, regs


def _h4_warn_active(chat_id):
    """V3.43.30: کلید «هشدار خلاف رژیم ۴ ساعته» برای این کاربر روشن است؟"""
    if chat_id is None:
        return False
    return bool(get_session(chat_id).get('symbol_h4_regime_warn_enabled', True))


def _symbol_h4_regime(symbol):
    """رژیم خودِ نماد روی ۴ ساعته ('BULLISH'/'BEARISH'/'RANGE' یا None) - همان معیار «رژیم نماد»
    (close نسبت به EMA50 و EMA20 نسبت به EMA50 روی آخرین کندل بسته‌شده)."""
    try:
        df = get_klines(symbol, '4hour', 160)
        if df is None or df.empty or len(df) < 60:
            return None
        return _signal_channel_symbol_regime(df)
    except Exception:
        logger.exception('symbol h4 regime failed symbol=%s', symbol)
        return None


def _h4_conflict(symbol, side):
    """(conflict, lines, regime): خرید فقط با ۴ساعته‌ی صعودی و فروش فقط با ۴ساعته‌ی نزولی هم‌جهت است.
    نزولی برای خرید / صعودی برای فروش / رنج => تضاد. نبود داده => بدون تضاد (مثل بقیه‌ی هشدارها)."""
    is_long = (side == 'BUY')
    reg = _symbol_h4_regime(symbol)
    fa = {'BULLISH': '🟢 صعودی', 'BEARISH': '🔴 نزولی', 'RANGE': '⚪️ رنج'}
    if reg is None:
        return False, ['• ۴ ساعته: ⚪ داده در دسترس نیست — بدون تضاد'], reg
    ok = (reg == 'BULLISH' and is_long) or (reg == 'BEARISH' and not is_long)
    if ok:
        return False, [f"• ۴ ساعته: {fa[reg]} — هم‌جهت ✅"], reg
    need = 'صعودی' if is_long else 'نزولی'
    why = 'خلاف جهت معامله' if reg != 'RANGE' else 'جهت‌دار نیست'
    return True, [f"• ۴ ساعته: {fa[reg]} — ⚠️ {why} (این معامله فقط با ۴ ساعته‌ی {need} هم‌جهت است)"], reg


def _assist_trend_conflict_text(symbol, side, tf, chat_id=None):
    """اگر جهت side با روند BTC یا ETH (کلیدهای trend_warn_*) و/یا اجماع اندیکاتورها (کلید ind_warn_enabled) در تضاد باشد
    متن هشدار، وگرنه None (بدون تضاد یا داده ناکافی). هر دو بررسی در یک کارت تایید می‌آیند."""
    syms = _trend_active_symbols(chat_id, symbol)
    ind_on = _ind_warn_active(chat_id)
    tfr_on = _tfr_warn_active(chat_id)
    h4_on = _h4_warn_active(chat_id)
    if not syms and not ind_on and not tfr_on and not h4_on:
        return None
    is_long = (side == 'BUY')
    lines, conflict = [], False
    if syms:
        try:
            with ThreadPoolExecutor(max_workers=len(syms)) as ex:
                snaps = dict(zip(syms, ex.map(lambda x: _trend_snapshot_cached(x, tf), syms)))
        except Exception:
            logger.exception('trend warn: snapshot failed symbol=%s', symbol)
            snaps = None
        for sym in (syms if snaps is not None else []):
            snap = snaps.get(sym)
            name = f"{_TREND_WARN_NAMES.get(sym, sym)} ({sym})"
            if not snap:
                lines.append(f"• {name}: ⚪ داده در دسترس نیست")
                continue
            sc = int(snap.get('score', 0))
            if sc > 0:
                bad = not is_long
                lines.append(f"• {name}: 🟢 صعودی — " + ("⚠️ با جهت معامله‌ی شما در تضاد است" if bad else "هم‌جهت ✅"))
            elif sc < 0:
                bad = is_long
                lines.append(f"• {name}: 🔴 نزولی — " + ("⚠️ با جهت معامله‌ی شما در تضاد است" if bad else "هم‌جهت ✅"))
            else:
                bad = False
                lines.append(f"• {name}: ⚪ خنثی / رنج — بدون تضاد")
            conflict = conflict or bad
    ind_conflict, ind_lines = (_indicator_conflict(symbol, side, tf) if ind_on else (False, []))
    tfr_conflict, tfr_lines = ((_tfr_conflict(symbol, side)[:2]) if tfr_on else (False, []))
    h4_conflict, h4_lines = ((_h4_conflict(symbol, side)[:2]) if h4_on else (False, []))
    if not conflict and not ind_conflict and not tfr_conflict and not h4_conflict:
        return None
    side_txt = '🟢 خرید (Long)' if is_long else '🔴 فروش (Short)'
    main_parts = []
    if conflict:
        main_parts.append('روند بازار')
    if ind_conflict:
        main_parts.append('اجماع اندیکاتورها')
    if h4_conflict:
        main_parts.append('رژیم ۴ ساعته‌ی نماد')
    if main_parts:
        title = 'ورود با ' + ' و '.join(main_parts) + ' در تضاد است'
        if tfr_conflict:
            title = title[:-len(' در تضاد است')] + ' و رژیم ۵/۱۵ دقیقه‌ی نماد در تضاد است'
    else:
        title = 'رژیم نماد در ۵ و ۱۵ دقیقه با این ورود نمی‌خواند'
    sections = []
    if lines:
        sections.append(('*روند بازار (BTC/ETH):*', lines, True))
    if ind_lines:
        sections.append(('*اندیکاتورها:*', ind_lines, False))
    if h4_lines:
        sections.append((f'*رژیم ۴ ساعته‌ی نماد ({symbol}):*', h4_lines, False))
    if tfr_lines:
        sections.append((f'*رژیم نماد ({symbol}) روی ۵ و ۱۵ دقیقه:*', tfr_lines, False))
    body = []
    for header, sec_lines, header_only_if_multiple in sections:
        if body:
            body.append('')
        if not header_only_if_multiple or len(sections) > 1:
            body.append(header)
        body += sec_lines
    tail = []
    if conflict:
        tail.append('روند نماد شما با روند بازار (BTC/ETH) هم‌جهت نیست و ریسک ورود بالاتر است.')
    if ind_conflict:
        tail.append('اندیکاتورها (RSI/MACD/ADX) یا خلاف این معامله‌اند یا هیچ‌کدام از آن پشتیبانی نمی‌کنند؛ شاید بهتر باشد صبر کنید.')
    if h4_conflict:
        tail.append('قاعده: خرید فقط وقتی رژیم ۴ ساعته‌ی نماد صعودی است و فروش فقط وقتی نزولی؛ این ورود با آن نمی‌خواند.')
    if tfr_conflict:
        tail.append('رژیم خودِ نماد روی ۵ و ۱۵ دقیقه یا با هم هم‌جهت نیست یا خلاف جهت این معامله است؛ اعتبار ورود کمتر است.')
    return (f"⚠️ *هشدار: {title}*\n\n"
            f"نماد: `{symbol}` | جهت: {side_txt} | تایم‌فریم فعال: `{tf}`\n\n"
            + "\n".join(body) + "\n\n" + "\n".join(tail) + "\n"
            "*ورود را تایید می‌کنید؟*")


def _entry_warning_tags(chat_id, symbol, side, tf):
    """V3.44.4: هشدارهای لحظه‌ی ورود به‌صورت برچسب‌های کوتاه (همان بررسی‌های کارت هشدار: روند BTC/ETH، اندیکاتورها،
    رژیم ۴ ساعته، رژیم ۵/۱۵ دقیقه). فقط بررسی‌هایی که کلیدشان روشن است سنجیده می‌شوند.
    خروجی: None = هیچ کلید هشداری روشن نیست (چیزی ثبت نمی‌شود) | [] = هشدار نداشت | ['روند BTC', 'اندیکاتورها', ...]"""
    syms = _trend_active_symbols(chat_id, symbol)
    ind_on = _ind_warn_active(chat_id); tfr_on = _tfr_warn_active(chat_id); h4_on = _h4_warn_active(chat_id)
    if not syms and not ind_on and not tfr_on and not h4_on:
        return None
    is_long = (side == 'BUY' or side_long(side))
    sig = 'BUY' if is_long else 'SELL'
    tags = []
    for sym in syms:
        try:
            snap = _trend_snapshot_cached(sym, tf)
        except Exception:
            snap = None
        if not snap:
            continue
        sc = int(snap.get('score', 0))
        if (sc > 0 and not is_long) or (sc < 0 and is_long):
            tags.append(f'روند {sym}')
    try:
        if ind_on and _indicator_conflict(symbol, sig, tf)[0]:
            tags.append('اندیکاتورها')
    except Exception:
        logger.debug('entry warn: indicator check failed %s', symbol)
    try:
        if h4_on and _h4_conflict(symbol, sig)[0]:
            tags.append('رژیم ۴ساعته')
    except Exception:
        logger.debug('entry warn: h4 check failed %s', symbol)
    try:
        if tfr_on and _tfr_conflict(symbol, sig)[0]:
            tags.append('رژیم ۵/۱۵م')
    except Exception:
        logger.debug('entry warn: tf regime check failed %s', symbol)
    return tags


def _entry_warn_line(trade):
    """یک خط کوتاه برای پیام‌ها؛ '' اگر برای این معامله چیزی ثبت نشده (قدیمی یا کلید هشدار خاموش بوده)."""
    w = trade.get('entry_warnings') if isinstance(trade, dict) else None
    if w is None:
        return ''
    return ('• ⚠️ هشدار لحظه‌ی ورود: ' + '، '.join(w) + '\n') if w else '• ✅ هشدار لحظه‌ی ورود: ندارد\n'


# ===================== V3.43.24: «تایید کامل هم‌جهتی» (کلیدهای gate_fc_*_enabled، هرکدام مستقل) =====================
# همه‌ی مواردی که در پیام بسته‌شدن پوزیشن با «هم‌جهت ✅» نشان داده می‌شوند، قبل از صدور سیگنال باید برقرار باشند:
# رژیم BTC و ETH، رژیم ۴ ساعته‌ی نماد، رژیم نماد در ۵ و ۱۵ دقیقه، RSI، MACD، حجم، روند ADX، و آخرین کندل بسته‌شده سمتِ درستِ سطح.
# هر اندیکاتور (RSI / MACD / حجم / ADX) کلید مستقل خودش را دارد. سخت‌گیرانه: خنثی/رنج یا نبودِ داده = شرط برقرار نیست = سیگنال صادر نمی‌شود.
def _single_indicator_biases(row):
    """V3.43.31: جهتِ هر اندیکاتور به‌صورت جدا: {'rsi','macd','adx'} -> 'BUY' | 'SELL' | None (خنثی/نبود داده)،
    به‌علاوه‌ی مقدارهای خام برای متن دلیل. همان آستانه‌های _signal_channel_indicator_summary."""
    out = {'rsi': None, 'macd': None, 'adx': None}
    raw = {}
    rsi = row.get('rsi')
    if rsi is not None and pd.notna(rsi):
        rsi = float(rsi); raw['rsi'] = rsi
        if rsi >= 70 or rsi <= 30:
            out['rsi'] = 'SELL' if rsi >= 70 else 'BUY'
        elif rsi >= 55:
            out['rsi'] = 'BUY'
        elif rsi <= 45:
            out['rsi'] = 'SELL'
    mh = row.get('macd_hist')
    if mh is not None and pd.notna(mh):
        mh = float(mh); raw['macd'] = mh
        out['macd'] = 'BUY' if mh > 0 else ('SELL' if mh < 0 else None)
    adx, pdi, mdi = row.get('adx'), row.get('plus_di'), row.get('minus_di')
    if adx is not None and pd.notna(adx):
        adx = float(adx); raw['adx'] = adx
        if adx >= 20 and pdi is not None and mdi is not None and pd.notna(pdi) and pd.notna(mdi):
            out['adx'] = 'BUY' if float(pdi) > float(mdi) else ('SELL' if float(mdi) > float(pdi) else None)
    return out, raw


def _full_confirm_check(symbol, sig, tf, reason='', ind_df=None, use=None):
    """(ok, [موارد ناهم‌جهت]) - sync است؛ از thread صدا زده شود.
    use: دیکشنری کلیدهای فعال‌بودن هر گروه شرط {'btceth','h4','tf','rsi','macd','vol','adx','level'} (پیش‌فرض: همه فعال)."""
    use = use or {}
    def _on(k):
        return bool(use.get(k, True))
    if sig not in ('BUY', 'SELL'):
        return False, ['جهت سیگنال نامشخص']
    is_long = (sig == 'BUY')
    want = 'BULLISH' if is_long else 'BEARISH'
    want_fa = 'صعودی' if is_long else 'نزولی'
    fa = {'BULLISH': 'صعودی', 'BEARISH': 'نزولی', 'RANGE': 'رنج'}
    bad = []
    sym_u = str(symbol or '').upper()
    for sym in (('BTC', 'ETH') if _on('btceth') else ()):
        if sym == sym_u:
            continue
        try:
            snap = _trend_snapshot_cached(sym, tf)
        except Exception:
            snap = None
        if not snap:
            bad.append(f'رژیم {sym}: داده در دسترس نیست')
            continue
        sc = int(snap.get('score', 0))
        if sc == 0 or (sc > 0) != is_long:
            bad.append(f"رژیم {sym} {'صعودی' if sc > 0 else ('نزولی' if sc < 0 else 'خنثی')} (لازم: {want_fa})")
    if _on('h4'):
        h4 = _symbol_h4_regime(symbol)
        if h4 != want:
            bad.append(f"رژیم ۴ ساعته {fa.get(h4, 'نامشخص')} (لازم: {want_fa})")
    if _on('tf'):
        regs = _symbol_tf_regimes(symbol)
        for t in _TFR_TIMEFRAMES:
            if regs.get(t) != want:
                bad.append(f"رژیم {TF_DISPLAY.get(t, t)} {fa.get(regs.get(t), 'نامشخص')} (لازم: {want_fa})")
    if not (_on('rsi') or _on('macd') or _on('vol') or _on('adx') or _on('level')):
        return (not bad), bad
    try:
        ind = ind_df
        if ind is None:
            d = get_klines(symbol, tf, 650 if tf in ('5min', '15min', '1hour') else 200)
            ind = calculate_indicators(d) if d is not None and not d.empty else None
        if ind is None or len(ind) < 4:
            raise ValueError('no indicator data')
        row = ind.iloc[-2]
        _bias, _raw = _single_indicator_biases(row.to_dict())
        _dir_fa = {'BUY': 'صعودی', 'SELL': 'نزولی', None: 'خنثی/نامشخص'}
        if _on('rsi') and _bias['rsi'] != sig:
            _v = f"{_raw['rsi']:.0f}" if 'rsi' in _raw else 'نامشخص'
            bad.append(f"RSI ({_v}) {_dir_fa[_bias['rsi']]} است (لازم: {want_fa})")
        if _on('macd') and _bias['macd'] != sig:
            bad.append(f"MACD {_dir_fa[_bias['macd']]} است (لازم: {want_fa})")
        if _on('adx') and _bias['adx'] != sig:
            _v = f"{_raw['adx']:.0f}" if 'adx' in _raw else 'نامشخص'
            bad.append(f"روند ADX ({_v}) {_dir_fa[_bias['adx']]} است (لازم: {want_fa}، حداقل ADX ۲۰)")
        if _on('vol'):
            _vr = row.get('volume_ratio')
            if _vr is None or pd.isna(_vr):
                bad.append('حجم: داده در دسترس نیست')
            elif float(_vr) < FULL_CONFIRM_MIN_VOLUME_RATIO:
                bad.append(f"حجم کافی نیست ({float(_vr):.1f}x؛ لازم: حداقل {FULL_CONFIRM_MIN_VOLUME_RATIO:g}x)")
        m = (re.search(r'HVL=([0-9.]+)', reason or '') or re.search(r'ANCHOR=([0-9.]+)', reason or '')) if _on('level') else None
        if m:
            lvl = float(m.group(1))
            last = float(row['close'])
            if not ((last > lvl) if is_long else (last < lvl)):
                bad.append(f"آخرین کندل بسته‌شده {'بالای' if is_long else 'پایین'} سطح {fmt(lvl)} نیست")
    except Exception:
        logger.exception('full confirm indicators failed symbol=%s', symbol)
        bad.append('اندیکاتورها/سطح: داده در دسترس نیست')
    return (not bad), bad


# ===================== V3.43.25: «🔄 بروزرسانی داده‌ها» روی کارت هشدار تضاد =====================
# اندیکاتورها و رژیم BTC/ETH همه روی «آخرین کندل بسته‌شده» حساب می‌شوند؛ پس نتیجه فقط با بسته شدن کندل تازه
# عوض می‌شود. دکمه کَش داده را دور می‌زند، دوباره می‌سنجد و زیر کارت یک بلوک وضعیت می‌گذارد (جایگزین بلوک قبلی؛
# کارت بزرگ نمی‌شود). ورود خودکار انجام نمی‌دهد: فقط مشورتی است و تصمیم با کاربر می‌ماند.
_TF_SECONDS = {'1min': 60, '5min': 300, '15min': 900, '30min': 1800, '1hour': 3600, '4hour': 14400, '1day': 86400}
TGREF_COOLDOWN_SECONDS = 10
TGREF_MAX_AGE_SECONDS = 3600
_TGREF_NAMES = {'BTC': 'بیت‌کوین', 'ETH': 'اتریوم', 'IND': 'اندیکاتورها', 'TFR': 'رژیم نماد ۵/۱۵ دقیقه', 'H4': 'رژیم ۴ ساعته‌ی نماد'}
_TGREF_DIV = '━━━━━━━━━━━━━━━━━━━━'


def _drop_kline_cache(sym):
    """کَش کندل و کَش روند این نماد پاک می‌شود تا بروزرسانی واقعاً داده‌ی تازه بگیرد."""
    try:
        with DATA_LOCK:
            for k in [k for k in DATA_CACHE if str(k).startswith(f'{sym}:')]:
                DATA_CACHE.pop(k, None)
        for k in [k for k in list(_TREND_SNAP_CACHE) if k[0] == sym]:
            _TREND_SNAP_CACHE.pop(k, None)
    except Exception:
        logger.exception('drop kline cache failed sym=%s', sym)


def _entry_refresh_check(chat_id, symbol, side, tf, fresh=True):
    """وضعیت فعلی تضادها: {'items': {BTC/ETH/IND: ('ok'|'bad'|'na', score)}, 'ind_lines', 'candle_close'}.
    همان معیارِ کارت هشدار (روند BTC/ETH و اجماع اندیکاتورها)؛ فقط کلیدهای روشن بررسی می‌شوند."""
    is_long = (side == 'BUY')
    syms = _trend_active_symbols(chat_id, symbol)
    ind_on = _ind_warn_active(chat_id)
    if fresh:
        for x in set(syms) | {symbol}:
            _drop_kline_cache(x)
    out = {'items': {}, 'ind_lines': [], 'candle_close': None, 'tfr': None}
    for sym in syms:
        snap = _market_snapshot(sym, tf)
        if not snap:
            out['items'][sym] = ('na', None)
            continue
        _TREND_SNAP_CACHE[(sym, tf, _venue())] = (time.time(), snap)
        sc = int(snap.get('score', 0))
        bad = (sc < 0 and is_long) or (sc > 0 and not is_long)
        out['items'][sym] = ('bad' if bad else 'ok', sc)
    if ind_on:
        conflict, lines = _indicator_conflict(symbol, side, tf)
        no_data = bool(lines) and 'داده‌ی کافی نیست' in lines[0]
        out['items']['IND'] = ('na' if no_data else ('bad' if conflict else 'ok'), None)
        out['ind_lines'] = lines
    if _h4_warn_active(chat_id):
        h4_bad, _hl, h4_reg = _h4_conflict(symbol, side)
        out['h4'] = h4_reg
        out['items']['H4'] = ('na' if h4_reg is None else ('bad' if h4_bad else 'ok'), None)
    if _tfr_warn_active(chat_id):
        tfr_bad, _tl, regs = _tfr_conflict(symbol, side)
        out['tfr'] = regs
        out['items']['TFR'] = ('na' if any(v is None for v in regs.values()) else ('bad' if tfr_bad else 'ok'), None)
    try:
        df = get_klines(symbol, tf, 160)
        ts = float(df.iloc[-2]['timestamp'])
        if ts > 1e11:
            ts /= 1000.0
        out['candle_close'] = ts + _TF_SECONDS.get(tf, 300)
    except Exception:
        pass
    return out


def _hm(ts, secs=False):
    t = fmt_scan_time(ts)
    return t[11:19] if secs else t[11:16]


def _entry_refresh_block(rec, res, now):
    items = res['items']
    base = rec.get('base') or {}
    tf_s = _TF_SECONDS.get(rec.get('tf') or '5min', 300)
    lines = [_TGREF_DIV, f"🔄 *بروزرسانی داده‌ها* — `{_hm(now, True)}`"]
    cc = res.get('candle_close')
    new_candle = False
    if cc:
        created_boundary = (float(rec.get('created_at', now)) // tf_s) * tf_s
        new_candle = cc > created_boundary + 1
        lines.append(f"• آخرین کندل بسته‌شده: `{_hm(cc)}` " + ("(بعد از ارسال هشدار بسته شده)" if new_candle else "(از زمان هشدار تغییری نکرده)"))
    for key in ('BTC', 'ETH', 'IND', 'H4', 'TFR'):
        if key not in items:
            continue
        st, sc = items[key]
        name = _TGREF_NAMES[key]
        back = ' — برطرف شد ✅' if (base.get(key) == 'bad' and st == 'ok') else (' — تازه به تضاد رسید ⚠️' if (base.get(key) == 'ok' and st == 'bad') else '')
        if key == 'H4':
            fa_h4 = {'BULLISH': '🟢 صعودی', 'BEARISH': '🔴 نزولی', 'RANGE': '⚪️ رنج'}.get(res.get('h4'), '⚪ ؟')
            lines.append(f"• {name}: {fa_h4} — " + ('هم‌جهت ✅' if st == 'ok' else ('⚠️ با جهت معامله نمی‌خواند' if st == 'bad' else 'داده کافی نیست')) + back)
            continue
        if key == 'TFR':
            fa_short = {'BULLISH': '🟢 صعودی', 'BEARISH': '🔴 نزولی', 'RANGE': '⚪️ رنج'}
            regs = res.get('tfr') or {}
            parts = ' | '.join(f"{TF_DISPLAY.get(t, t)} {fa_short.get(regs.get(t), '⚪ ؟')}" for t in _TFR_TIMEFRAMES)
            lines.append(f"• {name}: {parts}" + (' — هم‌جهت ✅' if st == 'ok' else (' — ⚠️ هم‌جهت نیست' if st == 'bad' else ' — داده کافی نیست')) + back)
            continue
        if key == 'IND':
            verdict = (res.get('ind_lines') or [''])[-1].lstrip('• ').strip()
            lines.append(f"• {verdict or name}" + back if st != 'na' else f"• {name}: ⚪ داده‌ی کافی نیست")
        elif st == 'na':
            lines.append(f"• {name}: ⚪ داده در دسترس نیست")
        else:
            icon = '🟢 صعودی' if sc > 0 else ('🔴 نزولی' if sc < 0 else '⚪ خنثی')
            lines.append(f"• {name}: {icon} — " + ('⚠️ در تضاد' if st == 'bad' else 'بدون تضاد ✅') + back)
    bad = [_TGREF_NAMES[k] for k, v in items.items() if v[0] == 'bad']
    na = [k for k, v in items.items() if v[0] == 'na']
    if not items:
        lines.append('ℹ️ هیچ بررسی هشداری روشن نیست.')
    elif na:
        lines.append('⚪ بخشی از داده‌ها در دسترس نبود؛ چند ثانیه بعد دوباره بروزرسانی کن. (تصمیم نهایی با توست)')
    elif not bad:
        far = None
        try:
            if rec.get('entry') and rec.get('sl') and rec.get('tp'):
                live = exchange_latest_price(rec['chat_id'], rec['symbol']) if get_session(rec['chat_id']).get('trading_mode') == 'REAL' else latest_price(rec['symbol'])
                if live:
                    live = float(live); is_long = rec['side'] == 'BUY'
                    entry, sl, tp = float(rec['entry']), float(rec['sl']), float(rec['tp'])
                    risk = abs(entry - sl)
                    crossed = (live <= sl or live >= tp) if is_long else (live >= sl or live <= tp)
                    drift = abs(live - entry) / risk if risk > 0 else 0.0
                    if crossed or drift > ASSIST_MAX_DRIFT_R:
                        far = (live, drift, crossed)
        except Exception:
            logger.exception('refresh price check failed symbol=%s', rec.get('symbol'))
        if far:
            lines.append(f"🚫 تضادها برطرف شده، ولی قیمت لحظه‌ای (`{fmt(far[0])}`) از ستاپ دور شده (`{far[1]:.2f}R`)"
                         + (" و از SL/TP عبور کرده" if far[2] else "") + "؛ ورود توصیه نمی‌شود.")
        else:
            lines.append('✅ *در این لحظه ورود تایید می‌شود:* تضادی با روند BTC/ETH و اندیکاتورها نیست. (تصمیم نهایی با توست)')
    else:
        was = [k for k, v in base.items() if v == 'bad']
        trend = ''
        if was:
            trend = ' (نسبت به هشدار: ' + ('بهتر شده' if len(bad) < len(was) else ('بدتر شده' if len(bad) > len(was) else 'بدون تغییر')) + ')'
        lines.append(f"⚠️ *هنوز در تضاد است:* {'، '.join(bad)}{trend}.")
    return '\n'.join(lines)


def entry_refresh_press(chat_id, token, message_id=None):
    s = get_session(chat_id)
    rec = (s.get('tg_refresh') or {}).get(token)
    now = time.time()
    if not rec or now - float(rec.get('created_at', 0) or 0) > TGREF_MAX_AGE_SECONDS:
        send_message(chat_id, 'ℹ️ این کارت قدیمی شده؛ بروزرسانی ممکن نیست.', keep=False); return
    if rec.get('kind') == 'auto':
        a = (s.get('auto_trend_pending') or {}).get(token)
        if not a or a.get('status') != 'pending' or now > float(a.get('expires_at', 0) or 0):
            send_message(chat_id, 'ℹ️ این سیگنال دیگر در انتظار تصمیم نیست.', keep=False); return
    if now - float(rec.get('last_refresh', 0) or 0) < TGREF_COOLDOWN_SECONDS:
        return      # لمس‌های پشت‌سرهم: جلوگیری از فشار به صرافی
    rec['last_refresh'] = now
    try:
        res = _entry_refresh_check(chat_id, rec['symbol'], rec['side'], rec.get('tf') or '5min', fresh=True)
        block = _entry_refresh_block(rec, res, now)
    except Exception:
        logger.exception('entry refresh failed symbol=%s', rec.get('symbol'))
        send_message(chat_id, '⚠️ بروزرسانی انجام نشد؛ چند ثانیه بعد دوباره امتحان کن.', keep=False); return
    markup = _warn_card_markup(token, rec['symbol'], rec.get('tf') or '5min', rec['ok_cb'], rec['no_cb'])
    send_message(chat_id, rec['text'] + '\n\n' + block, markup, message_id=message_id, keep=True)
    save_session(chat_id)


def _tgref_register(chat_id, token, kind, symbol, side, tf, text, ok_cb, no_cb, entry=None, sl=None, tp=None):
    """رکورد لازم برای دکمه‌ی بروزرسانی را ذخیره می‌کند (وضعیت پایه‌ی تضادها هم برای مقایسه‌ی «بهتر/بدتر شد»)."""
    s = get_session(chat_id)
    base = None
    try:
        base = {k: v[0] for k, v in _entry_refresh_check(chat_id, symbol, side, tf, fresh=False)['items'].items()}
    except Exception:
        logger.exception('refresh baseline failed symbol=%s', symbol)
    store = s.setdefault('tg_refresh', {})
    now = time.time()
    for k in [k for k, v in store.items() if now - float(v.get('created_at', 0) or 0) > 3 * 3600]:
        store.pop(k, None)
    store[token] = {'kind': kind, 'chat_id': chat_id, 'symbol': symbol, 'side': side, 'tf': tf, 'text': text,
                    'ok_cb': ok_cb, 'no_cb': no_cb, 'entry': entry, 'sl': sl, 'tp': tp,
                    'created_at': now, 'base': base, 'last_refresh': 0}


def _assist_trend_warn(chat_id, symbol, side, ok_cb, no_cb):
    """True = هشدار فرستاده شد و ورود تا تصمیم کاربر نگه داشته می‌شود؛ False = ورود می‌تواند ادامه یابد."""
    try:
        key = (chat_id, ok_cb)
        now = time.time()
        if now - _TREND_WARN_RECENT.get(key, 0) < 5:      # دابل‌کلیک: کارت هشدار دوباره نیاید
            return True
        s = get_session(chat_id)
        tf = s.get('timeframe', '5min')
        text = _assist_trend_conflict_text(symbol, side, tf, chat_id)
        if not text:
            return False
        _TREND_WARN_RECENT[key] = now
        token = hashlib.sha1(f"{chat_id}{symbol}{ok_cb}{now}".encode()).hexdigest()[:8]
        _tgref_register(chat_id, token, 'assist', symbol, side, tf, text, ok_cb, no_cb)
        send_message(chat_id, text, _warn_card_markup(token, symbol, tf, ok_cb, no_cb), keep=True)
        save_session(chat_id)
        return True
    except Exception:
        logger.exception('trend warn failed symbol=%s', symbol)
        return False


def _warn_card_markup(token, symbol, tf, ok_cb, no_cb):
    """V3.43.25: کیبورد کارت‌های هشدار تضاد (ورود خودکار نگه‌داشته‌شده و حالت دستیار):
    بله/نه + «🔄 بروزرسانی داده‌ها» + دکمه‌های نمایش چارت (MiniApp و TradingView)."""
    rows = [[{'text': '✅ بله، وارد شو', 'callback_data': ok_cb},
             {'text': '❌ نه', 'callback_data': no_cb}],
            [{'text': '🔄 بروزرسانی داده‌ها', 'callback_data': f'/tgref_{token}'}]]
    try:
        mini = miniapp_chart_url(symbol, tf)
    except Exception:
        mini = None
    if mini:
        rows.append([{'text': '🌐 چارت تعاملی (MiniApp)', 'web_app': {'url': mini}}])
    rows.append([{'text': '📈 نمایش چارت در TradingView', 'url': tradingview_chart_url(symbol, tf)}])
    return {'inline_keyboard': rows}


def _auto_gate_markup(rid, symbol, tf):
    """V3.43.24: کیبورد کارت «ورود خودکار نگه داشته شد» (توکن بروزرسانی = شناسه‌ی همان سیگنال)."""
    return _warn_card_markup(rid, symbol, tf, f'/autotg_ok_{rid}', f'/autotg_no_{rid}')


def _auto_gate_mark(s, rid, status):
    """وضعیت رکوردِ هم‌نام در «سیگنال‌های در انتظار» (assist_log) را با تصمیم/انقضای ورود نگه‌داشته‌شده هماهنگ می‌کند."""
    try:
        with _ASSIST_LOCK:
            a = _assist_find(s, rid)
            if a and a.get('auto_gate') and a.get('status') == 'pending':
                a['status'] = status
                a[f'{status}_at'] = time.time()
    except Exception:
        logger.exception('auto gate mark failed rid=%s', rid)


def _auto_gate_strip(chat_id, s, rid, rec):
    """دکمه‌های عملیاتی کارت (و کارتی که از لیست انتظار دوباره پایین چت آمده) برداشته می‌شود؛ دکمه‌ی چارت می‌ماند."""
    info = {'symbol': rec.get('symbol'), 'tf': rec.get('tf') or '5min'}
    mids = [rec.get('message_id')]
    a = _assist_find(s, rid)
    if a:
        mids.append(a.get('message_id'))
        mids += list(a.get('old_mids') or [])
    for mid in dict.fromkeys(m for m in mids if m):
        _assist_strip_buttons(chat_id, mid, info)


# ======================= V3.43.32: صبر برای تایید حرکت به نفع معامله =======================
# وقتی روشن باشد، سیگنال خودکار فوراً وارد نمی‌شود. مدتی (پیش‌فرض ۱۵ دقیقه) صبر می‌کند و روی «کلوز کندل‌های بسته‌شده‌ی
# بعد از سیگنال» نگاه می‌کند: x = حرکت قیمت به نفع معامله بر حسب R (R = فاصله‌ی ورودِ سیگنال تا SL).
#   x بین min_r و max_r (و R:R جدید هنوز >= FAV_CONFIRM_MIN_RR)  -> ورود (با همان SL/TP سیگنال)
#   x بالاتر از max_r (یا R:R جدید کمتر از حد)                   -> سیگنال منقضی (ورود دیرهنگام)
#   x <= -FAV_CONFIRM_CANCEL_R یا قیمت به SL/TP رسید               -> لغو
#   غیر از این                                                    -> صبر تا کندل بعدی / پایان مهلت
FAV_CONFIRM_MIN_RR = float(os.environ.get('FAV_CONFIRM_MIN_RR', '1.3'))
FAV_CONFIRM_CANCEL_R = float(os.environ.get('FAV_CONFIRM_CANCEL_R', '0.5'))
FAV_MIN_R_CHOICES = (0.10, 0.15, 0.20, 0.25)
FAV_MAX_R_CHOICES = (0.30, 0.35, 0.50)
FAV_WAIT_CHOICES = (600, 900, 1200, 1800)
FAV_EXTEND_SECONDS = max(60, int(os.environ.get('FAV_EXTEND_SECONDS', '1800')))   # V3.44.27: هر لمس «تمدید مهلت» این‌قدر به مهلت همان سیگنال اضافه می‌کند (۳۰ دقیقه)
FAV_MAX_PCT_CHOICES = (0.10, 0.15, 0.20, 0.25, 0.30, 0.40)
FAV_HARD_MAX_R = float(os.environ.get('FAV_HARD_MAX_R', '1.5'))      # در حالت «درصد مسیر تا هدف» هم سقف از این R بالاتر نمی‌رود


def _fav_cfg(s):
    try:
        mn = float(s.get('fav_confirm_min_r', 0.15)); mx = float(s.get('fav_confirm_max_r', 0.30))
        wt = int(s.get('fav_confirm_wait_sec', 1800))
    except Exception:
        mn, mx, wt = 0.15, 0.30, 1800
    if mx <= mn:
        mx = mn + 0.05
    return mn, mx, max(60, wt)


def _fav_max_mode(s):
    return 'r' if str(s.get('fav_confirm_max_mode', 'tp')).lower() == 'r' else 'tp'


def _fav_max_pct(s):
    try:
        v = float(s.get('fav_confirm_max_tp_pct', 0.20))
    except Exception:
        v = 0.20
    return min(max(v, 0.05), 0.90)


def _fav_max_label(s):
    if _fav_max_mode(s) == 'tp':
        return f"٪{_fav_max_pct(s) * 100:g} مسیر تا هدف"
    return f"+{_fav_cfg(s)[1]:g}R"


def _fav_effective_max_r(s, entry, sl, tp):
    """سقف ورود (بر حسب R) برای همین سیگنال. حالت 'tp': درصدی از فاصله‌ی ورود تا هدف؛ یعنی هر نماد سقف خودش را دارد
    (هدف دور = سقف بالاتر، هدف نزدیک = سقف کمتر). حالت 'r': همان عدد ثابت قبلی."""
    mn, mx_fixed, _wt = _fav_cfg(s)
    if _fav_max_mode(s) != 'tp':
        return mx_fixed
    try:
        risk = abs(float(entry) - float(sl)); reward = abs(float(tp) - float(entry))
    except Exception:
        return mx_fixed
    if risk <= 0 or reward <= 0:
        return mx_fixed
    mx = min(_fav_max_pct(s) * reward / risk, FAV_HARD_MAX_R)
    return max(mx, mn + 0.05)


def _fav_move_r(sig, entry, sl, px):
    """حرکت قیمت px به نفع معامله نسبت به ورودِ سیگنال، بر حسب R (منفی = خلاف جهت). None اگر ریسک نامعتبر."""
    risk = abs(float(entry) - float(sl))
    if risk <= 0:
        return None
    mv = (float(px) - float(entry)) if sig == 'BUY' else (float(entry) - float(px))
    return mv / risk


def _fav_eval_tf(s, tf):
    """V3.44.95: تایم‌فریمِ کندلی که تایید صف روی «کلوز بسته‌شده»‌اش سنجیده می‌شود.
    کلید fav_close_5m_enabled روشن و تایم‌فریم سیگنال بزرگ‌تر از ۵ دقیقه باشد = کلوز ۵ دقیقه‌ای (خروج زودتر)؛ وگرنه همان تایم‌فریم سیگنال.
    فقط ارزیابی حرکت قیمت (min/max/cancel) را عوض می‌کند؛ رژیم/BTC/سطح دیروز همچنان روی تایم‌فریم سیگنال سنجیده می‌شوند."""
    try:
        if s.get('fav_close_5m_enabled', False) and _TF_SECONDS.get(tf, 300) > 300:
            return '5min'
        if s.get('fav_close_15m_enabled', False) and _TF_SECONDS.get(tf, 300) > 900:      # V3.44.101: کلید جدا؛ مثلاً سیگنال ۱ ساعته با کلوز ۱۵ دقیقه‌ای
            return '15min'
    except Exception:
        pass
    return tf


def _fav_decide(sig, entry, sl, tp, px, min_r, max_r, min_rr=None, cancel_r=None):
    """تصمیم روی قیمت px (کلوز کندل بسته‌شده): 'confirm' | 'overrun' | 'cancel' | 'wait'."""
    min_rr = FAV_CONFIRM_MIN_RR if min_rr is None else min_rr
    cancel_r = FAV_CONFIRM_CANCEL_R if cancel_r is None else cancel_r
    x = _fav_move_r(sig, entry, sl, px)
    if x is None:
        return 'cancel'
    if sig == 'BUY':
        if px <= float(sl) or px >= float(tp):
            return 'cancel'
    else:
        if px >= float(sl) or px <= float(tp):
            return 'cancel'
    if x <= -cancel_r:
        return 'cancel'
    risk_new = abs(float(px) - float(sl)); reward_new = abs(float(tp) - float(px))
    rr_new = reward_new / risk_new if risk_new > 0 else 0.0
    if x > max_r or (x >= min_r and rr_new < min_rr):
        return 'overrun'
    if x >= min_r:
        return 'confirm'
    return 'wait'


# ===================== V3.44.31: کلید «رژیم بازار در مرحله‌ی آخر ورود» =====================
# در آخرین مرحله‌ای که سیگنال از صف خارج می‌شود و تبدیل به معامله (یا کارت دستیار) می‌شود، رژیم بازار روی تایم‌فریم سیگنال
# دوباره سنجیده می‌شود: خرید فقط وقتی رژیم «صعودی» و فروش فقط وقتی «نزولی» است. رژیمِ رنج یا خلافِ جهت (حتی قطعی) = سیگنال
# رد نمی‌شود، در صف می‌ماند و در هر تیک دوباره سنجیده می‌شود تا رژیم به نفع معامله شود؛ اگر تا پایان مهلت نشد، ورودی انجام نمی‌شود.
# ورود سریع دستی (رأی خود کاربر) و تایید دستی کارت‌ها از این کلید عبور می‌کنند.
_FINAL_REGIME_FA = {'BULLISH': 'صعودی', 'BEARISH': 'نزولی', 'RANGE': 'رنج'}


def _final_regime_verdict(gate, sig):
    """(ok, توضیح). gate = رژیم بازار ('BULLISH'/'BEARISH'/'RANGE' یا None)، sig = 'BUY'/'SELL'."""
    want = 'BULLISH' if sig == 'BUY' else 'BEARISH'
    if gate == want:
        return True, ''
    side_fa = 'خرید' if sig == 'BUY' else 'فروش'
    want_fa = _FINAL_REGIME_FA[want]
    if gate in ('BULLISH', 'BEARISH'):
        return False, f"رژیم بازار {_FINAL_REGIME_FA[gate]} است و با {side_fa} نمی‌خواند؛ صبر تا {want_fa} شدن"
    if gate == 'RANGE':
        return False, f"رژیم بازار رنج است؛ صبر تا {want_fa} شدن"
    return False, f"رژیم بازار نامشخص است؛ صبر تا {want_fa} شدن"


def _final_regime_check(tf, sig):
    """نسخه‌ی همگام (برای حلقه‌های پس‌زمینه): رژیم بازار تایم‌فریم tf را تازه می‌کند (کش TTL دارد) و حکم می‌دهد."""
    try:
        _ensure_tf_gate_sync(tf)
    except Exception:
        logger.exception('final regime: gate refresh failed tf=%s', tf)
    gate = (TIMEFRAME_REGIME_CACHE.get(_tfk(tf)) or {}).get('gate')
    return _final_regime_verdict(gate, sig)


def _pd_level_gate(s, symbol, sig, tf, live=None):
    """V3.44.58: کلید «سقف/کف دیروز جلوی معامله» (gate_pd_level_enabled)، فقط در مدل نصف‌کردن. (ok, توضیح).
    فروشِ نزدیکِ PDL (یا خریدِ نزدیکِ PDH) یا ورود درست بعد از برگشت قیمت از همین سطح نگه داشته می‌شود؛ سیگنال رد نمی‌شود و در بررسی بعدی
    دوباره سنجیده می‌شود. اگر داده‌ی کافی نبود ورود را نمی‌بندد (این کلید فقط یک محافظ اضافه است)."""
    try:
        if not gate_on(s, 'gate_pd_level_enabled'):
            return True, ''
        cfg = {**STRATEGY_DEFAULTS, **(s.get('strategy_config') or {})}
        if not cfg.get('halving_model_enabled'):
            return True, ''
        d = get_klines(symbol, tf, 650 if tf in ('5min', '15min', '1hour') else 200)
        if d is None or d.empty:
            return True, ''
        ind = calculate_indicators(d)
        if ind is None or len(ind) < 100:
            return True, ''
        if live is None:
            try:
                live = latest_price(symbol)
                live = float(live) if live else None
            except Exception:
                live = None
        _ok, _t = pd_level_guard_df(ind, sig, live, cfg)
        if not _ok and _t:
            _t = str(_t) + _btc_gate_key_line('gate_pd_level_enabled')
            _block_simple_register(_t, 'قیمت الان نزدیک یک نقطه‌ی مهم دیروز است و هنوز واکنشش مشخص نیست؛ در این شرایط ورود به معامله مجاز نیست. لطفاً صبور باشید.')
        return _ok, _t
    except Exception:
        logger.exception('pd level gate failed symbol=%s', symbol)
        return True, ''


def _fav_confirm_active(chat_id):
    return bool(get_session(chat_id).get('fav_confirm_enabled', False))


def _fav_confirm_hold(chat_id, symbol, sig, plan, entry, sl, tp, full_reason):
    """True = سیگنال در صف «صبر برای تایید» نگه داشته شد (ورود فعلاً انجام نمی‌شود)."""
    s = get_session(chat_id)
    if not s.get('fav_confirm_enabled', False):
        return False
    now = time.time()
    _tag, level_token, level_value = extract_setup_level(full_reason)
    seen_key = f"{symbol}|{sig}|{level_token}|{level_value}"
    waits = s.setdefault('fav_wait', {})
    try:
        _tid_now = _fn_current_tid()
    except Exception:
        _tid_now = None
    for r in waits.values():
        if r.get('symbol') == symbol and r.get('sig') == sig and r.get('status') == 'waiting':
            return True
    seen = s.setdefault('fav_wait_seen', {})
    if now - float(seen.get(seen_key, 0) or 0) < ASSIST_SEEN_TTL_SECONDS:
        return True
    mn, _mx_fixed, wt = _fav_cfg(s)
    mx = _fav_effective_max_r(s, entry, sl, tp)        # سقف مخصوص همین نماد/سیگنال
    tf = s.get('timeframe', '5min')
    rid = hashlib.sha1(f"fav{chat_id}{symbol}{now}".encode()).hexdigest()[:8]
    waits[rid] = {'id': rid, 'symbol': symbol, 'sig': sig, 'side_label': 'BUY (Long)' if sig == 'BUY' else 'SELL (Short)',
                  'entry': float(entry), 'sl': float(sl), 'tp': float(tp), 'reason': full_reason, 'tf': tf,
                  'structural_tp': bool(plan.get('structural_target', False)), 'score': plan.get('score'), 'rr': plan.get('rr'),
                  'quality_label': plan.get('quality_label'), 'tp_level_name': plan.get('tp_level_name'),
                  'tp_stages': plan.get('tp_stages'), 'min_r': mn, 'max_r': mx, 'max_mode': _fav_max_mode(s),
                  'created_at': now, 'expires_at': now + wt, 'last_eval_ts': 0.0, 'status': 'waiting',
                  'tid': _tid_now}
    seen[seen_key] = now
    try:
        _fn_fav_queued(chat_id, waits[rid])
    except Exception:
        logger.debug('funnel fav_queued failed', exc_info=True)
    for k in sorted(waits.keys(), key=lambda kk: float(waits[kk].get('created_at', 0) or 0)):   # سقف ۳۰۰ رکورد؛ قدیمی‌های تعیین‌تکلیف‌شده اول حذف می‌شوند
        if len(waits) <= 300:
            break
        if waits[k].get('status') != 'waiting' and waits[k].get('shadow_done'):
            waits.pop(k, None)
    save_session(chat_id)
    logger.info('fav confirm: queued %s %s entry=%s wait=%ss min=%sR max=%.2fR (%s)', symbol, sig, entry, wt, mn, mx, _fav_max_mode(s))
    return True


def _fav_finish(chat_id, s, rec, status, text):
    rec['status'] = status
    # علت پایان برای آمار: منقضی = یا «مهلت تمام شد» (timeout) یا «قیمت از سقف گذشت» (overrun)
    rec['why'] = ('btc' if rec.get('btc_blocked') else ('front' if rec.get('front_blocked') else ('pdlevel' if rec.get('pd_blocked') else ('regime' if rec.get('regime_blocked') else ('overrun' if rec.get('overran') else 'timeout'))))) if status == 'expired' else status
    rec[f'{status}_at'] = time.time()
    try:
        _fn_fav_final(chat_id, rec, status)
    except Exception:
        pass
    save_session(chat_id)
    _fav_update_card(chat_id, rec, force=True)          # V3.44.26: کارت مستقل این سیگنال درجا «پایان» می‌شود و دکمه‌هایش برداشته می‌شود
    logger.info('fav confirm: %s %s -> %s | %s', rec.get('symbol'), rec.get('sig'), status, text)      # بی‌صدا: فقط لاگ


FAV_REVERSE_TO_TOUCH = os.environ.get('FAV_REVERSE_TO_TOUCH', '1') != '0'
_FAV_FLIP_TAG = '🔁 معکوس‌شده از صف تایید حرکت'


def _fav_flip_to_touch(chat_id, s, rec, px=None, require_adverse=True):
    """V3.44.23: سیگنالی که در «صف تایید حرکت» رد شد (قیمت خلاف جهت رفت، یا تا پایان مهلت به نفع معامله حرکت نکرد)
    حذف نمی‌شود؛ در جهت مخالف وارد «📋 سیگنال‌های در انتظار» (رأی‌گیری فیلترها) می‌شود تا از اول بررسی شود.
    require_adverse=True: فقط وقتی قیمت px واقعاً خلاف جهت سیگنال بوده (نه رسیدن به TP). هر سیگنال فقط یک بار برمی‌گردد (ping-pong نداریم).
    بسته به تایید فیلترها همان مسیر عادی ادامه می‌یابد: ورود خودکار / صف تایید حرکت / کارت دستیار / ورود سریع دستی. True = ثبت شد."""
    if not FAV_REVERSE_TO_TOUCH:
        return False
    reason = str(rec.get('reason') or '')
    if rec.get('flipped') or _FAV_FLIP_TAG in reason:
        return False
    sig = rec.get('sig')
    if sig not in ('BUY', 'SELL'):
        return False
    if require_adverse:
        try:
            x = _fav_move_r(sig, rec['entry'], rec['sl'], px) if px else None
        except Exception:
            x = None
        if x is None or x >= 0:
            return False
    opp = 'SELL' if sig == 'BUY' else 'BUY'
    try:
        rec['flipped'] = True
        status, txt = _touch_register(chat_id, rec['symbol'], opp, f"{_FAV_FLIP_TAG} | {reason}", rec.get('tf') or '5min', flip_from=sig)
        rec['flip_status'] = status
        logger.info('fav confirm: %s %s rejected -> touch list %s (%s: %s)', rec['symbol'], sig, opp, status, txt)
        return status in ('touch_wait', 'assist_card', 'fav_wait', 'entry_opened')
    except Exception:
        logger.exception('fav confirm: flip to touch failed symbol=%s', rec.get('symbol'))
        return False


def _fav_process_one(chat_id, s, rec):
    """V3.44.72: پوشش ثبت قیف؛ tid صف به معاملهٔ بازشده وصل می‌شود."""
    try:
        _FN_TLS.tid = rec.get('tid') or rec.get('id')
    except Exception:
        pass
    try:
        return _fav_process_one_core(chat_id, s, rec)
    finally:
        try:
            _FN_TLS.tid = None
        except Exception:
            pass


def _fav_process_one_core(chat_id, s, rec):
    symbol, sig = rec['symbol'], rec['sig']
    now = time.time()
    side_txt = 'خرید' if sig == 'BUY' else 'فروش'
    if any(p.get('symbol') == symbol for p in s.get('paper_positions', [])):
        return _fav_finish(chat_id, s, rec, 'skipped', f"ℹ️ صف تایید `{symbol}` لغو شد: همین حالا پوزیشن باز روی این نماد وجود دارد.")
    tf = rec.get('tf') or '5min'
    ev_tf = _fav_eval_tf(s, tf)                 # V3.44.95: تایم‌فریم کندلِ ارزیابی (کلید «خروج سریع‌تر»: ۵ دقیقه)
    tf_s = _TF_SECONDS.get(ev_tf, 300)          # فقط برای برگرداندنِ last_eval_ts (دوباره‌سنجی همان کندل در تیک بعد)
    rec['eval_tf'] = ev_tf
    try:
        live = exchange_latest_price(chat_id, symbol) if s.get('trading_mode') == 'REAL' else latest_price(symbol)
        live = float(live) if live else None
    except Exception:
        live = None
    # لغو فوری اگر قیمت لحظه‌ای به SL/TP رسید یا خیلی خلاف جهت رفت
    if live:
        d_live = _fav_decide(sig, rec['entry'], rec['sl'], rec['tp'], live, rec['min_r'], rec['max_r'])
        if d_live == 'cancel':
            try:                                    # V3.44.107: فقط برای ثبت قیف
                rec['cancel_kind'] = 'live'
                _cr = _fav_move_r(sig, rec['entry'], rec['sl'], live)
                rec['cancel_r'] = None if _cr is None else round(float(_cr), 3)
            except Exception:
                pass
            _fav_flip_to_touch(chat_id, s, rec, live)
            return _fav_finish(chat_id, s, rec, 'cancelled', f"🚫 سیگنال `{symbol}` ({side_txt}) لغو شد: قیمت خلاف جهت رفت یا به SL/TP رسید؛ بدون ورود.")
    # ارزیابی روی کلوز کندل‌های بسته‌شده‌ی بعد از سیگنال (فقط کندل‌های جدید)
    decision, close_px = 'wait', None
    try:
        df = get_klines(symbol, ev_tf, 30)
        if df is not None and len(df) >= 3:
            closed = df.iloc[:-1]            # آخرین ردیف کندل در حال تشکیل است
            for _, row in closed.iterrows():
                ts = float(row['timestamp'])
                if ts > 1e11:
                    ts /= 1000.0
                if ts < rec['created_at'] - 90 or ts <= float(rec.get('last_eval_ts', 0) or 0):
                    continue          # کندل قبل از سیگنال (با ۹۰ ثانیه تلورانس) یا قبلاً بررسی‌شده
                rec['last_eval_ts'] = ts
                close_px = float(row['close'])
                decision = _fav_decide(sig, rec['entry'], rec['sl'], rec['tp'], close_px, rec['min_r'], rec['max_r'])
                try:                                    # V3.44.82: فقط برای ثبت قیف (تاثیری روی تصمیم ندارد)
                    rec['eval_n'] = int(rec.get('eval_n', 0) or 0) + 1
                    _lx = _fav_move_r(sig, rec['entry'], rec['sl'], close_px)
                    rec['last_x'] = None if _lx is None else round(float(_lx), 3)
                except Exception:
                    pass
                if decision == 'overrun':
                    rec['overran'] = True       # از سقف گذشت؛ سیگنال نمی‌میرد و تا پایان مهلت منتظر برگشت (پولبک) به محدوده می‌ماند
                    continue
                if decision != 'wait':
                    break
    except Exception:
        logger.exception('fav confirm: candle eval failed symbol=%s', symbol)
    if decision == 'cancel':
        rec['cancel_kind'] = 'close'                # V3.44.107: فقط برای ثبت قیف (R لغو = last_x)
        _fav_flip_to_touch(chat_id, s, rec, close_px or live)
        return _fav_finish(chat_id, s, rec, 'cancelled', f"🚫 سیگنال `{symbol}` ({side_txt}) لغو شد: کلوز کندل خلاف جهت یا به SL/TP رسید؛ بدون ورود.")
    if decision == 'confirm':
        # قیمت لحظه‌ای هم باید هنوز در محدوده‌ی مجاز باشد
        x_live = _fav_move_r(sig, rec['entry'], rec['sl'], live) if live else None
        if x_live is None or x_live < 0 or x_live > rec['max_r']:
            if x_live is not None and x_live > rec['max_r']:
                rec['overran'] = True           # بعد از تایید قیمت لحظه‌ای از سقف رد شد؛ منتظر برگشت می‌مانیم
            if now >= float(rec.get('expires_at', 0)):
                if x_live is not None and x_live < 0:
                    _fav_flip_to_touch(chat_id, s, rec, live)
                return _fav_finish(chat_id, s, rec, 'expired', f"⌛ مهلت صبر `{symbol}` ({side_txt}) تمام شد؛ تایید برقرار بود ولی قیمت لحظه‌ای دیگر در محدوده نبود؛ بدون ورود.")
            rec['last_eval_ts'] = float(rec.get('last_eval_ts', 0) or 0) - tf_s     # همین کندل در تیک بعدی دوباره با قیمت لحظه‌ای سنجیده می‌شود
            save_session(chat_id)
            return
        if gate_on(s, 'gate_final_regime_enabled'):
            # V3.44.31: آخرین مرحله‌ی خروج از صف: رژیم بازار باید به نفع معامله باشد؛ وگرنه در صف می‌ماند و تیک بعدی دوباره سنجیده می‌شود.
            reg_ok, reg_txt = _final_regime_check(tf, sig)
            if not reg_ok:
                rec['regime_blocked'] = True; rec['regime_hold'] = reg_txt; _fn_hold_tick(rec, 'regime')
                if now >= float(rec.get('expires_at', 0)):
                    return _fav_finish(chat_id, s, rec, 'expired', f"⌛ مهلت صبر `{symbol}` ({side_txt}) تمام شد؛ تایید حرکت برقرار بود ولی {reg_txt}؛ بدون ورود.")
                rec['last_eval_ts'] = float(rec.get('last_eval_ts', 0) or 0) - tf_s     # همین کندل در تیک بعدی دوباره سنجیده می‌شود
                save_session(chat_id)
                return
            rec.pop('regime_blocked', None); rec.pop('regime_hold', None)
        if gate_on(s, 'gate_pd_level_enabled'):
            # V3.44.58: آخرین مرحله‌ی خروج از صف: سقف/کف دیروز (PDH/PDL) نباید جلوی معامله باشد و قیمت نباید تازه از آن برگشته باشد؛ وگرنه سیگنال در صف می‌ماند.
            pd_ok, pd_txt = _pd_level_gate(s, symbol, sig, tf, live)
            if not pd_ok:
                rec['pd_blocked'] = True; rec['pd_hold'] = pd_txt; _fn_hold_tick(rec, 'pd')
                if now >= float(rec.get('expires_at', 0)):
                    return _fav_finish(chat_id, s, rec, 'expired', f"⌛ مهلت صبر `{symbol}` ({side_txt}) تمام شد؛ تایید حرکت برقرار بود ولی {pd_txt}؛ بدون ورود.")
                rec['last_eval_ts'] = float(rec.get('last_eval_ts', 0) or 0) - tf_s     # همین کندل در تیک بعدی دوباره سنجیده می‌شود
                save_session(chat_id)
                return
            rec.pop('pd_blocked', None); rec.pop('pd_hold', None)
        _ff, _fc = _btc_front_flags(s)
        if _ff or _fc:
            # V3.44.44: آخرین مرحله‌ی خروج از صف: فاصله‌ی کلوز BTC تا سطح جلویی باید معقول باشد؛ وگرنه هشدار ورود می‌آید و سیگنال (رد نمی‌شود) در صف می‌ماند.
            # V3.44.55: کلید مستقل «BTC کلاف دور سطح» هم از همین مرحله می‌گذرد.
            fl_ok, fl_txt = _btc_front_gate(chat_id, s, symbol, sig, tf, front=_ff, chop=_fc)
            if not fl_ok:
                rec['front_blocked'] = True; rec['front_hold'] = fl_txt; _fn_hold_tick(rec, 'front', fl_txt)
                if now >= float(rec.get('expires_at', 0)):
                    return _fav_finish(chat_id, s, rec, 'expired', f"⌛ مهلت صبر `{symbol}` ({side_txt}) تمام شد؛ تایید حرکت برقرار بود ولی {fl_txt}؛ بدون ورود.")
                rec['last_eval_ts'] = float(rec.get('last_eval_ts', 0) or 0) - tf_s     # همین کندل در تیک بعدی دوباره سنجیده می‌شود
                save_session(chat_id)
                return
            rec.pop('front_blocked', None); rec.pop('front_hold', None)
        if gate_on(s, 'gate_btc_candle_enabled') and not s.get('assist_mode_enabled'):
            # V3.44.42: ورود خودکار باید با کندل در حال تشکیل BTC هم‌جهت باشد؛ وگرنه در صف می‌ماند و تیک بعدی دوباره سنجیده می‌شود.
            # (در حالت دستیار کارت ساخته می‌شود و ورودِ دستیِ کارت در execute_trade رد می‌شود.)
            try:
                btc_ok, btc_txt = btc_candle_verdict(tf, sig)
            except Exception:
                logger.exception('fav confirm: btc candle check failed symbol=%s', symbol)
                btc_ok, btc_txt = False, f'{_BTC_CANDLE_BLOCK_PREFIX}: خطا در بررسی کندل'
            if not btc_ok:
                rec['btc_blocked'] = True; rec['btc_hold'] = btc_txt; _fn_hold_tick(rec, 'btc')
                if now >= float(rec.get('expires_at', 0)):
                    return _fav_finish(chat_id, s, rec, 'expired', f"⌛ مهلت صبر `{symbol}` ({side_txt}) تمام شد؛ تایید حرکت برقرار بود ولی {btc_txt}؛ بدون ورود.")
                rec['last_eval_ts'] = float(rec.get('last_eval_ts', 0) or 0) - tf_s     # همین کندل در تیک بعدی دوباره سنجیده می‌شود
                save_session(chat_id)
                return
            rec.pop('btc_blocked', None); rec.pop('btc_hold', None)
        rec['confirmed_at'] = now; rec['confirm_px'] = float(live)
        p_stub = {'structural_target': rec.get('structural_tp'), 'score': rec.get('score'), 'rr': rec.get('rr'),
                  'quality_label': rec.get('quality_label'), 'tp_level_name': rec.get('tp_level_name'), 'tp_stages': rec.get('tp_stages')}
        if s.get('assist_mode_enabled'):
            # حالت دستیار: همان کارت همیشگی (✅ ورود / ❌ رد) حالا نمایش داده می‌شود؛ ورودِ کارت = قیمت لحظه‌ی تایید، SL/TP همان سیگنال.
            try:
                df_card = get_klines(symbol, tf, 200)
            except Exception:
                df_card = None
            plan_card = dict(p_stub); plan_card['rr'] = None
            res = _assist_queue_signal(chat_id, symbol, sig, plan_card, float(live), rec['sl'], rec['tp'], rec['reason'],
                                       df=(df_card if (df_card is not None and len(df_card)) else None))
            return _fav_finish(chat_id, s, rec, 'card_sent', f"تایید برقرار شد ({x_live:+.2f}R)؛ کارت دستیار ارسال شد: {res}")
        try:
            held = _auto_trend_gate(chat_id, symbol, sig, p_stub, rec['entry'], rec['sl'], rec['tp'], rec['reason'])
        except Exception:
            logger.exception('fav confirm: trend gate failed symbol=%s', symbol)
            held = False
        if held:
            return _fav_finish(chat_id, s, rec, 'handed_to_warning', 'تایید برقرار شد؛ کارت هشدار ورود فرستاده شد')
        ok = execute_trade(chat_id, symbol, rec['side_label'], rec['entry'], rec['sl'], rec['tp'], rec['reason'],
                           structural_tp=rec.get('structural_tp', False), plan_score=rec.get('score'), plan_rr=rec.get('rr'),
                           plan_quality_label=rec.get('quality_label'), bypass_burst_cooldown=True,
                           tp_level_name=rec.get('tp_level_name'), tp_stages=rec.get('tp_stages'), keep_levels=True)
        s = get_session(chat_id)
        if ok:
            return _fav_finish(chat_id, s, rec, 'opened', f"تایید برقرار شد ({x_live:+.2f}R)؛ معامله باز شد")
        detail = _LAST_BLOCK_REASON.pop(chat_id, None) or 'ورود رد شد'
        return _fav_finish(chat_id, s, rec, 'blocked', f"ورود بعد از تایید باز نشد: {detail}")
    if now >= float(rec.get('expires_at', 0)):
        if not rec.get('overran') and not rec.get('regime_blocked') and not rec.get('btc_blocked') and not rec.get('front_blocked') and not rec.get('pd_blocked'):          # ورود دیرهنگام (قیمت به نفع سیگنال از سقف گذشته) یا مسدود‌شده با رژیم برعکس نمی‌شود؛ فقط «حرکت نکرد» برعکس می‌شود
            _fav_flip_to_touch(chat_id, s, rec, live, require_adverse=False)
        why_txt = ('کندل BTC تا پایان مهلت هم‌جهت معامله نشد' if rec.get('btc_blocked') else 'فاصله‌ی BTC تا سطح جلویی تا پایان مهلت معقول نشد' if rec.get('front_blocked') else 'سقف/کف دیروز تا پایان مهلت جلوی معامله ماند یا واکنش قیمت به آن مشخص نشد' if rec.get('pd_blocked') else 'رژیم بازار تا پایان مهلت به نفع معامله نشد' if rec.get('regime_blocked') else
                   ('قیمت از سقف گذشت و تا پایان مهلت به محدوده برنگشت' if rec.get('overran') else 'تایید نگرفت'))
        return _fav_finish(chat_id, s, rec, 'expired', f"⌛ مهلت صبر `{symbol}` ({side_txt}) تمام شد و {why_txt}؛ بدون ورود.")
    save_session(chat_id)


FAV_CARDS_PER_LIST = 8     # V3.44.26: هر سیگنال صف تایید حرکت یک پیامِ مستقل با دکمه‌های خودش است؛ حداکثر این‌قدر (جدیدترین پایین چت)
_FAV_FINAL_TXT = {'opened': '✅ بعد از تایید حرکت، معامله باز شد.', 'card_sent': '🤝 حرکت تایید شد و کارت دستیار (✅ ورود / ❌ رد) برایتان آمد.',
                  'handed_to_warning': '⚠️ حرکت تایید شد و کارت هشدار ورود برایتان آمد.', 'expired': '⌛ مهلت تمام شد؛ ورودی انجام نشد.',
                  'cancelled': '🚫 لغو شد: قیمت خلاف جهت رفت یا به SL/TP رسید.', 'skipped': '⏭ روی این نماد پوزیشن باز شد؛ از صف خارج شد.',
                  'blocked': '⛔ بعد از تایید، ورود توسط محدودیت‌ها رد شد.', 'entered_manual': '✅ با ورود سریع دستی وارد شدید.',
                  'rejected': '❌ شما این سیگنال را رد کردید؛ ورودی انجام نشد.'}


def _fav_card_payload(r, now=None):
    """متن + کیبورد پیامِ مستقلِ هر سیگنال صف تایید حرکت: ⚡ ورود سریع و 📈 TradingView کنار هم، زیر همان نماد."""
    now = now or time.time()
    s = None
    is_long = r['sig'] == 'BUY'
    tf = r.get('tf') or '5min'
    try:
        live = latest_price(r['symbol'])
    except Exception:
        live = None
    x = _fav_move_r(r['sig'], r['entry'], r['sl'], live) if live else None
    rem = max(0, int((float(r.get('expires_at', 0) or 0) - now + 59) // 60))
    if x is None:
        r_txt, hint = 'قیمت نامشخص', ''
    else:
        r_txt = f"`{x:+.2f}R`"
        hint = ' ✅ در محدوده' if (r['min_r'] <= x <= r['max_r']) else (' ⚠️ فعلاً از سقف گذشته؛ منتظر برگشت' if x > r['max_r'] else (' ⛔ خلاف جهت' if x <= -FAV_CONFIRM_CANCEL_R else ' · منتظر حرکت'))
    left = f" · ⏳ {rem} دقیقه" if r.get('status') == 'waiting' else ''
    star = '⭐ ' if (x is not None and r.get('status') == 'waiting' and r['min_r'] <= x <= r['max_r']) else ''      # V3.44.41: ⭐ = الان در محدوده
    lines = [f'{star}⏳ *صف تایید حرکت*',
             f"`{r['symbol']}` {'🟢 خرید' if is_long else '🔴 فروش'} · {TF_DISPLAY.get(tf, tf)}{left}",
             f"    ورود `{fmt(float(r['entry']))}` | الان {r_txt}{hint}"]
    if r.get('max_mode') == 'tp':
        lines.append(f"    سقف این نماد: `+{float(r['max_r']):.2f}R`")
    if r.get('regime_hold') and r.get('status') == 'waiting':
        lines.append(f"    🧭 {r['regime_hold']}")
    if r.get('btc_hold') and r.get('status') == 'waiting':
        lines.append(f"    ₿ {r['btc_hold']}")
    if r.get('front_hold') and r.get('status') == 'waiting':
        lines.append(f"    📏 {r['front_hold']}")
    if r.get('status') != 'waiting':
        lines += ['', _FAV_FINAL_TXT.get(r.get('status'), 'پایان') + (' 🔁 در جهت مخالف به «📋 سیگنال‌های در انتظار» رفت.' if r.get('flipped') and r.get('flip_status') in ('touch_wait', 'assist_card', 'fav_wait', 'entry_opened') else '')]
        return '\n'.join(lines), {'inline_keyboard': []}
    lines += ['', ('تایید فقط روی کلوز کندل بسته‌شده‌ی ۵ دقیقه‌ای انجام می‌شود.' if (r.get('eval_tf') == '5min' and tf != '5min') else ('تایید فقط روی کلوز کندل بسته‌شده‌ی ۱۵ دقیقه‌ای انجام می‌شود.' if (r.get('eval_tf') == '15min' and tf != '15min') else 'تایید فقط روی کلوز کندل بسته‌شده انجام می‌شود.'))]
    rid, sym = r['id'], r['symbol']
    row1 = [{'text': f"⚡ ورود سریع {sym} {'🟢 خرید' if is_long else '🔴 فروش'}", 'callback_data': f"/fq_qe_{'buy' if is_long else 'sell'}_{rid}"}]
    try:
        row1.append({'text': '📈 TradingView', 'url': tradingview_chart_url(sym, tf)})
    except Exception:
        logger.exception('fav queue: tradingview url failed symbol=%s', sym)
    row2 = []
    try:
        mini = miniapp_chart_url(sym, tf)
    except Exception:
        mini = None
    if mini:
        row2.append({'text': '🌐 چارت تعاملی', 'web_app': {'url': mini}})
    # V3.44.30: «🔄 بروزرسانی» و «⏳ تمدید مهلت» کنار هم در یک ردیف؛ چارت تعاملی (اگر باشد) ردیف جدا
    row3 = [{'text': '🔄 بروزرسانی', 'callback_data': f"/fq_ref_{rid}"},
            {'text': f"⏳ تمدید (+{FAV_EXTEND_SECONDS // 60} دقیقه)", 'callback_data': f"/fq_ext_{rid}"}]
    # V3.44.38: رد دستی سیگنال (ردیف جدا)
    # V3.44.39: کنارش «🔍 فیلترها»: نتیجه‌ی لحظه‌ای فیلترهای روشن به‌صورت پنجره‌ی بازشو (فقط نمایش؛ هیچ اثری روی صف ندارد)
    row4 = [{'text': '❌ رد سیگنال', 'callback_data': f"/fq_rej_{rid}"},
            {'text': '🔍 فیلترها', 'callback_data': f"/fq_flt_{rid}"}]
    return '\n'.join(lines), {'inline_keyboard': [r_ for r_ in (row1, row2, row3, row4) if r_]}


def _fav_send_card(chat_id, rec):
    """کارت مستقل این سیگنال را (جدید، پایین چت) می‌فرستد؛ کارت قبلیِ همین سیگنال حذف می‌شود تا تکراری نشود."""
    if not is_allowed(chat_id):
        return False
    old = rec.get('fq_msg_id')
    if old:
        tg('deleteMessage', {'chat_id': chat_id, 'message_id': old}, 10)
        rec['fq_msg_id'] = None
    text, markup = _fav_card_payload(rec)
    res = tg('sendMessage', {'chat_id': chat_id, 'text': text, 'reply_markup': markup, 'parse_mode': 'Markdown'}, 10)
    if res and res.get('ok'):
        rec['fq_msg_id'] = (res.get('result') or {}).get('message_id')
        return True
    return False


def _fav_update_card(chat_id, rec, force=True):
    """کارت همین سیگنال را درجا ویرایش می‌کند (وقتی تمام شد دکمه‌ها برداشته می‌شوند). هر خطایی بی‌صدا رد می‌شود."""
    try:
        mid = rec.get('fq_msg_id')
        if not mid or not is_allowed(chat_id):
            return False
        text, markup = _fav_card_payload(rec)
        res = tg('editMessageText', {'chat_id': chat_id, 'message_id': mid, 'text': text, 'reply_markup': markup, 'parse_mode': 'Markdown'}, 10)
        return bool(res and res.get('ok'))
    except Exception:
        logger.exception('fav card update failed symbol=%s', rec.get('symbol'))
        return False


def fav_card_refresh(chat_id, rid):
    """دکمه‌ی 🔄 زیر هر کارت: فقط همان کارت با قیمت لحظه‌ای تازه ویرایش می‌شود."""
    s = get_session(chat_id)
    rec = (s.get('fav_wait') or {}).get(rid)
    if not rec:
        send_message(chat_id, 'ℹ️ این مورد دیگر در صف نیست.'); return
    ctx = getattr(_CB_CTX, 'data', None)
    if ctx and ctx.get('chat_id') == chat_id and ctx.get('message_id'):
        rec['fq_msg_id'] = ctx['message_id']
        ctx['used'] = True
    _fav_update_card(chat_id, rec, force=True)
    save_session(chat_id)


def fav_extend(chat_id, rid):
    """V3.44.27: دکمه‌ی ⏳ تمدید مهلت زیر هر کارت صف تایید حرکت: با هر لمس ۳۰ دقیقه به مهلت همان سیگنال اضافه می‌شود
    (از زمان باقی‌مانده‌ی فعلی؛ لمس‌های پشت‌سرهم جمع می‌شوند). فقط همان کارت درجا ویرایش می‌شود."""
    s = get_session(chat_id)
    rec = (s.get('fav_wait') or {}).get(rid)
    if not rec or rec.get('status') != 'waiting':
        send_message(chat_id, 'ℹ️ این مورد دیگر در صف نیست.'); return
    now = time.time()
    rec['expires_at'] = max(float(rec.get('expires_at', 0) or 0), now) + FAV_EXTEND_SECONDS
    rec['ext'] = int(rec.get('ext', 0) or 0) + 1
    ctx = getattr(_CB_CTX, 'data', None)
    if ctx and ctx.get('chat_id') == chat_id and ctx.get('message_id'):
        rec['fq_msg_id'] = ctx['message_id']
        ctx['used'] = True
    _fav_update_card(chat_id, rec, force=True)
    save_session(chat_id)
    logger.info('fav confirm: extended %s %s +%ss (ext=%s)', rec.get('symbol'), rec.get('sig'), FAV_EXTEND_SECONDS, rec['ext'])


def fav_reject(chat_id, rid):
    """V3.44.38: دکمه‌ی ❌ رد سیگنال زیر کارت صف تایید حرکت: کاربر دستی سیگنال را رد می‌کند؛ از صف خارج می‌شود، ورودی انجام نمی‌شود
    و در جهت مخالف هم دوباره بررسی نمی‌شود (تصمیم کاربر است). در «آمار فیلتر» هم حساب نمی‌شود چون تصمیم فیلتر نبوده."""
    s = get_session(chat_id)
    rec = (s.get('fav_wait') or {}).get(rid)
    if not rec or rec.get('status') != 'waiting':
        send_message(chat_id, 'ℹ️ این مورد دیگر در صف نیست.'); return
    rec['manual_rejected'] = True
    ctx = getattr(_CB_CTX, 'data', None)
    if ctx and ctx.get('chat_id') == chat_id and ctx.get('message_id'):
        rec['fq_msg_id'] = ctx['message_id']
        ctx['used'] = True
    _fav_finish(chat_id, s, rec, 'rejected', f"❌ {rec.get('symbol')} ({rec.get('sig')}) به‌صورت دستی توسط کاربر رد شد")


def _tg_len(text):
    """طول متن به شیوه‌ی تلگرام (واحد UTF-16؛ ایموجی‌های بزرگ ۲ حساب می‌شوند)."""
    return len(str(text).encode('utf-16-le')) // 2


FAV_FLT_POPUP_MAX = 200     # V3.44.39: سقف تلگرام برای متن پنجره‌ی بازشو (answerCallbackQuery)
_FAV_FLT_SHORT = {'btceth': 'BTC/ETH', 'h4': '۴س', 'tf': '۵/۱۵', 'rsi': 'RSI', 'macd': 'MACD', 'adx': 'ADX',
                  'vol': 'حجم', 'level': 'سطح', 'ylevel': 'دیروز', 'btcpat': 'الگوی BTC', 'btcside': 'سمت BTC', 'symreg': 'رژیم نماد'}


def _fav_flt_mark(vote, sig):
    if vote == 'OK' or vote == sig:
        return '✅'
    if vote in ('BUY', 'SELL'):
        return '❌'
    return '⏳'


def _fav_flt_val(v):
    """مقدار کوتاهِ فیلترهای عددی برای پنجره‌ی بازشو (برای بقیه خالی)."""
    d = str(v.get('detail') or '')
    k = v.get('key')
    if k == 'rsi':
        return d if d and d != 'داده نیست' else ''
    if k == 'macd':
        return d if d in ('مثبت', 'منفی') else ''
    if k == 'adx':
        return d.replace('ADX ', '') if d.startswith('ADX ') else ''
    if k == 'vol':
        return d.split(' (')[0] if d and d != 'داده نیست' else ''
    return ''


def _fav_flt_build(rec, votes, live, last_close_r, reg_line, rem_min, tier):
    """متن پنجره‌ی بازشو در چند «سطح جزئیات»؛ هرچه tier بیشتر، فشرده‌تر. (tier 0 = کامل‌ترین)"""
    sig = rec['sig']
    x = _fav_move_r(sig, rec['entry'], rec['sl'], live) if live else None
    side = 'خرید' if sig == 'BUY' else 'فروش'
    head = f"🔍 {rec['symbol']} {side}" + (f" · ⏳{rem_min}د" if tier == 0 else '')
    lines = [head]
    mn, mx = float(rec['min_r']), float(rec['max_r'])
    if x is None:
        lines.append('حرکت: قیمت نامشخص')
    else:
        if mn <= x <= mx:
            mk = '✅'
        elif x > mx:
            mk = '⚠️'
        elif x <= -FAV_CONFIRM_CANCEL_R:
            mk = '⛔'
        else:
            mk = '⏳'
        lines.append(f"حرکت: {x:+.2f}R {mk}" + (f" (لازم {mn:+.2f} تا {mx:+.2f})" if tier <= 1 else ''))
    if tier == 0 and last_close_r is not None:
        lm = '✅' if mn <= last_close_r <= mx else '⏳'
        lines.append(f"کلوز آخر: {last_close_r:+.2f}R {lm}")
    if reg_line:
        lines.append(reg_line)
    parts = []
    for v in votes:
        nm = _FAV_FLT_SHORT.get(v['key'], v['key'])
        val = _fav_flt_val(v) if tier <= 1 else ''
        parts.append(f"{nm}{(' ' + val) if val else ''} {_fav_flt_mark(v['vote'], sig)}")
    if parts:
        lines.append(' '.join(parts) if tier >= 1 else ' · '.join(parts))
    elif not reg_line:
        lines.append('فیلتر دیگری روشن نیست')
    return '\n'.join(lines)


def fav_filters_popup(chat_id, rid):
    """V3.44.39: دکمه‌ی 🔍 فیلترها زیر کارت صف تایید حرکت: نتیجه‌ی «لحظه‌ای» فیلترهای روشن همین سیگنال (بدون ذخیره، بدون اثر روی صف).
    ✅ هم‌جهت با سیگنال | ❌ مخالف | ⏳ خنثی/منتظر. متن پنجره‌ی بازشو در تلگرام حداکثر ۲۰۰ کاراکتر است؛ اگر جزئیات جا نشد
    به‌تدریج فشرده‌تر می‌شود (اول حذف «کلوز آخر»، بعد مقدارهای عددی)."""
    s = get_session(chat_id)
    rec = (s.get('fav_wait') or {}).get(rid)
    if not rec or rec.get('status') != 'waiting':
        return 'ℹ️ این مورد دیگر در صف نیست.'
    try:
        sym, sig = rec['symbol'], rec['sig']
        tf = rec.get('tf') or '5min'
        try:
            live = exchange_latest_price(chat_id, sym) if s.get('trading_mode') == 'REAL' else latest_price(sym)
            live = float(live) if live else None
        except Exception:
            live = None
        keys = _touch_enabled_keys(s)
        votes = _touch_votes(sym, tf, rec.get('reason') or '', keys, cfg=s.get('strategy_config')) if keys else []
        try:
            if votes and _contra_active(s, rec.get('scn'), sig if gate_on(s, 'gate_touch_dir_fixed_enabled') else None):
                votes = _contra_flip_votes(votes)       # V3.44.88: همان رأی برگشتِ رأی‌گیری (هیچ خطایی نباید پنجره را خراب کند)
        except Exception:
            logger.debug('contra popup flip failed', exc_info=True)
        reg_line = ''
        if gate_on(s, 'gate_final_regime_enabled'):
            reg_ok, _t = _final_regime_check(tf, sig)
            gate = (TIMEFRAME_REGIME_CACHE.get(_tfk(tf)) or {}).get('gate')
            reg_fa = {'BULLISH': 'صعودی', 'BEARISH': 'نزولی', 'RANGE': 'رنج'}.get(gate, 'نامشخص')
            reg_line = f"🧭 رژیم {TF_DISPLAY.get(tf, tf)}: {reg_fa} {'✅' if reg_ok else '❌'}"
        last_close_r = None
        try:
            df = get_klines(sym, _fav_eval_tf(s, tf), 30)
            if df is not None and len(df) >= 3:
                row = df.iloc[-2]          # آخرین کندل بسته‌شده
                ts = float(row['timestamp'])
                if ts > 1e11:
                    ts /= 1000.0
                if ts >= float(rec.get('created_at', 0) or 0) - 90:
                    last_close_r = _fav_move_r(sig, rec['entry'], rec['sl'], float(row['close']))
        except Exception:
            logger.exception('fav filters popup: last close failed symbol=%s', sym)
        rem = max(0, int((float(rec.get('expires_at', 0) or 0) - time.time() + 59) // 60))
        txt = ''
        for tier in range(4):
            txt = _fav_flt_build(rec, votes, live, last_close_r, reg_line, rem, tier)
            if _tg_len(txt) <= FAV_FLT_POPUP_MAX:
                return txt
        while _tg_len(txt) > FAV_FLT_POPUP_MAX - 1:       # آخرین چاره: بریدن (نباید پیش بیاید)
            txt = txt[:-1]
        return txt + '…'
    except Exception:
        logger.exception('fav filters popup failed rid=%s', rid)
        return '⚠️ بررسی فیلترها انجام نشد؛ کمی بعد دوباره امتحان کنید.'


def fav_quick_entry(chat_id, rid, side):
    """دکمه‌ی ⚡ ورود سریع زیر هر سیگنال صف تایید حرکت (بدون صبر برای تایید؛ با قیمت لحظه‌ای)."""
    s = get_session(chat_id)
    rec = (s.get('fav_wait') or {}).get(rid)
    if not rec or rec.get('status') != 'waiting':
        send_message(chat_id, 'ℹ️ این مورد دیگر در صف نیست.'); return
    symbol = rec['symbol']
    had = any(p.get('symbol') == symbol for p in s.get('paper_positions', []))
    quick_channel_trade(chat_id, symbol, side, skip_trend=True)
    s = get_session(chat_id)
    if not had and any(p.get('symbol') == symbol for p in s.get('paper_positions', [])):
        rec['status'] = 'entered_manual'; rec['manual_side'] = side; rec['finished_at'] = time.time()
        _fav_update_card(chat_id, rec, force=True)
        save_session(chat_id)


def _fav_in_range(chat_id, r):
    """V3.44.41: True اگر قیمت لحظه‌ای الان در محدوده‌ی تایید این سیگنال است (همان ✅ و ⭐ کارت)."""
    try:
        s = get_session(chat_id)
        live = exchange_latest_price(chat_id, r['symbol']) if s.get('trading_mode') == 'REAL' else latest_price(r['symbol'])
        x = _fav_move_r(r['sig'], r['entry'], r['sl'], float(live)) if live else None
        return x is not None and float(r['min_r']) <= x <= float(r['max_r'])
    except Exception:
        return False


def fav_star_toggle(chat_id, message_id=None):
    s = get_session(chat_id)
    s['fav_star_only'] = not bool(s.get('fav_star_only', False))
    save_session(chat_id)
    fav_queue_list(chat_id, message_id=message_id)


def fav_queue_list(chat_id, message_id=None):
    """V3.43.32: فهرست سیگنال‌هایی که در صف «صبر برای تایید» منتظرند (بی‌صدا در پس‌زمینه).
    V3.44.26: بالای چت فقط خلاصه + دکمه‌های کلی؛ هر سیگنال پایین‌ترش یک پیام مستقل با ⚡ ورود سریع و 📈 TradingView خودش دارد."""
    s = get_session(chat_id)
    waiting = sorted([r for r in (s.get('fav_wait') or {}).values() if r.get('status') == 'waiting'],
                     key=lambda r: -float(r.get('created_at', 0) or 0))
    state_txt = '🟢 روشن' if s.get('fav_confirm_enabled', False) else '🔴 خاموش'
    mn, mx, wt = _fav_cfg(s)
    star_on = bool(s.get('fav_star_only', False))
    refresh = {'inline_keyboard': [[{'text': f"⭐ فقط در محدوده: {'🟢 روشن' if star_on else '🔴 خاموش'}", 'callback_data': '/fav_star'}],
                                   [{'text': '🔄 بروزرسانی', 'callback_data': '/fav_queue'}, {'text': '📊 آمار فیلتر', 'callback_data': '/fav_stats'}],
                                   [{'text': '📋 سیگنال‌های در انتظار', 'callback_data': '/assist_pending'},
                                    {'text': '🏠 منوی اصلی', 'callback_data': '/menu'}]]}
    if is_restricted_user(chat_id):        # V3.44.91: کاربر عادی بدون پارامترهای فیلتر (حداقل تایید/سقف ورود/مهلت)
        head = "⏳ *سیگنال‌های در حال تایید*"
    else:
        head = f"⏳ *صف تایید حرکت* ({state_txt})\nحداقل تایید: `+{mn:g}R` | سقف ورود: `{_fav_max_label(s)}` | مهلت: `{wt // 60}` دقیقه"
    if not waiting:
        send_message(chat_id, head + "\n\n✅ الان سیگنالی در صف نیست.", refresh, message_id=message_id)
        return
    total_waiting = len(waiting)
    if star_on:        # V3.44.41: فقط سیگنال‌های ⭐ (الان در محدوده)؛ کارت بقیه از چت پاک می‌شود (سیگنالشان در صف می‌ماند)
        in_rng = [r for r in waiting if _fav_in_range(chat_id, r)]
        for r in waiting:
            if r not in in_rng and r.get('fq_msg_id'):
                tg('deleteMessage', {'chat_id': chat_id, 'message_id': r['fq_msg_id']}, 10)
                r['fq_msg_id'] = None
        waiting = in_rng
        if not waiting:
            send_message(chat_id, head + f"\n\n⭐ الان هیچ سیگنالی در محدوده نیست (در صف: `{total_waiting}`).", refresh, message_id=message_id)
            save_session(chat_id)
            return
    shown = waiting[:FAV_CARDS_PER_LIST]
    lines = [head, (f"⭐ در محدوده: `{len(waiting)}` از `{total_waiting}` سیگنال صف" if star_on else f"در صف: `{len(waiting)}`"), "",
             f"هر سیگنال در یک پیام جدا و با دکمه‌های خودش (⚡ ورود سریع، 📈 TradingView) پایین همین پیام آمده است ({len(shown)} مورد؛ جدیدترین آخر)."]
    if len(waiting) > len(shown):
        lines.append(f"… {len(waiting) - len(shown)} سیگنال قدیمی‌تر بعد از ورود یا انقضای این‌ها نمایش داده می‌شوند.")
    lines.append("\nتایید فقط روی کلوز کندل بسته‌شده انجام می‌شود؛ ✅ یعنی قیمت لحظه‌ای الان در محدوده است. اگر قیمت از سقف گذشت، سیگنال تا پایان مهلت منتظر برگشت به محدوده می‌ماند.")
    send_message(chat_id, "\n".join(lines), refresh, message_id=message_id)
    for r in reversed(shown):            # قدیمی‌تر اول؛ جدیدترین پایین چت، کنار کیبورد
        try:
            _fav_send_card(chat_id, r)
        except Exception:
            logger.exception('fav card send failed symbol=%s', r.get('symbol'))
    save_session(chat_id)


