def _touch_enabled_keys(s):
    return [k for k in _TOUCH_KEYS if gate_on(s, f'gate_fc_{k}_enabled')]


YLEVEL_TOL_ATR = 0.15      # V3.44.36: «رسیدن به سطح» = تا این‌قدر (×ATR) مانده هم برخورد حساب می‌شود


def _ylevel_vote(ind, px):
    """رأیِ «سقف/کف دیروز» (PDH/PDL) از روی قیمت لحظه‌ای. خروجی (vote, توضیح)؛ vote: 'BUY' | 'SELL' | None.
    • قیمت از سقف دیروز گذشته (بالاتر از PDH + تلورانس) = خرید (ادامه‌ی صعود)
    • قیمت کف دیروز را از دست داده (پایین‌تر از PDL − تلورانس) = فروش (ادامه‌ی نزول)
    • به سقف دیروز رسیده ولی از آن نگذشته (فتیله/برخورد) = فروش (رد از سقف)
    • به کف دیروز رسیده ولی از آن پایین نرفته = خرید (حمایت کف)
    • وسط رنج دیروز = بدون رأی"""
    d, pdh, pdl = _compute_prev_day_levels(ind)
    if d is None or pdh is None or pdl is None or px is None or px <= 0:
        return None, 'سقف/کف دیروز نامشخص'
    try:
        atr = float(d['atr'].iloc[-2]) if 'atr' in d.columns else 0.0
    except (TypeError, ValueError):
        atr = 0.0
    if atr != atr:
        atr = 0.0
    tol = max(atr * YLEVEL_TOL_ATR, px * 0.0003)
    last2 = d.iloc[-2:]
    hi_c = max(float(last2['high'].max()), px)
    lo_c = min(float(last2['low'].min()), px)
    if px > pdh + tol:
        return 'BUY', f"از سقف دیروز ({fmt(pdh)}) گذشته"
    if px < pdl - tol:
        return 'SELL', f"کف دیروز ({fmt(pdl)}) را از دست داده"
    near_hi, near_lo = hi_c >= pdh - tol, lo_c <= pdl + tol
    if near_hi and near_lo:
        near_hi = abs(px - pdh) <= abs(px - pdl)
        near_lo = not near_hi
    if near_hi:
        return 'SELL', f"برخورد به سقف دیروز ({fmt(pdh)}) و عبور نکرده"
    if near_lo:
        return 'BUY', f"برخورد به کف دیروز ({fmt(pdl)}) و پایین‌تر نرفته"
    return None, 'وسط رنج دیروز'


_BTCPAT_CACHE = {}
BTCPAT_CACHE_TTL = 15.0


def _btc_pattern_vote(tf, cfg=None):
    """V3.44.47: رأیِ «الگوی BTC روی سطح خودش». همان تشخیص‌دهنده‌ی الگوی برخورد (برگشت / شکست کاذب / نفوذ و پولبک و ادامه)
    که برای نماد استفاده می‌شود روی داده‌ی BTC و سطوح خودِ BTC اجرا می‌شود. خروجی (vote, توضیح)؛ vote: 'BUY' | 'SELL' | None
    (الگویی روی BTC نیست، BTC بلاتکلیف است یا داده نیست). نتیجه ۱۵ ثانیه کش می‌شود تا هر بار بررسی لیست انتظار BTC را دوباره نخواند."""
    base = {**STRATEGY_DEFAULTS, **(cfg or {})}
    ckey = (_venue(), tf, hash(repr(sorted((k, repr(v)) for k, v in base.items()))))
    now = time.time()
    hit = _BTCPAT_CACHE.get(ckey)       # عملیات ساده‌ی dict زیر GIL امن است؛ بدون قفل (تا کد در تست‌های مستقل هم بارگذاری شود)
    if hit and now - hit[0] < BTCPAT_CACHE_TTL:
        return hit[1], hit[2]
    vote, detail = None, 'داده‌ی BTC نیست'
    try:
        limit = 650 if tf in ('5min', '15min', '1hour') else 200
        d = get_klines('BTC', tf, limit)
        if d is not None and not d.empty and len(d) >= 62:
            ind = calculate_indicators(d)
            c = dict(base)
            if c.get('halving_model_enabled'):
                rng = get_halving_range_sync('BTC')
                c = _with_halving_cfg(c, rng) if rng else c
            try:
                live = latest_price('BTC')
                live = float(live) if live else None
            except Exception:
                live = None
            md = {}
            for htf_key, htf_tf in {'5min': [('1h', '1hour'), ('4h', '4hour')], '15min': [('1h', '1hour'), ('4h', '4hour')],
                                    '1hour': [('4h', '4hour'), ('1d', '1day')], '4hour': [('1d', '1day')]}.get(tf, []):
                try:
                    hd = get_klines('BTC', htf_tf, 160)
                    if hd is not None and not hd.empty:
                        md[htf_key] = calculate_indicators(hd)
                except Exception:
                    logger.warning('btc pattern vote: htf klines failed tf=%s', htf_tf)
            # همان تابعی که اسکن نماد برای تولید سیگنال صدا می‌زند (get_signal_with_reason با استراتژی dynamic)
            sig, reason = get_signal_with_reason(ind, md, 'single', tf, 'dynamic', dict(FILTER_DEFAULTS), c, None, live_price=live)
            if sig in ('BUY', 'SELL'):
                _tag, _lt, _lv = extract_setup_level(reason)
                _scn = extract_scenario_tag(reason)
                try:
                    _lvl_txt, _scn_txt = _assist_describe_source(reason or '', _lt, _lv, _scn)
                except Exception:
                    _scn_txt = ''
                vote = sig
                detail = f"BTC: {'خرید' if sig == 'BUY' else 'فروش'}" + (f" ({_scn_txt})" if _scn_txt else '')
            else:
                detail = 'BTC الگویی روی سطح ندارد'
    except Exception:
        logger.exception('btc pattern vote failed tf=%s', tf)
        vote, detail = None, 'خطا در بررسی الگوی BTC'
    if len(_BTCPAT_CACHE) > 64:
        _BTCPAT_CACHE.clear()
    _BTCPAT_CACHE[ckey] = (now, vote, detail)
    return vote, detail


def _btc_side_vote(tf, cfg=None):
    """V3.44.102: رأیِ «سمت BTC نسبت به نزدیک‌ترین سطح». نزدیک‌ترین سطحِ BTC (از هر دو طرف) به کلوز آخرین کندل بسته‌شده‌ی BTC
    روی تایم‌فریم tf مرجع است؛ کلوز بالای آن = 'BUY'، پایین آن = 'SELL'، روی سطح/نبود داده = None. خروجی: (vote, توضیح).
    همان منبعِ «سمت درست سطحِ» دروازه‌ی BTC (btc_front_level_info) است، ولی اینجا فقط رأی می‌دهد و جلوی ورود را نمی‌گیرد."""
    try:
        info = btc_front_level_info({'strategy_config': cfg or {}}, tf, True)
    except Exception:
        logger.exception('btc side vote failed tf=%s', tf)
        return None, 'خطا در بررسی سطح BTC'
    if not info or info.get('ref_price') is None or info.get('close') is None:
        return None, 'سطح BTC در دسترس نیست'
    try:
        close, rp = float(info['close']), float(info['ref_price'])
    except Exception:
        return None, 'سطح BTC در دسترس نیست'
    lbl = info.get('ref_label') or 'سطح'
    if close > rp:
        return 'BUY', f"BTC بالای نزدیک‌ترین سطح ({lbl} {fmt(rp)})"
    if close < rp:
        return 'SELL', f"BTC پایین نزدیک‌ترین سطح ({lbl} {fmt(rp)})"
    return None, f"BTC روی نزدیک‌ترین سطح ({lbl} {fmt(rp)})"


SYMSTRUCT_BARS = 160


def _swing_structure(df, left=3, right=3):
    """V3.44.105: ساختار سقف/کفِ نماد روی کندل‌های بسته‌شده. خروجی: ('UP'|'DOWN'|None, info).
    UP = دو سقف آخر و دو کف آخر هر دو بالاتر (HH + HL)؛ DOWN = هر دو پایین‌تر (LH + LL)؛ غیر از این None (مختلط/رنج/داده‌ی ناکافی).
    پیوت‌ها علّی‌اند (هر پیوت بعد از `right` کندل تایید می‌شود) و کندل آخرِ df (در حال تشکیل) نادیده گرفته می‌شود.
    شکست ساختار: اگر کلوز آخرین کندل بسته‌شده زیر آخرین کفِ بالاتر (در UP) یا بالای آخرین سقفِ پایین‌تر (در DOWN) باشد، ساختار دیگر معتبر نیست → None."""
    try:
        if df is None or len(df) < left + right + 12:
            return None, {}
        d = df.iloc[:-1]
        hi = [float(x) for x in d['high']]
        lo = [float(x) for x in d['low']]
        cl = float(d['close'].iloc[-1])
        highs, lows = [], []
        for i in range(left, len(d) - right):
            if hi[i] > max(hi[i - left:i]) and hi[i] >= max(hi[i + 1:i + 1 + right]):
                highs.append((i, hi[i]))
            if lo[i] < min(lo[i - left:i]) and lo[i] <= min(lo[i + 1:i + 1 + right]):
                lows.append((i, lo[i]))
        if len(highs) < 2 or len(lows) < 2:
            return None, {}
        (_h1i, h1), (_h2i, h2) = highs[-2], highs[-1]
        (_l1i, l1), (_l2i, l2) = lows[-2], lows[-1]
        info = {'h1': h1, 'h2': h2, 'l1': l1, 'l2': l2, 'close': cl}
        if h2 > h1 and l2 > l1:
            return ('UP' if cl >= l2 else None), info
        if h2 < h1 and l2 < l1:
            return ('DOWN' if cl <= h2 else None), info
        return None, info
    except Exception:
        logger.exception('swing structure failed')
        return None, {}


def _symbol_structure_verdict(symbol, tf, sig, s=None):
    """V3.44.105: (ok, توضیح). ساختار UP جلوی فروش را می‌گیرد و ساختار DOWN جلوی خرید را؛ نبود داده/ساختار مختلط = مجاز.
    sig جهت برخورد است؛ با «معاملات معکوس» روشن جهت واقعی معامله برعکس می‌شود و همان سنجیده می‌شود."""
    eff = sig
    try:
        if s is not None and gate_on(s, 'gate_inverse_trading_enabled'):
            eff = 'SELL' if sig == 'BUY' else 'BUY'
        cfg = (s or {}).get('strategy_config') or {}
        pv = max(2, min(6, int(cfg.get('symstruct_pivot', 3))))
        df = get_klines(symbol, tf, SYMSTRUCT_BARS)
        st, info = _swing_structure(df, pv, pv)
    except Exception:
        logger.exception('symbol structure verdict failed symbol=%s', symbol)
        return True, ''
    if (st == 'UP' and eff == 'SELL') or (st == 'DOWN' and eff == 'BUY'):
        tf_fa = TF_DISPLAY.get(tf, tf)
        kind = 'صعودی (سقف‌ها و کف‌های بالاتر)' if st == 'UP' else 'نزولی (سقف‌ها و کف‌های پایین‌تر)'
        side_fa = 'فروش' if eff == 'SELL' else 'خرید'
        txt = (f"⛔ ساختار قیمت `{symbol}` در {tf_fa} {kind} است (سقف {fmt(info['h1'])}→{fmt(info['h2'])} · کف {fmt(info['l1'])}→{fmt(info['l2'])}) "
               f"و معامله‌ی {side_fa} خلاف آن است؛ این برخورد وارد لیست انتظار نمی‌شود"
               + _btc_gate_key_line('gate_symbol_structure_block_enabled'))
        _block_simple_register(txt, 'ساختار قیمت این نماد خلاف جهت این معامله است؛ در این شرایط ورود به معامله مجاز نیست.')
        return False, txt
    return True, ''


def _symbol_active_tf_regime(symbol, tf):
    """V3.44.104: رژیم خودِ نماد روی تایم‌فریم فعال tf ('BULLISH'|'BEARISH'|'RANGE'|None) با همان معیار رژیم ۵/۱۵ دقیقه و ۴ ساعته
    (close نسبت به EMA50 و EMA20 نسبت به EMA50 روی آخرین کندل بسته‌شده)."""
    try:
        df = get_klines(symbol, tf, 160)
        if df is None or df.empty or len(df) < 60:
            return None
        return _signal_channel_symbol_regime(df)
    except Exception:
        logger.exception('symbol active tf regime failed symbol=%s tf=%s', symbol, tf)
        return None


def _touch_votes(symbol, tf, reason, keys, ind_df=None, cfg=None):
    """sync (از thread صدا زده شود). خروجی: [{'key','label','vote','detail'}]؛ vote: 'BUY' | 'SELL' | None (خنثی/نبود داده)،
    و برای «حجم»: 'OK' | None."""
    out = []
    fa = {'BULLISH': 'صعودی', 'BEARISH': 'نزولی', 'RANGE': 'رنج'}
    r2v = {'BULLISH': 'BUY', 'BEARISH': 'SELL'}

    def add(k, vote, detail=''):
        out.append({'key': k, 'label': _TOUCH_LABELS[k], 'vote': vote, 'detail': detail})
    sym_u = str(symbol or '').upper()
    if 'btcpat' in keys and sym_u != 'BTC':
        _bv, _bd = _btc_pattern_vote(tf, cfg)
        add('btcpat', _bv, _bd)
    if 'btcside' in keys and sym_u != 'BTC':       # V3.44.102
        _sv, _sd = _btc_side_vote(tf, cfg)
        add('btcside', _sv, _sd)
    if 'btceth' in keys:
        regs = {}
        for sym in ('BTC', 'ETH'):
            if sym == sym_u:
                continue
            try:
                snap = _trend_snapshot_cached(sym, tf)
            except Exception:
                snap = None
            if snap:
                sc = int(snap.get('score', 0))
                regs[sym] = 'BULLISH' if sc > 0 else ('BEARISH' if sc < 0 else 'RANGE')
            else:
                regs[sym] = None
        vs = {r2v.get(r) for r in regs.values()}
        vote = next(iter(vs)) if (len(vs) == 1 and None not in vs) else None
        add('btceth', vote, '، '.join(f"{k} {fa.get(v, 'نامشخص')}" for k, v in regs.items()))
    if 'symreg' in keys:                      # V3.44.104: رأی «رژیم نماد در تایم‌فریم فعال»؛ صعودی = رأی خرید، نزولی = رأی فروش، رنج/نبود داده = بدون رأی
        reg = _symbol_active_tf_regime(symbol, tf)
        add('symreg', r2v.get(reg), f"{TF_DISPLAY.get(tf, tf)} {fa.get(reg, 'نامشخص')}")
    if 'h4' in keys:
        reg = _symbol_h4_regime(symbol)
        add('h4', r2v.get(reg), fa.get(reg, 'نامشخص'))
    if 'tf' in keys:
        regs = _symbol_tf_regimes(symbol)
        vs = {r2v.get(regs.get(t)) for t in _TFR_TIMEFRAMES}
        vote = next(iter(vs)) if (len(vs) == 1 and None not in vs) else None
        add('tf', vote, '، '.join(f"{TF_DISPLAY.get(t, t)} {fa.get(regs.get(t), 'نامشخص')}" for t in _TFR_TIMEFRAMES))
    if any(k in keys for k in ('rsi', 'macd', 'adx', 'vol', 'level', 'ylevel')):
        row, bias, raw = None, {}, {}
        try:
            ind = ind_df
            if ind is None:
                d = get_klines(symbol, tf, 650 if tf in ('5min', '15min', '1hour') else 200)
                ind = calculate_indicators(d) if d is not None and not d.empty else None
            if ind is None or len(ind) < 4:
                raise ValueError('no indicator data')
            row = ind.iloc[-2]
            bias, raw = _single_indicator_biases(row.to_dict())
        except Exception:
            logger.exception('touch votes indicators failed symbol=%s', symbol)
        if 'rsi' in keys:
            add('rsi', bias.get('rsi'), f"{raw['rsi']:.0f}" if 'rsi' in raw else 'داده نیست')
        if 'macd' in keys:
            add('macd', bias.get('macd'), ('مثبت' if raw.get('macd', 0) > 0 else 'منفی') if 'macd' in raw else 'داده نیست')
        if 'adx' in keys:
            add('adx', bias.get('adx'), f"ADX {raw['adx']:.0f}" if 'adx' in raw else 'داده نیست')
        if 'vol' in keys:
            vr = row.get('volume_ratio') if row is not None else None
            if vr is None or pd.isna(vr):
                add('vol', None, 'داده نیست')
            else:
                add('vol', ('OK' if float(vr) >= FULL_CONFIRM_MIN_VOLUME_RATIO else None), f"{float(vr):.1f}x (لازم {FULL_CONFIRM_MIN_VOLUME_RATIO:g}x)")
        if 'level' in keys:
            m = re.search(r'HVL=([0-9.]+)', reason or '') or re.search(r'ANCHOR=([0-9.]+)', reason or '')
            if m and row is not None:
                lvl = float(m.group(1)); last = float(row['close'])
                vote = 'BUY' if last > lvl else ('SELL' if last < lvl else None)
                add('level', vote, f"آخرین کلوز {'بالای' if last > lvl else 'پایین'} سطح" if vote else 'روی سطح')
            else:
                add('level', None, 'سطح/داده نامشخص')
        if 'ylevel' in keys:
            try:
                _yp = latest_price(symbol)
                _yp = float(_yp) if _yp else (float(row['close']) if row is not None else None)
                _yv, _yd = _ylevel_vote(ind, _yp)
            except Exception:
                logger.exception('touch votes ylevel failed symbol=%s', symbol)
                _yv, _yd = None, 'داده نیست'
            add('ylevel', _yv, _yd)
    return out


def _touch_summarize(votes, mode, fixed_dir=None):
    """votes را (درجا) با کلید 'status' علامت می‌زند. جهت از رأی گروه‌ها با وزن می‌آید (نه شمارش تک‌تک فیلترها)؛
    'agree/total' همچنان شمارش تک‌تک فیلترهای موافق است (برای حد ورود خودکار).
    خروجی: {'dir','agree','total','auto_ok','groups'}."""
    fixed = fixed_dir in ('BUY', 'SELL')
    members = {}
    for v in votes:
        if v['key'] == 'vol':
            continue
        g_k = _TOUCH_GROUP.get(v['key'], v['key'])
        if fixed and g_k == 'ylevel':
            g_k = 'structure'      # V3.44.47: «سطح» در حالت جهتِ ثابت یک رأی است (سقف/کف دیروز هم‌گروه با سطح)
        members.setdefault(g_k, []).append(v['vote'])
    groups = {}
    for g_, vs_ in members.items():
        b_, s_ = vs_.count('BUY'), vs_.count('SELL')
        groups[g_] = 'BUY' if b_ > s_ else ('SELL' if s_ > b_ else None)
    buy_w = sum(_TOUCH_GROUP_W.get(g_, 1) for g_, x in groups.items() if x == 'BUY')
    sell_w = sum(_TOUCH_GROUP_W.get(g_, 1) for g_, x in groups.items() if x == 'SELL')
    direction = fixed_dir if fixed else ('BUY' if buy_w > sell_w else ('SELL' if sell_w > buy_w else None))
    agree = 0
    for v in votes:
        if v['key'] == 'vol':
            st = 'ok' if v['vote'] == 'OK' else 'wait'
        elif direction is None:
            st = {'BUY': 'buy', 'SELL': 'sell'}.get(v['vote'], 'wait')
        elif v['vote'] == direction:
            st = 'ok'
        elif v['vote'] in ('BUY', 'SELL'):
            st = 'against'
        else:
            st = 'wait'
        v['status'] = st
        if st == 'ok':
            agree += 1
    total = len(votes)
    if fixed:
        # V3.44.47: جهت از الگوی برخورد ثابت است؛ شمارش روی «گروه‌های رأی» است نه تک‌تک فیلترها (حجم، اگر روشن باشد، جدا شمرده می‌شود)
        n_vol = sum(1 for v in votes if v['key'] == 'vol')
        agree = sum(1 for x in groups.values() if x == direction) + sum(1 for v in votes if v['key'] == 'vol' and v['vote'] == 'OK')
        total = len(groups) + n_vol
    need = {'all': total, 'minus1': max(1, total - 1), 'majority': total // 2 + 1}.get(mode, total)
    return {'dir': direction, 'agree': agree, 'total': total, 'groups': groups,
            'auto_ok': bool(direction and total > 0 and agree >= need)}


# V3.44.88: «رأی برگشت» (آزمایشی، پیش‌فرض خاموش). فقط رأی‌دهنده است و جلوی هیچ معامله‌ای را نمی‌گیرد.
# روی حالت‌های برگشتی (۱ و ۲: سویپ + ریکلیم، ۵ و ۶: شکست کاذب) رأی‌دهنده‌های مومنتوم/روند کوتاه‌مدت برعکس حساب می‌شوند:
# وقتی بازار هنوز خلاف جهت برگشت است (فرسودگیِ حرکت قبلی)، «مخالف» بودن آن‌ها یعنی «موافق برگشت».
# در داده‌ی قیف (۲۲ ساعت، بازار رنج) این رأی‌دهنده‌ها در برگشت‌ها عکس عمل کرده‌اند؛ هنوز اثبات‌شده نیست و باید روی داده‌ی چند روز دیگر سنجیده شود.
_REVERSAL_SCENARIOS = ('1', '2', '5', '6')
_CONTRA_FLIP_KEYS = ('btceth', 'tf', 'rsi', 'adx')


def _contra_flip_votes(votes):
    """نسخه‌ی تازه‌ی رأی‌ها با معکوس‌کردن BUY↔SELL برای _CONTRA_FLIP_KEYS. ورودی دست‌نخورده می‌ماند."""
    out = []
    for v in votes:
        nv = dict(v)
        if nv.get('key') in _CONTRA_FLIP_KEYS and nv.get('vote') in ('BUY', 'SELL'):
            nv['vote'] = 'SELL' if nv['vote'] == 'BUY' else 'BUY'
            nv['flipped'] = True
            nv['detail'] = (str(nv.get('detail') or '') + ' (معکوس برای برگشت)').strip()
        out.append(nv)
    return out


def _contra_active(s, scn, fixed_dir):
    """True اگر «رأی برگشت» روی این برخورد اعمال می‌شود: کلید روشن + حالت برگشتی + جهتِ ثابت از الگو."""
    try:
        return bool(fixed_dir in ('BUY', 'SELL') and str(scn or '') in _REVERSAL_SCENARIOS
                    and gate_on(s, 'gate_reversal_contra_enabled'))
    except Exception:
        return False


def _touch_eval_one(chat_id, rec):
    s = get_session(chat_id)
    keys = _touch_enabled_keys(s)
    tf = rec.get('tf') or s.get('timeframe', '5min')
    votes_all = None
    try:
        if not funnel_log.ENABLED or os.environ.get('FUNNEL_CF', '1') == '0':
            raise ValueError('funnel off')
        votes_all = _touch_votes(rec['symbol'], tf, rec.get('reason') or '', list(_TOUCH_KEYS), cfg=s.get('strategy_config'))      # V3.44.72: همه‌ی رأی‌ها یک‌بار؛ کلیدهای روشن همین فیلتر می‌شوند
        votes = [dict(v) for v in votes_all if v['key'] in keys]
    except Exception:
        votes_all = None
        votes = _touch_votes(rec['symbol'], tf, rec.get('reason') or '', keys, cfg=s.get('strategy_config')) if keys else []
    fixed_dir = rec.get('touch_sig') if (gate_on(s, 'gate_touch_dir_fixed_enabled') and rec.get('touch_sig') in ('BUY', 'SELL')) else None
    if (not fixed_dir) and gate_on(s, 'gate_touch_pattern_vote_enabled') and rec.get('touch_sig') in ('BUY', 'SELL'):
        # V3.44.15: جهتِ پیشنهادیِ خودِ الگوی برخورد (برگشت بدون نفوذ / شکست کاذب / پولبک و ادامه) هم یک رأی است
        _lt, _st = _assist_describe_source(rec.get('reason') or '', rec.get('level_token'), rec.get('level_value'), rec.get('scn'))
        votes.insert(0, {'key': 'pattern', 'label': 'الگوی برخورد با سطح', 'vote': rec['touch_sig'], 'detail': _st})
    _cmode = s.get('touch_auto_mode', 'all')
    _contra_on = _contra_active(s, rec.get('scn'), fixed_dir)
    _base_votes = votes
    if _contra_on:
        votes = _contra_flip_votes(votes)          # V3.44.88: رأی برگشت
    summ = _touch_summarize(votes, _cmode, fixed_dir=fixed_dir)
    try:       # V3.44.88: نتیجه‌ی هر دو حالت (بدون/با معکوس) برای ثبت قیف؛ روی تصمیم اثری ندارد
        if fixed_dir and _base_votes:
            _alt = _touch_summarize([dict(v) for v in _base_votes] if _contra_on else _contra_flip_votes(_base_votes), _cmode, fixed_dir=fixed_dir)
            _n_, _f_ = (_alt, summ) if _contra_on else (summ, _alt)
            _pack = lambda x: [x.get('dir'), x.get('agree'), x.get('total'), int(bool(x.get('auto_ok')))]
            rec['contra'] = {'on': bool(_contra_on), 'rev': str(rec.get('scn') or '') in _REVERSAL_SCENARIOS, 'n': _pack(_n_), 'f': _pack(_f_)}
    except Exception:
        logger.debug('contra counterfactual failed', exc_info=True)
    with _TOUCH_LOCK:
        rec['votes'] = votes
        rec.update(summ)
        rec['last_eval'] = time.time()
    try:
        _fn_after_eval(chat_id, s, rec, votes, votes_all, summ)
    except Exception:
        logger.debug('funnel after_eval failed', exc_info=True)


def _touch_register(chat_id, symbol, touch_sig, reason, tf, plan=None, flip_from=None):
    """برخورد با سطح را در لیست انتظار ثبت می‌کند (بدون صدور سیگنال). خروجی: (status, متن).
    V3.44.23: flip_from = جهتِ سیگنالی که در «صف تایید حرکت» رد شد و حالا در جهت مخالف از اول بررسی می‌شود؛ بررسی‌های «قبلاً ثبت/معامله شده» برایش کنار می‌رود."""
    s = get_session(chat_id)
    now = time.time()
    _tag, level_token, level_value = extract_setup_level(reason)
    scn = extract_scenario_tag(reason)
    if any(p.get('symbol') == symbol for p in s.get('paper_positions', [])):
        return 'touch_skipped', 'روی این نماد پوزیشن باز داریم'
    if (not flip_from) and level_token is not None and gate_on(s, 'gate_traded_level_enabled') and f"{symbol}:{level_token}:{level_value}" in s.get('traded_levels', {}):
        return 'touch_skipped', 'روی همین سطح قبلاً معامله شده'
    if gate_on(s, 'gate_symbol_structure_block_enabled'):
        # V3.44.105: ساختار قیمت نماد (سقف/کف‌ها) خلاف جهت معامله است → اصلاً وارد لیست انتظار رأی‌گیری نمی‌شود (هر ورودی به لیست از همین تابع می‌گذرد: اسکن و برگشت از صف تایید)
        _ss_ok, _ss_txt = _symbol_structure_verdict(symbol, tf, touch_sig, s)
        if not _ss_ok:
            return 'blocked', _ss_txt
    with _TOUCH_LOCK:
        waits = s.setdefault('touch_wait', {})
        if any(r.get('symbol') == symbol and r.get('status') == 'waiting' for r in waits.values()):
            return 'touch_wait', 'این نماد همین حالا در لیست انتظار رأی‌گیری است'
        seen = s.setdefault('touch_wait_seen', {})
        for k in [k for k, v in seen.items() if now - float(v or 0) >= ASSIST_SEEN_TTL_SECONDS]:
            seen.pop(k, None)
        seen_key = f"{symbol}|{level_token}|{level_value}"
        if seen_key in seen and not flip_from:
            return 'touch_skipped', 'این برخورد قبلاً ثبت شده'
        tid = hashlib.sha1(f"tw{chat_id}{symbol}{now}".encode()).hexdigest()[:8]
        try:
            _tp0 = exchange_latest_price(chat_id, symbol) if s.get('trading_mode') == 'REAL' else latest_price(symbol)
            _tp0 = float(_tp0) if _tp0 else None
        except Exception:
            _tp0 = None
        expiry = int(s.get('assist_expiry_seconds', 1800) or 1800)
        rec = {'id': tid, 'symbol': symbol, 'touch_sig': touch_sig, 'reason': str(reason or '')[:900], 'level_token': level_token,
               'level_value': level_value, 'scn': scn, 'tf': tf, 'created_at': now, 'expires_at': now + expiry, 'status': 'waiting',
               'last_eval': 0.0, 'votes': [], 'dir': None, 'agree': 0, 'total': 0, 'auto_ok': False,
               'touch_price': _tp0, 'plan': (dict(plan) if plan else None), 'flipped_from': flip_from}
        waits[tid] = rec
        seen[seen_key] = now
        if len(waits) > TOUCH_MAX_RECORDS:
            for k in sorted(waits, key=lambda kk: float(waits[kk].get('created_at', 0) or 0)):
                if len(waits) <= TOUCH_MAX_RECORDS:
                    break
                if waits[k].get('status') != 'waiting':
                    waits.pop(k, None)
    try:
        _fn_touch_created(chat_id, s, rec, plan, flip_from)
    except Exception:
        logger.debug('funnel touch_created failed', exc_info=True)
    _touch_eval_one(chat_id, rec)
    outcome = False
    if rec.get('auto_ok') and gate_on(s, 'gate_touch_vote_enabled'):
        outcome = _touch_auto_enter(chat_id, rec)
    save_session(chat_id)
    logger.info('touch vote: %s dir=%s agree=%s/%s auto=%s outcome=%s', symbol, rec.get('dir'), rec.get('agree'), rec.get('total'), rec.get('auto_ok'), outcome)
    if outcome == 'queued':
        return 'fav_wait', 'فیلترها تایید شدند؛ در صف صبر برای تایید حرکت به نفع معامله'
    if outcome == 'card_sent':
        return 'assist_card', 'فیلترها تایید شدند؛ کارت حالت دستیار ارسال شد'
    return ('entry_opened', 'ورود خودکار پس از تایید فیلترها') if outcome else ('touch_wait', 'برخورد در لیست انتظار؛ منتظر تایید فیلترها')


@_from_signal_origin
def _touch_auto_enter_core(chat_id, rec):
    """ورود خودکار بعد از تایید فیلترها (با قیمت لحظه‌ای؛ محدودیت‌های عادی ریسک/کول‌داون/سقف پوزیشن اعمال می‌شود).
    خروجی: 'opened' (پوزیشن باز شد) | 'queued' (رفت به «صف تایید حرکت») | 'card_sent' (کارت حالت دستیار) | False.
    V3.44.20: بعد از تایید فیلترها، همان مراحل پایانیِ مسیر عادی اجرا می‌شود: اگر «صبر برای تایید حرکت» روشن باشد سیگنال از لیست انتظار
    به صف تایید حرکت می‌رود و ورود نهایی فقط بعد از تایید حرکت به نفع معامله انجام می‌شود؛ اگر حالت دستیار روشن باشد کارت ✅/❌ می‌آید.
    V3.44.16: اگر جهت نهایی با جهت خودِ برخورد یکی باشد، SL/TP همان طرح اصلی ستاپ است (امتیاز کیفیت و هدف ساختاری حفظ می‌شود)؛
    وگرنه طرح ورود سریع. قبل از ورود: عبور نکردن قیمت از SL/TP، R:R لحظه‌ای >= حداقل R:R تنظیمات، و دور نشدن قیمت
    بیش از TOUCH_MAX_DRIFT_R از لحظه‌ی برخورد بررسی می‌شود؛ اگر رد شد مورد در لیست می‌ماند و در بروزرسانی بعدی دوباره سنجیده می‌شود."""
    s = get_session(chat_id)
    symbol, side = rec['symbol'], rec.get('dir')
    rec.pop('block_note', None)
    if side not in ('BUY', 'SELL'):
        return False
    if not s.get('is_bot_active') or s.get('daily_stopped'):
        return False
    if s.get('manual_block_all_entries') or (side == 'BUY' and s.get('manual_block_buy_entries')) or (side == 'SELL' and s.get('manual_block_sell_entries')):
        rec['block_note'] = 'بلاک دستی جهت/کل معاملات فعال است'
        return False
    tf = rec.get('tf') or s.get('timeframe', '5min')
    try:
        live = exchange_latest_price(chat_id, symbol) if s.get('trading_mode') == 'REAL' else latest_price(symbol)
        live = float(live) if live else None
    except Exception:
        live = None
    if not live:
        return False
    is_long = (side == 'BUY')
    plan = rec.get('plan') if (rec.get('plan') and side == rec.get('touch_sig')) else None
    if plan:
        sl, tp = float(plan['sl']), float(plan['tp'])
        risk0 = abs(float(plan.get('entry') or live) - sl)
        extra = dict(structural_tp=bool(plan.get('structural_target', False)), plan_score=plan.get('score'), plan_rr=plan.get('rr'),
                     plan_quality_label=plan.get('quality_label'), tp_level_name=plan.get('tp_level_name'), tp_stages=plan.get('tp_stages'))
        plan_reason = plan.get('reason') or ''
        base_reason = rec.get('reason') or ''
        if plan_reason and plan_reason not in base_reason:
            base_reason = f"{base_reason} | {plan_reason}"
    else:
        qp, _ = build_quick_plan_with_fallback(symbol, side, s.get('strategy_config'), live, tf)
        sl, tp = float(qp['sl']), float(qp['tp'])
        risk0 = abs(live - sl)
        extra = dict(plan_rr=qp.get('rr'), tp_level_name=qp.get('tp_level_name'))
        base_reason = f"{rec.get('reason') or ''} | {qp.get('reason', '')}"
    if not ((sl < live < tp) if is_long else (tp < live < sl)):
        rec['block_note'] = 'قیمت لحظه‌ای از حد ضرر/سود طرح گذشته است'
        return False
    rr_live = abs(tp - live) / abs(live - sl)
    min_rr = max(MIN_RR_FLOOR, float((s.get('strategy_config') or {}).get('min_rr', MIN_RR_FLOOR) or MIN_RR_FLOOR))
    if gate_on(s, 'gate_min_rr_enabled') and rr_live < min_rr:
        rec['block_note'] = f'R:R لحظه‌ای {rr_live:.2f} کمتر از حداقل {min_rr:g} است'
        return False
    t0 = rec.get('touch_price')
    if t0 and risk0 > 0:
        drift = abs(live - float(t0)) / risk0
        if drift > TOUCH_MAX_DRIFT_R:
            rec['block_note'] = f'قیمت {drift:.2f}R از لحظه‌ی برخورد دور شده (حداکثر {TOUCH_MAX_DRIFT_R:g}R)'
            return False
    side_fa = 'خرید' if is_long else 'فروش'
    # V3.44.47: وضعیت هر رأی در لحظه‌ی عبور از مرحله‌ی رأی‌گیری (Y موافق، N مخالف، - بی‌نظر/منتظر) برای ثبت در ژورنال
    _vt = ','.join(f"{v.get('key')}:{ {'ok': 'Y', 'against': 'N'}.get(v.get('status'), '-') }" for v in (rec.get('votes') or []))
    full_reason = (f"{base_reason} | ⚖️ رأی فیلترها: {side_fa} ({rec.get('agree')}/{rec.get('total')}) |VOTES={_vt}|"
                   + (' | طرح اصلی ستاپ' if plan else ' | طرح ورود سریع'))[:900]
    p_stub = {'structural_target': extra.get('structural_tp', False), 'score': extra.get('plan_score'), 'rr': extra.get('plan_rr'),
              'quality_label': extra.get('plan_quality_label'), 'tp_level_name': extra.get('tp_level_name'), 'tp_stages': extra.get('tp_stages')}

    def _finish(status):
        with _TOUCH_LOCK:
            rec['status'] = status; rec['finished_at'] = time.time()
        try:
            _fn_after_enter(chat_id, rec, status)
            _fn_touch_final(chat_id, rec)
        except Exception:
            pass
        _touch_update_card(chat_id, rec, force=True)
        return status
    # 1) صبر برای تایید حرکت: سیگنال از لیست انتظار به صف تایید می‌رود؛ ورود نهایی بعد از تایید حرکتِ قیمت به نفع معامله (و بررسی دوباره‌ی محدوده/R:R) انجام می‌شود.
    try:
        if _fav_confirm_hold(chat_id, symbol, side, p_stub, live, sl, tp, full_reason):
            return _finish('queued')
    except Exception:
        logger.exception('touch: fav confirm hold failed symbol=%s', symbol)
    # V3.44.31: کلید «رژیم بازار در مرحله‌ی آخر»: وقتی صف تایید حرکت خاموش است، همین‌جا آخرین مرحله است؛ مورد در لیست می‌ماند و تیک بعدی دوباره سنجیده می‌شود.
    if gate_on(s, 'gate_final_regime_enabled'):
        try:
            _rg_ok, _rg_txt = _final_regime_check(tf, side)
        except Exception:
            logger.exception('touch: final regime check failed symbol=%s', symbol)
            _rg_ok, _rg_txt = False, 'خطا در بررسی رژیم بازار'
        if not _rg_ok:
            rec['block_note'] = _rg_txt[:120]
            return False
    if gate_on(s, 'gate_pd_level_enabled'):
        # V3.44.58: لیست انتظار: سقف/کف دیروز (PDH/PDL) نباید جلوی معامله باشد و قیمت نباید تازه از آن برگشته باشد؛ وگرنه مورد در لیست می‌ماند و تیک بعدی دوباره سنجیده می‌شود.
        try:
            _pd_ok, _pd_txt = _pd_level_gate(s, symbol, side, tf, live)
        except Exception:
            logger.exception('touch: pd level check failed symbol=%s', symbol)
            _pd_ok, _pd_txt = True, ''
        if not _pd_ok:
            rec['block_note'] = _pd_txt[:120]
            return False
    _ff, _fc = _btc_front_flags(s)
    if _ff or _fc:
        # V3.44.44: لیست انتظار: فاصله‌ی کلوز BTC تا سطح جلویی باید معقول باشد؛ وگرنه هشدار ورود می‌آید و مورد (رد نمی‌شود) در لیست می‌ماند و تیک بعدی دوباره سنجیده می‌شود.
        _fl_ok, _fl_txt = _btc_front_gate(chat_id, s, symbol, side, tf, front=_ff, chop=_fc)
        if not _fl_ok:
            rec['block_note'] = _fl_txt[:120]
            return False
    # 2) حالت دستیار: ورود فقط بعد از تایید دستی کاربر (کارت ✅ ورود / ❌ رد).
    if s.get('assist_mode_enabled'):
        try:
            df_card = get_klines(symbol, tf, 200)
        except Exception:
            df_card = None
        _assist_queue_signal(chat_id, symbol, side, dict(p_stub, rr=None), live, sl, tp, full_reason,
                             df=(df_card if (df_card is not None and len(df_card)) else None))
        return _finish('card_sent')
    if gate_on(s, 'gate_btc_candle_enabled'):
        # V3.44.42: ورود خودکار از لیست انتظار: کندل در حال تشکیل BTC باید هم‌جهت باشد؛ وگرنه مورد در لیست می‌ماند و تیک بعدی دوباره سنجیده می‌شود.
        try:
            _bc_ok, _bc_txt = btc_candle_verdict(tf, side)
        except Exception:
            logger.exception('touch: btc candle check failed symbol=%s', symbol)
            _bc_ok, _bc_txt = False, f'{_BTC_CANDLE_BLOCK_PREFIX}: خطا در بررسی کندل'
        if not _bc_ok:
            rec['block_note'] = _bc_txt[:120]
            return False
    ok = execute_trade(chat_id, symbol, 'BUY (Long)' if is_long else 'SELL (Short)', live, sl, tp, full_reason,
                       bypass_burst_cooldown=True, **extra)
    if ok:
        return _finish('opened')
    rec['block_note'] = (_LAST_BLOCK_REASON.pop(chat_id, None) or 'ورود رد شد')[:120]
    return False


def _touch_auto_enter(chat_id, rec):
    """V3.44.72: پوشش برای ثبت قیف: tid برخورد در thread ثبت می‌شود تا صف تایید حرکت و معامله به همین برخورد وصل شوند."""
    try:
        _FN_TLS.tid = rec.get('id')
    except Exception:
        pass
    try:
        res = _touch_auto_enter_core(chat_id, rec)
    finally:
        try:
            _FN_TLS.tid = None
        except Exception:
            pass
    try:
        _fn_after_enter(chat_id, rec, res)
    except Exception:
        pass
    return res


def touch_quick_entry(chat_id, tid, side):
    """دکمه‌ی ⚡ ورود سریع زیر هر مورد لیست انتظار."""
    s = get_session(chat_id)
    rec = (s.get('touch_wait') or {}).get(tid)
    if not rec or rec.get('status') != 'waiting':
        send_message(chat_id, 'ℹ️ این مورد دیگر در لیست انتظار نیست.'); return
    symbol = rec['symbol']
    had = any(p.get('symbol') == symbol for p in s.get('paper_positions', []))
    quick_channel_trade(chat_id, symbol, side, skip_trend=True)
    s = get_session(chat_id)
    if not had and any(p.get('symbol') == symbol for p in s.get('paper_positions', [])):
        with _TOUCH_LOCK:
            rec['status'] = 'entered_manual'; rec['manual_side'] = side; rec['finished_at'] = time.time()
            try: _fn_touch_final(chat_id, rec)
            except Exception: pass
        _touch_update_card(chat_id, rec, force=True)
        save_session(chat_id)


def _touch_block_lines(r, n, now):
    tf = r.get('tf') or '5min'
    rem = max(0, int((float(r.get('expires_at', 0) or 0) - now + 59) // 60))
    level_txt, scn_txt = _assist_describe_source(r.get('reason') or '', r.get('level_token'), r.get('level_value'), r.get('scn'))
    d = r.get('dir')
    dir_txt = (f"{'🟢 خرید' if d == 'BUY' else '🔴 فروش'} ({r.get('agree', 0)} از {r.get('total', 0)} فیلتر موافق)") if d else '⏳ هنوز مشخص نیست'
    head = f"{n}) " if n else ''
    left = f" · ⏳ {rem} دقیقه" if r.get('status') == 'waiting' else ''
    lines = [f"{head}`{r['symbol']}` · {TF_DISPLAY.get(tf, tf)}{left}",
             f"    🎯 سطح: `{level_txt}` | سناریو: `{scn_txt}`"]
    if r.get('flipped_from'):
        lines.append(f"    🔁 سیگنال {'خرید' if r['flipped_from'] == 'BUY' else 'فروش'} در صف تایید حرکت رد شد؛ اینجا در جهت مخالف از اول بررسی می‌شود")
    lines.append(f"    جهت: {dir_txt}")
    votes = r.get('votes') or []
    if not votes:
        lines.append('    (هیچ فیلتر روشنی نیست؛ فقط ورود سریع)')
    # V3.44.29: فیلترهای تاییدشده (و رأی‌دهنده‌ها) بالا، «منتظر تایید» وسط، «مخالف» پایین؛ هر گروه با یک خط جدا می‌شود. شماره‌ها پشت‌سرهم‌اند.
    _grp = ([v for v in votes if v.get('status') in ('ok', 'buy', 'sell')],
            [v for v in votes if v.get('status') not in ('ok', 'buy', 'sell', 'against')],
            [v for v in votes if v.get('status') == 'against'])
    _i = 0
    for _gi, _g in enumerate([g_ for g_ in _grp if g_]):
        if _gi:
            lines.append('    ┄┄┄┄┄┄┄┄┄┄┄┄')
        for v in _g:
            _i += 1
            lines.append(f"    {_i}. {v['label']}: {_TOUCH_ST_TXT.get(v.get('status'), '⏳ منتظر تایید')}" + (f" ({v['detail']})" if v.get('detail') else ''))
    gv = r.get('groups') or {}
    if gv:
        _ic = {'BUY': '🟢', 'SELL': '🔴', None: '⏳'}
        lines.append('    ⚖️ گروه‌ها: ' + ' | '.join(f"{_TOUCH_GROUP_FA.get(g_, g_)} {_ic.get(x, '⏳')}" for g_, x in gv.items()))
    if r.get('block_note') and r.get('status') == 'waiting':
        lines.append(f"    ⛔ ورود خودکار انجام نشد: {r['block_note']}")
    return lines


def _touch_buttons(r):
    sym, tid, tf = r['symbol'], r['id'], r.get('tf') or '5min'
    try:
        chart = {'text': '📈 چارت TradingView', 'url': tradingview_chart_url(sym, tf)}
    except Exception:
        chart = None
    d = r.get('dir')
    if d:
        qe = [{'text': f"⚡ ورود سریع {sym} {'🟢 خرید' if d == 'BUY' else '🔴 فروش'}", 'callback_data': f"/tw_qe_{'buy' if d == 'BUY' else 'sell'}_{tid}"}]
    else:
        qe = [{'text': f"⚡ {sym} 🟢 خرید", 'callback_data': f'/tw_qe_buy_{tid}'}, {'text': f"⚡ {sym} 🔴 فروش", 'callback_data': f'/tw_qe_sell_{tid}'}]
    return [qe + ([chart] if chart else [])]


_TOUCH_FINAL_TXT = {'opened': '✅ ربات بعد از تایید فیلترها وارد شد.',
                    'queued': '⏳ فیلترها تایید شدند و سیگنال به «⏳ صف تایید حرکت» رفت؛ ورود نهایی فقط بعد از اینکه قیمت به نفع معامله حرکت کند و دوباره بررسی شود انجام می‌شود.',
                    'card_sent': '🤝 فیلترها تایید شدند و کارت حالت دستیار (✅ ورود / ❌ رد) برایتان آمد؛ ورود با تصمیم شماست.', 'entered_manual': '✅ با ورود سریع دستی وارد شدید.',
                    'expired': '⌛ مهلت تمام شد؛ ورودی انجام نشد.', 'skipped': '⏭ روی این نماد پوزیشن باز شد؛ از لیست خارج شد.'}


def _touch_card_payload(r, now=None):
    """متن + کیبورد پیامِ مستقلِ هر مورد. دکمه‌ها (ورود سریع، چارت، بروزرسانی) دقیقاً زیر همین مورد هستند."""
    now = now or time.time()
    lines = ['🎯 *برخورد با سطح — رأی‌گیری فیلترها*'] + _touch_block_lines(r, None, now)
    if r.get('status') != 'waiting':
        lines += ['', _TOUCH_FINAL_TXT.get(r.get('status'), 'پایان')]
        return '\n'.join(lines), {'inline_keyboard': []}
    rows = _touch_buttons(r) + [[{'text': '🔄 بروزرسانی', 'callback_data': f"/tw_ref_{r['id']}"}]]
    return '\n'.join(lines), {'inline_keyboard': rows}


def _touch_card_text(r, now=None):
    return _touch_card_payload(r, now)[0]


def _touch_waiting_recs(s):
    now = time.time()
    with _TOUCH_LOCK:
        recs = [r for r in (s.get('touch_wait') or {}).values() if r.get('status') == 'waiting' and float(r.get('expires_at', 0) or 0) > now]
    recs.sort(key=lambda r: -float(r.get('created_at', 0) or 0))
    return recs


def _touch_send_card(chat_id, rec):
    """کارت مستقل این مورد را (جدید، پایین چت) می‌فرستد؛ کارت قبلیِ همین مورد حذف می‌شود تا تکراری نشود."""
    if not is_allowed(chat_id):
        return False
    old = rec.get('msg_id')
    if old:
        tg('deleteMessage', {'chat_id': chat_id, 'message_id': old}, 10)
        rec['msg_id'] = None
    text, markup = _touch_card_payload(rec)
    res = tg('sendMessage', {'chat_id': chat_id, 'text': text, 'reply_markup': markup, 'parse_mode': 'Markdown'}, 10)
    if res and res.get('ok'):
        rec['msg_id'] = (res.get('result') or {}).get('message_id')
        rec['card_hash'] = hashlib.md5(text.encode('utf-8')).hexdigest()
        rec['card_fail'] = 0
        return True
    return False


def _touch_update_card(chat_id, rec, force=False):
    """کارت همین مورد را درجا ویرایش می‌کند (فقط اگر متن عوض شده باشد). وقتی مورد تمام شد دکمه‌ها برداشته می‌شوند."""
    mid = rec.get('msg_id')
    if not mid or not is_allowed(chat_id):
        return False
    text, markup = _touch_card_payload(rec)
    h = hashlib.md5(text.encode('utf-8')).hexdigest()
    if not force and h == rec.get('card_hash'):
        return True
    res = tg('editMessageText', {'chat_id': chat_id, 'message_id': mid, 'text': text, 'reply_markup': markup, 'parse_mode': 'Markdown'}, 10)
    if res and res.get('ok'):
        rec['card_hash'] = h; rec['card_fail'] = 0
        return True
    rec['card_fail'] = int(rec.get('card_fail', 0) or 0) + 1
    if rec['card_fail'] >= 3:
        rec['msg_id'] = None          # پیام پاک شده/قابل ویرایش نیست؛ با باز کردن لیست دوباره ساخته می‌شود
    return False


def touch_card_refresh(chat_id, tid):
    """دکمه‌ی 🔄 زیر هر کارت: فیلترها دوباره سنجیده می‌شوند و فقط همان کارت ویرایش می‌شود."""
    s = get_session(chat_id)
    rec = (s.get('touch_wait') or {}).get(tid)
    if not rec:
        send_message(chat_id, 'ℹ️ این مورد دیگر در لیست نیست.'); return
    ctx = getattr(_CB_CTX, 'data', None)
    if ctx and ctx.get('chat_id') == chat_id and ctx.get('message_id'):
        rec['msg_id'] = ctx['message_id']
        ctx['used'] = True
    if rec.get('status') == 'waiting':
        try:
            _touch_eval_one(chat_id, rec)
        except Exception:
            logger.exception('touch card refresh failed symbol=%s', rec.get('symbol'))
    _touch_update_card(chat_id, rec, force=True)
    save_session(chat_id)


def _touch_tick(chat_id):
    s = get_session(chat_id)
    now = time.time()
    changed = False
    for r in [r for r in (s.get('touch_wait') or {}).values() if r.get('status') == 'waiting']:
        try:
            if any(p.get('symbol') == r['symbol'] for p in s.get('paper_positions', [])):
                r['status'] = 'skipped'; r['finished_at'] = now; changed = True
                try: _fn_touch_final(chat_id, r)
                except Exception: pass
                _touch_update_card(chat_id, r, force=True); continue
            if now >= float(r.get('expires_at', 0) or 0):
                r['status'] = 'expired'; r['finished_at'] = now; changed = True
                try: _fn_touch_final(chat_id, r)
                except Exception: pass
                _touch_update_card(chat_id, r, force=True); continue
            if now - float(r.get('last_eval', 0) or 0) < TOUCH_EVAL_INTERVAL_SECONDS:
                continue
            _touch_eval_one(chat_id, r)
            changed = True
            if r.get('auto_ok') and gate_on(s, 'gate_touch_vote_enabled'):
                _touch_auto_enter(chat_id, r)
            _touch_update_card(chat_id, r)
        except Exception:
            logger.exception('touch tick failed chat=%s symbol=%s', chat_id, r.get('symbol'))
    if changed:
        save_session(chat_id)


def _touch_wait_loop():
    while True:
        try:
            for chat_id, s in list(USER_SESSIONS.items()):
                try:
                    if any(r.get('status') == 'waiting' for r in (s.get('touch_wait') or {}).values()):
                        _touch_tick(chat_id)
                except Exception:
                    logger.exception('touch wait loop per-user failure chat=%s', chat_id)
        except Exception:
            logger.exception('touch wait loop failed')
        time.sleep(10)
# END V3.44.14


def _assist_pending_recs(s):
    """همه‌ی سیگنال‌های در انتظار (ذخیره‌شده + منتظر تصمیم)، جدیدترین اول. V3.42: بدون فیلتر زمان."""
    now = time.time()
    with _ASSIST_LOCK:
        recs = [r for r in (s.get('assist_log') or [])
                if r.get('status') == 'pending' and (r.get('saved') or float(r.get('expires_at', 0) or 0) > now)]
    recs.sort(key=lambda r: float(r.get('created_at', 0) or 0), reverse=True)
    return recs


PENDING_HIGH_VOTE_PCT = min(1.0, max(0.5, float(os.environ.get('PENDING_HIGH_VOTE_PCT', '0.70'))))   # V3.44.24: حد «رأی بالا» (نسبت فیلترهای موافق به کل)
_PENDING_VF_ORDER = ('all', 'high', 'full')
_PENDING_VF_LABEL = {'all': '🔘 نمایش: همه', 'high': f'🔥 نمایش: رأی بالا (≥{int(round(PENDING_HIGH_VOTE_PCT * 100))}٪)', 'full': '💯 نمایش: رأی کامل'}


def _pending_vote_ok(r, mode):
    """آیا این مورد «برخورد با سطح» با فیلتر نمایش (all/high/full) جور است؟ بدون جهت یا بدون فیلتر در حالت فیلتر نمایش داده نمی‌شود."""
    if mode == 'all':
        return True
    try:
        agree, total = int(r.get('agree', 0) or 0), int(r.get('total', 0) or 0)
    except Exception:
        return False
    if not r.get('dir') or total <= 0:
        return False
    return agree == total if mode == 'full' else (agree / total) >= PENDING_HIGH_VOTE_PCT - 1e-9


def pending_vote_filter_cycle(chat_id, message_id=None):
    """دکمه‌ی فیلتر لیست انتظار: همه ← رأی بالا ← رأی کامل ← همه؛ همان پیام لیست درجا بروز می‌شود."""
    s = get_session(chat_id)
    cur = s.get('pending_vote_filter') if s.get('pending_vote_filter') in _PENDING_VF_ORDER else 'all'
    s['pending_vote_filter'] = _PENDING_VF_ORDER[(_PENDING_VF_ORDER.index(cur) + 1) % len(_PENDING_VF_ORDER)]
    save_session(chat_id)
    assist_pending_list(chat_id, message_id)


PENDING_PRESSURE_MIN_TOTAL = 4     # V3.44.38: کمتر از این تعداد سیگنال جهت‌دار، پیام فشار بازار با هشدار «نمونه کم» می‌آید


def _pending_pressure_lines(recs, t_all):
    """V3.44.38: فقط اطلاع‌رسانی (هیچ اثری روی رأی‌گیری، ورود یا مسدودسازی ندارد).
    تعداد سیگنال‌های خرید و فروش در «📋 سیگنال‌های در انتظار» (هم کارت‌های دستیار هم برخوردهای در حال رأی‌گیری) و پیام فشار بازار."""
    buy = sell = unk = 0
    for r in recs:
        if r.get('sig') == 'BUY':
            buy += 1
        elif r.get('sig') == 'SELL':
            sell += 1
    for r in t_all:
        d = r.get('dir')
        if d == 'BUY':
            buy += 1
        elif d == 'SELL':
            sell += 1
        else:
            unk += 1
    line = f"📊 خرید: {buy} | فروش: {sell}" + (f" | جهت نامشخص: {unk}" if unk else '')
    if buy > sell:
        msg = '🟢 ظاهراً در بازار فشار خرید بیشتر است'
    elif sell > buy:
        msg = '🔴 ظاهراً در بازار فشار فروش بیشتر است'
    else:
        msg = '⚖️ فعلاً فشار خرید و فروش تقریباً برابر است'
    if buy + sell < PENDING_PRESSURE_MIN_TOTAL:
        msg += ' (تعداد سیگنال کم است؛ اطمینان پایین)'
    return [line, msg]


PENDING_PLAIN_MAX_SYMBOLS = 30


def _assist_pending_list_plain(chat_id, message_id, recs, t_all):
    """V3.44.63: نسخه‌ی کاربر عادی «📋 سیگنال‌های در انتظار»: فقط نام نماد + جهت معامله + دکمه‌ی چارت TradingView.
    هیچ دکمه‌ی قابل‌لمسی برای باز کردن کارت/ورود وجود ندارد (فقط لینک TradingView)؛ بدون رأی‌گیری، مهلت، قیمت و اطلاعات فنی."""
    items, seen = [], set()
    for r in recs:                                   # کارت‌های دستیار: جهت = sig
        sym = r.get('symbol')
        if sym and sym not in seen:
            seen.add(sym); items.append((sym, r.get('tf') or '5min', r.get('sig')))
    for r in t_all:                                  # برخورد با سطح: جهت = dir (ممکن است هنوز مشخص نباشد)
        sym = r.get('symbol')
        if sym and sym not in seen:
            seen.add(sym); items.append((sym, r.get('tf') or '5min', r.get('dir')))

    def _side(d):
        return '🟢 خرید' if d == 'BUY' else ('🔴 فروش' if d == 'SELL' else '⏳ جهت نامشخص')

    shown = items[:PENDING_PLAIN_MAX_SYMBOLS]
    # V3.44.81: لیست متنیِ بالا حذف شد؛ جهت خرید/فروش روی خود دکمه‌ی هر نماد نوشته می‌شود (پیام فقط یک تیتر کوتاه دارد).
    lines = [f"📋 *سیگنال‌های در انتظار ({len(items)})*"]
    rows = []
    for sym, tf, d in shown:
        rows.append([{'text': f"📈 {sym} {_side(d)} — TradingView", 'url': tradingview_chart_url(sym, tf)}])
    if len(items) > len(shown):
        lines.append(f"… و {len(items) - len(shown)} نماد دیگر")
    send_message(chat_id, "\n".join(lines), {'inline_keyboard': rows}, message_id=message_id)


def assist_pending_list(chat_id, message_id=None):
    """V3.42: لیست همه‌ی نمادهای در انتظار بدون زمان؛ هر ردیف با یک لمس کارت سیگنال را دوباره پایین چت می‌آورد."""
    s = get_session(chat_id)
    recs = _assist_pending_recs(s)
    t_all = _touch_waiting_recs(s)
    if not recs and not t_all:
        send_message(chat_id, '✅ الان هیچ سیگنالی در انتظار تصمیم شما نیست.', message_id=message_id)
        return
    if is_restricted_user(chat_id):                  # V3.44.62: کاربر عادی لیست ساده می‌بیند
        _assist_pending_list_plain(chat_id, message_id, recs, t_all)
        return
    vf = s.get('pending_vote_filter') if s.get('pending_vote_filter') in _PENDING_VF_ORDER else 'all'
    t_recs = [r for r in t_all if _pending_vote_ok(r, vf)]
    shown = recs[:25]
    lines = [f"📋 *سیگنال‌های در انتظار ({len(recs) + len(t_recs)})*"]
    try:
        lines.extend(_pending_pressure_lines(recs, t_all))
    except Exception:
        logger.exception('pending pressure line failed')
    lines.append("")
    if vf != 'all':
        lines.append(f"🔎 فیلتر رأی: {'≥' + str(int(round(PENDING_HIGH_VOTE_PCT * 100))) + '٪ فیلترها موافق' if vf == 'high' else 'همه‌ی فیلترها موافق'} — {len(t_recs)} از {len(t_all)} مورد برخورد با سطح")
        lines.append("")
    rows = [[{'text': _PENDING_VF_LABEL[vf], 'callback_data': '/pending_vote_filter'}]]
    n = 0
    t_shown = t_recs[:TOUCH_CARDS_PER_LIST]
    _t_done = 0
    if t_all and not t_recs:
        lines.append(f"🎯 هیچ موردِ برخورد با سطح با این فیلتر جور نیست ({len(t_all)} مورد پنهان شد؛ برای دیدن همه، دکمه‌ی نمایش را بزنید).")
        lines.append("")
    if t_recs:
        lines.append(f"🎯 *برخورد با سطح — رأی‌گیری فیلترها: {len(t_recs)} مورد*")
        lines.append(f"🤖 ورود خودکار: {TOUCH_AUTO_LABELS.get(s.get('touch_auto_mode', 'all'), '')}")
        lines.append("")
        _now = time.time()
        for r in t_shown:
            if sum(len(x) + 1 for x in lines) > 3300:
                break
            n += 1
            _t_done += 1
            d = r.get('dir')
            tf = r.get('tf') or '5min'
            _rem = max(0, int((float(r.get('expires_at', 0) or 0) - _now + 59) // 60))
            agree, total = int(r.get('agree', 0) or 0), int(r.get('total', 0) or 0)
            if d:
                side_txt = '🟢 خرید' if d == 'BUY' else '🔴 فروش'
                vote_txt = f"✅ {agree} از {total} رأی موافق"
                btn_icon = '🟢' if d == 'BUY' else '🔴'
                btn_votes = f" ({agree}/{total})"
            else:
                side_txt = '⏳ جهت نامشخص'
                vote_txt = f"{total} فیلتر" if total else 'بدون فیلتر روشن'
                btn_icon = '⏳'
                btn_votes = ''
            lines.append(f"{n}) `{r['symbol']}`{' 🔁' if r.get('flipped_from') else ''} {side_txt} · {vote_txt} · {TF_DISPLAY.get(tf, tf)} · ⏳ {_rem} دقیقه")
            rows.append([{'text': f"🔎 {r['symbol']} {btn_icon}{btn_votes}", 'callback_data': f"/tw_open_{r['id']}"}])
        if len(t_recs) > _t_done:
            lines.append(f"… و {len(t_recs) - _t_done} مورد دیگر برخورد با سطح (بعد از ورود یا انقضای این‌ها نمایش داده می‌شوند)")
        lines.append("")
    _a_done = 0
    for r in shown:
        if sum(len(x) + 1 for x in lines) > 3300:
            break
        n += 1
        _a_done += 1
        is_long = r['sig'] == 'BUY'
        tf = r.get('tf') or '5min'
        side_txt = '🟢 خرید' if is_long else '🔴 فروش'
        if r.get('saved'):
            state_txt = '💾 ذخیره‌شده (بدون مهلت)'
        else:
            _rem_min = max(0, int((float(r.get('expires_at', 0) or 0) - time.time() + 59) // 60))
            state_txt = ('⚠️ منتظر تایید (هشدار روند)' if r.get('auto_gate') else 'منتظر تصمیم') + f' · ⏳ {_rem_min} دقیقه'
        try:
            live = latest_price(r['symbol'])
        except Exception:
            live = None
        price_txt = ''
        risk = abs(float(r['entry']) - float(r['sl']))
        if live and risk > 0:
            fav = ((float(live) - float(r['entry'])) if is_long else (float(r['entry']) - float(live))) / risk
            crossed_sl = (live <= r['sl']) if is_long else (live >= r['sl'])
            crossed_tp = (live >= r['tp']) if is_long else (live <= r['tp'])
            flag = ' ⚠️ از SL رد شده' if crossed_sl else (' ⚠️ از TP رد شده' if crossed_tp else '')
            price_txt = f" | لحظه‌ای `{fmt(float(live))}` (`{fav:+.2f}R`){flag}"
        lines.append(f"{n}) `{r['symbol']}` {side_txt} · {TF_DISPLAY.get(tf, tf)} · {state_txt}")
        lines.append(f"    ورود `{fmt(float(r['entry']))}`{price_txt}")
        rows.append([{'text': f"🔎 {r['symbol']} {'🟢' if is_long else '🔴'}" + (' 💾' if r.get('saved') else ''), 'callback_data': f"/assist_open_{r['id']}"}])
    if len(recs) > _a_done:
        lines.append(f"\n… و {len(recs) - _a_done} سیگنال دیگر (جدیدترین‌ها اول نمایش داده شد)")
    lines.append("\nروی نماد هر ردیف بزنید تا کارت همان سیگنال پایین چت بیاید. (`R` مثبت یعنی قیمت به نفع سیگنال رفته)")
    rows.append([{'text': '🔄 بروزرسانی', 'callback_data': '/assist_pending'}])
    rows.append([{'text': '⏳ صف تایید حرکت', 'callback_data': '/fav_queue'}])
    send_message(chat_id, "\n".join(lines), {'inline_keyboard': rows}, message_id=message_id)


def touch_open_card(chat_id, tid):
    """V3.44.21: لمس نماد در «📋 سیگنال‌های در انتظار» (بخش برخورد با سطح): فیلترها دوباره سنجیده می‌شوند و کارت همان مورد پایین چت می‌آید."""
    s = get_session(chat_id)
    rec = (s.get('touch_wait') or {}).get(tid)
    if not rec or rec.get('status') != 'waiting':
        send_message(chat_id, 'ℹ️ این مورد دیگر در لیست انتظار نیست.'); return
    try:
        _touch_eval_one(chat_id, rec)
    except Exception:
        logger.exception('touch open eval failed symbol=%s', rec.get('symbol'))
    if not _touch_send_card(chat_id, rec):
        send_message(chat_id, '⚠️ نمایش کارت ناموفق بود؛ چند ثانیه بعد دوباره امتحان کنید.'); return
    save_session(chat_id)


def _assist_card_text(rec):
    """متن کارت سیگنال را از رکورد دوباره می‌سازد (فقط برای حالتی که پیام اصلی دیگر قابل کپی نیست)."""
    if rec.get('auto_gate') and rec.get('card_text'):
        return rec['card_text']
    tf = rec.get('tf') or '5min'
    is_long = rec['sig'] == 'BUY'
    level_txt, scn_txt = _assist_describe_source(rec.get('reason') or '', rec.get('level_token'), rec.get('level_value'), rec.get('scn'))
    lines = [
        _tf_regime_line(tf),
        _symbol_regime_line(rec.get('symbol_regime'), tf),
        f"• `{rec['symbol']}` ({'🟢 خرید' if is_long else '🔴 فروش'}) | تایم‌فریم: `{TF_DISPLAY.get(tf, tf)}`",
        f"• سطح: `{level_txt}` | سناریو: `{scn_txt}`",
        f"• ورود پیشنهادی: `{fmt(float(rec['entry']))}` | SL: `{fmt(float(rec['sl']))}`",
        f"• TP: `{fmt(float(rec['tp']))}`",
        f"• R:R: `{float(rec.get('rr') or 0):.2f}`" + (f" | کیفیت: `{rec['score']}/100`" if rec.get('score') is not None else ""),
    ]
    if rec.get('exp_tp_pnl_net') is not None and rec.get('exp_sl_pnl_net') is not None:
        lines.append(f"• 💰 TP: `{float(rec['exp_tp_pnl_net']):+.2f}` USDT")
        lines.append(f"• 🛑 SL: `{float(rec['exp_sl_pnl_net']):+.2f}` USDT")
    return "\n".join(lines)


def assist_open(chat_id, aid):
    """کارت سیگنال در انتظار را با همان دکمه‌ها (و شمارش معکوس فعلی) دوباره پایین چت می‌آورد؛ کارت قبلی فقط دکمه‌ی چارت را نگه می‌دارد."""
    s = get_session(chat_id)
    rec = _assist_pending_or_notify(chat_id, s, aid)
    if not rec:
        return
    old_mid = rec.get('message_id')
    markup = _auto_gate_markup(aid, rec['symbol'], rec.get('tf') or '5min') if rec.get('auto_gate') else _assist_markup(rec)
    new_mid = None
    if old_mid:
        res = tg('copyMessage', {'chat_id': chat_id, 'from_chat_id': chat_id, 'message_id': old_mid, 'reply_markup': markup}, 15)
        if res and res.get('ok'):
            new_mid = (res.get('result') or {}).get('message_id')
    if new_mid is None:      # پیام اصلی حذف شده/قابل کپی نیست → کارت از روی رکورد ساخته می‌شود
        res = tg('sendMessage', {'chat_id': chat_id, 'text': _assist_card_text(rec), 'parse_mode': 'Markdown', 'reply_markup': markup}, 10)
        if res and res.get('ok'):
            new_mid = (res.get('result') or {}).get('message_id')
    if new_mid is None:
        send_message(chat_id, '⚠️ نمایش کارت سیگنال ناموفق بود؛ چند ثانیه بعد دوباره امتحان کنید.'); return
    with _ASSIST_LOCK:
        if old_mid and old_mid != new_mid:
            rec.setdefault('old_mids', []).append(old_mid)   # V3.38.8: کارت قدیمی هم در پاک‌سازی روز بعد حذف شود
        rec['message_id'] = new_mid
        _ASSIST_CD_LAST.pop(aid, None)
    save_session(chat_id)
    if old_mid and old_mid != new_mid:
        _assist_strip_buttons(chat_id, old_mid, rec)


def _assist_pending_or_notify(chat_id, s, aid):
    """rec در انتظار و منقضی‌نشده را برمی‌گرداند؛ وگرنه پیام مناسب می‌فرستد و None برمی‌گرداند."""
    with _ASSIST_LOCK:
        rec = _assist_find(s, aid)
        if not rec or rec['status'] != 'pending':
            send_message(chat_id, 'ℹ️ این سیگنال دیگر در انتظار تصمیم نیست.'); return None
        if _assist_now() > float(rec['expires_at']) + ASSIST_SAVE_GRACE_SECONDS and not rec.get('saved'):
            rec['status'] = 'expired'
            save_session(chat_id); _assist_strip_buttons(chat_id, rec.get('message_id'), rec)
            send_message(chat_id, '⌛ مهلت تایید این سیگنال تمام شده بود؛ برای ارزیابی ثبت شد.'); return None
        return rec


def assist_reverse(chat_id, aid, skip_trend=False):
    """معامله‌ی برعکسِ جهت سیگنال، با قیمت لحظه‌ای (همان مسیر ورود سریع: SL/TP از سوینگ/ATR و سطح مقابل)."""
    s = get_session(chat_id)
    rec = _assist_pending_or_notify(chat_id, s, aid)
    if not rec:
        return
    symbol = rec['symbol']
    opp = 'SELL' if rec['sig'] == 'BUY' else 'BUY'
    if not skip_trend and _assist_trend_warn(chat_id, symbol, opp, f'/assist_revok_{aid}', '/assist_trendcancel'):
        return
    had = any(p.get('symbol') == symbol for p in s.get('paper_positions', []))
    quick_channel_trade(chat_id, symbol, opp, skip_trend=True)      # هشدار روند همین چند خط بالاتر انجام شده
    s = get_session(chat_id)
    opened = (not had) and any(p.get('symbol') == symbol for p in s.get('paper_positions', []))
    if opened:
        with _ASSIST_LOCK:
            rec = _assist_find(s, aid) or rec
            # سیگنال اصلی «ردشده» حساب می‌شود تا نتیجه‌ی فرضی‌اش برای آمار پیگیری شود
            rec['status'] = 'rejected'; rec['rejected_at'] = time.time(); rec['reversed'] = True
        save_session(chat_id)
        _assist_strip_buttons(chat_id, rec.get('message_id'), rec)


def assist_manual_start(chat_id, aid):
    s = get_session(chat_id)
    rec = _assist_pending_or_notify(chat_id, s, aid)
    if not rec:
        return
    try:
        live = exchange_latest_price(chat_id, rec['symbol']) if s.get('trading_mode') == 'REAL' else latest_price(rec['symbol'])
    except Exception:
        live = None
    s['user_state'] = 'WAIT_MANUAL_ENTRY_PRICE'
    s['_manual_entry_ctx'] = {'kind': 'assist', 'aid': aid}
    save_session(chat_id)
    send_message(chat_id,
        f"✏️ *ورود با قیمت دستی — `{rec['symbol']}`*\n"
        f"قیمت ورود دلخواهت را (فقط عدد) بفرست.\n"
        f"• ورود پیشنهادی ربات: `{fmt(rec['entry'])}`" + (f" | لحظه‌ای: `{fmt(live)}`" if live else "") + "\n"
        f"• SL `{fmt(rec['sl'])}` و TP `{fmt(rec['tp'])}` همان سیگنال می‌مانند.\n"
        f"معامله وقتی قیمت به عدد تو برسد باز می‌شود.")


def manual_entry_start_channel(chat_id, symbol, side):
    """شروع ورود با قیمت دستی از دکمه‌ی زیر پیام کانال."""
    s = get_session(chat_id)
    symbol = re.sub(r'[^A-Z0-9]', '', str(symbol).upper())
    if not (2 <= len(symbol) <= 12):
        send_message(chat_id, '⚠️ نماد نامعتبر است.'); return
    if any(p['symbol'] == symbol for p in s['paper_positions']):
        send_message(chat_id, f'⚠️ برای `{symbol}` همین حالا یک پوزیشن باز داری.'); return
    try:
        live = exchange_latest_price(chat_id, symbol) if s.get('trading_mode') == 'REAL' else latest_price(symbol)
    except Exception:
        live = None
    s['user_state'] = 'WAIT_MANUAL_ENTRY_PRICE'
    s['_manual_entry_ctx'] = {'kind': 'qt', 'symbol': symbol, 'side': side}
    save_session(chat_id)
    send_message(chat_id,
        f"✏️ *ورود با قیمت دستی — `{symbol}` ({'🟢 خرید' if side == 'BUY' else '🔴 فروش'})*\n"
        f"قیمت ورود دلخواهت را (فقط عدد) بفرست." + (f"\nقیمت لحظه‌ای: `{fmt(live)}`" if live else "") + "\n"
        f"SL/TP بر اساس همان قیمت ورود ساخته می‌شوند و معامله وقتی قیمت به عدد تو برسد باز می‌شود.")


def manual_entry_price_received(chat_id, raw):
    s = get_session(chat_id)
    ctx = dict(s.get('_manual_entry_ctx') or {})
    s['user_state'] = None
    save_session(chat_id)
    try:
        price = float(str(raw).replace(',', '').strip())
        if not math.isfinite(price) or price <= 0:
            raise ValueError
    except Exception:
        send_message(chat_id, '⚠️ قیمت معتبر نیست؛ دوباره روی دکمه‌ی «ورود با قیمت دستی» بزن و فقط عدد بفرست.'); return
    if ctx.get('kind') == 'assist':
        rec = _assist_pending_or_notify(chat_id, s, ctx.get('aid'))
        if not rec:
            return
        symbol, side = rec['symbol'], rec['sig']
        sl, tp, tp_name, reason, aid = float(rec['sl']), float(rec['tp']), rec.get('tp_level_name'), rec['reason'], rec['id']
    elif ctx.get('kind') == 'qt':
        symbol, side = ctx['symbol'], ctx['side']
        plan, _ = build_quick_plan_with_fallback(symbol, side, s.get('strategy_config'), price, s['timeframe'])
        sl, tp, tp_name, reason, aid = float(plan['sl']), float(plan['tp']), plan.get('tp_level_name'), plan['reason'], None
    else:
        send_message(chat_id, 'ℹ️ درخواست ورود دستی پیدا نشد؛ دوباره از دکمه‌ی زیر سیگنال شروع کن.'); return
    live = latest_price(symbol)
    if live and abs(price - float(live)) / float(live) > 0.20:
        send_message(chat_id, f"⚠️ قیمت `{fmt(price)}` بیش از ۲۰٪ با قیمت لحظه‌ای (`{fmt(live)}`) فاصله دارد؛ دوباره تلاش کن."); return
    is_long = side == 'BUY'
    if not ((is_long and sl < price < tp) or ((not is_long) and tp < price < sl)):
        send_message(chat_id,
            f"⚠️ با ورود `{fmt(price)}` ترتیب SL/TP با جهت {'خرید' if is_long else 'فروش'} نمی‌خواند "
            f"(باید {'SL < ورود < TP' if is_long else 'TP < ورود < SL'} باشد؛ SL `{fmt(sl)}` | TP `{fmt(tp)}`). قیمت دیگری بفرست."); return
    rr = abs(tp - price) / abs(price - sl)
    _m, _lev = estimate_session_size(chat_id, symbol, price, sl)
    try:
        _prate = float(get_user_fee_rate(chat_id))
    except Exception:
        _prate = None
    lines = [
        f"🖐 *خلاصه‌ی ورود با قیمت دستی*",
        f"• نماد: `{symbol}` ({'🟢 خرید' if is_long else '🔴 فروش'})",
        f"• ورود (دستی): `{fmt(price)}`",
        f"• حد ضرر: `{fmt(sl)}`",
        f"• هدف (TP): `{fmt(tp)}`" + (f" — سطح: `{tp_name}`" if tp_name else ""),
        f"• R:R: `{rr:.2f}`",
    ]
    if rr < MIN_RR_FLOOR:
        lines.append(f"⚠️ R:R کمتر از حداقل `{MIN_RR_FLOOR:g}` است (تصمیم با خودت).")
    lines.extend(pnl_estimate_lines(price, sl, tp, side, _m, _lev, platform_rate=_prate))
    lines.append("\nتایید می‌کنی؟ اوردر ثبت می‌شود و وقتی قیمت به ورودِ تو برسد، معامله باز می‌شود.")
    s['_manual_entry_tmp'] = {'symbol': symbol, 'side': side, 'entry': price, 'sl': sl, 'tp': tp,
                              'tp_level_name': tp_name, 'reason': reason, 'assist_id': aid,
                              'exp_tp_pnl_net': (round(estimate_trade_pnl(price, sl, tp, side, _m, _lev)['tp_net'], 4) if (_m and _lev) else None),
                              'exp_sl_pnl_net': (round(estimate_trade_pnl(price, sl, tp, side, _m, _lev)['sl_net'], 4) if (_m and _lev) else None)}
    save_session(chat_id)
    send_message(chat_id, "\n".join(lines), {'inline_keyboard': [[
        {'text': '✅ ثبت اوردر ورود', 'callback_data': '/confirm_manual_entry'},
        {'text': '❌ انصراف', 'callback_data': '/cancel'}]]})


@_from_signal_origin
def manual_entry_confirm(chat_id, skip_trend=False):
    s = get_session(chat_id)
    tmp = s.get('_manual_entry_tmp')
    if not tmp:
        send_message(chat_id, '⚠️ اطلاعات ورود دستی پیدا نشد یا قبلاً ثبت شده؛ از اول شروع کن.'); return
    symbol = tmp['symbol']
    if any(p['symbol'] == symbol for p in s['paper_positions']):
        send_message(chat_id, f'⚠️ برای `{symbol}` همین حالا یک پوزیشن باز داری.'); return
    aid = tmp.get('assist_id')
    if aid:
        rec = _assist_pending_or_notify(chat_id, s, aid)
        if not rec:
            s.pop('_manual_entry_tmp', None); save_session(chat_id); return
    if not skip_trend and _assist_trend_warn(chat_id, symbol, tmp['side'], '/manual_entry_tgok', '/cancel'):
        return
    order = {
        'order_id': f"{symbol}-{int(time.time())}", 'symbol': symbol,
        'side': 'BUY (Long)' if tmp['side'] == 'BUY' else 'SELL (Short)',
        'trigger_price': None, 'entry_price': tmp['entry'], 'tp': tmp['tp'], 'sl': tmp['sl'],
        'margin': float(s.get('trade_amount_usdt') or 0), 'leverage': s.get('leverage'),
        'created_at': time.time(), 'triggered': True, 'force': True,
        'reason': tmp.get('reason') or 'ورود دستی', 'tp_level_name': tmp.get('tp_level_name'), 'assist_id': aid,
        'exp_tp_pnl_net': tmp.get('exp_tp_pnl_net'), 'exp_sl_pnl_net': tmp.get('exp_sl_pnl_net'),
    }
    s.setdefault('pending_orders', []).append(order)
    if aid:
        with _ASSIST_LOCK:
            rec = _assist_find(s, aid)
            if rec:
                rec['status'] = 'approved'; rec['approved_at'] = time.time(); rec['manual_entry'] = tmp['entry']
        _assist_strip_buttons(chat_id, (rec or {}).get('message_id'), rec)
    s.pop('_manual_entry_tmp', None)
    save_session(chat_id)
    send_message(chat_id, f"✅ اوردر `{symbol}` با ورود `{fmt(tmp['entry'])}` ثبت شد؛ وقتی قیمت به آن برسد با همین SL/TP معامله باز می‌شود.", pending_orders_keyboard(chat_id))


def _assist_resolve_shadow(rec, tf, df):
    """با کندل‌های بعد از لحظه‌ی سیگنال تعیین می‌کند اگر وارد شده بودیم اول SL می‌خورد یا TP.
    اگر هر دو در یک کندل باشند محافظه‌کارانه SL حساب می‌شود."""
    try:
        ts = df['timestamp'].astype('float64')
        if ts.max() > 1e12:
            ts = ts / 1000.0
        is_long = rec['sig'] == 'BUY'
        for t, hi, lo in zip(ts.values, df['high'].values, df['low'].values):
            if t < rec['created_at']:
                continue
            hit_sl = (lo <= rec['sl']) if is_long else (hi >= rec['sl'])
            hit_tp = (hi >= rec['tp']) if is_long else (lo <= rec['tp'])
            if hit_sl:
                return {'outcome': 'sl', 'r': -1.0, 'ts': float(t)}
            if hit_tp:
                return {'outcome': 'tp', 'r': float(rec.get('rr') or 0.0), 'ts': float(t)}
    except Exception:
        logger.exception('assist shadow resolve failed')
    return None


def assist_maintenance_once():
    now = time.time()
    for chat_id, s in list(USER_SESSIONS.items()):
        try:
            log = s.get('assist_log') or []
            if not log:
                continue
            changed = False
            for rec in log:
                if rec.get('status') == 'pending' and now > rec.get('expires_at', 0) and not rec.get('saved'):
                    _expired_now = False
                    with _ASSIST_LOCK:
                        # V3.42.12: بین بررسی شرط و قفل ممکن است کاربر «ذخیره» را زده باشد؛ دوباره چک می‌کنیم
                        if rec.get('status') == 'pending' and not rec.get('saved') and now > rec.get('expires_at', 0):
                            rec['status'] = 'expired'; changed = True; _expired_now = True
                    if _expired_now:
                        _assist_strip_buttons(chat_id, rec.get('message_id'), rec)
            # V3.38.8: کارت سیگنال‌های منقضی/نامعتبر ۱ ساعت بعد از انقضا از چت پاک می‌شوند (خودِ رکورد و آمار سایه می‌ماند).
            if ASSIST_EXPIRED_DELETE_AFTER_SECONDS > 0:
                for rec in log:
                    if (rec.get('status') in ('expired', 'invalidated') and not rec.get('msg_deleted')
                            and now - float(rec.get('expires_at', 0) or 0) >= ASSIST_EXPIRED_DELETE_AFTER_SECONDS):
                        for mid in ([rec.get('message_id')] + list(rec.get('old_mids') or [])):
                            if mid:
                                try: tg('deleteMessage', {'chat_id': chat_id, 'message_id': mid}, 10)
                                except Exception: logger.exception('assist: expired card delete failed')
                        rec['msg_deleted'] = True; rec['message_id'] = None; rec['old_mids'] = []; changed = True
            todo = [r for r in log if r.get('status') in ('rejected', 'expired', 'invalidated') and not r.get('shadow_done')]
            by_symbol = {}
            for r in todo:
                by_symbol.setdefault(r['symbol'], []).append(r)
            for sym, recs in by_symbol.items():
                try:
                    df = get_klines_for(chat_id, sym, recs[0].get('tf') or '5min', 300)
                except Exception:
                    df = None
                if df is None or getattr(df, 'empty', True):
                    continue
                for r in recs:
                    res = _assist_resolve_shadow(r, r.get('tf'), df)
                    if res:
                        r['shadow'] = res; r['shadow_done'] = True; changed = True
                    elif now - r['created_at'] > ASSIST_SHADOW_HORIZON_SECONDS:
                        r['shadow'] = {'outcome': 'timeout', 'r': None, 'ts': now}; r['shadow_done'] = True; changed = True
            if changed:
                save_session(chat_id)
        except Exception:
            logger.exception('V3.42.13 per-user failure isolated: %s chat=%s', 'assist_maintenance_once', chat_id)  # خطای یک کاربر بقیه را متوقف نکند


def _assist_loop():
    tick = 0
    while True:
        if tick % 3 == 0:          # برچسب شمارش معکوس (فقط کارت‌های قدیمیِ تمدیدشده) هر ~۱۵ ثانیه
            try:
                assist_countdown_once()
            except Exception:
                logger.exception('assist countdown failed')
        if tick % 6 == 0:          # نگهداری اصلی (کندل‌ها/سایه) هر ~۳۰ ثانیه
            try:
                assist_maintenance_once()
            except Exception:
                logger.exception('assist maintenance failed')
        try:
            assist_saved_touch_once()     # V3.42: پایش تاچ ورود سیگنال‌های ذخیره‌شده (هر ~۵ ثانیه)
        except Exception:
            logger.exception('assist saved touch failed')
        tick += 1
        time.sleep(5)


def assist_stats_text(s):
    log = list(s.get('assist_log') or [])
    if not log:
        return '📊 هنوز هیچ سیگنالی از حالت دستیار ثبت نشده است.'
    from collections import Counter
    c = Counter(r.get('status') for r in log)
    lines = ['📊 *آمار حالت دستیار*',
             f"• کل سیگنال‌ها: `{len(log)}` | تاییدشده: `{c.get('approved', 0)}` | ردشده: `{c.get('rejected', 0)}` | منقضی: `{c.get('expired', 0)}` | در انتظار: `{c.get('pending', 0)}`"]
    ids = {r['id'] for r in log if r.get('status') == 'approved'}
    trades = [p for p in closed_for_mode(s) if p.get('assist_id') in ids]
    open_n = sum(1 for p in open_for_mode(s) if p.get('assist_id') in ids)
    lines.append('\n*معاملات تاییدشده (نتیجه‌ی واقعی):*')
    if trades:
        wins = sum(1 for p in trades if float(p.get('pnl_usdt') or 0) > 0)
        avg_r = sum(float(p.get('realized_r') or 0) for p in trades) / len(trades)
        net = sum(float(p.get('pnl_usdt') or 0) for p in trades)
        lines.append(f"• بسته‌شده: `{len(trades)}` | نرخ برد: `{wins / len(trades) * 100:.0f}%` | میانگین R: `{avg_r:+.2f}` | مجموع: `{net:+.2f}` USDT")
    else:
        lines.append('• هنوز معامله‌ی بسته‌شده‌ای نداریم.')
    if open_n:
        lines.append(f"• باز: `{open_n}`")
    sh = [r for r in log if r.get('shadow_done') and (r.get('shadow') or {}).get('outcome') in ('tp', 'sl')]
    lines.append('\n*ردشده/منقضی‌شده‌ها (اگر وارد شده بودیم):*')
    if sh:
        w = sum(1 for r in sh if r['shadow']['outcome'] == 'tp')
        avg_r_sh = sum(float(r['shadow']['r']) for r in sh) / len(sh)
        lines.append(f"• تعیین‌تکلیف‌شده: `{len(sh)}` | می‌برد: `{w / len(sh) * 100:.0f}%` | میانگین R فرضی: `{avg_r_sh:+.2f}`")
        if trades:
            avg_r = sum(float(p.get('realized_r') or 0) for p in trades) / len(trades)
            verdict = ('✅ تشخیص شما تا الان بهتر از پذیرش کورکورانه‌ی همه‌ی سیگنال‌ها عمل کرده.'
                       if avg_r > avg_r_sh else '⚠️ تا الان رد کردن‌های شما بهتر از تایید کردن‌ها نبوده.')
            lines.append(f"\n{verdict}")
    else:
        lines.append('• هنوز نتیجه‌ی فرضی‌ای تعیین‌تکلیف نشده (تا ۲۴ ساعت پیگیری می‌شود).')
    n_small = len(trades) < 30 or len(sh) < 30
    if n_small:
        lines.append('\n_توجه: نمونه هنوز کمتر از ۳۰ مورد است؛ نتیجه‌گیری قطعی نکنید._')
    return '\n'.join(lines)


