def strategy_families_keyboard(chat_id):
    """فقط سوییچ‌های فعال/غیرفعال هر خانواده‌ی استراتژی - جدا از فیلترهای دیگر."""
    s = get_session(chat_id)
    scfg = s.get('strategy_config') or {}

    def cell(flag_val, on_label, cb):
        icon = '🟢' if flag_val else '🔴'
        # V3.44.49: تلگرام متن بلند دکمه را از ابتدا می‌برد و آیکن روشن/خاموش دیده نمی‌شود؛ برچسب‌ها کوتاه نگه داشته می‌شوند
        if len(on_label) > 46:
            on_label = on_label[:45].rstrip() + '…'
        return {'text': f'{icon} {on_label}', 'callback_data': cb}

    # تنها یک استراتژی معاملاتی وجود دارد - Liquidity Sweep پنج‌سطحی (۵/۱۵ دقیقه).
    # Trend Following، Breakout، Mean Reversion، ORB/Judas، برگشت در ۱ و ۴ ساعته و سطوح ساعات بازار
    # کامل از کد حذف شدند؛ دیگر دکمه‌ای ندارند.
    sweep_on = bool(scfg.get('strategy_sweep_enabled', True))

    return {
        'inline_keyboard': [
            [cell(sweep_on, 'دام قیمتی (چارت ۵ و ۱۵ دقیقه)', '/toggle_strategy_sweep')],
            [{'text': '🔙 قوانین معامله (فیلترها)', 'callback_data': '/trade_filter_management'}],
            [{'text': '🏠 منوی اصلی', 'callback_data': '/menu'}],
        ]
    }


def trade_pipeline_report(chat_id):
    s = get_session(chat_id)
    events = list(s.get('trade_pipeline_audit') or [])
    if not events:
        return '🔎 *ممیزی کامل مسیر معاملات*\n\nهنوز داده‌ای ثبت نشده است. اول از دکمه‌ی «ردیابی معاملات» روشنش کن.'
    events = events[-120:]
    lines = ['🔎 *ممیزی کامل مسیر معاملات*', '━━━━━━━━━━━━━━━━━━━━', f'📌 آخرین رویدادها: `{len(events)}`', '']
    grouped = {}
    for e in events:
        key = f"{e.get('symbol','?')}|{e.get('timeframe','?')}"
        grouped.setdefault(key, []).append(e)
    for key, rows in list(grouped.items())[-40:]:
        last = rows[-1]
        first = rows[0]
        path = ' → '.join(str(x.get('stage') or '—') for x in rows[-8:])
        status = last.get('status', '—')
        reason = last.get('reason', '—')
        scan_time = first.get('scan_time') or fmt_scan_time(first.get('ts'))
        setup_tag = last.get('setup_tag') or first.get('setup_tag')
        line = f"• `{key}` → `{status}`\n  🕒 زمان اسکن: `{scan_time}`"
        if setup_tag:
            line += f"\n  🎯 ستاپ: `{setup_tag}`"
        line += f"\n  مسیر: `{path}`\n  علت نهایی: {reason}"
        lines.append(line)
    return '\n'.join(lines)


def export_trade_pipeline(chat_id):
    if not is_allowed(chat_id) or not TELEGRAM_TOKEN:
        return False
    s = get_session(chat_id)
    pipeline = list(s.get('trade_pipeline_audit') or [])
    opens = [audit_trade_record(p) for p in open_for_mode(s)]
    closes = [audit_trade_record(p) for p in closed_for_mode(s)]
    payload = {
        'report_metadata': {
            'report_type': 'trade_pipeline_audit',
            'generated_at': time.time(),
            'chat_id': chat_id,
            'account_mode': 'REAL' if _mode_is_real(s) else 'PAPER',
            'timeframe': s.get('timeframe'),
            'audit_enabled': bool(s.get('trade_pipeline_enabled', False)),
        },
        'pipeline_events': pipeline,
        'open_positions': opens,
        'closed_positions': closes,
    }
    raw = json.dumps(payload, ensure_ascii=False, indent=2, default=str).encode('utf-8')
    try:
        fname = f"trade_pipeline_audit_{s.get('timeframe','5min')}_{time.strftime('%Y-%m-%d_%H-%M-%S', time.localtime())}.json"
        caption = f'🧭 خروجی کامل ممیزی Pipeline | تایم‌فریم: {TF_DISPLAY.get(s.get("timeframe"),s.get("timeframe"))}'
        resp = requests.post(f'https://api.telegram.org/bot{TELEGRAM_TOKEN}/sendDocument', data={'chat_id': chat_id, 'caption': caption}, files={'document': (fname, io.BytesIO(raw), 'application/json')}, timeout=30)
        try: schedule_auto_delete(chat_id, (((resp.json() or {}).get('result') or {}).get('message_id')))
        except Exception: pass
        if not resp.ok or not (resp.json() or {}).get('ok', False):
            logger.warning('export trade pipeline telegram send failed: %s', resp.text[:500])
            send_message(chat_id, '❌ خروجی JSON ممیزی ساخته شد اما ارسال فایل به تلگرام ناموفق بود.')
            return False
        return True
    except Exception as exc:
        logger.warning('export trade pipeline failed: %s', exc)
        send_message(chat_id, f'❌ خطا در خروجی JSON ممیزی: {exc}')
        return False


def full_reset(chat_id):
    """پاک کردن کامل سشن این کاربر (پوزیشن‌ها، آمار، تنظیمات، فیلترها، همه‌چیز) و
    بازگشت به حالت پیش‌فرض کاملاً تازه — دقیقاً مثل یک کاربر جدید."""
    s = get_session(chat_id)
    if s.get('paper_positions'):
        return False, '❌ تا وقتی پوزیشن باز دارید، ریست کامل مجاز نیست. ابتدا همه پوزیشن‌ها را ببندید.'
    if s.get('is_bot_active'):
        stop_scan(chat_id, 'full-reset')
    with STATE_LOCK:
        USER_SESSIONS[chat_id] = default_session()
        _apply_default_mode(chat_id, USER_SESSIONS[chat_id])
    save_session(chat_id)
    return True, '✅ *همه‌چیز پاک شد.*\nحالا از صفر شروع می‌کنیم؛ لطفاً تنظیمات را قدم‌به‌قدم دوباره انتخاب کنید.'


def trade_audit_report(chat_id):
    s=get_session(chat_id); positions=open_for_mode(s); closed=closed_for_mode(s)
    allp=closed+positions
    if not allp: return '🔎 *ممیزی معامله*\n\nهنوز معامله‌ای برای بررسی ثبت نشده است.'
    p=max(allp,key=lambda x: float(x.get('opened_at',0) or 0)); tid=p.get('trade_id','—')
    lines=['🔎 *ممیزی صفر تا صد آخرین پوزیشن*','━━━━━━━━━━━━━━━━━━━━',f'🆔 شناسه: `{tid}`',f'🪙 نماد: `{p.get("symbol")}` | {"LONG" if side_long(p.get("side")) else "SHORT"}',f'⏱ تایم‌فریم: `{TF_DISPLAY.get(p.get("timeframe"),p.get("timeframe"))}`',f'🎯 Entry: `{fmt(p.get("entry_price",0))}` | SL: `{fmt(p.get("sl",0))}` | TP: `{fmt(p.get("tp",0))}`',f'📦 وضعیت: `{"بسته‌شده" if p in closed else "باز"}`']
    if p in closed:
        lines += [f'🚪 خروج: `{fmt(p.get("close_price",0))}`',f'💰 PnL: `{float(p.get("pnl_usdt",0) or 0):+.2f} USDT`',f'📝 علت خروج: `{p.get("close_reason","—")}`']
    return '\n'.join(lines)


def _journal_trades_for(chat_id, real=None):
    """V3.44.65: ژورنال همین چت، فقط مود فعلی (real=None) / مود مشخص؛ real='all' = هر دو."""
    if real is None:
        real = _mode_is_real(get_session(chat_id))
    try:
        path = _journal_path()
        if not os.path.exists(path):
            return []
        with _JOURNAL_LOCK:
            with open(path, 'r', encoding='utf-8') as fh:
                data = json.load(fh)
        return [t for t in (data.get('trades') or []) if str(t.get('chat_id')) == str(chat_id) and (real == 'all' or bool(t.get('is_real')) == bool(real))]
    except Exception:
        logger.exception('journal read failed')
        return []


def preset_stats_text(chat_id):
    return presets_mod.format_stats(presets_mod.summarize(_journal_trades_for(chat_id)))


def export_trade_journal(chat_id):
    """فایل ژورنال معاملات (با برچسب پریست) را به تلگرام می‌فرستد؛ بدون حذف خودکار تا بتوانی فوروارد کنی."""
    if not is_allowed(chat_id) or not TELEGRAM_TOKEN:
        return False
    trades = _journal_trades_for(chat_id)
    raw = json.dumps({'version': 2, 'bot_version': BOT_VERSION, 'chat_id': chat_id, 'generated_at': time.time(), 'trades': trades,
                      'settings': _settings_lookup([t.get('settings_hash') for t in trades]),
                      'rejected': _reject_tail(chat_id, 500)},
                     ensure_ascii=False, indent=1, default=str).encode('utf-8')
    try:
        resp = requests.post(f'https://api.telegram.org/bot{TELEGRAM_TOKEN}/sendDocument',
                             data={'chat_id': chat_id, 'caption': f'📤 ژورنال معاملات حساب {"واقعی" if _mode_is_real(get_session(chat_id)) else "کاغذی"} ({len(trades)} معامله)'},
                             files={'document': ('trade_journal.json', io.BytesIO(raw), 'application/json')}, timeout=30)
        if not resp.ok or not (resp.json() or {}).get('ok', False):
            logger.warning('journal export send failed: %s', resp.text[:500])
            send_message(chat_id, '❌ فایل ژورنال ساخته شد اما ارسال آن به تلگرام ناموفق بود.')
            return False
        return True
    except Exception as exc:
        logger.warning('journal export failed: %s', exc)
        send_message(chat_id, f'❌ خطا در ارسال ژورنال: {exc}')
        return False


def export_trade_data(chat_id):
    if not is_allowed(chat_id) or not TELEGRAM_TOKEN: return False
    s=get_session(chat_id)
    payload={'generated_at':time.time(),'chat_id':chat_id,'account_mode':'REAL' if _mode_is_real(s) else 'PAPER','open_positions':[audit_trade_record(p) for p in open_for_mode(s)],'closed_positions':[audit_trade_record(p) for p in closed_for_mode(s)],'trade_audit':s.get('trade_audit',[])}
    raw=json.dumps(payload,ensure_ascii=False,indent=2,default=str).encode('utf-8')
    try:
        resp=requests.post(f'https://api.telegram.org/bot{TELEGRAM_TOKEN}/sendDocument',data={'chat_id':chat_id,'caption':'📦 خروجی کامل داده‌های معاملات — حساب '+('واقعی' if _mode_is_real(s) else 'کاغذی')},files={'document':('trade_audit.json',io.BytesIO(raw),'application/json')},timeout=30)
        try: schedule_auto_delete(chat_id, (((resp.json() or {}).get('result') or {}).get('message_id')))
        except Exception: pass
        if not resp.ok or not (resp.json() or {}).get('ok', False):
            logger.warning('export trade data telegram send failed: %s', resp.text[:500])
            send_message(chat_id, '❌ خروجی JSON ساخته شد اما ارسال فایل به تلگرام ناموفق بود.')
            return False
        return True
    except Exception as exc:
        logger.warning('export trade data failed: %s',exc)
        send_message(chat_id, f'❌ خطا در ساخت/ارسال خروجی JSON: {exc}')
        return False


def _reset_start_balance(s):
    """(موجودی اولیه، ثبت‌شده؟). اگر کاربر هرگز موجودی را از منو انتخاب نکرده یا نسخه‌ی قدیمی بوده، پیش‌فرض ۱۰۰۰ برمی‌گردد."""
    try:
        v = float(s.get('paper_start_balance'))
        if math.isfinite(v) and v > 0:
            return v, True
    except (TypeError, ValueError):
        pass
    return float(default_session()['paper_balance']), False


def _journal_reset_chat(chat_id, real=None):
    """ژورنال معاملات این چت را (بدون حذف) به یک فایل پشتیبان منتقل می‌کند و از ژورنال زنده برمی‌دارد.
    (تعداد، مسیر پشتیبان) برمی‌گرداند؛ خطا = (None, None) و ژورنال دست‌نخورده می‌ماند."""
    path = _journal_path()
    try:
        with _JOURNAL_LOCK:
            if not os.path.exists(path):
                return 0, None
            with open(path, 'r', encoding='utf-8') as fh:
                data = json.load(fh)
            trades = data.get('trades') if isinstance(data, dict) else None
            if not isinstance(trades, list):
                return 0, None
            _sel = lambda t: str(t.get('chat_id')) == str(chat_id) and (real is None or bool(t.get('is_real')) == bool(real))
            mine = [t for t in trades if _sel(t)]
            if not mine:
                return 0, None
            bak = f'{path}.reset-{chat_id}-{int(time.time())}.json'
            with open(bak, 'w', encoding='utf-8') as fh:
                json.dump({'version': 1, 'chat_id': chat_id, 'archived_at': time.time(), 'trades': mine}, fh, ensure_ascii=False, indent=1, default=str)
            data['trades'] = [t for t in trades if not _sel(t)]
            data['updated_at'] = time.time()
            tmp = f'{path}.tmp'
            with open(tmp, 'w', encoding='utf-8') as fh:
                json.dump(data, fh, ensure_ascii=False, indent=1, default=str)
            os.replace(tmp, path)
            return len(mine), bak
    except Exception:
        logger.exception('journal reset failed chat=%s', chat_id)
        return None, None


def reset_stats_prompt_text(chat_id):
    s = get_session(chat_id)
    if s.get('trading_mode') == 'REAL':
        bal = 'موجودی حساب واقعی صرافی تغییر نمی‌کند (فقط مبنای ریسک روز از موجودی فعلی صرافی گرفته می‌شود)'
    else:
        start, known = _reset_start_balance(s)
        bal = f"موجودی به `{start:.2f} USDT` برمی‌گردد" + (' (موجودی اولیه‌ای که انتخاب کرده بودید)' if known else ' (موجودی اولیه ثبت نشده؛ مقدار پیش‌فرض ربات)')
    return ('⚠️ *ریست آمار و موجودی*\n\n'
            f'• {bal}\n'
            '• پاک می‌شود: تاریخچه معاملات بسته‌شده‌ی همین حساب (' + ('واقعی' if s.get('trading_mode') == 'REAL' else 'کاغذی') + '؛ تاریخچه‌ی حساب دیگر دست‌نخورده می‌ماند)، ممیزی و مسیر معاملات، آمار اسکن، آمار صف تایید حرکت و لیست انتظار، آمار کارمزد، لاگ دستیار، '
            'ژورنال معاملات و آمار پریست‌ها (نسخه‌ی پشتیبان ژورنال در پوشه‌ی داده می‌ماند)\n'
            '• تنظیمات، فیلترها و سیگنال‌های در حال انتظار دست‌نخورده می‌مانند\n'
            '• تا وقتی پوزیشن باز دارید ریست انجام نمی‌شود\n\nمطمئن هستید؟')


def reset_stats(chat_id):
    s=get_session(chat_id)
    if s.get('paper_positions'):
        return False, '❌ تا وقتی پوزیشن باز دارید، ریست آمار مجاز نیست. ابتدا پوزیشن‌ها را ببندید.'
    real = s.get('trading_mode') == 'REAL'
    start, known = _reset_start_balance(s)
    n_closed = len(closed_for_mode(s, real))
    s['closed_positions'] = closed_for_mode(s, not real)       # V3.44.65: فقط تاریخچه‌ی مود فعلی پاک می‌شود؛ مود دیگر دست‌نخورده می‌ماند
    s['trade_audit'] = []
    s['trade_pipeline_audit'] = []
    s['assist_log'] = []
    s['scan_stats'] = {'scans':0,'symbols':0,'signals':0,'entries':0,'blocked':0,'data_errors':0,'reason_counts':{}}
    s['platform_fee_total_usdt'] = 0.0
    s['platform_fee_trade_count'] = 0
    for key in ('fav_wait', 'touch_wait'):          # آمار صف تایید حرکت/لیست انتظار: موردهای تمام‌شده پاک می‌شوند، موردهای در حال انتظار می‌مانند
        d = s.get(key)
        if isinstance(d, dict):
            s[key] = {k: v for k, v in d.items() if isinstance(v, dict) and v.get('status') == 'waiting'}
    s['daily_stopped'] = False
    if real:
        equity = exchange_balance(chat_id)
    else:
        s['paper_balance'] = float(start)
        s['paper_start_balance'] = float(start)
        equity = float(start)
    s['daily_start_equity'] = float(equity)
    s['daily_start_date'] = time.strftime('%Y-%m-%d', time.gmtime())
    n_j, bak = _journal_reset_chat(chat_id, real)
    save_session(chat_id)
    lines = ['✅ *آمار و موجودی ریست شد*', '']
    lines.append(f"موجودی: `{equity:.2f} USDT`" + (' (حساب واقعی؛ تغییر نکرد)' if real else (' (موجودی اولیه)' if known else ' (پیش‌فرض ربات؛ موجودی اولیه ثبت نشده بود)')))
    lines.append(f"معاملات بسته‌شده‌ی پاک‌شده: `{n_closed}`")
    if n_j is None:
        lines.append('⚠️ ژورنال معاملات پاک نشد (خطا)؛ لاگ ربات را ببینید.')
    elif n_j:
        lines.append(f"ژورنال: `{n_j}` رکورد به فایل پشتیبان منتقل شد: `{os.path.basename(bak)}`")
    return True, '\n'.join(lines)


def analyze(chat_id,symbol):
    s=get_session(chat_id)
    tf=s['timeframe']
    d=get_klines(symbol,tf,160)
    if d.empty:
        return f'❌ داده کافی برای تحلیل `{symbol}` پیدا نشد.', None
    d=calculate_indicators(d); c=d.iloc[-2]
    live_price=latest_price(symbol)
    # V3.19: تنها یک استراتژی معاملاتی هست (Liquidity Sweep)؛ همان مسیر واقعی
    # اسکن زنده (get_signal_with_reason) اینجا هم صدا زده می‌شود تا این تحلیل با تصمیم واقعی ربات یکی باشد.
    sig,reason=get_signal_with_reason(d,None,'single',tf,'dynamic',s['filters'],_with_halving_cfg(s['strategy_config'], get_halving_range_sync(symbol) if s['strategy_config'].get('halving_model_enabled') else None),None,live_price=live_price)

    close=float(c.close); ema20=float(c.ema20); ema50=float(c.ema50)
    adx=float(c.adx or 0); plus_di=float(c.plus_di or 0); minus_di=float(c.minus_di or 0)

    if regime_advanced_on():
        _rg_an = regime_from_ind_df(d)      # V3.43.25: وقتی کلید «تشخیص رژیم دقیق‌تر» روشن است همان معیار مرکزیِ گیت‌ها
    elif close>ema20>ema50 and plus_di>minus_di and adx>=MARKET_REGIME_MIN_ADX:
        _rg_an = 'BULLISH'
    elif close<ema20<ema50 and minus_di>plus_di and adx>=MARKET_REGIME_MIN_ADX:
        _rg_an = 'BEARISH'
    else:
        _rg_an = 'RANGE'
    if _rg_an == 'BULLISH':
        trend_text='📈 صعودی'
    elif _rg_an == 'BEARISH':
        trend_text='📉 نزولی'
    else:
        trend_text='➡️ رنج (بدون روند مشخص)'

    good_entry=sig in ('BUY','SELL')
    if good_entry:
        strategy_text=f'✅ موقعیت مناسب برای ورود ({"خرید" if sig=="BUY" else "فروش"})'
    else:
        strategy_text=f'⚠️ موقعیت مناسب ورود نیست\n_({reason or "شرایط استراتژی هنوز کامل نشده است"})_'

    price_to_show=live_price if live_price is not None else close

    text = (
        f"🔍 *تحلیل {symbol}*\n\n"
        f"💰 قیمت لحظه‌ای: `{fmt(price_to_show)}`\n"
        f"⏱ تایم‌فریم: `{TF_DISPLAY.get(s['timeframe'],s['timeframe'])}`\n"
        f"📊 روند: {trend_text}\n"
        f"🎯 وضعیت نسبت به استراتژی: {strategy_text}"
    )
    keyboard = {'inline_keyboard': [
        [{'text':'🔎 بررسی و ورود سریع','callback_data':f'/check_entry_{symbol}'}],
        [{'text':'🎯 سطوح مهم و سقف/کف تاریخی','callback_data':f'/lv_{symbol}'}],
        [{'text':'📈 چارت در TradingView','url':tradingview_chart_url(symbol, tf)}],
        [{'text':'🏠 منوی اصلی','callback_data':'/menu'}],
    ]}
    return text, keyboard


# ===================== V3.44.89: «سطوح نماد» - سقف/کف تاریخی + سطوح مهم =====================
def _levels_symbol(raw):
    v = str(raw or '').strip().upper().replace('/', '').replace(' ', '').replace('-', '')
    if not v:
        return None
    if not v.endswith('USDT'):
        v += 'USDT'
    return v if 5 <= len(v) <= 20 and v.isalnum() else None


def _pct_from(price, level):
    try:
        return f"{(float(level) / float(price) - 1.0) * 100:+.1f}٪"
    except Exception:
        return ''


def render_levels_chart_png(symbol, d, price, up, dn, tf_label, depth, step, src_label=''):
    """V3.44.93: چارت PNG «سطوح ربات»: کندل‌های اخیر + قیمت لحظه‌ای + سطوح نصف‌کردن (۳ بالا / ۳ پایین) که ربات
    روی آن‌ها معامله می‌کند. up/dn: لیست {'price','depth'}. خروجی: BytesIO یا None."""
    try:
        if d is None or len(d) < 5:
            return None
        d = d.tail(110).reset_index(drop=True)
        fig, ax = plt.subplots(figsize=(11.5, 6.2), dpi=120)
        fig.patch.set_facecolor('#0f172a'); ax.set_facecolor('#0f172a')
        for i, row in d.iterrows():
            o = float(row['open']); h = float(row['high']); l = float(row['low']); c = float(row['close'])
            col = '#22c55e' if c >= o else '#ef4444'
            ax.vlines(i, l, h, color=col, linewidth=1.1, alpha=0.95, zorder=2)
            ax.add_patch(plt.Rectangle((i - 0.31, min(o, c)), 0.62, max(abs(c - o), max((h - l) * 0.003, 1e-12)),
                                       facecolor=col, edgecolor=col, linewidth=0.7, alpha=0.92, zorder=3))
        x_right = len(d) + 1.8
        items = [(float(x['price']), int(x['depth']), '#8b5cf6') for x in (list(up) + list(dn))]
        items.append((float(price), None, '#60a5fa'))
        # برچسب‌های نزدیک به هم روی هم نیفتند: فقط جای «متن» جابه‌جا می‌شود، خط سر جای واقعی‌اش می‌ماند
        _yl = [min(float(d['low'].min()), *[v for v, _, _ in items]), max(float(d['high'].max()), *[v for v, _, _ in items])]
        _gap = max((_yl[1] - _yl[0]) * 0.045, 1e-12)
        _order = sorted(range(len(items)), key=lambda k: items[k][0])
        _ty = {}
        for n_, k_ in enumerate(_order):
            _ty[k_] = items[k_][0] if n_ == 0 else max(items[k_][0], _ty[_order[n_ - 1]] + _gap)
        for k_, (value, dp, color) in enumerate(items):
            if dp is None:
                ax.axhline(value, color=color, linestyle='-', linewidth=1.6, alpha=0.95, zorder=1)
                label = f' PRICE  {fmt(value)} '
            else:
                ax.axhline(value, color=color, linestyle=':', linewidth=1.3, alpha=0.95, zorder=1)
                label = f' {_hv_level_label(dp)}  {fmt(value)}  ({_pct_from(price, value)}) '
            ax.text(x_right, _ty[k_], label, va='center', ha='left', fontsize=9.5, fontweight='bold', color='white',
                    bbox=dict(boxstyle='round,pad=0.28', facecolor=color, edgecolor='none', alpha=0.95), clip_on=False, zorder=5)
        ax.set_title(f'{symbol}  •  {tf_label}  •  Bot levels (3 up / 3 down)', loc='left',
                     color='white', fontsize=15, fontweight='bold', pad=14)
        summary = f'Depth: {depth} | Step: {fmt(step)}' + (f' | {src_label}' if src_label else '')
        ax.text(0.01, 0.015, summary, transform=ax.transAxes, color='#cbd5e1', fontsize=9.5, va='bottom', ha='left',
                bbox=dict(boxstyle='round,pad=0.35', facecolor='#1e293b', edgecolor='#334155', alpha=0.95))
        vals = [v for v, _, _ in items] + list(_ty.values())
        ymin = min(float(d['low'].min()), *vals); ymax = max(float(d['high'].max()), *vals)
        pad = max((ymax - ymin) * 0.06, abs(price) * 0.001)
        ax.set_ylim(ymin - pad, ymax + pad); ax.set_xlim(-1, len(d) + 5.5)
        ax.grid(True, axis='y', color='#334155', alpha=0.45, linewidth=0.7); ax.grid(False, axis='x')
        ax.tick_params(axis='both', colors='#94a3b8', labelsize=8.5)
        for sp in ax.spines.values(): sp.set_visible(False)
        ax.set_xticks([]); ax.set_ylabel('Price', color='#94a3b8', fontsize=9)
        plt.subplots_adjust(left=0.06, right=0.78, top=0.90, bottom=0.10)
        b = io.BytesIO()
        plt.savefig(b, format='png', dpi=120, bbox_inches='tight', facecolor=fig.get_facecolor())
        plt.close(fig); b.seek(0)
        return b
    except Exception:
        logger.exception('levels chart render error')
        try: plt.close('all')
        except Exception: pass
        return None


def symbol_levels_chart(chat_id, raw_symbol):
    """V3.44.93: (BytesIO, caption, keyboard) یا (None, پیام خطا, None). همان سقف/کف، عمق و ATR که گزارش
    «سطوح مهم» و معاملات ربات استفاده می‌کنند؛ ۳ سطح بالا و ۳ سطح پایین قیمت."""
    symbol = _levels_symbol(raw_symbol)
    if not symbol:
        return None, '⚠️ نام نماد معتبر نیست. مثال: `BTC` یا `ETH`', None
    s = get_session(chat_id)
    tf = s['timeframe']
    rng = get_halving_range_sync(symbol)
    if not rng:
        return None, f'⚠️ سقف/کف تاریخی `{symbol}` در دسترس نیست.', None
    df = get_klines(symbol, tf, 650 if tf in ('5min', '15min', '1hour') else 200)
    if df is None or df.empty:
        return None, f'❌ داده‌ی کافی برای `{symbol}` پیدا نشد.', None
    live = latest_price(symbol)
    price = float(live) if live is not None else float(df['close'].iloc[-1])
    ind = calculate_indicators(df)
    dated_df, _a, _b = _compute_prev_day_levels(df)
    if dated_df is None or ind is None or len(ind) != len(dated_df) or 'atr' not in ind.columns:
        return None, f'❌ محاسبه‌ی ATR برای `{symbol}` ممکن نشد.', None
    dated_df['atr'] = ind['atr'].values
    scfg = s.get('strategy_config') or {}
    cfg = {**get_timeframe_preset(tf), 'halving_model_enabled': True,
           'halving_high': float(rng[0]), 'halving_low': float(rng[1])}
    for k in ('halving_k_atr', 'halving_min_depth', 'halving_max_depth', 'halving_dynamic_k'):
        if k in scfg:
            cfg[k] = scfg[k]
    cfg.update(_halving_tf_params(scfg, tf))
    ctx = _halving_context(dated_df, len(dated_df) - 1, _halving_cfg(cfg), span_cells=8)
    if not (ctx and ctx.get('levels')):
        return None, f'⚠️ سطوح نصف‌کردن `{symbol}` ساخته نشد.', None
    lv = sorted(({'price': float(x['price']), 'depth': int(x['depth'])} for x in ctx['levels']), key=lambda x: x['price'])
    up = [x for x in lv if x['price'] > price][:3]
    dn = [x for x in reversed([x for x in lv if x['price'] <= price])][:3]
    src_rec = _HIST_RANGE_SRC.get(symbol)
    src_label = {'Manual': 'Range: manual/TV', 'Binance': 'Range: Binance'}.get(src_rec[0], '') if src_rec else ''
    png = render_levels_chart_png(symbol, dated_df, price, up, dn, TF_DISPLAY.get(tf, tf), ctx['depth'], ctx['step'], src_label)
    if png is None:
        return None, '❌ ساخت چارت ناموفق بود.', None
    caption = (f"🖼 *چارت سطوح ربات — {symbol}*\n"
               f"عمق `{ctx['depth']}` | فاصله‌ی سطوح `{fmt(ctx['step'])}` | قیمت `{fmt(price)}`\n"
               f"همین سطوح مبنای معاملات ربات هستند (۳ بالا / ۳ پایین).")
    kb = {'inline_keyboard': [
        [{'text': '🔄 بروزرسانی چارت', 'callback_data': f'/lvc_{symbol}'}, {'text': '🎯 گزارش سطوح', 'callback_data': f'/lv_{symbol}'}],
        [{'text': '🏠 منوی اصلی', 'callback_data': '/menu'}],
    ]}
    return png, caption, kb


def symbol_levels_report(chat_id, raw_symbol):
    """گزارش سطوح مهم یک نماد: سقف/کف تاریخیِ مورد استفاده‌ی ربات (و منبعش)، جایگاه قیمت در بازه،
    نزدیک‌ترین سطوح نصف‌کردن بالا/پایین قیمت (با عمق)، و سقف/کف دیروز، ۴ساعته، هفته و ماه قبل.
    خروجی: (متن، کیبورد). هیچ سفارشی ثبت نمی‌شود؛ فقط نمایش."""
    symbol = _levels_symbol(raw_symbol)
    if not symbol:
        return '⚠️ نام نماد معتبر نیست. مثال: `BTC` یا `ETH`', None
    s = get_session(chat_id)
    tf = s['timeframe']
    rng = get_halving_range_sync(symbol)
    df = get_klines(symbol, tf, 650 if tf in ('5min', '15min', '1hour') else 200)
    if df is None or df.empty:
        return f'❌ داده‌ی کافی برای `{symbol}` پیدا نشد.', None
    live = latest_price(symbol)
    price = float(live) if live is not None else float(df['close'].iloc[-1])
    lines = [f'🎯 *سطوح مهم {symbol}*',
             f"💰 قیمت لحظه‌ای: `{fmt(price)}`   ⏱ تایم‌فریم ربات: `{TF_DISPLAY.get(tf, tf)}`", '']

    # --- سقف و کف تاریخی ---
    if rng:
        hi, lo = float(rng[0]), float(rng[1])
        src_rec = _HIST_RANGE_SRC.get(symbol)
        _lbl = {'Manual': 'جدول دستی (هم‌تراز با TradingView)', 'Binance': 'Binance', 'Bitunix': 'Bitunix'}
        src = _lbl.get(src_rec[0]) if (src_rec and src_rec[0] in _lbl and (abs(src_rec[1][0] - hi) < 1e-12 * max(1.0, hi)) and (abs(src_rec[1][1] - lo) < 1e-12 * max(1.0, lo))) \
            else 'نامشخص'
        pos = min(100.0, max(0.0, (price - lo) / (hi - lo) * 100.0)) if hi > lo else 0.0
        lines += ['📜 *سقف و کف تاریخی (مبنای مدل نصف‌کردن)*',
                  f"• سقف تاریخی: `{fmt(hi)}`  ({_pct_from(price, hi)})",
                  f"• کف تاریخی: `{fmt(lo)}`  ({_pct_from(price, lo)})",
                  f"• جایگاه قیمت در بازه: `{pos:.1f}٪` از کف به سقف",
                  f"• منبع: {src}"]
    else:
        lines.append('⚠️ سقف/کف تاریخی این نماد در دسترس نیست (روی Binance نیست).')

    # --- سطوح نصف‌کردن اطراف قیمت + سطوح دوره‌ای ---
    dated_df = None
    try:
        ind = calculate_indicators(df)
        dated_df, _pdh_unused, _pdl_unused = _compute_prev_day_levels(df)
        if dated_df is not None and ind is not None and len(ind) == len(dated_df) and 'atr' in ind.columns:
            dated_df['atr'] = ind['atr'].values
    except Exception:
        logger.exception('levels report: indicators failed %s', symbol)
        dated_df = None

    if rng and dated_df is not None and 'atr' in dated_df.columns:
        try:
            scfg = s.get('strategy_config') or {}
            cfg = {**get_timeframe_preset(tf), 'halving_model_enabled': True,
                   'halving_high': float(rng[0]), 'halving_low': float(rng[1])}
            for k in ('halving_k_atr', 'halving_min_depth', 'halving_max_depth', 'halving_dynamic_k'):
                if k in scfg:
                    cfg[k] = scfg[k]
            cfg.update(_halving_tf_params(scfg, tf))
            ctx = _halving_context(dated_df, len(dated_df) - 1, _halving_cfg(cfg), span_cells=8)
            if ctx and ctx.get('levels'):
                lv = sorted(({'price': float(x['price']), 'depth': int(x['depth'])} for x in ctx['levels']), key=lambda x: x['price'])
                up = [x for x in lv if x['price'] > price][:3]
                dn = [x for x in reversed([x for x in lv if x['price'] <= price])][:3]
                lines += ['', f"🧮 *سطوح نصف‌کردن* (عمق انتخابی `{ctx['depth']}` | فاصله‌ی هر سطح `{fmt(ctx['step'])}`)"]
                for x in reversed(up):
                    lines.append(f"🔺 `{fmt(x['price'])}`  ({_pct_from(price, x['price'])})  عمق {x['depth']}")
                lines.append(f"▶️ قیمت: `{fmt(price)}`")
                for x in dn:
                    lines.append(f"🔻 `{fmt(x['price'])}`  ({_pct_from(price, x['price'])})  عمق {x['depth']}")
        except Exception:
            logger.exception('levels report: halving failed %s', symbol)

    if dated_df is not None:
        try:
            n = len(dated_df)
            rows = []
            pdh, pdl = _pdh_pdl_at(dated_df, n - 1)
            if pdh is not None and pdl is not None:
                rows.append(('دیروز', pdh, pdl))
            htf = _compute_prev_htf_levels(dated_df, n - 1)
            for name, hk, lk in (('۴ساعته قبل', 'P4H', 'P4L'), ('هفته‌ی قبل', 'PWH', 'PWL'), ('ماه قبل', 'PMH', 'PML')):
                if hk in htf and lk in htf:
                    rows.append((name, htf[hk], htf[lk]))
            if rows:
                lines += ['', '📅 *سقف / کف دوره‌های قبل*']
                for name, h_, l_ in rows:
                    lines.append(f"• {name}: سقف `{fmt(h_)}` ({_pct_from(price, h_)}) | کف `{fmt(l_)}` ({_pct_from(price, l_)})")
        except Exception:
            logger.exception('levels report: periodic levels failed %s', symbol)

    keyboard = {'inline_keyboard': [
        [{'text': '🔄 بروزرسانی', 'callback_data': f'/lv_{symbol}'}, {'text': '🔎 تحلیل', 'callback_data': f'/an_{symbol}'}],
        [{'text': '🖼 چارت سطوح ربات', 'callback_data': f'/lvc_{symbol}'}],
        [{'text': '📈 چارت در TradingView', 'url': tradingview_chart_url(symbol, tf)}],
        [{'text': '🏠 منوی اصلی', 'callback_data': '/menu'}],
    ]}
    return '\n'.join(lines), keyboard


# ===================== V3.44.57: انتخاب صرافی و اتصال حساب REAL =====================
# جریان: «حساب واقعی» → انتخاب صرافی (Binance/Bitunix) → (کلید ذخیره‌شده یا ثبت کلید جدید) → API Key → Secret
# → اتصال و نمایش موجودی → اگر موجودی قابل‌استفاده کافی بود: ادامه (مارجین/اهرم/...)، وگرنه پیام «موجودی خود را شارژ کنید».
# امنیت: پیام حاوی کلید/Secret بلافاصله از چت پاک می‌شود؛ API Key فقط در حافظه (نه در session) نگه داشته می‌شود و بعد از
# اتصال موفق هر دو رمزشده در دیتابیس ذخیره می‌شوند (credentials_store). هیچ‌وقت چیزی از آن‌ها لاگ نمی‌شود.
_REAL_PENDING_KEYS = {}          # {chat_id: (venue, api_key, ts)}  فقط حافظه
_REAL_PENDING_TTL = 600.0


def _real_has_saved(chat_id, venue):
    return account_credentials(chat_id, venue) is not None


def _real_saved_label(chat_id, venue):
    try:
        h = CREDENTIALS.hint(chat_id, venue)
    except Exception:
        h = None
    if h: return f'…{h}'
    return 'تنظیم‌شده توسط ادمین' if (venue == 'binance' and _real_has_saved(chat_id, venue)) else '-'


def real_exchange_keyboard(chat_id):
    rows = [[{'text': f"{'✅ ' if _real_has_saved(chat_id, v) else ''}{name}", 'callback_data': f'/real_pick_{v}'}] for v, name in REAL_VENUES.items()]
    rows.append([{'text': '↩️ بازگشت', 'callback_data': '/menu'}])
    return {'inline_keyboard': rows}


def paper_exchange_keyboard(chat_id):
    """V3.44.108: انتخاب صرافی برای حساب کاغذی (اولین مرحله‌ی ویزارد)."""
    cur = (get_session(chat_id) or {}).get('paper_exchange', 'binance')
    rows = [[{'text': f"{'✅ ' if v == cur else ''}{name}", 'callback_data': f'/paper_pick_{v}'}] for v, name in REAL_VENUES.items()]
    rows.append([{'text': '🏠 منوی اصلی', 'callback_data': '/menu'}])
    return {'inline_keyboard': rows}


def paper_exchange_text(chat_id):
    return '📄 *حساب کاغذی*\n\nرباتِ کاغذی با داده‌ی کدام صرافی کار کند؟'


def real_start_picker(chat_id, message_id=None):
    s = get_session(chat_id); s['user_state'] = None; save_session(chat_id)
    _REAL_PENDING_KEYS.pop(chat_id, None)
    edit_page(chat_id, '🔴 *حساب واقعی*\n\nصرافی‌ای که می‌خواهید روی آن معامله کنید را انتخاب کنید.\n(✅ یعنی کلید API این صرافی قبلاً ذخیره شده است.)',
              real_exchange_keyboard(chat_id), message_id)


def real_pick_exchange(chat_id, venue, message_id=None):
    if venue not in REAL_VENUES: return
    if PAPER_ONLY:
        send_message(chat_id,'🟢 این Build برای تست PAPER قفل شده و ورود REAL عمداً غیرفعال است.'); return
    name = REAL_VENUES[venue]
    if _real_has_saved(chat_id, venue):
        rows = [[{'text': '✅ استفاده از کلید ذخیره‌شده', 'callback_data': f'/real_use_{venue}'}],
                [{'text': '🔑 ثبت کلید جدید', 'callback_data': f'/real_new_{venue}'}]]
        try:
            if CREDENTIALS.has(chat_id, venue): rows.append([{'text': '🗑 حذف کلید ذخیره‌شده', 'callback_data': f'/real_del_{venue}'}])
        except Exception: pass
        rows.append([{'text': '↩️ انتخاب صرافی دیگر', 'callback_data': '/mode_real'}])
        edit_page(chat_id, f'🔑 برای *{name}* یک کلید API ذخیره شده است (`{_real_saved_label(chat_id, venue)}`).\nکدام را می‌خواهید؟',
                  {'inline_keyboard': rows}, message_id)
        return
    real_prompt_api_key(chat_id, venue)


def real_prompt_api_key(chat_id, venue):
    if PAPER_ONLY:
        send_message(chat_id,'🟢 این Build برای تست PAPER قفل شده و ورود REAL عمداً غیرفعال است.'); return
    s = get_session(chat_id); name = REAL_VENUES[venue]
    s['user_state'] = 'WAIT_REAL_API_KEY'; s['_real_tmp'] = {'venue': venue}; save_session(chat_id)
    _REAL_PENDING_KEYS.pop(chat_id, None)
    send_message(chat_id,
                 f'🔑 *اتصال {name}*\n\n'
                 f'۱) در {name.split()[0]} یک کلید API بسازید.\n'
                 '۲) فقط دسترسی *Futures / Trade (خواندن + معامله)* را روشن کنید.\n'
                 '۳) دسترسی *برداشت (Withdraw) را حتماً خاموش* بگذارید.\n'
                 '۴) اگر امکان دارد، IP سرور ربات را در لیست مجاز کلید وارد کنید.\n\n'
                 '👇 حالا *API Key* را همین‌جا بفرستید. پیام شما بلافاصله پاک می‌شود.\n'
                 'برای انصراف: /cancel')


def _real_delete_user_message(chat_id, message_id):
    if not message_id: return
    try: tg('deleteMessage', {'chat_id': chat_id, 'message_id': message_id}, 10)
    except Exception: pass


def real_handle_credentials_text(chat_id, raw, message_id=None):
    """مرحله‌های WAIT_REAL_API_KEY / WAIT_REAL_API_SECRET. هیچ استثنایی بیرون نمی‌دهد (تا متن حاوی Secret لاگ نشود)."""
    try:
        _real_delete_user_message(chat_id, message_id)
        s = get_session(chat_id); state = str(s.get('user_state') or '')
        text = (raw or '').strip(); venue = (s.get('_real_tmp') or {}).get('venue')
        if venue not in REAL_VENUES:
            s['user_state'] = None; save_session(chat_id); return
        if text.lower() in ('/cancel', 'لغو', 'انصراف') or text.startswith('/'):
            s['user_state'] = None; s.pop('_real_tmp', None); save_session(chat_id); _REAL_PENDING_KEYS.pop(chat_id, None)
            send_message(chat_id, '❌ اتصال حساب لغو شد.'); return
        if not (8 <= len(text) <= 256) or any(ch.isspace() for ch in text):
            send_message(chat_id, '⚠️ مقدار نامعتبر است (باید یک رشته‌ی بدون فاصله باشد). دوباره بفرستید یا /cancel را بزنید.'); return
        if state == 'WAIT_REAL_API_KEY':
            _REAL_PENDING_KEYS[chat_id] = (venue, text, time.time())
            s['user_state'] = 'WAIT_REAL_API_SECRET'; save_session(chat_id)
            send_message(chat_id, '✅ API Key دریافت شد (و از چت پاک شد).\n\n👇 حالا *Secret* را بفرستید (آن هم بلافاصله پاک می‌شود).'); return
        if state == 'WAIT_REAL_API_SECRET':
            pend = _REAL_PENDING_KEYS.pop(chat_id, None)
            s['user_state'] = None; s.pop('_real_tmp', None); save_session(chat_id)
            if not pend or pend[0] != venue or time.time() - pend[2] > _REAL_PENDING_TTL:
                send_message(chat_id, '⌛ مهلت ثبت کلید تمام شد. از «حساب واقعی» دوباره شروع کنید.'); return
            real_try_connect(chat_id, venue, pend[1], text)
    except Exception:
        logger.error('real credential step failed chat=%s (details suppressed)', chat_id)
        try: send_message(chat_id, '❌ خطای داخلی در ثبت کلید. دوباره از «حساب واقعی» شروع کنید.')
        except Exception: pass


def _real_balance_numbers(ex):
    b = ex.fetch_balance()
    total = float(((b or {}).get('total') or {}).get('USDT') or 0.0)
    free = ((b or {}).get('free') or {}).get('USDT')
    avail = float(free) if free is not None else total
    if not (math.isfinite(total) and math.isfinite(avail)): raise ExchangeStateError('invalid balance')
    return max(0.0, total), max(0.0, avail)


def _real_connect_error_text(venue, exc, secrets=()):
    msg = str(exc)
    for sec in secrets:
        if sec: msg = msg.replace(sec, '***')
    msg = ' '.join(msg.split())[:240]
    return (f'❌ اتصال به {REAL_VENUES[venue]} ناموفق بود.\n\nدلیل: {msg}\n\n'
            '• API Key و Secret را درست و کامل کپی کرده‌اید؟\n'
            '• برای کلید، دسترسی Futures / Trade فعال است؟\n'
            '• اگر محدودیت IP دارد، IP سرور ربات مجاز است؟\n'
            '• معاملات فیوچرز روی حساب شما فعال است؟')


def real_try_connect(chat_id, venue, key=None, secret=None, message_id=None):
    """key/secret خالی = استفاده از کلید ذخیره‌شده. حالت REAL فقط با موجودی کافی فعال می‌شود."""
    if venue not in REAL_VENUES: return
    s = get_session(chat_id); name = REAL_VENUES[venue]
    if PAPER_ONLY:
        send_message(chat_id, '🟢 این Build برای تست PAPER قفل شده و ورود REAL عمداً غیرفعال است.'); return
    if s['paper_positions']:
        send_message(chat_id, '❌ ابتدا تمام پوزیشن‌های فعلی را ببندید.'); return
    using_saved = key is None
    if using_saved:
        creds = account_credentials(chat_id, venue)
        if not creds:
            send_message(chat_id, f'❌ برای {name} کلیدی ذخیره نشده است.', real_exchange_keyboard(chat_id)); return
        key, secret = creds
    send_message(chat_id, f'⏳ در حال اتصال به {name} ...', parse_mode=None)
    try:
        ex = build_exchange(venue, key, secret)
        equity, avail = _real_balance_numbers(ex)
    except Exception as exc:
        logger.warning('real connect failed chat=%s venue=%s: %s', chat_id, venue, type(exc).__name__)
        send_message(chat_id, _real_connect_error_text(venue, exc, (key, secret)),
                     {'inline_keyboard': [[{'text': '🔑 ثبت کلید دیگر', 'callback_data': f'/real_new_{venue}'}], [{'text': '↩️ انتخاب صرافی', 'callback_data': '/mode_real'}]]}, parse_mode=None)
        return
    if not using_saved:
        try:
            CREDENTIALS.save(chat_id, venue, key, secret); _cred_cache_clear(chat_id)
        except Exception as exc:
            logger.error('saving credentials failed chat=%s: %s', chat_id, type(exc).__name__)
            send_message(chat_id, f'⚠️ اتصال برقرار شد ولی ذخیره‌ی امن کلید ممکن نشد ({exc}). برای ادامه کلید باید ذخیره شود؛ مدیر سرور را مطلع کنید.', parse_mode=None); return
    real_enter_or_charge(chat_id, venue, equity, avail, message_id)


def real_enter_or_charge(chat_id, venue, equity, avail, message_id=None):
    s = get_session(chat_id); name = REAL_VENUES[venue]
    if avail >= max(REAL_MIN_BALANCE_USDT, 1e-9):
        s['real_exchange'] = venue; EXCHANGE_CACHE.pop(chat_id, None); _cred_cache_clear(chat_id)
        s['trading_mode'] = 'REAL'; s['is_bot_active'] = False; s['daily_start_equity'] = equity
        s['daily_start_date'] = time.strftime('%Y-%m-%d', time.gmtime()); s['daily_stopped'] = False; save_session(chat_id)
        send_message(chat_id, f'✅ به *{name}* متصل شدید.\n\n💰 موجودی کل: `{equity:.2f}` USDT\n✅ قابل استفاده: `{avail:.2f}` USDT\n\n⚙️ مقدار استفاده‌شده در هر معامله:', get_margin_keyboard(back='/menu'))
        return
    send_message(chat_id,
                 f'✅ اتصال به *{name}* برقرار شد، اما موجودی فیوچرز شما برای شروع کافی نیست.\n\n'
                 f'💰 موجودی کل: `{equity:.2f}` USDT\n💳 قابل استفاده: `{avail:.2f}` USDT\n'
                 f'📌 حداقل لازم: `{REAL_MIN_BALANCE_USDT:g}` USDT\n\n'
                 f'لطفاً *موجودی خود را شارژ کنید* (به حساب *Futures* در {name.split()[0]} منتقل کنید) و بعد «🔄 بررسی مجدد موجودی» را بزنید.',
                 {'inline_keyboard': [[{'text': '🔄 بررسی مجدد موجودی', 'callback_data': f'/real_use_{venue}'}],
                                      [{'text': '↩️ انتخاب صرافی دیگر', 'callback_data': '/mode_real'}],
                                      [{'text': '📄 ادامه با حساب کاغذی', 'callback_data': '/mode_paper'}]]})


def menu(chat_id,message_id=None):
    s=get_session(chat_id)
    bal=exchange_balance(chat_id) if s['trading_mode']=='REAL' else s['paper_balance']
    maxp=s['max_open_positions'] if s['max_open_positions']>0 else '∞'
    max_same=s.get('max_same_direction_positions',0)
    max_same_disp = max_same if max_same>0 else '∞'
    dir_cd = s.get('same_direction_entry_cooldown_seconds',0)
    diag = "🟢 فعال" if s.get('entry_diag_enabled', True) else "🔴 خاموش"
    try:
        mode_line = presets_mod.panel_line(s)      # V3.44.102: حالت معامله / پریست فعال
    except Exception:
        mode_line = ''
    text=f"📊 *پنل اصلی ربات*\n\n🟢 اسکن: `{'فعال' if s['is_bot_active'] else 'متوقف'}`\n💳 حساب: `{('واقعی · '+real_venue_name(chat_id).split()[0]) if s['trading_mode']=='REAL' else 'کاغذی · '+REAL_VENUES.get(s.get('paper_exchange','binance'),'Binance').split()[0]}`  |  ⏱ تایم‌فریم: `{TF_DISPLAY.get(s['timeframe'],s['timeframe'])}`\n📈 استراتژی: `{'پویا (دوطرفه)' if s['active_strategy']=='dynamic' else s['active_strategy']}`\n{mode_line}\n💰 موجودی: `{bal:.2f} USDT`  |  ⚙️ مقدار هر معامله: `{s['trade_amount_usdt']:.0f} USDT`\n📌 پوزیشن‌های باز: `{maxp}`  |  🔍 لاگ ورود: `{diag}`\n🛡 ریسک هر معامله: `{s['risk_per_trade_pct']:.2f}%`  |  حد ضرر روزانه: `{s['daily_loss_limit_pct']:.2f}%`\n🧭 سقف هم‌جهت هم‌زمان: `{max_same_disp}`  |  فاصله ورود هم‌جهت: `{dir_cd:.0f}s`\n\nاز منوی زیر بخش موردنظر را انتخاب کن:"
    if is_restricted_user(chat_id):
        # V3.44.59: پنل کاربر عادی بدون جزئیات استراتژی (تایم‌فریم، نوع استراتژی، لاگ ورود، قوانین هم‌جهت).
        text = (f"📊 *پنل اصلی ربات*\n\n🟢 اسکن: `{'فعال' if s['is_bot_active'] else 'متوقف'}`\n"
                f"💳 حساب: `{('واقعی · '+real_venue_name(chat_id).split()[0]) if s['trading_mode']=='REAL' else 'کاغذی · '+REAL_VENUES.get(s.get('paper_exchange','binance'),'Binance').split()[0]}`  |  ⏱ تایم‌فریم: `{TF_DISPLAY.get(s['timeframe'],s['timeframe'])}`\n"
                f"{mode_line}\n"
                f"💰 موجودی: `{bal:.2f} USDT`  |  ⚙️ مقدار هر معامله: `{s['trade_amount_usdt']:.0f} USDT`\n"
                f"📌 حداکثر پوزیشن باز: `{maxp}`\n"
                f"🤝 حالت دستیار: `{'روشن (ورود فقط با تایید شما)' if s.get('assist_mode_enabled') else 'خاموش (ورود خودکار)'}`\n\nاز منوی زیر بخش موردنظر را انتخاب کن:")
    send_message(chat_id,text,get_main_menu_keyboard(s['is_bot_active'], s.get('entry_diag_enabled', True), is_admin(chat_id), s.get('trading_mode', 'PAPER'), bool(s.get('assist_mode_enabled', False)), is_restricted_user(chat_id)),message_id)


def stop_scan(chat_id, reason='manual'):
    s=get_session(chat_id)
    with STATE_LOCK:
        s['scan_generation']=int(s.get('scan_generation',0))+1
        s['is_bot_active']=False
        s['last_stop_reason']=reason
    save_session(chat_id)
    with get_entry_lock(chat_id):
        pass
    return s


def start_scan(chat_id,message_id=None):
    s=get_session(chat_id)
    if s['daily_stopped']:
        equity=exchange_balance(chat_id) if s['trading_mode']=='REAL' else current_paper_equity(s)
        s['daily_stopped']=False
        s['daily_start_equity']=equity
    if s['trading_mode']=='REAL':
        if not get_exchange(chat_id):
            send_message(chat_id,f'❌ حساب {real_venue_name(chat_id)} برای این کاربر تنظیم نشده است. از «حساب واقعی» صرافی و کلید API را ثبت کنید.')
            return
        if not reconcile_real(chat_id):
            return
        s['real_reconciliation_required']=False
    with get_entry_lock(chat_id):
        s['scan_generation']=int(s.get('scan_generation',0))+1
        s['is_bot_active']=True
        s['last_stop_reason']=None
        save_session(chat_id)
    menu(chat_id,message_id)
    sync_bottom_keyboard(chat_id, "🟢 اسکن فعال شد.\n🔒 تنظیمات حساس تا توقف اسکن قفل هستند.")


def reload_and_restart_scan(chat_id, message_id=None):
    """
    توجه: این تابع فقط تنظیمات استراتژی (strategy_config) را بر اساس تایم‌فریم
    فعلی همین اکانت بازسازی و اسکن را دوباره فعال می‌کند. عمداً importlib.reload
    حذف شد — در بات چندکاربره‌ای که چند اکانت روی یک پردازه اجرا می‌شوند، بازخوانی
    زنده‌ی ماژول strategy نه اثر واقعی داشت (چون bot.py توابع را یک‌بار در ابتدای
    اجرا import کرده و دیگر آپدیت نمی‌شدند) و نه بی‌خطر بود (می‌توانست هم‌زمان با
    اجرای اسکن سایر اکانت‌ها تداخل ایجاد کند). timeframe و تنظیمات این اکانت دست
    نخورده باقی می‌ماند؛ اگر بعد از این دکمه بازهم تنظیمات به‌طور کامل به حالت
    پیش‌فرض برگشت، علتش خارج از این تابع است — احتمالاً ری‌استارت کل پردازه/کانتینر
    میزبان و نبودِ دیسک دائمی برای BOT_DB_PATH (به هشدار init_db مراجعه کنید).
    """
    try:
        s = get_session(chat_id)
        _old_cfg = s.get('strategy_config')
        s['strategy_config'] = _p4_keep_flags(_old_cfg, get_timeframe_preset(s.get('timeframe', '5min')))
        _halving_tf_apply(s['strategy_config'], s.get('timeframe', '5min'))      # V3.44.40
        _p4_sync_tags(s)
        save_session(chat_id)
        start_scan(chat_id, message_id)
        send_message(chat_id, "🔄 *تنظیمات استراتژی بر اساس تایم‌فریم فعلی بازسازی شد و اسکن فعال گردید.*")
    except Exception as exc:
        send_message(chat_id, f"❌ خطا در بازسازی تنظیمات استراتژی: `{exc}`")


def _market_snapshot(symbol, tf):
    try:
        d = get_klines(symbol, tf, 160)
        if d.empty or len(d) < 60: return None
        d = calculate_indicators(d); c = d.iloc[-2]
        close = float(c.close); ema20 = float(c.ema20); ema50 = float(c.ema50); adx = float(c.adx); rsi = float(c.rsi); atr = float(c.atr)
        vol_ratio = float(c.volume / d['volume'].rolling(20).mean().iloc[-2]) if float(d['volume'].rolling(20).mean().iloc[-2]) > 0 else 0.0
        _rg = regime_from_ind_df(d)
        if _rg is None: return None
        score = 1 if _rg == 'BULLISH' else (-1 if _rg == 'BEARISH' else 0)
        return {'symbol': symbol, 'close': close, 'adx': adx, 'rsi': rsi, 'atr_pct': atr / close * 100 if close else 0.0, 'volume_ratio': vol_ratio, 'score': score}
    except Exception:
        return None


MARKET_REPORT_SYMBOLS = ['BTC','ETH','SOL','BNB','XRP','DOGE','ADA','AVAX','LINK','DOT']
# --- گیت جهت بازار (کش رژیم تایم‌فریم؛ برای داشبورد، کانال سیگنال، هم‌جهتی کامل و فیلتر P4) ---------------------------------
# روی تایم‌فریم فعال، ۱۰ نماد شاخص (MARKET_REPORT_SYMBOLS) با همان معیار «داشبورد بازار»
# (close نسبت به EMA50 و EMA20>=EMA50 روی آخرین کندل بسته‌شده) امتیاز می‌گیرند:
#   ≥ MARKET_GATE_MIN_SYMBOLS نماد صعودی  => BULLISH => ورود فروش مسدود
#   ≥ MARKET_GATE_MIN_SYMBOLS نماد نزولی  => BEARISH => ورود خرید مسدود
#   غیر از این (رنج / داده ناکافی)         => RANGE   => هیچ ورودی انجام نمی‌شود
# فقط ورودهای جدید را تحت تأثیر قرار می‌دهد؛ پوزیشن‌های باز دست‌نخورده می‌مانند.
MARKET_GATE_MIN_SYMBOLS = int(os.environ.get('MARKET_GATE_MIN_SYMBOLS', '7'))
TIMEFRAME_REGIME_TTL = float(os.environ.get('TIMEFRAME_REGIME_TTL_SECONDS', '150'))
TIMEFRAME_REGIME_CACHE: Dict[str, Dict[str, Any]] = {}


async def _market_snapshot_async(http, symbol, tf):
    try:
        d = await get_klines_async(http, symbol, tf, 160)
        if d is None or d.empty or len(d) < 60: return None
        d = calculate_indicators(d); c = d.iloc[-2]
        close = float(c.close); ema20 = float(c.ema20); ema50 = float(c.ema50)
        _rg = regime_from_ind_df(d)
        if _rg is None: return None
        score = 1 if _rg == 'BULLISH' else (-1 if _rg == 'BEARISH' else 0)
        return score
    except Exception:
        return None


async def refresh_market_gate(http, timeframe):
    """'BULLISH' / 'BEARISH' / 'RANGE' برای تایم‌فریم داده‌شده (کش‌شده).
    اگر داده‌ی معتبرِ کمتر از آستانه دریافت شود نتیجه RANGE است (ورود ممنوع) و کش نمی‌شود
    تا چرخه‌ی بعد دوباره تلاش شود."""
    tf = timeframe
    now = time.time()
    c = TIMEFRAME_REGIME_CACHE.get(_tfk(tf))
    if c and now - c['ts'] < TIMEFRAME_REGIME_TTL:
        return c['gate']
    scores = await asyncio.gather(*[_market_snapshot_async(http, sym, tf) for sym in MARKET_REPORT_SYMBOLS])
    scores = [x for x in scores if x is not None]
    total = len(scores)
    bull_n = sum(1 for x in scores if x > 0)
    bear_n = sum(1 for x in scores if x < 0)
    if bull_n >= MARKET_GATE_MIN_SYMBOLS:
        gate = 'BULLISH'
    elif bear_n >= MARKET_GATE_MIN_SYMBOLS:
        gate = 'BEARISH'
    else:
        gate = 'RANGE'
    entry = {
        'ts': now, 'gate': gate, 'bull_n': bull_n, 'bear_n': bear_n, 'total': total,
        # برای ثبت در رکورد معامله (_regime_alignment_snapshot)
        'bull_pct': (bull_n / total * 100.0) if total else 0.0,
        'bear_pct': (bear_n / total * 100.0) if total else 0.0,
    }
    if total < MARKET_GATE_MIN_SYMBOLS:
        entry['ts'] = 0.0  # داده‌ی ناکافی: ورود ممنوع، ولی نتیجه کش نمی‌شود و چرخه‌ی بعد دوباره تلاش می‌کند
    TIMEFRAME_REGIME_CACHE[_tfk(tf)] = entry
    return gate


def market_report(chat_id):
    s = get_session(chat_id)
    tf = s['timeframe']
    symbols = MARKET_REPORT_SYMBOLS
    results = []
    with ThreadPoolExecutor(max_workers=min(6, len(symbols))) as ex:
        futures = [ex.submit(_market_snapshot, sym, tf) for sym in symbols]
        for f in as_completed(futures):
            item = f.result()
            if item: results.append(item)
    if not results:
        return '❌ داده کافی برای ساخت داشبورد بازار دریافت نشد.'
    total = len(results)
    bullish = sum(1 for x in results if x['score'] > 0)
    bearish = sum(1 for x in results if x['score'] < 0)
    ranged = total - bullish - bearish

    if bullish >= MARKET_GATE_MIN_SYMBOLS:
        overall = '📈 بازار در مجموع در این تایم‌فریم تمایل صعودی دارد.'
    elif bearish >= MARKET_GATE_MIN_SYMBOLS:
        overall = '📉 بازار در مجموع در این تایم‌فریم تمایل نزولی دارد.'
    else:
        overall = '➡️ بازار در مجموع در این تایم‌فریم رنج و بدون روند مشخص است.'

    return (
        '🌐 *داشبورد بازار*\n'
        f"⏱ تایم‌فریم: `{TF_DISPLAY.get(tf, tf)}`\n\n"
        f"{overall}\n"
        f"📊 از بین {total} ارز بررسی‌شده: {bullish} صعودی، {bearish} نزولی، {ranged} رنج"
    )


# --- داشبورد بازار روی همه‌ی تایم‌فریم‌ها (دکمه‌ی «وضعیت بازار») -------------------------
# ماهانه/هفتگی به‌صورت مستقیم period='1month'/'1week' به منابع داده (Bitunix/Binance) پاس داده می‌شود
# (چون در TIMEFRAME_MAP نیستند، get_klines آن‌ها را دست‌نخورده رد می‌کند؛ اگر منبع داده این
# پریودها را پشتیبانی نکند، همان fallback موجود به منبع بعدی کار را انجام می‌دهد).
# عمداً sync (ThreadPoolExecutor + get_klines/_market_snapshot) است، نه async: نسخه‌ی اولیه
# از get_klines_async استفاده می‌کرد که به ASYNC_SEMAPHORE سراسری نیاز دارد؛ آن سمافور توسط
# scan_loop() در ترد و event-loop جداگانه‌ی خودش ساخته می‌شود، و acquire زدن رویش از
# event-loopِ دیگری (که اینجا با asyncio.run در ترد هندلر تلگرام ساخته می‌شد) با خطای
# «Future attached to a different loop» شکست می‌خورد - این خطا توسط except Exception عمومی
# در _market_snapshot_async بی‌صدا قورت داده می‌شد و باعث می‌شد همه‌ی تایم‌فریم‌ها همزمان
# «داده کافی دریافت نشد» برگردانند. مسیر sync زیر اصلاً از asyncio/ASYNC_SEMAPHORE استفاده
# نمی‌کند و همین باگ را کاملاً دور می‌زند.
MARKET_DASHBOARD_TIMEFRAMES = [
    ('1month', 'ماهانه'),
    ('1week', 'هفتگی'),
    ('1day', 'روزانه'),
    ('4hour', '۴ ساعته'),
    ('1hour', '۱ ساعته'),
    ('15min', '۱۵ دقیقه'),
    ('5min', '۵ دقیقه'),
]


def _market_dashboard_line(tf_label, scores):
    """همان آستانه‌ی گیت جهت بازار (MARKET_GATE_MIN_SYMBOLS از N)؛ عمداً هم‌جهت با
    refresh_market_gate است تا برچسب داشبورد با «رژیم تایم‌فریم فعال» تناقض نداشته باشد
    (قبلاً اکثریت ساده‌ی ۵۰٪ بود و مثلاً ۶ از ۱۰ را «صعودی» می‌گفت، ولی گیت با همان ۶ از ۱۰
    چون به آستانه‌ی ۷ نمی‌رسید «رنج» اعلام می‌کرد)."""
    total = len(scores)
    if total == 0:
        return f"⏱ *{tf_label}*: داده کافی دریافت نشد."
    bullish = sum(1 for x in scores if x > 0)
    bearish = sum(1 for x in scores if x < 0)
    ranged = total - bullish - bearish
    if bullish >= MARKET_GATE_MIN_SYMBOLS:
        overall = '📈 صعودی'
    elif bearish >= MARKET_GATE_MIN_SYMBOLS:
        overall = '📉 نزولی'
    else:
        overall = '➡️ رنج'
    return f"⏱ *{tf_label}*: {overall} ({bullish} صعودی، {bearish} نزولی، {ranged} رنج از {total})"


def market_dashboard_all_timeframes(chat_id=None):
    """داشبورد بازار روی تمام تایم‌فریم‌ها (ماهانه تا ۵ دقیقه) هم‌زمان - فقط برای دکمه‌ی
    «📊 وضعیت بازار»؛ نسخه‌ی تک‌تایم‌فریمی قدیمی (market_report) دست‌نخورده باقی مانده."""
    symbols = MARKET_REPORT_SYMBOLS
    scores_by_tf: Dict[str, list] = {tf: [] for tf, _ in MARKET_DASHBOARD_TIMEFRAMES}
    jobs = [(tf, sym) for tf, _ in MARKET_DASHBOARD_TIMEFRAMES for sym in symbols]
    with ThreadPoolExecutor(max_workers=min(20, len(jobs))) as ex:
        futures = {ex.submit(_market_snapshot, sym, tf): tf for tf, sym in jobs}
        for f in as_completed(futures):
            tf = futures[f]
            item = f.result()
            if item:
                scores_by_tf[tf].append(item['score'])

    lines = ['🌐 *داشبورد بازار*', f'📊 از بین {len(symbols)} ارز شاخص، در هر تایم‌فریم:', '']
    for tf, label in MARKET_DASHBOARD_TIMEFRAMES:
        lines.append(_market_dashboard_line(label, scores_by_tf.get(tf, [])))
    return "\n".join(lines)


